import { Test, TestingModule } from "@nestjs/testing";
import { ExecutionContext } from "@nestjs/common";
import { AdminGuard } from "./admin.guard";
import { UsersService } from "../users/users.service";

describe("AdminGuard", () => {
  let guard: AdminGuard;
  let usersService: UsersService;
  let mockExecutionContext: ExecutionContext;

  const mockUsersService = {
    findOne: jest.fn(),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        AdminGuard,
        {
          provide: UsersService,
          useValue: mockUsersService,
        },
      ],
    }).compile();

    guard = module.get<AdminGuard>(AdminGuard);
    usersService = module.get<UsersService>(UsersService);

    mockExecutionContext = {
      switchToHttp: jest.fn().mockReturnValue({
        getRequest: jest.fn(),
      }),
    } as unknown as ExecutionContext;
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe("canActivate", () => {
    it("should return true for admin user", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockResolvedValue({
        id: userId,
        isAdmin: true,
      });

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(true);
      expect(usersService.findOne).toHaveBeenCalledWith(userId);
    });

    it("should return false for non-admin user", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockResolvedValue({
        id: userId,
        isAdmin: false,
      });

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
      expect(usersService.findOne).toHaveBeenCalledWith(userId);
    });

    it("should return false when user isAdmin is undefined", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockResolvedValue({
        id: userId,
        // isAdmin is undefined
      });

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
      expect(usersService.findOne).toHaveBeenCalledWith(userId);
    });

    it("should return false when userId is missing from request", async () => {
      const mockRequest = {
        user: {}, // No userId
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
      expect(usersService.findOne).not.toHaveBeenCalled();
    });

    it("should return false when user object is missing from request", async () => {
      const mockRequest = {}; // No user object

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
      expect(usersService.findOne).not.toHaveBeenCalled();
    });

    it("should return false when user is not found", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockResolvedValue(null);

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
      expect(usersService.findOne).toHaveBeenCalledWith(userId);
    });

    it("should handle errors from usersService gracefully", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockRejectedValue(new Error("Database error"));

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "Database error",
      );
      expect(usersService.findOne).toHaveBeenCalledWith(userId);
    });

    it("should return false when isAdmin is explicitly false", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockUsersService.findOne.mockResolvedValue({
        id: userId,
        isAdmin: false,
      });

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(false);
    });
  });
});

import { Logger } from "@nestjs/common";
import * as fs from "fs";
import * as path from "path";

// Ensure logs directory exists
const LOGS_DIR = path.join(process.cwd(), "logs");
if (!fs.existsSync(LOGS_DIR)) {
  fs.mkdirSync(LOGS_DIR, { recursive: true });
}

const AUTH_LOG_FILE = path.join(LOGS_DIR, "auth-failures.log");
const DEBUG_LOG_FILE = path.join(LOGS_DIR, "debug.log");

// Helper to write to log file
function writeToAuthLog(message: string) {
  try {
    // Ensure logs directory exists (in case it was deleted)
    if (!fs.existsSync(LOGS_DIR)) {
      fs.mkdirSync(LOGS_DIR, { recursive: true });
    }
    const timestamp = new Date().toISOString();
    const logLine = `[${timestamp}] ${message}\n`;
    fs.appendFileSync(AUTH_LOG_FILE, logLine, "utf8");
  } catch (error) {
    console.error("Failed to write to auth log file:", error);
  }
}

// Helper to write debug logs to file
export function writeDebugLog(message: string) {
  try {
    // Ensure logs directory exists (in case it was deleted)
    if (!fs.existsSync(LOGS_DIR)) {
      fs.mkdirSync(LOGS_DIR, { recursive: true });
    }
    const timestamp = new Date().toISOString();
    const logLine = `[${timestamp}] ${message}\n`;
    fs.appendFileSync(DEBUG_LOG_FILE, logLine, "utf8");
  } catch (error) {
    console.error("Failed to write to debug log file:", error);
  }
}

export class AuthLogger {
  private readonly logger = new Logger("AuthLogger");

  /**
   * Log Google authentication failure with comprehensive details
   */
  // eslint-disable-next-line complexity
  logAuthFailure(
    userId: string,
    userEmail: string | null,
    context: string,
    error: unknown | null,
    additionalDetails?: Record<string, unknown>,
  ): void {
    const isSuccess = context === "LOGIN_SUCCESS" && !error;
    const errorDetails = {
      userId,
      userEmail,
      // e.g., 'syncEmails', 'scanHistory', 'tokenRefresh', 'LOGIN_SUCCESS'
      context,
      timestamp: new Date().toISOString(),
      errorType: (() => {
        if (error && typeof error === "object" && "code" in error) {
          return String((error as { code?: unknown }).code);
        }
        if (error && typeof error === "object" && "name" in error) {
          return String((error as { name?: unknown }).name);
        }
        return isSuccess ? "SUCCESS" : "Unknown";
      })(),
      errorMessage: (() => {
        if (error && typeof error === "object" && "message" in error) {
          return String((error as { message?: unknown }).message);
        }
        return isSuccess ? "Login successful" : String(error);
      })(),
      errorCode:
        error && typeof error === "object" && "code" in error
          ? (error as { code?: unknown }).code
          : undefined,
      httpStatus:
        (error && typeof error === "object" && "response" in error
          ? (error as { response?: { status?: unknown } }).response?.status
          : undefined) ||
        (error && typeof error === "object" && "status" in error
          ? (error as { status?: unknown }).status
          : undefined),
      // eslint-disable-next-line id-denylist
      errorData: (() => {
        if (error && typeof error === "object" && "response" in error) {
          // eslint-disable-next-line id-denylist
          return (error as { response?: { data?: unknown } }).response?.data;
        }
        if (error && typeof error === "object" && "data" in error) {
          // eslint-disable-next-line id-denylist
          return (error as { data?: unknown }).data;
        }
        return undefined;
      })(),
      // Determine cause (if error)
      cause: error ? this.determineCause(error) : "Login successful",
      // Additional context
      ...additionalDetails,
    };

    const logMessage = isSuccess
      ? `🔐 AUTH EVENT - LOGIN:\n${JSON.stringify(errorDetails, null, 2)}`
      : `🔐 AUTH FAILURE:\n${JSON.stringify(errorDetails, null, 2)}`;

    // Log to console
    if (isSuccess) {
      this.logger.log(logMessage);
    } else {
      this.logger.error(logMessage);
    }

    // Also write to file
    writeToAuthLog(logMessage);
  }

  /**
   * Determine the likely cause of the auth failure
   */
  private determineCause(error: unknown): string {
    if (!error) return "Unknown error";

    // Type guard helper
    const hasCode = (e: unknown): e is { code: string | number } =>
      typeof e === "object" && e !== null && "code" in e;

    const hasResponse = (
      e: unknown,
    ): e is { response: { data?: { error?: string }; status?: number } } =>
      typeof e === "object" &&
      e !== null &&
      "response" in e &&
      typeof (e as { response: unknown }).response === "object";

    const hasMessage = (e: unknown): e is { message: string } =>
      typeof e === "object" && e !== null && "message" in e;

    // Check for specific error codes
    if (
      (hasCode(error) && error.code === "invalid_grant") ||
      (hasResponse(error) && error.response?.data?.error === "invalid_grant")
    ) {
      return "Refresh token is invalid, expired, or revoked. User must re-authenticate.";
    }

    if (
      (hasCode(error) && error.code === 401) ||
      (hasResponse(error) && error.response?.status === 401)
    ) {
      return "Unauthorized - access token expired or invalid. Refresh token should have been used.";
    }

    if (hasMessage(error) && error.message.includes("Refresh token missing")) {
      return "Refresh token not found in database. User must re-authenticate.";
    }

    if (hasMessage(error) && error.message.includes("Token refresh failed")) {
      return "Token refresh attempt failed. Refresh token may be invalid or expired.";
    }

    if (
      (hasCode(error) && error.code === "ECONNREFUSED") ||
      (hasMessage(error) && error.message.includes("ECONNREFUSED"))
    ) {
      return "Network error - cannot connect to Google OAuth servers.";
    }

    if (
      (hasCode(error) && error.code === "ETIMEDOUT") ||
      (hasMessage(error) && error.message.includes("timeout"))
    ) {
      return "Timeout connecting to Google OAuth servers.";
    }

    const errorMessage = hasMessage(error)
      ? error.message
      : JSON.stringify(error);
    return `Unknown error: ${errorMessage}`;
  }
}

// Export singleton instance
export const authLogger = new AuthLogger();

// Initialize log file on module load to ensure it exists
try {
  if (!fs.existsSync(LOGS_DIR)) {
    fs.mkdirSync(LOGS_DIR, { recursive: true });
  }
  // Touch the log file to ensure it exists (create empty if it doesn't)
  if (!fs.existsSync(AUTH_LOG_FILE)) {
    fs.writeFileSync(
      AUTH_LOG_FILE,
      `[${new Date().toISOString()}] Auth log file initialized\n`,
      "utf8",
    );
  }
} catch (error) {
  console.error("Failed to initialize auth log file:", error);
}

import {
  Controller,
  Post,
  Get,
  Body,
  UseGuards,
  Request,
  Res,
  BadRequestException,
  Query,
  Logger,
  Put,
} from "@nestjs/common";
import { JwtAuthGuard } from "./jwt-auth.guard";
import { AuthService } from "./auth.service";
import { LocalAuthGuard } from "./local-auth.guard";
import { GoogleAuthGuard } from "./google-auth.guard";
import { MicrosoftAuthGuard } from "./microsoft-auth.guard";
import { ZohoAuthGuard } from "./zoho-auth.guard";
import { GoogleAccountsService } from "../google-accounts/google-accounts.service";
import { Office365AccountsService } from "../office365-accounts/office365-accounts.service";
import { ZohoAccountsService } from "../zoho-accounts/zoho-accounts.service";
import { WaitlistService } from "../waitlist/waitlist.service";
import { AUTH_CONSTANTS } from "../constants/auth-constants";

@Controller("auth")
export class AuthController {
  private readonly logger = new Logger(AuthController.name);

  constructor(
    private authService: AuthService,
    private googleAccountsService: GoogleAccountsService,
    private office365AccountsService: Office365AccountsService,
    private zohoAccountsService: ZohoAccountsService,
    private waitlistService: WaitlistService,
  ) {}

  @Post("register")
  async register(
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    @Body() _body: { email: string; password: string; name?: string },
  ) {
    // Registration is disabled - users must join waitlist first
    throw new BadRequestException(
      "Registration is currently closed. Please join our waitlist first.",
    );
  }

  @Post("setup-password")
  async setupPassword(@Body() body: { token: string; password: string }) {
    return this.authService.setupPassword(body.token, body.password);
  }

  /**
   * Set password for an authenticated SSO user.
   * This allows users who logged in via Google/Microsoft/Zoho to also have a password.
   */
  @UseGuards(JwtAuthGuard)
  @Put("set-password")
  async setPassword(
    @Request() req,
    @Body() body: { password: string; confirmPassword: string },
  ) {
    if (!body.password || !body.confirmPassword) {
      throw new BadRequestException("Password and confirmation are required");
    }

    if (body.password !== body.confirmPassword) {
      throw new BadRequestException("Passwords do not match");
    }

    if (body.password.length < AUTH_CONSTANTS.MIN_PASSWORD_LENGTH) {
      throw new BadRequestException(
        "Password must be at least 8 characters long",
      );
    }

    try {
      await this.authService.setPasswordForSsoUser(
        req.user.userId,
        body.password,
      );
      return { success: true, message: "Password set successfully" };
    } catch (error) {
      throw new BadRequestException(error.message || "Failed to set password");
    }
  }

  /**
   * Check if the authenticated user has a password set.
   */
  @UseGuards(JwtAuthGuard)
  @Get("has-password")
  async hasPassword(@Request() req) {
    const hasPassword = await this.authService.hasPassword(req.user.userId);
    return { hasPassword };
  }

  @UseGuards(LocalAuthGuard)
  @Post("login")
  async login(@Request() req) {
    return this.authService.login(req.user);
  }

  @Get("google")
  @UseGuards(GoogleAuthGuard)
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async googleAuth(@Request() _req) {}

  @Get("google/callback")
  @UseGuards(GoogleAuthGuard)
  async googleAuthRedirect(
    @Request() req,
    @Res() res,
    @Query("state") state?: string,
  ) {
    const frontendUrl = process.env.FRONTEND_URL || "http://localhost:3000";

    // Check if there was an auth error (set by GoogleAuthGuard)
    if (req.authError || req.user?.authFailed) {
      const error = req.authError as Error;
      const errorMessage = error?.message || "Authentication failed";
      this.logger.warn(`Google auth error: ${errorMessage}`);

      // Determine error type based on message content
      let errorType = "auth_error";
      if (errorMessage.includes("pending approval")) {
        errorType = "pending_approval";
      } else if (
        errorMessage.includes("waitlist") ||
        errorMessage.includes("join the waitlist")
      ) {
        errorType = "not_on_waitlist";
      }

      // Build redirect URL with error info
      const errorParams = new URLSearchParams({
        error: "auth_failed",
        message: errorMessage,
        type: errorType,
      });

      return res.redirect(
        `${frontendUrl}/auth-error?${errorParams.toString()}`,
      );
    }

    // Check if this is a connection flow (has state with userId)
    if (state) {
      try {
        const stateData = JSON.parse(Buffer.from(state, "base64").toString());
        if (stateData.action === "connect" && stateData.userId) {
          // This is a connection flow, not a login
          const googleUser = req.user as {
            googleProfile?: {
              id?: string;
              emails?: Array<{ value: string }>;
              displayName?: string;
            };
            googleAccessToken?: string;
            googleRefreshToken?: string;
            googleId?: string;
            googleCalendarAccessToken?: string;
            googleCalendarRefreshToken?: string;
            email?: string;
            name?: string;
          };
          const profile = googleUser.googleProfile;
          const accessToken =
            googleUser.googleAccessToken ||
            googleUser.googleCalendarAccessToken;
          const refreshToken =
            googleUser.googleRefreshToken ||
            googleUser.googleCalendarRefreshToken;
          const googleId =
            googleUser.googleId || profile?.id || googleUser.googleId;
          const email = profile?.emails?.[0]?.value || googleUser.email;
          const name = profile?.displayName || googleUser.name || "";

          if (googleId && email && accessToken && refreshToken) {
            const existingAccounts =
              await this.googleAccountsService.findAllByUser(stateData.userId);
            const accountExists = existingAccounts.find(
              (acc) => acc.googleId === googleId,
            );

            if (accountExists) {
              await this.googleAccountsService.updateTokens(
                accountExists.id,
                stateData.userId,
                accessToken,
                refreshToken,
              );
            } else {
              const isPrimary = existingAccounts.length === 0;
              await this.googleAccountsService.create(
                stateData.userId,
                googleId,
                email,
                name,
                accessToken,
                refreshToken,
                isPrimary,
              );
            }

            return res.redirect(`${frontendUrl}/settings?googleConnected=true`);
          }
        }
      } catch (e) {
        // Invalid state, fall through to login flow
        console.error("Error parsing state in Google callback:", e);
      }
    }

    // Regular login flow
    const loginData = await this.authService.login(req.user);
    res.redirect(`${frontendUrl}/login?token=${loginData.access_token}`);
  }

  @Get("microsoft")
  @UseGuards(MicrosoftAuthGuard)
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async microsoftAuth(@Request() _req) {}

  @Get("microsoft/callback")
  @UseGuards(MicrosoftAuthGuard)
  async microsoftAuthRedirect(
    @Request() req,
    @Res() res,
    @Query("state") state?: string,
  ) {
    const frontendUrl = process.env.FRONTEND_URL || "http://localhost:3000";

    // Check if there was an auth error (set by MicrosoftAuthGuard)
    if (req.authError || req.user?.authFailed) {
      const error = req.authError as Error;
      const errorMessage = error?.message || "Authentication failed";
      this.logger.warn(`Microsoft auth error: ${errorMessage}`);

      // Determine error type based on message content
      let errorType = "auth_error";
      if (errorMessage.includes("pending approval")) {
        errorType = "pending_approval";
      } else if (
        errorMessage.includes("waitlist") ||
        errorMessage.includes("join the waitlist")
      ) {
        errorType = "not_on_waitlist";
      }

      const errorParams = new URLSearchParams({
        error: "auth_failed",
        message: errorMessage,
        type: errorType,
      });

      return res.redirect(
        `${frontendUrl}/auth-error?${errorParams.toString()}`,
      );
    }

    // Check if this is a connection flow (has state with userId)
    if (state) {
      try {
        const stateData = JSON.parse(Buffer.from(state, "base64").toString());
        if (stateData.action === "connect" && stateData.userId) {
          // This is a connection flow, not a login
          const microsoftUser = req.user as {
            microsoftProfile?: {
              id?: string;
              mail?: string;
              userPrincipalName?: string;
              displayName?: string;
            };
            microsoftAccessToken?: string;
            microsoftRefreshToken?: string;
            microsoftId?: string;
          };
          const profile = microsoftUser.microsoftProfile;
          const accessToken = microsoftUser.microsoftAccessToken;
          const refreshToken = microsoftUser.microsoftRefreshToken;
          const microsoftId = microsoftUser.microsoftId || profile?.id || "";
          const email = profile?.mail || profile?.userPrincipalName || "";
          const name = profile?.displayName || "";

          if (microsoftId && email && accessToken && refreshToken) {
            const existingAccounts =
              await this.office365AccountsService.findAllByUser(
                stateData.userId,
              );
            const accountExists = existingAccounts.find(
              (acc) => acc.microsoftId === microsoftId,
            );

            if (accountExists) {
              await this.office365AccountsService.updateTokens(
                accountExists.id,
                stateData.userId,
                accessToken,
                refreshToken,
              );
            } else {
              const isPrimary = existingAccounts.length === 0;
              await this.office365AccountsService.create(
                stateData.userId,
                microsoftId,
                email,
                name,
                accessToken,
                refreshToken,
                isPrimary,
              );
            }

            return res.redirect(
              `${frontendUrl}/settings?office365Connected=true`,
            );
          }
        }
      } catch (e) {
        // Invalid state, fall through to login flow
        console.error("Error parsing state in Microsoft callback:", e);
      }
    }

    // Regular login flow
    const loginData = await this.authService.login(req.user);
    res.redirect(`${frontendUrl}/login?token=${loginData.access_token}`);
  }

  @Get("zoho")
  @UseGuards(ZohoAuthGuard)
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async zohoAuth(@Request() _req) {}

  @Get("zoho/callback")
  @UseGuards(ZohoAuthGuard)
  async zohoAuthRedirect(
