import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { AutoResponseLog } from "../database/entities/auto-response-log.entity";
import {
  QASearchResult,
  EmailClassification,
  AutoResponseLogPriority,
} from "./types/auto-responder.types";

/**
 * Service for auto-response analytics and logging
 */
@Injectable()
export class AutoResponderAnalyticsService {
  private readonly logger = new Logger(AutoResponderAnalyticsService.name);

  constructor(
    @InjectRepository(AutoResponseLog)
    private autoResponseLogRepository: Repository<AutoResponseLog>,
  ) {}

  /**
   * Log an auto-response
   */
  async logAutoResponse(
    userId: string,
    emailThreadId: string,
    senderEmailHash: string,
    priorityLevel: "low" | "medium" | "high",
    qaResult: QASearchResult | null,
    templateUsed: string,
    responseSubject: string,
    responseBody: string,
    classification: EmailClassification,
  ): Promise<void> {
    await this.autoResponseLogRepository.save({
      userId,
      emailThreadId,
      senderEmailHash,
      priorityLevel: priorityLevel as AutoResponseLogPriority,
      qaAnswerProvided: !!qaResult,
      confidenceScore: qaResult?.confidence || null,
      templateUsed,
      responseSubject,
      responseBody,
      classificationDetails: {
        isAutomated: classification.isAutomated,
        isNewsletter: classification.isNewsletter,
        isColdOutreach: classification.isColdOutreach,
        personalizationScore: classification.personalizationScore,
        reasons: classification.reasons,
      },
    });
  }

  /**
   * Check if auto-response was already sent to this thread
   */
  async hasExistingResponse(
    userId: string,
    emailThreadId: string,
  ): Promise<AutoResponseLog | null> {
    return this.autoResponseLogRepository.findOne({
      where: { userId, emailThreadId },
    });
  }

  /**
   * Get analytics for auto-responses
   */
  async getAnalytics(
    userId: string,
    dateRange?: { start: Date; end: Date },
  ): Promise<{
    totalSent: number;
    byPriority: { low: number; medium: number; high: number };
    qaAnswerRate: number;
    escalationRate: number;
    templateBreakdown: Record<string, number>;
  }> {
    const queryBuilder = this.autoResponseLogRepository
      .createQueryBuilder("log")
      .where("log.userId = :userId", { userId });

    if (dateRange) {
      queryBuilder
        .andWhere("log.sentAt >= :start", { start: dateRange.start })
        .andWhere("log.sentAt <= :end", { end: dateRange.end });
    }

    const logs = await queryBuilder.getMany();

    const totalSent = logs.length;
    const byPriority = {
      low: logs.filter(
        (log) => log.priorityLevel === AutoResponseLogPriority.LOW,
      ).length,
      medium: logs.filter(
        (log) => log.priorityLevel === AutoResponseLogPriority.MEDIUM,
      ).length,
      high: logs.filter(
        (log) => log.priorityLevel === AutoResponseLogPriority.HIGH,
      ).length,
    };
    const qaAnswerCount = logs.filter((log) => log.qaAnswerProvided).length;
    const escalationCount = logs.filter(
      (log) => log.escalationRequested,
    ).length;

    const templateBreakdown: Record<string, number> = {};
    for (const log of logs) {
      templateBreakdown[log.templateUsed] =
        (templateBreakdown[log.templateUsed] || 0) + 1;
    }

    return {
      totalSent,
      byPriority,
      qaAnswerRate: totalSent > 0 ? qaAnswerCount / totalSent : 0,
      escalationRate: totalSent > 0 ? escalationCount / totalSent : 0,
      templateBreakdown,
    };
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { User } from "../database/entities/user.entity";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { AutoResponderTemplateService } from "./auto-responder-template.service";
import { QueueStatsService } from "./queue-stats.service";
import { AutoResponderQaService } from "./auto-responder-qa.service";
import {
  AutoResponderConfig,
  AutoResponseTemplateVars,
} from "./types/auto-responder.types";
import {
  PRIORITY_THRESHOLDS,
  PREVIEW_DEFAULTS,
} from "./auto-responder-constants";

/**
 * Service for previewing auto-responses
 */
@Injectable()
export class AutoResponderPreviewService {
  private readonly logger = new Logger(AutoResponderPreviewService.name);

  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    private templateService: AutoResponderTemplateService,
    private queueStatsService: QueueStatsService,
    private qaService: AutoResponderQaService,
  ) {}

  /**
   * Determine priority level from thread's star count and urgency
   */
  determinePriorityLevel(
    thread: EmailThread | null,
  ): "low" | "medium" | "high" {
    // If no thread, default to medium priority
    if (!thread) {
      return "medium";
    }
    // High priority: 3 stars or high urgency score
    if (
      thread.starCount >= PRIORITY_THRESHOLDS.HIGH_PRIORITY_STARS ||
      thread.urgencyScore >= PRIORITY_THRESHOLDS.HIGH_URGENCY
    ) {
      return "high";
    }
    // Low priority: 1 star or low urgency
    if (
      thread.starCount === PRIORITY_THRESHOLDS.LOW_PRIORITY_STARS ||
      thread.urgencyScore < PRIORITY_THRESHOLDS.LOW_URGENCY
    ) {
      return "low";
    }
    // Medium priority: default
    return "medium";
  }

  /**
   * Preview auto-response with sample data
   */
  async previewAutoResponse(
    userId: string,
    templateType: "standard" | "highPriority" | "lowPriority" | "zeroBacklog",
    config: AutoResponderConfig,
  ): Promise<{ subject: string; body: string }> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    const queueStats = await this.queueStatsService.getQueueStats(userId);

    const sampleVars: AutoResponseTemplateVars = {
      userName: user?.name || "Your Name",
      senderName: "John Smith",
      originalSubject: "Question about your project",
      priorityLevel:
        templateType === "highPriority"
          ? "high"
          : templateType === "lowPriority"
            ? "low"
            : "medium",
      actionCount:
        queueStats.actionCount || PREVIEW_DEFAULTS.SAMPLE_ACTION_COUNT,
      triageCount:
        queueStats.triageCount || PREVIEW_DEFAULTS.SAMPLE_TRIAGE_COUNT,
      avgResponseTime: queueStats.avgResponseTime || "~4 days",
      urgentResponseTime: queueStats.urgentResponseTime || "12-24 hours",
      aiAnswer:
        "Based on previous conversations, the project timeline is approximately 3-4 weeks from kickoff to delivery.",
      hasAiAnswer: true,
    };

    const template = config.templates[templateType];
    const body = this.templateService.renderTemplate(template, sampleVars);

    return {
      subject: `Re: ${sampleVars.originalSubject} - BearlyMail Auto-Response`,
      body,
    };
  }

  /**
   * Preview auto-response for a specific email (shows what would actually be sent)
   */
  async previewAutoResponseForEmail(
    userId: string,
    emailId: string,
    config: AutoResponderConfig,
  ): Promise<{
    subject: string;
    body: string;
    templateUsed: string;
    priorityLevel: string;
    senderName: string;
    originalSubject: string;
  }> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    const queueStats = await this.queueStatsService.getQueueStats(userId);

    // Get the email
    const email = await this.emailRepository.findOne({
      where: { id: emailId, userId },
    });

    if (!email) {
      throw new Error("Email not found");
    }

    // Get the thread to determine priority
    const thread = email.emailThreadId
      ? await this.emailThreadRepository.findOne({
          where: { id: email.emailThreadId, userId },
        })
      : null;

    // Determine priority level from thread's star count and urgency
    const priorityLevel = this.determinePriorityLevel(thread);

    // Build template variables with real data
    const templateVars: AutoResponseTemplateVars = {
      userName: user?.name || "the recipient",
      senderName: email.fromName || email.from.split("@")[0],
      originalSubject: email.subject,
      priorityLevel,
      actionCount: queueStats.actionCount,
      triageCount: queueStats.triageCount,
      avgResponseTime: queueStats.avgResponseTime,
      urgentResponseTime: queueStats.urgentResponseTime,
      aiAnswer: null,
      hasAiAnswer: false,
    };

    // Generate Q&A answer if enabled
    if (config.qaContextEnabled) {
      const qaResult = await this.qaService.generateQAAnswer(
        userId,
        email.subject,
        email.body,
        config.qaMinConfidence,
      );
      if (qaResult && qaResult.confidence >= config.qaMinConfidence) {
        templateVars.aiAnswer = qaResult.answer;
        templateVars.hasAiAnswer = true;
      }
    }

    // Select the appropriate template
    const template = this.templateService.selectTemplate(
      config,
      priorityLevel,
      queueStats,
    );
    const templateUsed = this.templateService.getTemplateType(config, template);

    const body = this.templateService.renderTemplate(template, templateVars);

    return {
      subject: `Re: ${email.subject} - BearlyMail Auto-Response`,
      body,
      templateUsed,
      priorityLevel,
      senderName: templateVars.senderName,
      originalSubject: email.subject,
    };
  }

  /**
   * Get recent emails for preview selection
   * Only returns incoming emails (not sent by the user) that would be eligible for auto-response
   */
  async getRecentEmailsForPreview(
    userId: string,
    limit = 10,
  ): Promise<
    Array<{
      id: string;
      from: string;
      fromName: string | null;
      subject: string;
      receivedAt: Date;
      priorityScore: number | null;
    }>
  > {
    // Get user's email to filter out sent emails
    const user = await this.userRepository.findOne({
      where: { id: userId },
      select: ["email"],
    });

    if (!user) {
      return [];
    }

    const userEmail = user.email?.toLowerCase();

    // Fetch more emails than needed since we'll filter out sent emails
    const emails = await this.emailRepository.find({
      where: { userId },
      order: { receivedAt: "DESC" },
      take: limit * 3,
      select: [
        "id",
        "from",
        "fromName",
        "subject",
        "receivedAt",
        "emailThreadId",
      ],
    });

    // Filter out emails sent by the user (only show incoming emails)
    const incomingEmails = emails.filter((email) => {
      const fromEmail = email.from?.toLowerCase();
      return fromEmail && fromEmail !== userEmail;
    });

    // Get thread priority scores for incoming emails only
    const emailsWithPriority = await Promise.all(
      incomingEmails.slice(0, limit).map(async (email) => {
        let priorityScore: number | null = null;
        if (email.emailThreadId) {
          const thread = await this.emailThreadRepository.findOne({
            where: { id: email.emailThreadId, userId },
            select: ["priorityScore"],
          });
          priorityScore = thread?.priorityScore || null;
        }
        return {
          id: email.id,
          from: email.from,
          fromName: email.fromName,
          subject: email.subject,
          receivedAt: email.receivedAt,
          priorityScore,
        };
      }),
    );

    return emailsWithPriority;
  }
}

import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import {
  UserContext,
  ContextKey,
} from "../database/entities/user-context.entity";
import { LLMService } from "../llm/llm.service";
import { getPrompt, renderPrompt } from "../llm/prompts";
import { cleanEmailContent } from "../llm/email-content-cleaner";
import { QASearchResult } from "./types/auto-responder.types";
import { RATIOS } from "../constants/percentages";
import { LLM_CONFIG } from "./auto-responder-constants";

const LLM_OP_GENERATE_QA_ANSWER = "generate_qa_answer";

/**
 * Service for generating Q&A answers from user context
 */
@Injectable()
export class AutoResponderQaService {
  private readonly logger = new Logger(AutoResponderQaService.name);

  constructor(
    @InjectRepository(UserContext)
    private userContextRepository: Repository<UserContext>,
    @Inject(forwardRef(() => LLMService))
    private llmService: LLMService,
  ) {}

  /**
   * Generate Q&A answer from user's context
   */
  async generateQAAnswer(
    userId: string,
    subject: string,
    body: string,
    minConfidence: number,
  ): Promise<QASearchResult | null> {
    try {
      // Get Q&A context entries
      const qaContexts = await this.userContextRepository.find({
        where: {
          userId,
          contextKey: ContextKey.Q_AND_A,
        },
      });

      if (qaContexts.length === 0) {
        return null;
      }

      // Parse Q&A pairs from context
      const qaPairs: Array<{ question: string; answer: string }> = [];
      for (const ctx of qaContexts) {
        try {
          const parsed = JSON.parse(ctx.contextValue);
          if (parsed.question && parsed.answer) {
            qaPairs.push(parsed);
          }
        } catch {
          // If not JSON, try to parse as "Q: ... A: ..." format
          const match = ctx.contextValue.match(/Q:\s*(.*?)\s*A:\s*(.*)/is);
          if (match) {
            qaPairs.push({
              question: match[1].trim(),
              answer: match[2].trim(),
            });
          }
        }
      }

      if (qaPairs.length === 0) {
        return null;
      }

      // Use LLM to find relevant answer
      const promptConfig = getPrompt("generate_qa_answer");
      if (!promptConfig) {
        this.logger.warn("generate_qa_answer prompt not found");
        return null;
      }

      const cleanedBody = cleanEmailContent(
        body,
        null,
        LLM_CONFIG.MAX_BODY_LENGTH_FOR_QA,
      );

      const prompt = renderPrompt(promptConfig.prompt || "", {
        subject,
        body: cleanedBody,
        qaPairs: qaPairs
          .map((qa, i) => `${i + 1}. Q: ${qa.question}\n   A: ${qa.answer}`)
          .join("\n\n"),
      });

      const response = await this.llmService.generateText(
        {
          prompt,
          systemPrompt: promptConfig.systemPrompt || "",
          temperature: RATIOS.THIRTY_PERCENT,
          maxTokens: LLM_CONFIG.QA_MAX_TOKENS,
        },
        undefined,
        userId,
        LLM_OP_GENERATE_QA_ANSWER as any,
      );

      // Parse response
      try {
        const jsonMatch = response.match(/\{[\s\S]*\}/);
        if (jsonMatch) {
          const parsed = JSON.parse(jsonMatch[0]);
          if (parsed.confidence >= minConfidence && parsed.answer) {
            return {
              answer: parsed.answer,
              confidence: parsed.confidence,
              sources: parsed.sources || [],
            };
          }
        }
      } catch (parseError) {
        this.logger.warn("Failed to parse Q&A response", parseError);
      }

      return null;
    } catch (error) {
      this.logger.error("Failed to generate Q&A answer", error);
      return null;
    }
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, MoreThan } from "typeorm";
import * as crypto from "crypto";
import { AutoResponseSuppression } from "../database/entities/auto-response-suppression.entity";
import { SuppressionReason } from "./types/auto-responder.types";

/**
 * Service for managing auto-response suppressions (cooldowns and opt-outs)
 */
@Injectable()
export class AutoResponderSuppressionService {
  private readonly logger = new Logger(AutoResponderSuppressionService.name);

  constructor(
    @InjectRepository(AutoResponseSuppression)
    private autoResponseSuppressionRepository: Repository<AutoResponseSuppression>,
  ) {}

  /**
   * Hash an email address for storage/lookup
   */
  hashEmail(email: string): string {
    return crypto
      .createHash("sha256")
      .update(email.toLowerCase().trim())
      .digest("hex");
  }

  /**
   * Check if sender is suppressed
   */
  async checkSuppression(
    userId: string,
    senderEmailHash: string,
  ): Promise<AutoResponseSuppression | null> {
    const now = new Date();

    // Check for permanent suppression (opt-out)
    const permanentSuppression =
      await this.autoResponseSuppressionRepository.findOne({
        where: {
          userId,
          senderEmailHash,
          reason: SuppressionReason.OPT_OUT,
        },
      });
    if (permanentSuppression) {
      return permanentSuppression;
    }

    // Check for active cooldown
    const cooldownSuppression =
      await this.autoResponseSuppressionRepository.findOne({
        where: {
          userId,
          senderEmailHash,
          reason: SuppressionReason.COOLDOWN,
          suppressUntil: MoreThan(now),
        },
      });

    return cooldownSuppression;
  }

  /**
   * Add cooldown suppression for a sender
   */
  async addCooldownSuppression(
    userId: string,
    senderEmailHash: string,
    cooldownDays: number,
  ): Promise<void> {
    const suppressUntil = new Date();
    suppressUntil.setDate(suppressUntil.getDate() + cooldownDays);

    // Remove existing cooldown for this sender
    await this.autoResponseSuppressionRepository.delete({
      userId,
      senderEmailHash,
      reason: SuppressionReason.COOLDOWN,
    });

    // Add new cooldown
    await this.autoResponseSuppressionRepository.save({
      userId,
      senderEmailHash,
      reason: SuppressionReason.COOLDOWN,
      suppressUntil,
      notes: `Auto-response cooldown for ${cooldownDays} days`,
    });
  }

  /**
   * Add opt-out suppression for a sender
   */
  async addOptOutSuppression(
    userId: string,
    senderEmail: string,
    notes?: string,
  ): Promise<void> {
    const senderEmailHash = this.hashEmail(senderEmail);

    // Remove any existing suppressions for this sender
    await this.autoResponseSuppressionRepository.delete({
      userId,
      senderEmailHash,
    });

    // Add permanent opt-out
    await this.autoResponseSuppressionRepository.save({
      userId,
      senderEmailHash,
      reason: SuppressionReason.OPT_OUT,
      suppressUntil: null, // Permanent
      notes: notes || "User requested opt-out",
    });
  }

  /**
   * Remove opt-out suppression for a sender
   */
  async removeOptOutSuppression(
    userId: string,
    senderEmail: string,
  ): Promise<void> {
    const senderEmailHash = this.hashEmail(senderEmail);
    await this.autoResponseSuppressionRepository.delete({
      userId,
      senderEmailHash,
      reason: SuppressionReason.OPT_OUT,
    });
  }
}

import { Injectable, Logger, OnModuleInit, Inject } from "@nestjs/common";
import PgBoss from "pg-boss";
import { AutoResponderService } from "./auto-responder.service";
import { getJobPriority } from "../queue/job-priorities";
import { autoresponderLogger } from "./autoresponder-logger";
import { QUEUE_CONFIG } from "./auto-responder-constants";

interface AutoResponderJobData {
  userId: string;
  emailThreadId: string;
  headers?: Record<string, string>;
}

@Injectable()
export class AutoResponderProcessor implements OnModuleInit {
  private readonly logger = new Logger(AutoResponderProcessor.name);

  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    private autoResponderService: AutoResponderService,
  ) {}

  async onModuleInit() {
    // Register worker for auto-responder jobs
    await this.boss.work(
      "auto-responder",
      {
        teamConcurrency: 5, // Process up to 5 jobs concurrently
        teamSize: 1,
      },
      async (job) => {
        const { userId, emailThreadId, headers } =
          job.data as AutoResponderJobData;
        this.logger.debug(
          `Processing auto-responder job for thread ${emailThreadId}`,
        );

        try {
          const result =
            await this.autoResponderService.processEmailForAutoResponse(
              userId,
              emailThreadId,
              headers,
            );

          this.logger.log(
            `Auto-responder result for thread ${emailThreadId}: ${result.reason}`,
          );

          return result;
        } catch (error) {
          this.logger.error(
            `Failed to process auto-responder job for thread ${emailThreadId}`,
            error,
          );
          throw error;
        }
      },
    );

    this.logger.log("Auto-responder processor initialized");
  }

  /**
   * Queue an auto-responder job for processing
   * Called after email triage is complete
   */
  async queueAutoResponseJob(
    userId: string,
    emailThreadId: string,
    headers?: Record<string, string>,
  ): Promise<string | null> {
    const logContext = { userId, emailThreadId };

    try {
      const jobId = await this.boss.send(
        "auto-responder",
        {
          userId,
          emailThreadId,
          headers,
        } as AutoResponderJobData,
        {
          priority: getJobPriority("auto-responder"),
          retryLimit: 2,
          retryDelay: QUEUE_CONFIG.RETRY_DELAY_SECONDS,
          expireInMinutes: 60, // Expire after 1 hour
          singletonKey: `auto-responder-${emailThreadId}`, // Prevent duplicate jobs for same thread
        },
      );

      this.logger.debug(
        `Queued auto-responder job ${jobId} for thread ${emailThreadId}`,
      );

      autoresponderLogger.logQueueJob(logContext, jobId, true);

      return jobId;
    } catch (error) {
      this.logger.error(
        `Failed to queue auto-responder job for thread ${emailThreadId}`,
        error,
      );

      autoresponderLogger.logQueueJob(logContext, null, false);

      return null;
    }
  }
}

import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { User } from "../database/entities/user.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { EmailClassifierService } from "./email-classifier.service";
import { QueueStatsService } from "./queue-stats.service";
import { AutoResponderTemplateService } from "./auto-responder-template.service";
import { AutoResponderSuppressionService } from "./auto-responder-suppression.service";
import { AutoResponderQaService } from "./auto-responder-qa.service";
import { AutoResponderAnalyticsService } from "./auto-responder-analytics.service";
import { AutoResponderPreviewService } from "./auto-responder-preview.service";
import { EmailProviderManager } from "../emails/email-provider-manager.service";
import {
  AutoResponderConfig,
  DEFAULT_AUTO_RESPONDER_CONFIG,
  AutoResponseTemplateVars,
} from "./types/auto-responder.types";
import {
  autoresponderLogger,
  AutoresponderDecisionContext,
} from "./autoresponder-logger";
import { PRIORITY_THRESHOLDS } from "./auto-responder-constants";

@Injectable()
export class AutoResponderService {
  private readonly logger = new Logger(AutoResponderService.name);

  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    private emailClassifierService: EmailClassifierService,
    private queueStatsService: QueueStatsService,
    private templateService: AutoResponderTemplateService,
    private suppressionService: AutoResponderSuppressionService,
    private qaService: AutoResponderQaService,
    private analyticsService: AutoResponderAnalyticsService,
    private previewService: AutoResponderPreviewService,
    @Inject(forwardRef(() => EmailProviderManager))
    private emailProviderManager: EmailProviderManager,
  ) {}

  /**
   * Get user's auto-responder configuration
   */
  async getConfig(userId: string): Promise<AutoResponderConfig> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user?.autoResponderSettings) {
      return DEFAULT_AUTO_RESPONDER_CONFIG;
    }
    return { ...DEFAULT_AUTO_RESPONDER_CONFIG, ...user.autoResponderSettings };
  }

  /**
   * Update user's auto-responder configuration
   */
  async updateConfig(
    userId: string,
    config: Partial<AutoResponderConfig>,
  ): Promise<AutoResponderConfig> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new Error("User not found");
    }

    const currentConfig =
      user.autoResponderSettings || DEFAULT_AUTO_RESPONDER_CONFIG;
    const newConfig = { ...currentConfig, ...config };

    await this.userRepository.update(userId, {
      autoResponderSettings: newConfig,
    });

    return newConfig;
  }

  /**
   * Main entry point: determine if auto-response should be sent and send it
   */
  async processEmailForAutoResponse(
    userId: string,
    emailThreadId: string,
    headers?: Record<string, string>,
  ): Promise<{ sent: boolean; reason: string }> {
    const logContext: AutoresponderDecisionContext = {
      userId,
      emailThreadId,
    };

    autoresponderLogger.logProcessingStart(logContext);

    const config = await this.getConfig(userId);

    // Log config check
    autoresponderLogger.logConfigCheck(logContext, config.enabled, {
      sendForHighPriority: config.sendFor.highPriority,
      sendForStandardPriority: config.sendFor.standardPriority,
      sendForLowPriority: config.sendFor.lowPriority,
      qaContextEnabled: config.qaContextEnabled,
      customExclusionRulesCount: config.customExclusionRules?.length || 0,
    });

    // Check if auto-responder is enabled
    if (!config.enabled) {
      const reason = "Auto-responder disabled";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
      });
      return { sent: false, reason };
    }

    // Get the email thread with emails
    const thread = await this.emailThreadRepository.findOne({
      where: { id: emailThreadId, userId },
      relations: ["emails"],
    });

    if (!thread || !thread.emails || thread.emails.length === 0) {
      const reason = "Thread or emails not found";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { threadFound: !!thread, emailCount: thread?.emails?.length },
      });
      return { sent: false, reason };
    }

    // Get the latest email in the thread (the one that triggered this)
    const latestEmail = thread.emails.sort(
      (a, b) =>
        new Date(b.receivedAt).getTime() - new Date(a.receivedAt).getTime(),
    )[0];

    // Update log context with email details
    logContext.senderEmail = latestEmail.from;
    logContext.subject = latestEmail.subject;

    // Check if this is a new thread (only one email, no replies)
    const hasUserReplies = await this.threadHasUserReplies(userId, thread);
    if (hasUserReplies) {
      const reason = "Thread already has user replies";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { emailCount: thread.emails.length },
      });
      return { sent: false, reason };
    }

    // Check if we've already sent an auto-response to this thread
    const existingResponse = await this.analyticsService.hasExistingResponse(
      userId,
      emailThreadId,
    );
    if (existingResponse) {
      const reason = "Auto-response already sent to this thread";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { previousResponseId: existingResponse.id },
      });
      return { sent: false, reason };
    }

    // Check sender suppression (opt-out or cooldown)
    const senderEmailHash = this.suppressionService.hashEmail(latestEmail.from);
    const suppression = await this.suppressionService.checkSuppression(
      userId,
      senderEmailHash,
    );

    autoresponderLogger.logSuppressionCheck(
      logContext,
      !!suppression,
      suppression?.reason,
    );

    if (suppression) {
      const reason = `Sender suppressed: ${suppression.reason}`;
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: {
          suppressionReason: suppression.reason,
          suppressUntil: suppression.suppressUntil,
        },
      });
      return { sent: false, reason };
    }

    // Classify the email
    const classification = await this.emailClassifierService.classifyEmail(
      {
        from: latestEmail.from,
        fromName: latestEmail.fromName || undefined,
        subject: latestEmail.subject,
        body: latestEmail.body,
        htmlBody: latestEmail.htmlBody || undefined,
      },
      headers,
      hasUserReplies,
    );

    // Log classification results
    autoresponderLogger.logClassification(logContext, {
      isAutomated: classification.isAutomated,
      isNewsletter: classification.isNewsletter,
      isColdOutreach: classification.isColdOutreach,
      isBounce: classification.isBounce,
      isOutOfOffice: classification.isOutOfOffice,
      personalizationScore: classification.personalizationScore,
      reasons: classification.reasons,
    });

    // Always exclude bounce and out-of-office emails
    if (classification.isBounce) {
      const reason = "Bounce email excluded";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { classification: "bounce" },
      });
      return { sent: false, reason };
    }
    if (classification.isOutOfOffice) {
      const reason = "Out-of-office reply excluded";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { classification: "out-of-office" },
      });
      return { sent: false, reason };
    }

    // Check custom exclusion rules using AI
    if (config.customExclusionRules && config.customExclusionRules.length > 0) {
      const customExclusionResult =
        await this.emailClassifierService.checkCustomExclusionRules(
          {
            from: latestEmail.from,
            fromName: latestEmail.fromName || undefined,
            subject: latestEmail.subject,
            body: latestEmail.body,
          },
          config.customExclusionRules,
        );

      if (customExclusionResult.matched) {
        const reason = `Custom exclusion rule matched: ${customExclusionResult.matchedRule} (${customExclusionResult.reason})`;
        autoresponderLogger.logDecision(logContext, {
          decision: "SKIP",
          reason,
          details: {
            matchedRule: customExclusionResult.matchedRule,
            ruleReason: customExclusionResult.reason,
          },
        });
        return { sent: false, reason };
      }
    }

    // Determine priority level from thread
    const priorityLevel = this.determinePriorityLevel(thread);

    // Log priority check
    autoresponderLogger.logPriorityCheck(
      logContext,
      priorityLevel,
      thread.starCount,
      thread.urgencyScore,
      {
        sendForHighPriority: config.sendFor.highPriority,
        sendForStandardPriority: config.sendFor.standardPriority,
        sendForLowPriority: config.sendFor.lowPriority,
      },
    );

    // Check if we should send for this priority level
    if (priorityLevel === "high" && !config.sendFor.highPriority) {
      const reason = "High priority auto-response disabled";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { priorityLevel, configSetting: "sendFor.highPriority=false" },
      });
      return { sent: false, reason };
    }
    if (priorityLevel === "medium" && !config.sendFor.standardPriority) {
      const reason = "Standard priority auto-response disabled";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: {
          priorityLevel,
          configSetting: "sendFor.standardPriority=false",
        },
      });
      return { sent: false, reason };
    }
    if (priorityLevel === "low" && !config.sendFor.lowPriority) {
      const reason = "Low priority auto-response disabled";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
        details: { priorityLevel, configSetting: "sendFor.lowPriority=false" },
      });
      return { sent: false, reason };
    }

    // Get user info and queue stats
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) {
      const reason = "User not found";
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason,
      });
      return { sent: false, reason };
    }

    const queueStats = await this.queueStatsService.getQueueStats(userId);

    // Get category-specific response time if available
    const categoryResponseTime =
      this.queueStatsService.getResponseTimeForCategory(
        queueStats,
        thread.category,
      );

    // Generate Q&A answer if enabled
    let qaResult = null;
    if (config.qaContextEnabled) {
      qaResult = await this.qaService.generateQAAnswer(
        userId,
        latestEmail.subject,
        latestEmail.body,
        config.qaMinConfidence,
      );
    }

    // Render the response
    const templateVars: AutoResponseTemplateVars = {
      userName: user.name || "the recipient",
      senderName: latestEmail.fromName || latestEmail.from.split("@")[0],
      originalSubject: latestEmail.subject,
      priorityLevel,
      actionCount: queueStats.actionCount,
      triageCount: queueStats.triageCount,
      avgResponseTime: categoryResponseTime,
      urgentResponseTime: queueStats.urgentResponseTime,
      aiAnswer: qaResult?.answer || null,
      hasAiAnswer: !!qaResult && qaResult.confidence >= config.qaMinConfidence,
    };

    const template = this.templateService.selectTemplate(
      config,
      priorityLevel,
      queueStats,
    );
    const templateUsed = this.templateService.getTemplateType(config, template);
    const responseBody = this.templateService.renderTemplate(
      template,
      templateVars,
    );
    const responseSubject = `Re: ${latestEmail.subject} - BearlyMail Auto-Response`;

    // Convert markdown to HTML for proper email formatting
    const responseHtmlBody = this.templateService.markdownToHtml(responseBody);

    // Log send attempt
    autoresponderLogger.logSendAttempt(
      logContext,
      templateUsed,
      responseSubject,
    );

    // Send the auto-response
    try {
      const provider =
        await this.emailProviderManager.getPrimaryProvider(userId);
      if (!provider) {
        const reason = "No email provider connected";
        autoresponderLogger.logSendError(
          logContext,
          new Error(reason),
          "get_provider",
        );
        autoresponderLogger.logDecision(logContext, {
          decision: "SKIP",
          reason,
        });
        return { sent: false, reason };
      }

      // Use Reply-To address if available, otherwise fall back to From address
      const replyToAddress = latestEmail.replyTo || latestEmail.from;

      await provider.sendReply(
        userId,
        thread.threadId,
        replyToAddress,
        responseSubject,
        responseBody,
        undefined,
        responseHtmlBody,
      );

      // Log the auto-response
      await this.analyticsService.logAutoResponse(
        userId,
        emailThreadId,
        senderEmailHash,
        priorityLevel,
        qaResult,
        templateUsed,
        responseSubject,
        responseBody,
        classification,
      );

      // Add cooldown suppression for this sender
      await this.suppressionService.addCooldownSuppression(
        userId,
        senderEmailHash,
        config.cooldownPeriodDays,
      );

      // Log success
      autoresponderLogger.logSendSuccess(logContext, templateUsed, !!qaResult);
      autoresponderLogger.logDecision(logContext, {
        decision: "SEND",
        reason: "Auto-response sent successfully",
        details: {
          templateUsed,
          priorityLevel,
          qaAnswerProvided: !!qaResult,
          recipient: latestEmail.from,
        },
      });

      this.logger.log(
        `Auto-response sent for thread ${emailThreadId} to ${latestEmail.from}`,
      );

      return { sent: true, reason: "Auto-response sent successfully" };
    } catch (error) {
      autoresponderLogger.logSendError(logContext, error, "send_reply");
      autoresponderLogger.logDecision(logContext, {
        decision: "SKIP",
        reason: `Send failed: ${(error as Error).message}`,
        details: { error: (error as Error).message },
      });

      this.logger.error(
        `Failed to send auto-response for thread ${emailThreadId}`,
        error,
      );
      return {
        sent: false,
        reason: `Send failed: ${(error as Error).message}`,
      };
    }
  }

  /**
   * Check if thread has any replies from the user
   */
  private async threadHasUserReplies(
    userId: string,
    thread: EmailThread,
  ): Promise<boolean> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) return false;

    const userEmail = user.email.toLowerCase();
    return thread.emails.some(
      (email) => email.from.toLowerCase() === userEmail,
    );
  }

  /**
   * Determine priority level from thread's star count and urgency
   */
  private determinePriorityLevel(
    thread: EmailThread | null,
  ): "low" | "medium" | "high" {
    if (!thread) {
      return "medium";
    }
    if (
      thread.starCount >= PRIORITY_THRESHOLDS.HIGH_PRIORITY_STARS ||
      thread.urgencyScore >= PRIORITY_THRESHOLDS.HIGH_URGENCY
    ) {
      return "high";
    }
    if (
      thread.starCount === PRIORITY_THRESHOLDS.LOW_PRIORITY_STARS ||
      thread.urgencyScore < PRIORITY_THRESHOLDS.LOW_URGENCY
    ) {
      return "low";
    }
    return "medium";
  }

  // === Delegated methods to extracted services ===

  /**
   * Add opt-out suppression for a sender
   */
  async addOptOutSuppression(
    userId: string,
    senderEmail: string,
    notes?: string,
  ): Promise<void> {
    return this.suppressionService.addOptOutSuppression(
      userId,
      senderEmail,
      notes,
    );
  }

  /**
   * Remove opt-out suppression for a sender
   */
  async removeOptOutSuppression(
    userId: string,
    senderEmail: string,
  ): Promise<void> {
    return this.suppressionService.removeOptOutSuppression(userId, senderEmail);
  }

  /**
   * Get analytics for auto-responses
   */
  async getAnalytics(
    userId: string,
    dateRange?: { start: Date; end: Date },
  ): Promise<{
    totalSent: number;
    byPriority: { low: number; medium: number; high: number };
    qaAnswerRate: number;
    escalationRate: number;
    templateBreakdown: Record<string, number>;
  }> {
    return this.analyticsService.getAnalytics(userId, dateRange);
  }

  /**
   * Preview auto-response with sample data
   */
  async previewAutoResponse(
    userId: string,
    templateType: "standard" | "highPriority" | "lowPriority" | "zeroBacklog",
  ): Promise<{ subject: string; body: string }> {
    const config = await this.getConfig(userId);
    return this.previewService.previewAutoResponse(
      userId,
      templateType,
      config,
    );
  }

  /**
   * Preview auto-response for a specific email
   */
  async previewAutoResponseForEmail(
    userId: string,
    emailId: string,
  ): Promise<{
    subject: string;
    body: string;
    templateUsed: string;
    priorityLevel: string;
    senderName: string;
    originalSubject: string;
  }> {
    const config = await this.getConfig(userId);
    return this.previewService.previewAutoResponseForEmail(
      userId,
      emailId,
      config,
    );
  }

  /**
   * Get recent emails for preview selection
   */
  async getRecentEmailsForPreview(
    userId: string,
    limit = 10,
  ): Promise<
    Array<{
      id: string;
      from: string;
      fromName: string | null;
      subject: string;
      receivedAt: Date;
      priorityScore: number | null;
    }>
  > {
    return this.previewService.getRecentEmailsForPreview(userId, limit);
  }
}

import { Test, TestingModule } from "@nestjs/testing";
import { EmailClassifierService } from "./email-classifier.service";
import { LLMService } from "../llm/llm.service";

describe("EmailClassifierService", () => {
  let service: EmailClassifierService;
  let llmService: jest.Mocked<LLMService>;

  beforeEach(async () => {
    const mockLLMService = {
      generateText: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EmailClassifierService,
        {
          provide: LLMService,
          useValue: mockLLMService,
        },
      ],
    }).compile();

    service = module.get<EmailClassifierService>(EmailClassifierService);
    llmService = module.get(LLMService);
  });

  it("should be defined", () => {
    expect(service).toBeDefined();
  });

  describe("classifyEmail", () => {
    describe("header-based detection", () => {
      it("should detect automated emails via Auto-Submitted header", async () => {
        const result = await service.classifyEmail(
          {
            from: "test@example.com",
            subject: "Test",
            body: "Test body",
          },
          { "Auto-Submitted": "auto-generated" },
        );

        expect(result.isAutomated).toBe(true);
        expect(result.reasons).toContain(
          "Automated email detected via headers",
        );
      });

      it("should detect newsletters via List-Unsubscribe header", async () => {
        const result = await service.classifyEmail(
          {
            from: "newsletter@company.com",
            subject: "Weekly Update",
            body: "This week's news...",
          },
          { "List-Unsubscribe": "<mailto:unsubscribe@company.com>" },
        );

        expect(result.isNewsletter).toBe(true);
        expect(result.reasons).toContain(
          "Newsletter detected via headers (List-Unsubscribe)",
        );
      });

      it("should detect out-of-office replies", async () => {
        const result = await service.classifyEmail(
          {
            from: "colleague@company.com",
            subject: "Out of Office: Re: Meeting",
            body: "I am currently out of the office...",
          },
          { "Auto-Submitted": "auto-replied" },
        );

        expect(result.isOutOfOffice).toBe(true);
      });

      it("should detect bounces via content-type", async () => {
        const result = await service.classifyEmail(
          {
            from: "mailer-daemon@mail.example.com",
            subject: "Delivery Status Notification",
            body: "Your message could not be delivered...",
          },
          { "Content-Type": "multipart/report; report-type=delivery-status" },
        );

        expect(result.isBounce).toBe(true);
      });
    });

    describe("sender-based detection", () => {
      it("should detect noreply senders as automated", async () => {
        const result = await service.classifyEmail(
          {
            from: "noreply@company.com",
            subject: "Your order confirmation",
            body: "Thank you for your order...",
          },
          {},
        );

        expect(result.isAutomated).toBe(true);
        expect(
          result.reasons.some((r) => r.includes("Automated sender pattern")),
        ).toBe(true);
      });

      it("should detect do-not-reply senders as automated", async () => {
        const result = await service.classifyEmail(
          {
            from: "do-not-reply@service.com",
            subject: "Notification",
            body: "You have a new message...",
          },
          {},
        );

        expect(result.isAutomated).toBe(true);
      });

      it("should detect newsletter senders", async () => {
        const result = await service.classifyEmail(
          {
            from: "newsletter@updates.company.com",
            subject: "Monthly Newsletter",
            body: "Here's what happened this month...",
          },
          {},
        );

        expect(result.isNewsletter).toBe(true);
      });
    });

    describe("subject-based detection", () => {
      it("should detect auto-reply subjects", async () => {
