import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { LLMService, LLMProvider } from "../llm/llm.service";
import { getPrompt, renderPrompt } from "../llm/prompts";
import { EmailClassification } from "./types/auto-responder.types";
import { cleanEmailContent } from "../llm/email-content-cleaner";
import { RATIOS } from "../constants/percentages";
import { LLM_CONFIG } from "./auto-responder-constants";
import { EMAIL_CLASSIFICATION } from "../constants/llm-constants";

// LLM operation for email classification
const LLM_OP_CLASSIFY_EMAIL = "classify_email_type";

/**
 * Service for classifying emails to determine if auto-response should be sent
 * Uses a combination of header analysis and LLM-based content classification
 */
@Injectable()
export class EmailClassifierService {
  private readonly logger = new Logger(EmailClassifierService.name);

  // Common automated email patterns
  private readonly automatedPatterns = {
    senders: [
      /^noreply@/i,
      /^no-reply@/i,
      /^donotreply@/i,
      /^do-not-reply@/i,
      /^mailer-daemon@/i,
      /^postmaster@/i,
      /^notifications?@/i,
      /^alerts?@/i,
      /^auto@/i,
      /^automated@/i,
      /^system@/i,
      /^support@.*\.(zendesk|freshdesk|intercom|helpscout)/i,
      /^.*@.*\.notifications\./i,
    ],
    subjects: [
      /\[auto(-)?reply\]/i,
      /automatic reply/i,
      /out of (the )?office/i,
      /auto(-)?response/i,
      /delivery (status )?notification/i,
      /undeliverable/i,
      /read receipt/i,
      /return receipt/i,
    ],
  };

  // Newsletter patterns
  private readonly newsletterPatterns = {
    senders: [
      /@.*mail\.(mailchimp|constantcontact|sendgrid|mailgun|convertkit)/i,
      /@.*\.substack\.com$/i,
      /newsletter@/i,
      /digest@/i,
      /updates@/i,
      /marketing@/i,
      /promo(tions)?@/i,
    ],
    subjects: [
      /\bunsubscribe\b/i,
      /\bweekly digest\b/i,
      /\bdaily digest\b/i,
      /\bnewsletter\b/i,
      /\bmonthly update\b/i,
    ],
  };

  // Cold outreach patterns
  private readonly coldOutreachPatterns = {
    greetings: [
      /^dear (sir|madam|sir\/madam|hiring manager|recruiter)/i,
      /^to whom it may concern/i,
      /^hello there[,!]?\s*$/i,
      /^greetings[,!]?\s*$/i,
    ],
    mergeFields: [
      // Handlebars-style
      /\{\{.*?\}\}/g,
      // Double bracket style
      /\[\[.*?\]\]/g,
      // Percent-style
      /%[A-Z_]+%/g,
      // Template literal style
      /\$\{.*?\}/g,
      /\{FIRST_?NAME\}/i,
      /\{COMPANY\}/i,
      /\{NAME\}/i,
    ],
    phrases: [
      /\bquick question\b/i,
      /\bwanted to reach out\b/i,
      /\bhope this finds you well\b/i,
      /\bjust following up\b/i,
      /\bsaw your (profile|linkedin|company)/i,
      /\bI came across your/i,
      /\bwould love to connect\b/i,
      /\bschedule a (quick )?call\b/i,
      /\b15 (minute|min) (call|chat)\b/i,
    ],
  };

  constructor(
    @Inject(forwardRef(() => LLMService))
    private llmService: LLMService,
  ) {}

  /**
   * Classify an email to determine if auto-response should be sent
   * @param email Email content and metadata
   * @param headers Optional email headers for header-based detection
   * @param threadHasReplies Whether this thread already has replies from the user
   */
  async classifyEmail(
    email: {
      from: string;
      fromName?: string;
      subject: string;
      body: string;
      htmlBody?: string;
    },
    headers?: Record<string, string>,
    threadHasReplies?: boolean,
  ): Promise<EmailClassification> {
    const reasons: string[] = [];

    // First, check headers (fast, no LLM call needed)
    const headerClassification = this.classifyByHeaders(headers || {});

    if (headerClassification.isAutomated) {
      reasons.push("Automated email detected via headers");
    }
    if (headerClassification.isNewsletter) {
      reasons.push("Newsletter detected via headers (List-Unsubscribe)");
    }
    if (headerClassification.isBounce) {
      reasons.push("Bounce/delivery notification detected via headers");
    }
    if (headerClassification.isOutOfOffice) {
      reasons.push("Out-of-office reply detected via headers");
    }

    // Check by sender pattern
    const senderClassification = this.classifyBySender(email.from);
    if (senderClassification.isAutomated && !headerClassification.isAutomated) {
      reasons.push(`Automated sender pattern: ${email.from}`);
    }
    if (
      senderClassification.isNewsletter &&
      !headerClassification.isNewsletter
    ) {
      reasons.push(`Newsletter sender pattern: ${email.from}`);
    }

    // Check by subject pattern
    const subjectClassification = this.classifyBySubject(email.subject);
    if (subjectClassification.isAutomated) {
      reasons.push(`Automated subject pattern: ${email.subject}`);
    }
    if (subjectClassification.isOutOfOffice) {
      reasons.push(`Out-of-office subject pattern: ${email.subject}`);
    }

    // Combine header and pattern-based results
    const isAutomated =
      headerClassification.isAutomated ||
      senderClassification.isAutomated ||
      subjectClassification.isAutomated;
    const isNewsletter =
      headerClassification.isNewsletter || senderClassification.isNewsletter;
    const { isBounce } = headerClassification;
    const isOutOfOffice =
      headerClassification.isOutOfOffice || subjectClassification.isOutOfOffice;

    // If already classified as automated/newsletter/bounce, skip LLM
    if (isAutomated || isNewsletter || isBounce || isOutOfOffice) {
      return {
        isAutomated,
        isNewsletter,
        isColdOutreach: false,
        isReply: threadHasReplies || false,
        isOutOfOffice,
        isBounce,
        personalizationScore: 0,
        urgencyLevel: "low",
        reasons,
      };
    }

    // Check for obvious cold outreach patterns in content
    const coldOutreachScore = this.detectColdOutreachPatterns(email.body);
    if (coldOutreachScore > EMAIL_CLASSIFICATION.COLD_OUTREACH_HIGH) {
      reasons.push("Cold outreach patterns detected in content");
      return {
        isAutomated: false,
        isNewsletter: false,
        isColdOutreach: true,
        isReply: threadHasReplies || false,
        isOutOfOffice: false,
        isBounce: false,
        personalizationScore: 1 - coldOutreachScore,
        urgencyLevel: "low",
        reasons,
      };
    }

    // Use LLM for more nuanced classification
    try {
      const llmClassification = await this.classifyWithLLM(email);
      return {
        ...llmClassification,
        isReply: threadHasReplies || false,
        isBounce: false,
        isOutOfOffice: false,
        reasons: [...reasons, ...llmClassification.reasons],
      };
    } catch (error) {
      this.logger.error("LLM classification failed, using fallback", error);
      // Fallback to pattern-based classification
      return {
        isAutomated: false,
        isNewsletter: false,
        isColdOutreach:
          coldOutreachScore > EMAIL_CLASSIFICATION.COLD_OUTREACH_MEDIUM,
        isReply: threadHasReplies || false,
        isOutOfOffice: false,
        isBounce: false,
        personalizationScore: 1 - coldOutreachScore,
        urgencyLevel: this.detectUrgency(email.subject, email.body),
        reasons: [...reasons, "Fallback classification (LLM unavailable)"],
      };
    }
  }

  /**
   * Classify email by analyzing headers
   */
  private classifyByHeaders(headers: Record<string, string>): {
    isAutomated: boolean;
    isNewsletter: boolean;
    isBounce: boolean;
    isOutOfOffice: boolean;
  } {
    const normalizedHeaders: Record<string, string> = {};
    for (const [key, value] of Object.entries(headers)) {
      normalizedHeaders[key.toLowerCase()] = value;
    }

    // Check Auto-Submitted header (RFC 3834)
    const autoSubmitted = normalizedHeaders["auto-submitted"];
    const isAutoSubmitted = autoSubmitted && autoSubmitted !== "no";

    // Check X-Auto-Response-Suppress header
    const autoResponseSuppress = normalizedHeaders["x-auto-response-suppress"];
    const hasAutoResponseSuppress = !!autoResponseSuppress;

    // Check Precedence header
    const precedence = normalizedHeaders["precedence"];
    const isBulkPrecedence =
      precedence &&
      ["bulk", "junk", "list", "auto_reply"].includes(precedence.toLowerCase());

    // Check List-Unsubscribe header (newsletter indicator)
    const hasListUnsubscribe = !!normalizedHeaders["list-unsubscribe"];
    const hasListId = !!normalizedHeaders["list-id"];

    // Check for bounce indicators
    const contentType = normalizedHeaders["content-type"] || "";
    const isDeliveryStatus = contentType.includes("delivery-status");

    // Check for OOO
    const isOutOfOffice =
      autoSubmitted === "auto-replied" ||
      (autoResponseSuppress && autoResponseSuppress.includes("OOF"));

    return {
      isAutomated:
        !!isAutoSubmitted || hasAutoResponseSuppress || !!isBulkPrecedence,
      isNewsletter: hasListUnsubscribe || hasListId,
      isBounce: isDeliveryStatus,
      isOutOfOffice,
    };
  }

  /**
   * Classify by sender email pattern
   */
  private classifyBySender(from: string): {
    isAutomated: boolean;
    isNewsletter: boolean;
  } {
    const email = from.toLowerCase();

    const isAutomated = this.automatedPatterns.senders.some((pattern) =>
      pattern.test(email),
    );

    const isNewsletter = this.newsletterPatterns.senders.some((pattern) =>
      pattern.test(email),
    );

    return { isAutomated, isNewsletter };
  }

  /**
   * Classify by subject line pattern
   */
  private classifyBySubject(subject: string): {
    isAutomated: boolean;
    isOutOfOffice: boolean;
  } {
    const subjectLower = subject.toLowerCase();

    const isAutomated = this.automatedPatterns.subjects.some((pattern) =>
      pattern.test(subjectLower),
    );

    const isOutOfOffice =
      /out of (the )?office/i.test(subjectLower) ||
      /auto(-)?reply/i.test(subjectLower);

    return { isAutomated, isOutOfOffice };
  }

  /**
   * Detect cold outreach patterns in email body
   * Returns a score from 0 (definitely not cold outreach) to 1 (definitely cold outreach)
   */
  private detectColdOutreachPatterns(body: string): number {
    let score = 0;
    const maxScore = 5;
    const indicators: string[] = [];

    // Check for generic greetings
    for (const pattern of this.coldOutreachPatterns.greetings) {
      if (pattern.test(body)) {
        score += EMAIL_CLASSIFICATION.GENERIC_GREETING_SCORE;
        indicators.push("generic greeting");
        break;
      }
    }

    // Check for merge field artifacts
    for (const pattern of this.coldOutreachPatterns.mergeFields) {
      if (pattern.test(body)) {
        score += 2;
        indicators.push("merge field artifact");
        break;
      }
    }

    // Check for common cold outreach phrases
    let phraseMatches = 0;
    for (const pattern of this.coldOutreachPatterns.phrases) {
      if (pattern.test(body)) {
        phraseMatches++;
      }
    }
    if (phraseMatches >= 2) {
      score += EMAIL_CLASSIFICATION.GENERIC_GREETING_SCORE;
      indicators.push(`${phraseMatches} cold outreach phrases`);
    } else if (phraseMatches === 1) {
      score += EMAIL_CLASSIFICATION.SINGLE_PHRASE_SCORE;
    }

    this.logger.debug(
      `Cold outreach score: ${score}/${maxScore}, indicators: ${indicators.join(", ")}`,
    );

    return Math.min(score / maxScore, 1);
  }

  /**
   * Detect urgency level from subject and body
   */
  private detectUrgency(
    subject: string,
    body: string,
  ): "low" | "medium" | "high" {
    const text = `${subject} ${body}`.toLowerCase();

    const urgentPatterns = [
      /\burgent\b/,
      /\basap\b/,
      /\bimmediate(ly)?\b/,
      /\bcritical\b/,
      /\bemergency\b/,
      /\btime[- ]sensitive\b/,
      /\bdeadline (today|tomorrow|tonight)/,
      /\bneed(ed)? (by|before) (today|tomorrow|tonight|eod|cob)/i,
    ];

    const highUrgencyMatches = urgentPatterns.filter((p) =>
      p.test(text),
    ).length;

    if (highUrgencyMatches >= 2) return "high";
    if (highUrgencyMatches === 1) return "medium";

    // Default to medium for human emails
    return "medium";
  }

  /**
   * Use LLM to classify email content
   */
  private async classifyWithLLM(email: {
    from: string;
    fromName?: string;
    subject: string;
    body: string;
  }): Promise<EmailClassification> {
    const promptConfig = getPrompt("classify_email_type");
    if (!promptConfig) {
      this.logger.warn(
        "classify_email_type prompt not found, using fallback classification",
      );
      return this.getFallbackClassification();
    }

    // Clean and truncate body for LLM
    const cleanedBody = cleanEmailContent(email.body, null, 1000);

    const prompt = renderPrompt(promptConfig.prompt || "", {
      from: email.from,
      fromName: email.fromName || email.from,
      subject: email.subject,
      body: cleanedBody,
    });

    const response = await this.llmService.generateText(
      {
        prompt,
        systemPrompt: promptConfig.systemPrompt || "",
        temperature: RATIOS.THIRTY_PERCENT,
        maxTokens: LLM_CONFIG.CLASSIFICATION_MAX_TOKENS,
      },
      LLMProvider.OPENAI,
      undefined,
      LLM_OP_CLASSIFY_EMAIL as any,
    );

    try {
      // Parse JSON response
      let jsonString = response;
      jsonString = jsonString
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

      const jsonMatch = jsonString.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        return {
          isAutomated: parsed.isAutomated || false,
          isNewsletter: parsed.isNewsletter || false,
          isColdOutreach: parsed.isColdOutreach || false,
          isReply: false,
          isOutOfOffice: parsed.isOutOfOffice || false,
          isBounce: false,
          personalizationScore:
            parsed.personalizationScore ||
            EMAIL_CLASSIFICATION.DEFAULT_PERSONALIZATION,
          urgencyLevel: parsed.urgencyLevel || "medium",
          reasons: parsed.reasons || [],
        };
      }
    } catch (error) {
      this.logger.warn("Failed to parse LLM classification response", error);
    }

    return this.getFallbackClassification();
  }

  /**
   * Get fallback classification when LLM fails
   */
  private getFallbackClassification(): EmailClassification {
    return {
      isAutomated: false,
      isNewsletter: false,
      isColdOutreach: false,
      isReply: false,
      isOutOfOffice: false,
      isBounce: false,
      personalizationScore: 0.5,
      urgencyLevel: "medium",
      reasons: ["Fallback classification"],
    };
  }

  /**
   * Check if email headers indicate this is a reply
   */
  isReplyByHeaders(headers: Record<string, string>): boolean {
    const normalizedHeaders: Record<string, string> = {};
    for (const [key, value] of Object.entries(headers)) {
      normalizedHeaders[key.toLowerCase()] = value;
    }

    return (
      !!normalizedHeaders["in-reply-to"] || !!normalizedHeaders["references"]
    );
  }

  /**
   * Check if an email matches any custom exclusion rules using AI
   * @param email Email content and metadata
   * @param customRules Array of custom exclusion rule descriptions
   * @returns The matched rule description if any, or null if no rules match
   */
  async checkCustomExclusionRules(
    email: {
      from: string;
      fromName?: string;
      subject: string;
      body: string;
    },
    customRules: string[],
  ): Promise<{ matched: boolean; matchedRule: string | null; reason: string }> {
    if (!customRules || customRules.length === 0) {
      return {
        matched: false,
        matchedRule: null,
        reason: "No custom rules defined",
      };
    }

    try {
      const cleanedBody = cleanEmailContent(email.body, null, 1000);

      const rulesText = customRules
        .map((rule, index) => `${index + 1}. ${rule}`)
        .join("\n");

      const prompt = `You are an email classification assistant. Analyze the following email and determine if it matches ANY of the user's custom exclusion rules.

CUSTOM EXCLUSION RULES:
${rulesText}

EMAIL TO ANALYZE:
From: ${email.fromName || email.from} <${email.from}>
Subject: ${email.subject}
Body:
${cleanedBody}

INSTRUCTIONS:
- Carefully read each exclusion rule and the email content
- Determine if the email matches ANY of the rules
- Be reasonably flexible in interpretation (e.g., "Automated emails" should match system notifications, auto-replies, etc.)
- If the email matches a rule, explain why

Respond with a JSON object in this exact format:
{
  "matched": true/false,
  "matchedRule": "the exact rule text that matched" or null if no match,
  "reason": "brief explanation of why it matched or didn't match"
}`;

      const response = await this.llmService.generateText(
        {
          prompt,
          systemPrompt:
            "You are an email classification assistant. Analyze emails against user-defined exclusion rules and provide structured results.",
          temperature: RATIOS.THIRTY_PERCENT,
          maxTokens: LLM_CONFIG.CUSTOM_RULES_MAX_TOKENS,
        },
        LLMProvider.OPENAI,
        undefined,
        "check_custom_exclusion_rules" as any,
      );

      // Parse JSON response
      let jsonString = response;
      jsonString = jsonString
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

      const jsonMatch = jsonString.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        return {
          matched: parsed.matched || false,
          matchedRule: parsed.matchedRule || null,
          reason: parsed.reason || "No reason provided",
        };
      }

      this.logger.warn("Failed to parse custom exclusion rules response");
      return {
        matched: false,
        matchedRule: null,
        reason: "Failed to parse LLM response",
      };
    } catch (error) {
      this.logger.error("Error checking custom exclusion rules", error);
      return {
        matched: false,
        matchedRule: null,
        reason: `Error: ${(error as Error).message}`,
      };
    }
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, MoreThan } from "typeorm";
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { AutoResponseLog } from "../database/entities/auto-response-log.entity";
import { QueueStats, CategoryReplyTime } from "./types/auto-responder.types";
import { DISPLAY_LIMITS, STATS_CONFIG } from "./auto-responder-constants";
import { LEARNING_THRESHOLDS } from "../constants/service-constants";
import { RATIOS } from "../constants/percentages";
import { DAYS } from "../constants/time-constants";

// Default response times when no data is available (calculated from typical patterns)
const DEFAULT_RESPONSE_TIMES = {
  // Default when no reply data exists at all
  NO_DATA: "a few days",
  // Default for urgent emails when no data
  URGENT_NO_DATA: "12-24 hours",
} as const;

@Injectable()
export class QueueStatsService {
  private readonly logger = new Logger(QueueStatsService.name);

  constructor(
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(AutoResponseLog)
    private autoResponseLogRepository: Repository<AutoResponseLog>,
  ) {}

  /**
   * Calculate current queue statistics for a user
   */
  async getQueueStats(userId: string): Promise<QueueStats> {
    try {
      // Count emails flagged for action (starred, not archived)
      const actionCount = await this.emailThreadRepository.count({
        where: {
          userId,
          starCount: MoreThan(0),
          isArchived: false,
        },
      });

      // Count emails pending triage (not starred, not archived)
      const triageCount = await this.emailThreadRepository.count({
        where: {
          userId,
          starCount: 0,
          isArchived: false,
        },
      });

      // Calculate average response time from recent emails
      const avgResponseTime = await this.calculateAverageResponseTime(userId);
      const urgentResponseTime = await this.calculateUrgentResponseTime(userId);

      // Get category-specific reply times for more accurate auto-response messaging
      const categoryReplyTimes = await this.calculateCategoryReplyTimes(userId);

      return {
        actionCount: this.formatCount(actionCount),
        triageCount: this.formatCount(triageCount),
        avgResponseTime,
        urgentResponseTime,
        categoryReplyTimes,
      };
    } catch (error) {
      this.logger.error(`Failed to get queue stats for user ${userId}`, error);
      return {
        actionCount: 0,
        triageCount: 0,
        avgResponseTime: DEFAULT_RESPONSE_TIMES.NO_DATA,
        urgentResponseTime: DEFAULT_RESPONSE_TIMES.URGENT_NO_DATA,
      };
    }
  }

  /**
   * Format count for display (cap at 100+)
   */
  private formatCount(count: number): number {
    // Return actual count, the template can format as needed
    return count;
  }

  /**
   * Calculate average response time for medium priority emails
   */
  private async calculateAverageResponseTime(userId: string): Promise<string> {
    try {
      // Get emails with timeToReply in the last N days
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(
        thirtyDaysAgo.getDate() - STATS_CONFIG.LOOKBACK_DAYS,
      );

      const emailsWithReply = await this.emailRepository
        .createQueryBuilder("email")
        .select("AVG(email.timeToReply)", "avgReplyTime")
        .where("email.userId = :userId", { userId })
        .andWhere("email.timeToReply IS NOT NULL")
        .andWhere("email.timeToReply > 0")
        .andWhere("email.receivedAt > :thirtyDaysAgo", { thirtyDaysAgo })
        .getRawOne();

      if (emailsWithReply?.avgReplyTime) {
        const avgMinutes = parseFloat(emailsWithReply.avgReplyTime);
        return this.formatResponseTime(avgMinutes);
      }

      return DEFAULT_RESPONSE_TIMES.NO_DATA;
    } catch (error) {
      this.logger.warn("Failed to calculate average response time", error);
      return DEFAULT_RESPONSE_TIMES.NO_DATA;
    }
  }

  /**
   * Calculate response time for high priority/urgent emails
   */
  private async calculateUrgentResponseTime(userId: string): Promise<string> {
    try {
      // Get starred (high priority) emails with timeToReply
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(
        thirtyDaysAgo.getDate() - STATS_CONFIG.LOOKBACK_DAYS,
      );

      const urgentEmails = await this.emailRepository
        .createQueryBuilder("email")
        .innerJoin("email.thread", "thread")
        .select("AVG(email.timeToReply)", "avgReplyTime")
        .where("email.userId = :userId", { userId })
        .andWhere("email.timeToReply IS NOT NULL")
        .andWhere("email.timeToReply > 0")
        .andWhere("thread.starCount >= 2") // High priority
        .andWhere("email.receivedAt > :thirtyDaysAgo", { thirtyDaysAgo })
        .getRawOne();

      if (urgentEmails?.avgReplyTime) {
        const avgMinutes = parseFloat(urgentEmails.avgReplyTime);
        return this.formatResponseTime(avgMinutes);
      }

      return DEFAULT_RESPONSE_TIMES.URGENT_NO_DATA;
    } catch (error) {
      this.logger.warn("Failed to calculate urgent response time", error);
      return DEFAULT_RESPONSE_TIMES.URGENT_NO_DATA;
    }
  }

  /**
   * Calculate reply times broken down by email category
   * Used for more accurate auto-response messaging based on the email's category
   */
  private async calculateCategoryReplyTimes(
    userId: string,
  ): Promise<CategoryReplyTime[]> {
    try {
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(
        thirtyDaysAgo.getDate() - STATS_CONFIG.LOOKBACK_DAYS,
      );

      const categoryStats = await this.emailRepository
        .createQueryBuilder("email")
        .innerJoin("email.thread", "thread")
        .select("thread.category", "category")
        .addSelect("AVG(email.timeToReply)", "avgReplyTimeMinutes")
        .addSelect("COUNT(email.id)", "repliedCount")
        .where("email.userId = :userId", { userId })
        .andWhere("email.timeToReply IS NOT NULL")
        .andWhere("email.timeToReply > 0")
        .andWhere("email.receivedAt > :thirtyDaysAgo", { thirtyDaysAgo })
        .groupBy("thread.category")
        .getRawMany();

      return categoryStats.map((stat) => ({
        category: stat.category || "Other",
        avgReplyTimeMinutes: parseFloat(stat.avgReplyTimeMinutes),
        repliedCount: parseInt(stat.repliedCount, 10),
      }));
    } catch (error) {
      this.logger.warn("Failed to calculate category reply times", error);
      return [];
    }
  }

  /**
   * Get formatted response time for a specific category
   * Falls back to overall average if category-specific data is not available
   */
  getResponseTimeForCategory(
    stats: QueueStats,
    category: string | null,
  ): string {
    if (!category || !stats.categoryReplyTimes?.length) {
      return stats.avgResponseTime;
    }

    const categoryData = stats.categoryReplyTimes.find(
      (c) => c.category.toLowerCase() === category.toLowerCase(),
    );

    if (
      categoryData &&
      categoryData.repliedCount >= LEARNING_THRESHOLDS.MIN_CATEGORY_DATA_POINTS
    ) {
      // Only use category-specific time if we have at least MIN_CATEGORY_DATA_POINTS data points
      return this.formatResponseTime(categoryData.avgReplyTimeMinutes);
    }

    return stats.avgResponseTime;
  }

  /**
   * Format response time in human-readable format
   */
  private formatResponseTime(minutes: number): string {
    if (minutes < 60) {
      return `~${Math.round(minutes)} minutes`;
    }

    const hours = minutes / 60;
    if (hours < 24) {
      if (hours < 2) {
        return "~1 hour";
      }
      return `~${Math.round(hours)} hours`;
    }

    const days = hours / 24;
    if (days < RATIOS.ONE_POINT_FIVE) {
      return "~1 day";
    }
    if (days < DAYS.WEEK) {
      return `~${Math.round(days)} days`;
    }

    const weeks = days / DAYS.WEEK;
    if (weeks < RATIOS.ONE_POINT_FIVE) {
      return "~1 week";
    }
    return `~${Math.round(weeks)} weeks`;
  }

  /**
   * Get formatted display string for queue stats
   */
  formatStatsForDisplay(stats: QueueStats): string {
    const actionText =
      stats.actionCount > DISPLAY_LIMITS.MAX_DISPLAY_COUNT
        ? `${DISPLAY_LIMITS.MAX_DISPLAY_COUNT}+ emails flagged for action`
        : `${stats.actionCount} emails flagged for action`;
    const triageText =
      stats.triageCount > DISPLAY_LIMITS.MAX_DISPLAY_COUNT
        ? `${DISPLAY_LIMITS.MAX_DISPLAY_COUNT}+ emails still to triage`
        : `${stats.triageCount} emails still to triage`;

    return `📬 ${actionText}\n📋 ${triageText}\n⏱️ Average response time: ${stats.avgResponseTime}`;
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import {
  CloudWatchClient,
  PutMetricDataCommand,
  StandardUnit,
} from "@aws-sdk/client-cloudwatch";
import { QUERY_LIMITS } from "../constants/query-limits";

@Injectable()
export class CloudWatchService {
  private readonly logger = new Logger(CloudWatchService.name);
  private readonly client: CloudWatchClient | null;
  private readonly namespace: string;
  private readonly enabled: boolean;

  constructor(private configService: ConfigService) {
    this.enabled =
      this.configService.get<string>("AUTOSCALING_ENABLED") !== "false";
    this.namespace =
      this.configService.get<string>("CLOUDWATCH_METRIC_NAMESPACE") ||
      "BearlyMail/Queue";

    // Check if we're in local development
    const nodeEnv = this.configService.get<string>("NODE_ENV");
    const dbHost = this.configService.get<string>("DB_HOST");
    const isLocalDev =
      nodeEnv === "development" ||
      dbHost === "localhost" ||
      dbHost === "127.0.0.1";

    if (this.enabled && !isLocalDev) {
      const region =
        this.configService.get<string>("AWS_REGION") || "us-east-1";
      this.client = new CloudWatchClient({ region });
      this.logger.log(
        `CloudWatch service initialized (namespace: ${this.namespace}, region: ${region})`,
      );
    } else {
      this.client = null;
      if (isLocalDev) {
        this.logger.log("CloudWatch service disabled (local development mode)");
      } else {
        this.logger.log(
          "CloudWatch service disabled (AUTOSCALING_ENABLED=false)",
        );
      }
    }
  }

  /**
   * Publish a custom metric to CloudWatch
   */
  async putMetric(
    metricName: string,
    value: number,
    unit: StandardUnit = StandardUnit.None,
  ): Promise<void> {
    if (!this.enabled || !this.client) {
      return;
    }

    try {
      const command = new PutMetricDataCommand({
        Namespace: this.namespace,
        MetricData: [
          {
            MetricName: metricName,
            Value: value,
            Unit: unit,
            Timestamp: new Date(),
          },
        ],
      });

      await this.client.send(command);
      this.logger.debug(
        `Published metric ${metricName}=${value} to CloudWatch`,
      );
    } catch (error) {
      this.logger.error(
        `Failed to publish metric ${metricName} to CloudWatch:`,
        error,
      );
      // Don't throw - autoscaling should continue even if metrics fail
    }
  }

  /**
   * Publish multiple metrics in a single call
   */
  async putMetrics(
    metrics: Array<{ name: string; value: number; unit?: StandardUnit }>,
  ): Promise<void> {
    if (!this.enabled || !this.client) {
      return;
    }

    try {
      const command = new PutMetricDataCommand({
        Namespace: this.namespace,
        MetricData: metrics.map((metric) => ({
          MetricName: metric.name,
          Value: metric.value,
          Unit: metric.unit || StandardUnit.None,
          Timestamp: new Date(),
        })),
      });

      await this.client.send(command);
      this.logger.debug(`Published ${metrics.length} metrics to CloudWatch`);
    } catch (error) {
      this.logger.error("Failed to publish metrics to CloudWatch:", error);
      // Don't throw - autoscaling should continue even if metrics fail
    }
  }

  /**
   * Publish a performance budget exceeded metric with dimensions to identify which budget was exceeded
   */
  async putPerformanceBudgetMetric(params: {
    budgetName: string;
    budgetType: "job" | "operation" | "batch";
    durationMs: number;
    budgetMs: number;
    exceeded: boolean;
    metadata?: Record<string, string>;
  }): Promise<void> {
    if (!this.enabled || !this.client) {
      return;
    }

    const { budgetName, budgetType, durationMs, budgetMs, exceeded, metadata } =
      params;

    try {
      const dimensions = [
        { Name: "BudgetName", Value: budgetName },
        { Name: "BudgetType", Value: budgetType },
      ];

      // Add any additional metadata as dimensions (limited to 30 dimensions per metric)
      if (metadata) {
        Object.entries(metadata)
          .slice(0, QUERY_LIMITS.CLOUDWATCH_MAX_DIMENSIONS) // Leave room for the required dimensions
          .forEach(([key, value]) => {
            if (value) {
              dimensions.push({ Name: key, Value: value });
            }
          });
      }

      const metricData = [
        // Count of budget exceeded occurrences (1 if exceeded, 0 if not)
        {
          MetricName: "PerformanceBudgetExceeded",
          Value: exceeded ? 1 : 0,
          Unit: StandardUnit.Count,
          Timestamp: new Date(),
          Dimensions: dimensions,
        },
        // Duration of the operation in milliseconds
        {
          MetricName: "PerformanceBudgetDuration",
          Value: durationMs,
          Unit: StandardUnit.Milliseconds,
          Timestamp: new Date(),
          Dimensions: dimensions,
        },
        // How much over/under budget (positive = over, negative = under)
        {
          MetricName: "PerformanceBudgetOverage",
          Value: durationMs - budgetMs,
          Unit: StandardUnit.Milliseconds,
          Timestamp: new Date(),
          Dimensions: dimensions,
        },
      ];

      const command = new PutMetricDataCommand({
        Namespace: this.namespace,
        MetricData: metricData,
      });

      await this.client.send(command);

      if (exceeded) {
        this.logger.debug(
          `Published performance budget exceeded: ${budgetName} (${budgetType}) ${durationMs}ms > ${budgetMs}ms`,
        );
      }
    } catch (error) {
      this.logger.error(
        `Failed to publish performance budget metric for ${budgetName}:`,
        error,
      );
      // Don't throw - metrics should not impact main functionality
    }
  }
}

import { Test, TestingModule } from "@nestjs/testing";
import { getRepositoryToken } from "@nestjs/typeorm";
import { BatchScheduleService } from "./batch-schedule.service";
import { BatchSchedule } from "../database/entities/batch-schedule.entity";

describe("BatchScheduleService", () => {
  let service: BatchScheduleService;

  const mockRepository = {
    findOne: jest.fn(),
    create: jest.fn(),
    save: jest.fn(),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        BatchScheduleService,
        {
          provide: getRepositoryToken(BatchSchedule),
          useValue: mockRepository,
        },
      ],
    }).compile();

    service = module.get<BatchScheduleService>(BatchScheduleService);
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe("getSchedule", () => {
    it("should return schedule for user", async () => {
      const userId = "user-123";
      const mockSchedule = {
        id: "schedule-1",
        userId,
        deliveryDays: [1, 2, 3],
        deliveryTimes: ["09:00", "17:00"],
        timezone: "UTC",
        isEnabled: true,
      };

      mockRepository.findOne.mockResolvedValue(mockSchedule);

      const result = await service.getSchedule(userId);

      expect(result).toEqual(mockSchedule);
      expect(mockRepository.findOne).toHaveBeenCalledWith({
        where: { userId },
      });
    });

    it("should return null when schedule not found", async () => {
      const userId = "user-123";

      mockRepository.findOne.mockResolvedValue(null);

      const result = await service.getSchedule(userId);

      expect(result).toBeNull();
    });
  });

  describe("upsertSchedule", () => {
    it("should create new schedule when none exists", async () => {
      const userId = "user-123";
      const scheduleData = {
        deliveryDays: [1, 2, 3],
        deliveryTimes: ["09:00", "17:00"],
        timezone: "America/New_York",
        isEnabled: true,
        urgentBypassSchedule: false,
      };
      const mockSchedule = {
        id: "schedule-1",
        userId,
        ...scheduleData,
      };

      mockRepository.findOne.mockResolvedValue(null);
      mockRepository.create.mockReturnValue(mockSchedule);
      mockRepository.save.mockResolvedValue(mockSchedule);

      const result = await service.upsertSchedule(userId, scheduleData);

      expect(result).toEqual(mockSchedule);
      expect(mockRepository.create).toHaveBeenCalledWith({
        userId,
        ...scheduleData,
      });
      expect(mockRepository.save).toHaveBeenCalledWith(mockSchedule);
    });

    it("should update existing schedule", async () => {
      const userId = "user-123";
      const existingSchedule = {
        id: "schedule-1",
        userId,
        deliveryDays: [1, 2],
        deliveryTimes: ["09:00"],
        timezone: "UTC",
        isEnabled: true,
        urgentBypassSchedule: false,
      };
      const scheduleData = {
        deliveryDays: [1, 2, 3, 4, 5],
        deliveryTimes: ["09:00", "17:00"],
        timezone: "America/New_York",
        isEnabled: true,
        urgentBypassSchedule: true,
      };

      mockRepository.findOne.mockResolvedValue(existingSchedule);
      mockRepository.save.mockResolvedValue({
        ...existingSchedule,
        ...scheduleData,
      });

      const result = await service.upsertSchedule(userId, scheduleData);

      expect(result.deliveryDays).toEqual(scheduleData.deliveryDays);
      expect(result.deliveryTimes).toEqual(scheduleData.deliveryTimes);
      expect(result.timezone).toBe(scheduleData.timezone);
      expect(result.urgentBypassSchedule).toBe(
        scheduleData.urgentBypassSchedule,
      );
      expect(mockRepository.create).not.toHaveBeenCalled();
    });
  });

  describe("getNextBatchReleaseTime", () => {
    it("should return null when batching is disabled", () => {
      const schedule = {
        isEnabled: false,
        deliveryDays: [1, 2, 3],
        deliveryTimes: ["09:00"],
        timezone: "UTC",
      } as BatchSchedule;

      const result = service.getNextBatchReleaseTime(schedule, 0);

      expect(result).toBeNull();
    });

    it("should return null when priorityScore >= 75 and urgentBypassSchedule is enabled", () => {
      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3],
        deliveryTimes: ["09:00"],
        timezone: "UTC",
        urgentBypassSchedule: true,
      } as BatchSchedule;

      // Priority score 75 (>= 75) should bypass
      const result = service.getNextBatchReleaseTime(schedule, 75);

      expect(result).toBeNull();
    });

    it("should NOT bypass when priorityScore < 75 even with urgentBypassSchedule enabled", () => {
      jest.useFakeTimers();
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z")); // Monday 8am UTC

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"],
        timezone: "UTC",
        urgentBypassSchedule: true,
      } as BatchSchedule;

      // Priority score 74 (not >= 75) should NOT bypass
      const result = service.getNextBatchReleaseTime(schedule, 74);

      // Should return next scheduled time, not null
      expect(result).not.toBeNull();

      jest.useRealTimers();
    });

    it("should return null when no delivery days configured", () => {
      const schedule = {
        isEnabled: true,
        deliveryDays: [],
        deliveryTimes: ["09:00"],
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextBatchReleaseTime(schedule, 0);

      expect(result).toBeNull();
    });
  });

  describe("isWithinDeliveryWindow", () => {
    it("should return true when batching is disabled", () => {
      const schedule = {
        isEnabled: false,
        deliveryDays: [1, 2, 3],
        deliveryTimes: ["09:00"],
        timezone: "UTC",
      } as BatchSchedule;

      const result = service.isWithinDeliveryWindow(schedule);

      expect(result).toBe(true);
    });

    it("should return false when not a delivery day", () => {
      jest.useFakeTimers();
      jest.setSystemTime(new Date("2024-01-07T10:00:00Z")); // Sunday (0)

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00"],
        timezone: "UTC",
      } as BatchSchedule;

      const result = service.isWithinDeliveryWindow(schedule);

      expect(result).toBe(false);

      jest.useRealTimers();
    });
  });

  describe("getDefaultSchedule", () => {
    it("should return default schedule configuration", () => {
      const result = service.getDefaultSchedule();

      expect(result.deliveryDays).toEqual([1, 2, 3, 4, 5]);
      expect(result.deliveryTimes).toEqual(["11:00", "15:00"]);
      expect(result.timezone).toBe("UTC");
      expect(result.isEnabled).toBe(true);
      expect(result.urgentBypassSchedule).toBe(true);
    });
  });

  describe("getNextScheduledDeliveryTime - timezone conversion", () => {
    afterEach(() => {
      jest.useRealTimers();
    });

    it("should calculate next delivery time correctly in UTC", () => {
      jest.useFakeTimers();
      // Monday 8am UTC
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"],
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 9am UTC
      expect(result?.toISOString()).toBe("2024-01-08T09:00:00.000Z");
    });

    it("should calculate next delivery time correctly in America/New_York", () => {
      jest.useFakeTimers();
      // Monday 8am UTC = Monday 3am EST (UTC-5)
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm EST
        timezone: "America/New_York",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 9am EST = 2pm UTC
      expect(result?.toISOString()).toBe("2024-01-08T14:00:00.000Z");
    });

    it("should calculate next delivery time correctly in Europe/London", () => {
      jest.useFakeTimers();
      // Monday 8am UTC = Monday 8am GMT (no offset in winter)
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["11:00", "15:00"], // 11am and 3pm GMT
        timezone: "Europe/London",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 11am GMT = 11am UTC (winter time)
      expect(result?.toISOString()).toBe("2024-01-08T11:00:00.000Z");
    });

    it("should calculate next delivery time correctly in Asia/Tokyo", () => {
      jest.useFakeTimers();
      // Monday 8am UTC = Monday 5pm JST (UTC+9)
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm JST
        timezone: "Asia/Tokyo",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Current time is Monday 5pm JST, so next delivery is Tuesday 9am JST
      // Tuesday 9am JST = Tuesday 0am UTC
      expect(result?.toISOString()).toBe("2024-01-09T00:00:00.000Z");
    });

    it("should handle DST transition correctly (spring forward)", () => {
      jest.useFakeTimers();
      // March 10, 2024 is when DST starts in America/New_York (2am → 3am)
      // Set time to Sunday 1am UTC = Saturday 8pm EST
      jest.setSystemTime(new Date("2024-03-10T01:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [0, 1, 2, 3, 4, 5, 6], // All days
        deliveryTimes: ["09:00"], // 9am EST/EDT
        timezone: "America/New_York",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Sunday 9am EDT = 1pm UTC (EDT is UTC-4)
      // The DST transition happens at 2am Sunday, so 9am Sunday is in EDT
      expect(result?.getUTCHours()).toBe(13);
      expect(result?.getUTCDate()).toBe(10);
    });

    it("should handle DST transition correctly (fall back)", () => {
      jest.useFakeTimers();
      // November 3, 2024 is when DST ends in America/New_York (2am → 1am)
      // Set time to Sunday 1am UTC = Saturday 9pm EDT
      jest.setSystemTime(new Date("2024-11-03T01:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [0, 1, 2, 3, 4, 5, 6], // All days
        deliveryTimes: ["09:00"], // 9am EDT/EST
        timezone: "America/New_York",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Sunday 9am EST = 2pm UTC (EST is UTC-5)
      // After DST ends at 2am Sunday, 9am is in EST
      expect(result?.getUTCHours()).toBe(14);
      expect(result?.getUTCDate()).toBe(3);
    });

    it("should skip to next delivery time on same day if current time passed", () => {
      jest.useFakeTimers();
      // Monday 10am UTC
      jest.setSystemTime(new Date("2024-01-08T10:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm UTC
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 3pm UTC (skipped 9am)
      expect(result?.toISOString()).toBe("2024-01-08T15:00:00.000Z");
    });

    it("should move to next delivery day when all times passed today", () => {
      jest.useFakeTimers();
      // Monday 4pm UTC (after both delivery times)
      jest.setSystemTime(new Date("2024-01-08T16:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm UTC
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Tuesday at 9am UTC
      expect(result?.toISOString()).toBe("2024-01-09T09:00:00.000Z");
    });

    it("should skip to next delivery day when today is not a delivery day", () => {
      jest.useFakeTimers();
      // Sunday 10am UTC
      jest.setSystemTime(new Date("2024-01-07T10:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday (no Sunday)
        deliveryTimes: ["09:00", "15:00"],
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 9am UTC
      expect(result?.toISOString()).toBe("2024-01-08T09:00:00.000Z");
    });

    it("should handle timezone where current date differs from UTC", () => {
      jest.useFakeTimers();
      // Monday 11pm UTC = Tuesday 8am JST (UTC+9)
      jest.setSystemTime(new Date("2024-01-08T23:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5], // Monday-Friday
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm JST
        timezone: "Asia/Tokyo",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Current time is Tuesday 8am JST, next is Tuesday 9am JST
      // Tuesday 9am JST = Tuesday 0am UTC
      expect(result?.toISOString()).toBe("2024-01-09T00:00:00.000Z");
    });

    it("should return null when no delivery days configured", () => {
      jest.useFakeTimers();
      jest.setSystemTime(new Date("2024-01-08T10:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [], // No delivery days
        deliveryTimes: ["09:00", "15:00"],
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).toBeNull();
    });

    it("should return null when no delivery times configured", () => {
      jest.useFakeTimers();
      jest.setSystemTime(new Date("2024-01-08T10:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5],
        deliveryTimes: [], // No delivery times
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).toBeNull();
    });

    it("should sort delivery times and use earliest available", () => {
      jest.useFakeTimers();
      // Monday 8am UTC
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5],
        deliveryTimes: ["15:00", "09:00", "12:00"], // Unsorted
        timezone: "UTC",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should use earliest time (09:00), not the first in the array
      expect(result?.toISOString()).toBe("2024-01-08T09:00:00.000Z");
    });

    it("should handle negative UTC offsets correctly", () => {
      jest.useFakeTimers();
      // Monday 8am UTC = Monday 1am MST (UTC-7)
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5],
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm MST
        timezone: "America/Denver",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Should be Monday at 9am MST = 4pm UTC
      expect(result?.toISOString()).toBe("2024-01-08T16:00:00.000Z");
    });

    it("should handle positive UTC offsets correctly", () => {
      jest.useFakeTimers();
      // Monday 8am UTC = Monday 7pm AEDT (UTC+11 during DST)
      jest.setSystemTime(new Date("2024-01-08T08:00:00Z"));

      const schedule = {
        isEnabled: true,
        deliveryDays: [1, 2, 3, 4, 5],
        deliveryTimes: ["09:00", "15:00"], // 9am and 3pm AEDT
        timezone: "Australia/Sydney",
        urgentBypassSchedule: false,
      } as BatchSchedule;

      const result = service.getNextScheduledDeliveryTime(schedule);

      expect(result).not.toBeNull();
      // Current time is Monday 7pm AEDT, next delivery is Tuesday 9am AEDT
      // Tuesday 9am AEDT = Monday 10pm UTC
      expect(result?.toISOString()).toBe("2024-01-08T22:00:00.000Z");
    });
  });
});

