const ICAL_HOUR_START = 9;
const ICAL_HOUR_END = 11;
const ICAL_MINUTE_START = 11;
const ICAL_MINUTE_END = 13;
const ICAL_DATE_WITH_HOURS_LENGTH = 10;

export interface TimeSlot {
  start: string;
  end: string;
  duration: number;
}

export interface TimeSlotsWithTimezone {
  slots: TimeSlot[];
  timezone: string;
}

interface BusyPeriod {
  start: string;
  end: string;
}

@Injectable()
export class CalendarService {
  private oauth2Client: OAuth2Client;

  constructor(
    private usersService: UsersService,
    private llmService: LLMService,
    private emailsService: EmailsService,
    private schedulingPreferencesService: SchedulingPreferencesService,
  ) {
    this.oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI ||
        "http://localhost:3001/auth/google/callback",
    );
  }

  async getAvailableTimeSlots(
    userId: string,
    daysAhead: number = 7,
    prefsOverride?: SchedulingPreferenceData,
  ): Promise<TimeSlot[]> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      throw new Error("Google Calendar not connected");
    }

    this.oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const calendar = google.calendar({
      version: "v3",
      auth: this.oauth2Client,
    });
    const now = new Date();
    const endDate = new Date(now.getTime() + daysAhead * 24 * 60 * 60 * 1000);

    try {
      const response = await calendar.freebusy.query({
        requestBody: {
          timeMin: now.toISOString(),
          timeMax: endDate.toISOString(),
          items: [{ id: "primary" }],
        },
      });

      // Find free slots (simplified - in production, you'd calculate gaps between busy periods)
      const busy = (response.data.calendars?.primary?.busy || []).filter(
        (period): period is BusyPeriod =>
          period.start !== undefined && period.end !== undefined,
      ) as BusyPeriod[];
      const prefs =
        prefsOverride ||
        (await this.schedulingPreferencesService.getPreferences(userId));
      const freeSlots = this.calculateFreeSlots(now, endDate, busy, prefs);

      return freeSlots;
    } catch (error) {
      console.error("Error fetching calendar:", error);
      throw new Error("Failed to fetch calendar data");
    }
  }

  async getAvailableSlotsWithTimezone(
    userId: string,
    daysAhead: number = 7,
  ): Promise<TimeSlotsWithTimezone> {
    const prefs =
      await this.schedulingPreferencesService.getPreferences(userId);
    const slots = await this.getAvailableTimeSlots(userId, daysAhead, prefs);
    return {
      slots,
      timezone: prefs.timezone || "UTC",
    };
  }

  private toTzDate(date: Date, tz: string): Date {
    const dateString = date.toLocaleString("en-US", { timeZone: tz });
    return new Date(dateString);
  }

  private toDayKey(date: Date, tz: string): string {
    const tzDate = this.toTzDate(date, tz);
    const year = tzDate.getFullYear();
    const month = String(tzDate.getMonth() + 1).padStart(2, "0");
    const day = String(tzDate.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  private alignToSlotBoundary(date: Date, slotDurationMinutes: number): Date {
    const aligned = new Date(date);
    const minutes = aligned.getMinutes();
    const remainder = minutes % slotDurationMinutes;
    if (remainder !== 0) {
      aligned.setMinutes(minutes + (slotDurationMinutes - remainder));
      aligned.setSeconds(0, 0);
    } else {
      aligned.setSeconds(0, 0);
    }
    return aligned;
  }

  private calculateFreeSlots(
    start: Date,
    end: Date,
    busy: BusyPeriod[],
    prefs?: SchedulingPreferenceData,
  ): TimeSlot[] {
    const slots: TimeSlot[] = [];
    const slotDuration = prefs?.slotDurationMinutes || MINUTES.THIRTY;
    const startHour = prefs?.availabilityStartHour ?? HOURS.NINE;
    const endHour = prefs?.availabilityEndHour ?? HOURS.SEVENTEEN;
    const availDays = prefs?.availabilityDays ?? [1, 2, 3, 4, 5];
    const gapMinutes = prefs?.meetingGapMinutes ?? MINUTES.THIRTY;
    const deepWorkHours = prefs?.deepWorkHoursPerDay ?? 2;
    const tz = prefs?.timezone || "UTC";
    let current = this.alignToSlotBoundary(start, slotDuration);

    const meetingMinutesPerDay = new Map<string, number>();

    while (current < end) {
      const slotEnd = new Date(current.getTime() + slotDuration * 60 * 1000);
      const tzDate = this.toTzDate(current, tz);
      const dayKey = this.toDayKey(current, tz);
      const dayOfWeek = tzDate.getDay();
      const hourInTz = tzDate.getHours();

      if (!availDays.includes(dayOfWeek)) {
        current = new Date(current.getTime() + slotDuration * 60 * 1000);
        continue;
      }

      if (hourInTz < startHour || hourInTz >= endHour) {
        current = new Date(current.getTime() + slotDuration * 60 * 1000);
        continue;
      }

      const isBusy = busy.some((b) => {
        const busyStart = new Date(b.start);
        const busyEnd = new Date(b.end);
        return (
          (current >= busyStart && current < busyEnd) ||
          (slotEnd > busyStart && slotEnd <= busyEnd) ||
          (current <= busyStart && slotEnd >= busyEnd)
        );
      });

      const isTooCloseToMeeting = busy.some((b) => {
        const busyEnd = new Date(b.end);
        const busyStart = new Date(b.start);
        const gapMs = gapMinutes * 60 * 1000;
        const tooCloseAfter =
          current.getTime() >= busyEnd.getTime() &&
          current.getTime() < busyEnd.getTime() + gapMs;
        const tooCloseBefore =
          slotEnd.getTime() <= busyStart.getTime() &&
          slotEnd.getTime() > busyStart.getTime() - gapMs;
        return tooCloseAfter || tooCloseBefore;
      });

      const totalAvailMinutes = (endHour - startHour) * 60;
      const existingMeetingMinutes = this.getMeetingMinutesForDay(
        dayKey,
        busy,
        startHour,
        endHour,
        tz,
      );
      const bookedSlotMinutes = meetingMinutesPerDay.get(dayKey) || 0;
      const totalBooked = existingMeetingMinutes + bookedSlotMinutes;
      const deepWorkMinutes = deepWorkHours * 60;
      const maxBookableMinutes = totalAvailMinutes - deepWorkMinutes;

      if (
        !isBusy &&
        !isTooCloseToMeeting &&
        totalBooked + slotDuration <= maxBookableMinutes
      ) {
        slots.push({
          start: current.toISOString(),
          end: slotEnd.toISOString(),
          duration: slotDuration,
        });
        meetingMinutesPerDay.set(dayKey, bookedSlotMinutes + slotDuration);
      }

      current = new Date(current.getTime() + slotDuration * 60 * 1000);
    }

    return slots.slice(0, 10);
  }

  private getMeetingMinutesForDay(
    dayKey: string,
    busy: BusyPeriod[],
    startHour: number,
    endHour: number,
    tz: string,
  ): number {
    let total = 0;
    for (const b of busy) {
      const busyStart = new Date(b.start);
      const busyEnd = new Date(b.end);
      if (this.toDayKey(busyStart, tz) !== dayKey) continue;
      const tzStart = this.toTzDate(busyStart, tz);
      const dayStart = new Date(tzStart);
      dayStart.setHours(startHour, 0, 0, 0);
      const dayEnd = new Date(tzStart);
      dayEnd.setHours(endHour, 0, 0, 0);
      const effectiveStart = tzStart < dayStart ? dayStart : tzStart;
      const effectiveEnd =
        this.toTzDate(busyEnd, tz) > dayEnd
          ? dayEnd
          : this.toTzDate(busyEnd, tz);
      if (effectiveEnd > effectiveStart) {
        total +=
          (effectiveEnd.getTime() - effectiveStart.getTime()) / (60 * 1000);
      }
    }
    return total;
  }

  // eslint-disable-next-line max-params
  async createEvent(
    userId: string,
    startTime: string,
    durationMinutes: number,
    guestEmail: string,
    guestName?: string,
    title?: string,
    description?: string,
  ): Promise<calendar_v3.Schema$Event> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      throw new Error("Google Calendar not connected");
    }

    this.oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const calendar = google.calendar({
      version: "v3",
      auth: this.oauth2Client,
    });
    const start = new Date(startTime);
    const end = new Date(start.getTime() + durationMinutes * 60 * 1000);

    try {
      const event = await calendar.events.insert({
        calendarId: "primary",
        requestBody: {
          summary: title || `Meeting with ${guestName || guestEmail}`,
          description: description || "Scheduled via ADHD Email Client",
          start: { dateTime: start.toISOString() },
          end: { dateTime: end.toISOString() },
          attendees: [{ email: guestEmail }],
        },
      });
      return event.data;
    } catch (error) {
      console.error("Error creating calendar event:", error);
      throw new Error("Failed to create calendar event");
    }
  }

  async findEventsWithAttendee(
    userId: string,
    attendeeEmail: string,
    daysAhead: number = 90,
    daysBack: number = 30,
  ): Promise<
    Array<{
      id: string | null | undefined;
      summary: string | null | undefined;
      description: string | null | undefined;
      start: string | null | undefined;
      end: string | null | undefined;
      attendees?: Array<{
        email: string | null | undefined;
        displayName: string | null | undefined;
        responseStatus: string | null | undefined;
      }>;
      htmlLink: string | null | undefined;
      location: string | null | undefined;
    }>
  > {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      throw new Error("Google Calendar not connected");
    }

    this.oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const calendar = google.calendar({
      version: "v3",
      auth: this.oauth2Client,
    });

    const now = new Date();
    const timeMin = new Date(now.getTime() - daysBack * 24 * 60 * 60 * 1000);
    const timeMax = new Date(now.getTime() + daysAhead * 24 * 60 * 60 * 1000);

    try {
      const response = await calendar.events.list({
        calendarId: "primary",
        timeMin: timeMin.toISOString(),
        timeMax: timeMax.toISOString(),
        maxResults: 100,
        singleEvents: true,
        orderBy: "startTime",
      });

      const events = (response.data.items || []).filter((event) => {
        // Check if the attendee email is in the attendees list
        if (event.attendees) {
          return event.attendees.some(
            (attendee) =>
              attendee.email?.toLowerCase() === attendeeEmail.toLowerCase(),
          );
        }
        return false;
      });

      return events.map((event) => ({
        id: event.id,
        summary: event.summary,
        description: event.description,
        start: event.start?.dateTime || event.start?.date,
        end: event.end?.dateTime || event.end?.date,
        attendees: event.attendees?.map((a) => ({
          email: a.email,
          displayName: a.displayName,
          responseStatus: a.responseStatus,
        })),
        htmlLink: event.htmlLink,
        location: event.location,
      }));
    } catch (error) {
      console.error("Error finding calendar events:", error);
      throw new Error("Failed to find calendar events");
    }
  }

  /**
   * Detect if an email is a calendar invitation
   * Uses strict criteria to avoid false positives
   */
  isCalendarInvitation(email: {
    subject?: string;
    body?: string;
    htmlBody?: string;
  }): boolean {
    const subject = (email.subject || "").toLowerCase();
    const body = (email.body || "").toLowerCase();
    const htmlBody = (email.htmlBody || "").toLowerCase();
    const combinedText = `${subject} ${body} ${htmlBody}`;

    // Check subject for specific invitation keywords (more strict)
    const invitationKeywords = [
      // Most common format
      "invitation:",
      // Alternative format
      "invite:",
      "meeting invitation",
      "event invitation",
      "calendar invitation",
      "you're invited to",
      "you are invited to",
      "meeting request",
      "event request",
    ];

    const hasInvitationKeyword = invitationKeywords.some((keyword) =>
      subject.includes(keyword),
    );

    // Check for iCal content patterns (most reliable indicator)
    const hasICalPattern =
      combinedText.includes("begin:vcalendar") ||
      combinedText.includes("method:request") ||
      combinedText.includes("content-type:text/calendar") ||
      combinedText.includes("content-type: text/calendar") ||
      (combinedText.includes('attachment; filename="') &&
        combinedText.includes(".ics"));

    // Check for iCal-specific headers (strict patterns)
    const hasICalHeaders =
      combinedText.includes("dtstart:") ||
      combinedText.includes("dtend:") ||
      combinedText.includes("organizer:mailto:") ||
      combinedText.includes("attendee:mailto:") ||
      (combinedText.includes("uid:") && combinedText.includes("@"));

    // Only return true if we have strong indicators
    // Require either invitation keyword in subject OR iCal patterns
    return hasInvitationKeyword || hasICalPattern || hasICalHeaders;
  }

  /**
   * Respond to a calendar invitation
   */
  async respondToInvitation(
    userId: string,
    emailId: string,
    response: "accepted" | "declined" | "tentative",
  ): Promise<void> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      throw new Error("Google Calendar not connected");
    }

    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Check if email is a calendar invitation
    if (!this.isCalendarInvitation(email)) {
      throw new Error("Email is not a calendar invitation");
    }

    this.oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const calendar = google.calendar({
      version: "v3",
      auth: this.oauth2Client,
    });

    // Try to find the event by searching for events with matching subject/time
    // First, try to extract event details from email
    const subject = email.subject || "";
    const body = email.body || email.htmlBody || "";

    // Parse iCal content if present
    let eventId: string | null = null;
    let eventStart: Date | null = null;

    // Try to extract from iCal format
    const icalMatch = body.match(/BEGIN:VEVENT[\s\S]*?END:VEVENT/);
    if (icalMatch) {
      const icalContent = icalMatch[0];
      const uidMatch = icalContent.match(/UID:([^\r\n]+)/);
      const organizerMatch = icalContent.match(
        /ORGANIZER[^:]*:MAILTO:([^\r\n]+)/i,
      );
      const dtstartMatch = icalContent.match(/DTSTART[^:]*:([^\r\n]+)/i);

      if (uidMatch) {
        // UID might be the event ID or contain it
        eventId = uidMatch[1].trim();
      }
      if (organizerMatch) {
        // organizerEmail extracted for potential future use
        organizerMatch[1].trim();
      }
      if (dtstartMatch) {
        try {
          // Parse iCal date format (YYYYMMDDTHHMMSS or YYYYMMDD)
          const dateStr = dtstartMatch[1].trim();
          if (dateStr.length >= ICAL_DATE_MIN_LENGTH) {
            const year = dateStr.substring(0, ICAL_YEAR_END);
            const month = dateStr.substring(ICAL_MONTH_START, ICAL_MONTH_END);
            const day = dateStr.substring(ICAL_DAY_START, ICAL_DAY_END);
            const hour =
              dateStr.length > ICAL_DATE_MIN_LENGTH
                ? dateStr.substring(ICAL_HOUR_START, ICAL_HOUR_END)
                : "00";
            const minute =
              dateStr.length > ICAL_DATE_WITH_HOURS_LENGTH
                ? dateStr.substring(ICAL_MINUTE_START, ICAL_MINUTE_END)
                : "00";
            eventStart = new Date(
              `${year}-${month}-${day}T${hour}:${minute}:00`,
            );
          }
        } catch (error) {
          console.error("Error parsing iCal date:", error);
        }
      }
    }

    // If we have event details, try to find the event in Google Calendar
    if (eventStart) {
      // 1 day before
      const timeMin = new Date(eventStart.getTime() - 24 * 60 * 60 * 1000);
      // 1 day after
      const timeMax = new Date(eventStart.getTime() + 24 * 60 * 60 * 1000);

      try {
        const eventsResponse = await calendar.events.list({
          calendarId: "primary",
          timeMin: timeMin.toISOString(),
          timeMax: timeMax.toISOString(),
          maxResults: 50,
          singleEvents: true,
        });

        // Try to match by subject or UID
        const matchingEvent = eventsResponse.data.items?.find((event) => {
          if (eventId && event.iCalUID === eventId) {
            return true;
          }
          if (
            event.summary &&
            subject.toLowerCase().includes(event.summary.toLowerCase())
          ) {
            return true;
          }
          // Check if user is an attendee
          if (event.attendees) {
            const userEmail = EncryptionHelper.decrypt(user.email);
            return event.attendees.some(
              (attendee) =>
                attendee.email?.toLowerCase() === userEmail?.toLowerCase(),
            );
          }
          return false;
        });

        if (matchingEvent?.id) {
          eventId = matchingEvent.id;
        }
      } catch (error) {
        console.error("Error searching for calendar event:", error);
      }
    }

    // If we found an event ID, update the attendee response
    if (eventId) {
      try {
        // Get the event first to check current attendee status
        const event = await calendar.events.get({
          calendarId: "primary",
          eventId,
        });

        if (!event.data.attendees) {
          throw new Error("Event has no attendees");
        }

        const userEmail = EncryptionHelper.decrypt(user.email);
        const attendeeIndex = event.data.attendees.findIndex(
          (attendee) =>
            attendee.email?.toLowerCase() === userEmail?.toLowerCase(),
        );

        if (attendeeIndex === -1) {
          throw new Error("User is not an attendee of this event");
        }

        // Map response to Google Calendar response status
        let responseStatus: string;
        if (response === "accepted") {
          responseStatus = "accepted";
        } else if (response === "declined") {
          responseStatus = "declined";
        } else {
          responseStatus = "tentative";
        }

        // Update the attendee's response status
        const updatedAttendees = [...(event.data.attendees || [])];
        updatedAttendees[attendeeIndex] = {
          ...updatedAttendees[attendeeIndex],
          responseStatus,
        };

        await calendar.events.patch({
          calendarId: "primary",
          eventId,
          requestBody: {
            attendees: updatedAttendees,
          },
        });

        return;
      } catch (error) {
        console.error("Error updating calendar event:", error);
        throw new Error(
          `Failed to respond to invitation: ${error instanceof Error ? error.message : "Unknown error"}`,
        );
      }
    }

    // If we couldn't find the event, throw an error
    throw new Error(
      "Could not find corresponding calendar event. Please respond to the invitation directly in your calendar.",
    );
  }

  async generateMeetingReply(
    userId: string,
    emailId: string,
    provider?: "gemini" | "openai",
  ): Promise<string> {
    const slots = await this.getAvailableTimeSlots(userId);
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const user = await this.usersService.findOne(userId);
    const email = await this.emailsService.getEmailById(userId, emailId);

    if (!email) {
      throw new Error("Email not found");
    }

    if (slots.length === 0) {
      // Use LLM even for no-slots scenario
      try {
        let llmProvider: LLMProvider | undefined;
        if (provider) {
          llmProvider =
            provider === "gemini" ? LLMProvider.GEMINI : LLMProvider.OPENAI;
        }
        return await this.llmService.generateMeetingReply(
          {
            from: email.from,
            fromName: email.fromName,
            subject: email.subject,
            body: email.body,
          },
          [],
          process.env.CALENDAR_BOOKING_URL,
          llmProvider,
          userId,
        );
      } catch (error) {
        // Fallback
        return `Hi there,

Thank you for reaching out about scheduling a meeting. Unfortunately, I don't have any available slots in the next week.

Please let me know your availability and I'll do my best to accommodate.

Best regards`;
      }
    }

    // Format slots for LLM
    const formattedSlots = slots.slice(0, 5).map((slot) => ({
      start: slot.start,
      end: slot.end,
    }));

    try {
      let llmProvider: LLMProvider | undefined;
      if (provider) {
        llmProvider =
          provider === "gemini" ? LLMProvider.GEMINI : LLMProvider.OPENAI;
      }
      return await this.llmService.generateMeetingReply(
        {
          from: email.from,
          fromName: email.fromName,
          subject: email.subject,
          body: email.body,
        },
        formattedSlots,
        process.env.CALENDAR_BOOKING_URL,
        llmProvider,
        userId,
      );
    } catch (error) {
      console.error(
        "LLM meeting reply generation failed, using fallback",
        error,
      );
      // Fallback to template-based reply
      const slotsText = slots
        .slice(0, 5)
        .map((slot, i) => {
          const start = new Date(slot.start);
          return `${i + 1}. ${start.toLocaleDateString()} at ${start.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`;
        })
        .join("\n");

      return `Hi there,

Thank you for reaching out about scheduling a meeting. Here are some times that work for me:

${slotsText}

You can also book directly on my calendar: ${process.env.CALENDAR_BOOKING_URL || "https://calendly.com/your-link"}

Let me know what works best for you!

Best regards`;
    }
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { google } from "googleapis";
import { UsersService } from "../../users/users.service";
import {
  ContactProvider,
  RawContact,
} from "../interfaces/contact-provider.interface";
import { isApiError } from "../../types/common";
import { QUERY_LIMITS } from "../../constants/query-limits";

@Injectable()
export class GmailContactsProvider implements ContactProvider {
  readonly providerName = "gmail";
  private readonly logger = new Logger(GmailContactsProvider.name);

  constructor(private usersService: UsersService) {}

  async isConnected(userId: string): Promise<boolean> {
    const user = await this.usersService.findOne(userId);
    return !!user?.googleCalendarAccessToken;
  }

  // eslint-disable-next-line max-lines-per-function, max-statements
  async syncContacts(
    userId: string,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    _fullSync: boolean = false,
  ): Promise<number> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      this.logger.log(
        `User ${userId} not connected to Google, skipping contact sync.`,
      );
      return 0;
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    // Handle token refresh
    oauth2Client.on("tokens", async (tokens) => {
      if (tokens.access_token) {
        await this.usersService.update(userId, {
          googleCalendarAccessToken: tokens.access_token,
          ...(tokens.refresh_token && {
            googleCalendarRefreshToken: tokens.refresh_token,
          }),
        });
      }
    });

    const people = google.people({ version: "v1", auth: oauth2Client });

    try {
      const contacts: RawContact[] = [];
      let nextPageToken: string | undefined;
      let totalSynced = 0;

      do {
        const response = await people.people.connections.list({
          resourceName: "people/me",
          pageSize: 1000,
          personFields:
            "names,emailAddresses,phoneNumbers,organizations,photos",
          pageToken: nextPageToken,
        });

        const connections = response.data.connections || [];

        for (const person of connections) {
          const email = person.emailAddresses?.[0]?.value;
          // Skip contacts without email
          if (!email) continue;

          const name = person.names?.[0];
          const org = person.organizations?.[0];
          const photo = person.photos?.[0];

          contacts.push({
            providerId: person.resourceName || "",
            email: email.toLowerCase().trim(),
            name: name?.displayName,
            firstName: name?.givenName,
            lastName: name?.familyName,
            phone: person.phoneNumbers?.[0]?.value,
            company: org?.name,
            jobTitle: org?.title,
            photoUrl: photo?.url,
          });
        }

        nextPageToken = response.data.nextPageToken || undefined;
        totalSynced = contacts.length;

        // Limit to prevent excessive API calls
        if (contacts.length >= 5000) {
          this.logger.log(`Contact sync limit reached for user ${userId}`);
          break;
        }
      } while (nextPageToken);

      this.logger.log(
        `Fetched ${contacts.length} contacts from Gmail for user ${userId}`,
      );

      // Return raw contacts - the service will handle storing them
      // The ContactsService will call this and then store them
      return totalSynced;
    } catch (error: unknown) {
      console.error(`Error syncing contacts for user ${userId}:`, error);

      const errorCode =
        typeof error === "object" && error !== null && "code" in error
          ? (error as { code?: number | string }).code
          : undefined;
      let errorMessage: string;
      if (error instanceof Error) {
        errorMessage = error.message;
      } else if (
        typeof error === "object" &&
        error !== null &&
        "message" in error
      ) {
        errorMessage = String((error as { message?: unknown }).message);
      } else {
        errorMessage = "";
      }

      if (
        errorCode === 401 ||
        errorCode === 403 ||
        errorMessage.includes("invalid_grant")
      ) {
        await this.usersService.update(userId, { needsRelogin: true });
      }

      throw error;
    }
  }

  async searchContacts(
    userId: string,
    query: string,
    maxResults: number = 20,
  ): Promise<RawContact[]> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      return [];
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const people = google.people({ version: "v1", auth: oauth2Client });
    const resultsMap = new Map<string, RawContact>();
    const pageSize = Math.min(maxResults, QUERY_LIMITS.MAX_ISSUES_SEARCH);

    try {
      const response = await people.people.searchContacts({
        query,
        pageSize,
        readMask: "names,emailAddresses,phoneNumbers,organizations,photos",
      });

      for (const result of response.data.results || []) {
        const { person } = result;
        if (!person) continue;

        const email = person.emailAddresses?.[0]?.value;
        if (!email) continue;

        const emailKey = email.toLowerCase().trim();
        if (resultsMap.has(emailKey)) continue;

        const name = person.names?.[0];
        const org = person.organizations?.[0];
        const photo = person.photos?.[0];

        resultsMap.set(emailKey, {
          providerId: person.resourceName || "",
          email: emailKey,
          name: name?.displayName,
          firstName: name?.givenName,
          lastName: name?.familyName,
          phone: person.phoneNumbers?.[0]?.value,
          company: org?.name,
          jobTitle: org?.title,
          photoUrl: photo?.url,
        });
      }
    } catch (error: unknown) {
      this.logger.error(
        `Error searching main contacts for user ${userId}:`,
        error,
      );
    }

    try {
      const otherResponse = await people.otherContacts.search({
        query,
        pageSize,
        readMask: "names,emailAddresses,phoneNumbers",
      });

      for (const result of otherResponse.data.results || []) {
        const { person } = result;
        if (!person) continue;

        const email = person.emailAddresses?.[0]?.value;
        if (!email) continue;

        const emailKey = email.toLowerCase().trim();
        if (resultsMap.has(emailKey)) continue;

        const name = person.names?.[0];
        const org = person.organizations?.[0];
        const photo = person.photos?.[0];

        resultsMap.set(emailKey, {
          providerId: person.resourceName || "",
          email: emailKey,
          name: name?.displayName,
          firstName: name?.givenName,
          lastName: name?.familyName,
          phone: person.phoneNumbers?.[0]?.value,
          company: org?.name,
          jobTitle: org?.title,
          photoUrl: photo?.url,
        });
      }
    } catch (error: unknown) {
      this.logger.warn(
        `Error searching other contacts for user ${userId} (may be expected if scope not granted):`,
        error,
      );
    }

    return Array.from(resultsMap.values()).slice(0, maxResults);
  }

  async getContact(
    userId: string,
    providerId: string,
  ): Promise<RawContact | null> {
    const user = await this.usersService.findOne(userId);
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    if (!user?.googleCalendarAccessToken) {
      return null;
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const people = google.people({ version: "v1", auth: oauth2Client });
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    try {
      const response = await people.people.get({
        resourceName: providerId,
        personFields: "names,emailAddresses,phoneNumbers,organizations,photos",
      });

      const person = response.data;
      const email = person.emailAddresses?.[0]?.value;
      if (!email) return null;

      const name = person.names?.[0];
      const org = person.organizations?.[0];
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      const photo = person.photos?.[0];

      return {
        providerId: person.resourceName || "",
        email: email.toLowerCase().trim(),
        name: name?.displayName,
        firstName: name?.givenName,
        lastName: name?.familyName,
        phone: person.phoneNumbers?.[0]?.value,
        company: org?.name,
        jobTitle: org?.title,
        photoUrl: photo?.url,
      };
    } catch (error) {
      console.error(
        `Error getting contact ${providerId} for user ${userId}:`,
        error,
      );
      return null;
    }
  }

  /**
   * Fetch all contacts from Gmail (internal method for sync)
   * Returns raw contacts that ContactsService will process and store
   * Fetches from both "connections" (explicitly added contacts) and
   * "otherContacts" (auto-created from interactions like emails)
   */
  // eslint-disable-next-line max-statements, max-lines-per-function
  async fetchAllContacts(userId: string): Promise<RawContact[]> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      this.logger.log(
        `User ${userId} has no Google access token, skipping contact fetch`,
      );
      return [];
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    oauth2Client.on("tokens", async (tokens) => {
      if (tokens.access_token) {
        await this.usersService.update(userId, {
          googleCalendarAccessToken: tokens.access_token,
          ...(tokens.refresh_token && {
            googleCalendarRefreshToken: tokens.refresh_token,
          }),
        });
      }
    });

    const people = google.people({ version: "v1", auth: oauth2Client });
    const contactsMap = new Map<string, RawContact>();

    // Fetch from connections (explicitly added contacts)
    await this.fetchConnectionsContacts(userId, people, contactsMap);

    // Fetch from "Other contacts" (auto-created from interactions)
    await this.fetchOtherContacts(userId, people, contactsMap);

    const contacts = Array.from(contactsMap.values());
    this.logger.log(
      `Fetched ${contacts.length} total contacts for user ${userId}`,
    );

    return contacts;
  }

  /**
   * Fetch contacts from people.connections (explicitly added contacts)
   */
  private async fetchConnectionsContacts(
    userId: string,
    people: ReturnType<typeof google.people>,
    contactsMap: Map<string, RawContact>,
  ): Promise<void> {
    let nextPageToken: string | undefined;

    try {
      do {
        const response = await people.people.connections.list({
          resourceName: "people/me",
          pageSize: 1000,
          personFields:
            "names,emailAddresses,phoneNumbers,organizations,photos",
          pageToken: nextPageToken,
        });

        const connections = response.data.connections || [];
        this.logger.log(
          `Fetched ${connections.length} connections for user ${userId}`,
        );

        for (const person of connections) {
          const email = person.emailAddresses?.[0]?.value;
          if (!email) continue;

          const emailKey = email.toLowerCase().trim();
          if (contactsMap.has(emailKey)) continue;

          const name = person.names?.[0];
          const org = person.organizations?.[0];
          const photo = person.photos?.[0];

          contactsMap.set(emailKey, {
            providerId: person.resourceName || "",
            email: emailKey,
            name: name?.displayName,
            firstName: name?.givenName,
            lastName: name?.familyName,
            phone: person.phoneNumbers?.[0]?.value,
            company: org?.name,
            jobTitle: org?.title,
            photoUrl: photo?.url,
          });
        }

        nextPageToken = response.data.nextPageToken || undefined;

        if (contactsMap.size >= 5000) {
          this.logger.log(`Contact limit reached for user ${userId}`);
          return;
        }
      } while (nextPageToken);
    } catch (error: unknown) {
      this.logger.error(
        `Error fetching connections for user ${userId}:`,
        error,
      );
      await this.handleApiError(userId, error);
      throw error;
    }
  }

  /**
   * Fetch contacts from otherContacts (auto-created from interactions like emails)
   * These are contacts that Google automatically creates when you email someone
   */
  private async fetchOtherContacts(
    userId: string,
    people: ReturnType<typeof google.people>,
    contactsMap: Map<string, RawContact>,
  ): Promise<void> {
    let nextPageToken: string | undefined;

    try {
      do {
        const response = await people.otherContacts.list({
          pageSize: 1000,
          readMask: "names,emailAddresses,phoneNumbers,photos",
          pageToken: nextPageToken,
        });

        const otherContacts = response.data.otherContacts || [];
        this.logger.log(
          `Fetched ${otherContacts.length} other contacts for user ${userId}`,
        );

        for (const person of otherContacts) {
          const email = person.emailAddresses?.[0]?.value;
          if (!email) continue;

          const emailKey = email.toLowerCase().trim();
          // Skip if we already have this contact from connections
          if (contactsMap.has(emailKey)) continue;

          const name = person.names?.[0];
          const org = person.organizations?.[0];
          const photo = person.photos?.[0];

          contactsMap.set(emailKey, {
            providerId: person.resourceName || "",
            email: emailKey,
            name: name?.displayName,
            firstName: name?.givenName,
            lastName: name?.familyName,
            phone: person.phoneNumbers?.[0]?.value,
            company: org?.name,
            jobTitle: org?.title,
            photoUrl: photo?.url,
          });
        }

        nextPageToken = response.data.nextPageToken || undefined;

        if (contactsMap.size >= 5000) {
          this.logger.log(`Contact limit reached for user ${userId}`);
          return;
        }
      } while (nextPageToken);
    } catch (error: unknown) {
      // Log but don't throw - otherContacts might fail if scope isn't granted
      // but we still want to return the connections we already fetched
      this.logger.warn(
        `Error fetching other contacts for user ${userId} (this may be expected if scope not granted):`,
        error,
      );
    }
  }

  /**
   * Handle API errors and update user status if needed
   */
  private async handleApiError(userId: string, error: unknown): Promise<void> {
    const apiError = isApiError(error) ? error : null;
    const errorCode = apiError?.code;
    let errorMessage: string;
    if (error instanceof Error) {
      errorMessage = error.message;
    } else if (
      typeof error === "object" &&
      error !== null &&
      "message" in error
    ) {
      errorMessage = String((error as { message?: unknown }).message);
    } else {
      errorMessage = "";
    }
    if (errorCode === 401 || errorMessage.includes("invalid_grant")) {
      await this.usersService.update(userId, { needsRelogin: true });
    }
  }
}

import { SearchIndexHelper } from "./search-index.helper";

describe("SearchIndexHelper", () => {
  describe("hashExact", () => {
    it("should hash a string value", () => {
      const value = "test@example.com";
      const hash = SearchIndexHelper.hashExact(value);
      expect(hash).toBeTruthy();
      expect(hash.length).toBe(64); // SHA-256 produces 64 hex characters
      expect(typeof hash).toBe("string");
    });

    it("should return empty string for empty input", () => {
      const result = SearchIndexHelper.hashExact("");
      expect(result).toBe("");
    });

    it("should normalize to lowercase", () => {
      const value1 = "Test@Example.com";
      const value2 = "test@example.com";
      const hash1 = SearchIndexHelper.hashExact(value1);
      const hash2 = SearchIndexHelper.hashExact(value2);
      expect(hash1).toBe(hash2);
    });

    it("should trim whitespace before hashing", () => {
      const value1 = "test@example.com";
      const value2 = "  test@example.com  ";
      const hash1 = SearchIndexHelper.hashExact(value1);
      const hash2 = SearchIndexHelper.hashExact(value2);
      expect(hash1).toBe(hash2);
    });

    it("should produce consistent hashes for same input", () => {
      const value = "test@example.com";
      const hash1 = SearchIndexHelper.hashExact(value);
      const hash2 = SearchIndexHelper.hashExact(value);
      expect(hash1).toBe(hash2);
    });

    it("should produce different hashes for different inputs", () => {
      const hash1 = SearchIndexHelper.hashExact("test1@example.com");
      const hash2 = SearchIndexHelper.hashExact("test2@example.com");
      expect(hash1).not.toBe(hash2);
    });

    it("should match expected SHA-256 hash format", () => {
      const value = "test";
      const hash = SearchIndexHelper.hashExact(value);
      // Verify it's a valid hex string
      expect(hash).toMatch(/^[a-f0-9]{64}$/);
    });

    it("should handle special characters", () => {
      const value = "test+tag@example.com";
      const hash = SearchIndexHelper.hashExact(value);
      expect(hash).toBeTruthy();
      expect(hash.length).toBe(64);
    });

    it("should handle unicode characters", () => {
      const value = "test@例子.com";
      const hash = SearchIndexHelper.hashExact(value);
      expect(hash).toBeTruthy();
      expect(hash.length).toBe(64);
    });
  });

  describe("generateSearchTokens", () => {
    it("should generate tokens from single value", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("John Smith");
      expect(tokens.length).toBeGreaterThan(0);
      expect(Array.isArray(tokens)).toBe(true);
    });

    it("should generate tokens from multiple values", () => {
      const tokens = SearchIndexHelper.generateSearchTokens(
        "John",
        "Smith",
        "john.smith@example.com",
      );
      expect(tokens.length).toBeGreaterThan(0);
    });

    it("should skip null and undefined values", () => {
      const tokens = SearchIndexHelper.generateSearchTokens(
        "John",
        null,
        undefined,
        "Smith",
      );
      expect(tokens.length).toBeGreaterThan(0);
      // Should not throw error
    });

    it("should generate trigram tokens", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("John");
      // Should include trigrams like "joh", "ohn"
      expect(tokens.length).toBeGreaterThan(1);
    });

    it("should generate word tokens", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("John Smith");
      // Should include tokens for "john" and "smith"
      expect(tokens.length).toBeGreaterThan(2);
    });

    it("should normalize tokens to lowercase", () => {
      const tokens1 = SearchIndexHelper.generateSearchTokens("John Smith");
      const tokens2 = SearchIndexHelper.generateSearchTokens("john smith");
      // Should produce same tokens (after normalization)
      expect(tokens1.length).toBe(tokens2.length);
    });

    it("should handle empty strings", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("", "John");
      expect(tokens.length).toBeGreaterThan(0);
    });

    it("should generate unique tokens (no duplicates)", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("John John");
      const uniqueTokens = new Set(tokens);
      expect(tokens.length).toBe(uniqueTokens.size);
    });

    it("should handle email addresses", () => {
      const tokens = SearchIndexHelper.generateSearchTokens(
        "john.smith@example.com",
      );
      expect(tokens.length).toBeGreaterThan(0);
    });

    it("should handle long strings", () => {
      const longString = "A".repeat(1000);
      const tokens = SearchIndexHelper.generateSearchTokens(longString);
      expect(tokens.length).toBeGreaterThan(0);
    });
  });

  describe("hashToken", () => {
    // hashToken is private, but we can test it indirectly through generateSearchTokens
    it("should hash tokens consistently", () => {
      const tokens1 = SearchIndexHelper.generateSearchTokens("test");
      const tokens2 = SearchIndexHelper.generateSearchTokens("test");
      // Same input should produce same tokens
      expect(tokens1).toEqual(tokens2);
    });

    it("should produce truncated hex hashes (16 chars)", () => {
      const tokens = SearchIndexHelper.generateSearchTokens("test");
      tokens.forEach((token) => {
        // hashToken truncates to 16 chars
        expect(token.length).toBe(16);
        expect(token).toMatch(/^[a-f0-9]{16}$/);
      });
    });
  });

  describe("generateQueryTokens", () => {
    it("should generate tokens from query string", () => {
      const tokens = SearchIndexHelper.generateQueryTokens("John Smith");
      expect(tokens.length).toBeGreaterThan(0);
      expect(Array.isArray(tokens)).toBe(true);
    });

    it("should return empty array for empty query", () => {
      const tokens = SearchIndexHelper.generateQueryTokens("");
      expect(tokens).toEqual([]);
    });

    it("should generate same tokens as generateSearchTokens for same input", () => {
      const query = "John Smith";
      const queryTokens = SearchIndexHelper.generateQueryTokens(query);
      const searchTokens = SearchIndexHelper.generateSearchTokens(query);
      // Should have similar structure (both use hashToken)
      expect(queryTokens.length).toBeGreaterThan(0);
      expect(searchTokens.length).toBeGreaterThan(0);
    });

    it("should generate prefix tokens for partial matching", () => {
      const tokens = SearchIndexHelper.generateQueryTokens("John");
      // Should include prefixes like "jo", "joh", "john"
      expect(tokens.length).toBeGreaterThan(1);
    });

    it("should normalize query to lowercase", () => {
      const tokens1 = SearchIndexHelper.generateQueryTokens("John");
      const tokens2 = SearchIndexHelper.generateQueryTokens("john");
      expect(tokens1).toEqual(tokens2);
    });

    it("should trim whitespace", () => {
      const tokens1 = SearchIndexHelper.generateQueryTokens("John");
      const tokens2 = SearchIndexHelper.generateQueryTokens("  John  ");
      expect(tokens1).toEqual(tokens2);
    });
  });

  describe("extractEmailDomain", () => {
    it("should extract domain from email address", () => {
      const domain = SearchIndexHelper.extractEmailDomain("test@example.com");
      expect(domain).toBe("example.com");
    });

    it("should return lowercase domain", () => {
      const domain = SearchIndexHelper.extractEmailDomain("test@EXAMPLE.COM");
      expect(domain).toBe("example.com");
    });

    it("should return null for empty string", () => {
      const domain = SearchIndexHelper.extractEmailDomain("");
      expect(domain).toBeNull();
    });

    it("should return null for email without @", () => {
      const domain = SearchIndexHelper.extractEmailDomain("notanemail");
      expect(domain).toBeNull();
    });

    it("should handle emails with subdomains", () => {
      const domain = SearchIndexHelper.extractEmailDomain(
        "test@mail.example.com",
      );
      expect(domain).toBe("mail.example.com");
    });

    it("should handle emails with plus signs", () => {
      const domain = SearchIndexHelper.extractEmailDomain(
        "test+tag@example.com",
      );
      expect(domain).toBe("example.com");
    });
  });

  describe("extractEmailLocalPart", () => {
    it("should extract local part from email address", () => {
      const local = SearchIndexHelper.extractEmailLocalPart("test@example.com");
      expect(local).toBe("test");
    });

    it("should return lowercase local part", () => {
      const local = SearchIndexHelper.extractEmailLocalPart("TEST@example.com");
      expect(local).toBe("test");
    });

    it("should return null for empty string", () => {
      const local = SearchIndexHelper.extractEmailLocalPart("");
      expect(local).toBeNull();
    });

    it("should return local part for email without @", () => {
      const local = SearchIndexHelper.extractEmailLocalPart("notanemail");
      expect(local).toBe("notanemail");
    });

    it("should handle emails with plus signs", () => {
      const local = SearchIndexHelper.extractEmailLocalPart(
        "test+tag@example.com",
      );
      expect(local).toBe("test+tag");
    });

    it("should handle emails with dots", () => {
      const local = SearchIndexHelper.extractEmailLocalPart(
        "first.last@example.com",
      );
      expect(local).toBe("first.last");
    });
  });
});

import { Injectable, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, MoreThan } from "typeorm";
import { ContextAnalysis } from "../database/entities/context-analysis.entity";
import { getErrorMessage } from "../types/common";
import { writeAnalysisLog } from "./context-analysis-logger";
import { getJobPriority } from "../queue/job-priorities";
import PgBoss = require("pg-boss");

/**
 * Service for managing context analysis progress tracking and job synchronization.
 * Handles analysis progress queries, batch completion checks, and PgBoss job syncing.
 */
@Injectable()
export class ContextAnalysisProgressService {
  private readonly logger = new Logger(ContextAnalysisProgressService.name);

  constructor(
    @InjectRepository(ContextAnalysis)
    private contextAnalysisRepository: Repository<ContextAnalysis>,
    @Inject("PG_BOSS") private boss: PgBoss,
  ) {}

  /**
   * Get an analysis record by ID
   */
  async getAnalysisRecordById(
    analysisRecordId: string,
  ): Promise<ContextAnalysis | null> {
    return await this.contextAnalysisRepository.findOne({
      where: { id: analysisRecordId },
    });
  }

  /**
   * Check if all batches are complete for an analysis
   */
  async getCompletedBatchCount(analysisRecordId: string): Promise<number> {
    const analysisRecord = await this.contextAnalysisRepository.findOne({
      where: { id: analysisRecordId },
    });

    if (!analysisRecord || !analysisRecord.stats) {
      return 0;
    }

    const { stats } = analysisRecord;
    const batchResults = (stats.batchResults as Record<string, unknown>) || {};
    return Object.keys(batchResults).length;
  }

  /**
   * Find the most recent active or completed analysis for a user
   */
  async findActiveAnalysis(
    userId: string,
    analysisId?: string,
  ): Promise<ContextAnalysis | null> {
    if (analysisId) {
      return await this.contextAnalysisRepository.findOne({
        where: { id: analysisId, userId },
      });
    }

    // Fall back to most recent running/pending analysis
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    let analysis = await this.contextAnalysisRepository.findOne({
      where: [
        { userId, status: "running", createdAt: MoreThan(oneHourAgo) },
        { userId, status: "pending", createdAt: MoreThan(oneHourAgo) },
      ],
      order: { createdAt: "DESC" },
    });

    if (!analysis) {
      analysis = await this.contextAnalysisRepository.findOne({
        where: [
          { userId, status: "running" },
          { userId, status: "pending" },
        ],
        order: { createdAt: "DESC" },
      });
    }

    return analysis;
  }

  /**
   * Find the most recently completed analysis for a user
   */
  async findRecentlyCompletedAnalysis(
    userId: string,
    maxAgeMinutes: number = 5,
  ): Promise<ContextAnalysis | null> {
    const recentCompleted = await this.contextAnalysisRepository.findOne({
      where: { userId, status: "completed" },
      order: { createdAt: "DESC" },
    });

    if (recentCompleted && recentCompleted.updatedAt) {
      const completedAgo = Date.now() - recentCompleted.updatedAt.getTime();
      if (completedAgo < maxAgeMinutes * 60 * 1000) {
        return recentCompleted;
      }
    }

    return null;
  }

  /**
   * Check and sync jobs between DB and PgBoss
   * Logs the difference and re-queues missing jobs
   */
  async checkAndSyncJobs(userId: string, analysisId?: string): Promise<void> {
    const analysis = await this.findActiveAnalysis(userId, analysisId);

    if (!analysis || !analysis.stats) {
      this.logger.debug(
        `[PROGRESS-CHECK] No active analysis found for user ${userId}`,
      );
      return;
    }

    const { stats } = analysis;
    const batchResults = (stats.batchResults as Record<string, unknown>) || {};
    const failedBatches = (stats.failedBatches as number[]) || [];
    const batchJobIds =
      (stats.batchJobIds as Record<number, string | null>) || {};
    const batchPayloadsForRetry =
      (stats.batchPayloadsForRetry as Record<
        number,
        Array<{
          threadId?: string;
          from: string;
          fromName?: string;
          subject: string;
          body: string;
          receivedAt: string;
          isRead?: boolean;
          timeToReply?: number | null;
          starCount?: number;
          isArchived?: boolean;
        }>
      >) || {};
    const totalBatches = stats.totalBatches as number;

    // If totalBatches is 0 or missing, DON'T try to infer it
    if (!totalBatches || totalBatches === 0) {
      const completedBatchIndices = Object.keys(batchResults).map((k) =>
        parseInt(k, 10),
      );
      this.logger.log(
        `[PROGRESS-CHECK] totalBatches is ${totalBatches || "not set"} and ${completedBatchIndices.length} batches completed. ` +
          `This is normal during progressive fetching - NOT inferring totalBatches.`,
      );
      return;
    }

    // Check DB state
    const completedBatchesInDb = Object.keys(batchResults).length;
    const failedBatchesInDb = failedBatches.length;
    const batchesWithJobIdsInDb = Object.keys(batchJobIds).filter(
      (k) => batchJobIds[parseInt(k, 10)] !== null,
    ).length;
    const remainingBatchesInDb =
      totalBatches - completedBatchesInDb - failedBatchesInDb;

    // Check PgBoss queue state
    let queuedJobsInPgBoss = 0;
    try {
      queuedJobsInPgBoss = await this.boss.getQueueSize(
        "analyze-context-batch",
      );
    } catch (error) {
      this.logger.error(
        `[PROGRESS-CHECK] Failed to get PgBoss queue size: ${getErrorMessage(error)}`,
      );
      return;
    }

    const missingJobs = Math.max(0, remainingBatchesInDb - queuedJobsInPgBoss);

    // Log the comparison
    this.logger.debug(
      `\n[PROGRESS-CHECK] =========================================\n` +
        `Analysis: ${analysis.id} (User: ${userId})\n` +
        `\n📊 DB State:\n` +
        `  • Total batches: ${totalBatches}\n` +
        `  • Completed in DB: ${completedBatchesInDb}\n` +
        `  • Failed in DB: ${failedBatchesInDb}\n` +
        `  • Remaining in DB: ${remainingBatchesInDb}\n` +
        `  • Batches with job IDs: ${batchesWithJobIdsInDb}\n` +
        `\n📦 PgBoss State:\n` +
        `  • Queued jobs (pending + active): ${queuedJobsInPgBoss}\n` +
        `\n🔍 Difference:\n` +
        `  • Expected remaining: ${remainingBatchesInDb}\n` +
        `  • Actually queued: ${queuedJobsInPgBoss}\n` +
        `  • Missing jobs: ${missingJobs}\n` +
        `=========================================\n`,
    );

    this.logger.log(
      `[PROGRESS-CHECK] Analysis ${analysis.id} (user ${userId}): ` +
        `DB: ${completedBatchesInDb}/${totalBatches} completed, ` +
        `${failedBatchesInDb} failed, ${remainingBatchesInDb} remaining | ` +
        `PgBoss: ${queuedJobsInPgBoss} queued | ` +
        `Missing: ${missingJobs}`,
    );

    // Find and re-queue missing batches
    const completedBatchIndices = Object.keys(batchResults).map((k) =>
      parseInt(k, 10),
    );
    const missingBatchIndices: number[] = [];

    for (let i = 0; i < totalBatches; i++) {
      if (!completedBatchIndices.includes(i) && !failedBatches.includes(i)) {
        missingBatchIndices.push(i);
      }
    }

    if (missingBatchIndices.length > 0) {
      this.logger.warn(
        `[PROGRESS-CHECK] Found ${missingBatchIndices.length} missing batches: ${missingBatchIndices.slice(0, 10).join(", ")}${missingBatchIndices.length > 10 ? ` ... (${missingBatchIndices.length - 10} more)` : ""}`,
      );

      let requeuedCount = 0;
      let requeueFailedCount = 0;

      for (const batchIndex of missingBatchIndices) {
        const existingJobId = batchJobIds[batchIndex];
        if (existingJobId) {
          try {
            const jobDetails = await this.boss.getJobById(existingJobId);
            if (
              jobDetails &&
              (jobDetails.state === "created" ||
                jobDetails.state === "active" ||
                jobDetails.state === "retry")
            ) {
              this.logger.debug(
                `[PROGRESS-CHECK] Batch ${batchIndex} has job ID ${existingJobId} with state '${jobDetails.state}' - still processing, skipping re-queue`,
              );
              continue;
            } else {
              this.logger.warn(
                `[PROGRESS-CHECK] ⚠️ Batch ${batchIndex} has job ID ${existingJobId} but job is ${jobDetails ? `in state '${jobDetails.state}'` : "not found in PgBoss"} - will re-queue`,
              );
            }
          } catch (error) {
            this.logger.warn(
              `[PROGRESS-CHECK] ⚠️ Failed to check job ${existingJobId} for batch ${batchIndex}: ${getErrorMessage(error)} - will attempt re-queue`,
            );
          }
        }

        // Try to re-queue
        const batchPayload = batchPayloadsForRetry[batchIndex];
        if (batchPayload && batchPayload.length > 0) {
          try {
            const jobId = await this.boss.send(
              "analyze-context-batch",
              {
                userId,
                batchIndex,
                emailBatch: batchPayload,
                analysisId: analysis.id,
              },
              {
                priority: getJobPriority("analyze-context-batch"),
                singletonKey: `context-batch-${analysis.id}-${batchIndex}`,
              },
            );

            if (jobId) {
              batchJobIds[batchIndex] = jobId;
              requeuedCount++;
              this.logger.log(
                `[PROGRESS-CHECK] ✅ Re-queued batch ${batchIndex} with job ID ${jobId}`,
              );
            }
          } catch (error) {
            requeueFailedCount++;
            this.logger.error(
              `[PROGRESS-CHECK] ❌ Failed to re-queue batch ${batchIndex}: ${getErrorMessage(error)}`,
            );
          }
        } else {
          this.logger.warn(
            `[PROGRESS-CHECK] ⚠️ Cannot re-queue batch ${batchIndex} - no payload found in batchPayloadsForRetry`,
          );
        }
      }

      if (requeuedCount > 0 || requeueFailedCount > 0) {
        // Update batchJobIds in stats
        await this.contextAnalysisRepository.update(
          { id: analysis.id },
          {
            stats: {
              ...stats,
              batchJobIds,
            },
          },
        );
        this.logger.log(
          `[PROGRESS-CHECK] Re-queued ${requeuedCount} batches, ${requeueFailedCount} failed`,
        );
      }
    } else {
      this.logger.log(
        `[PROGRESS-CHECK] ✅ All batches accounted for - no missing jobs detected`,
      );
    }
  }

  /**
   * Check if all batches are complete for an analysis
   */
  async checkBatchesComplete(
    analysisRecordId: string,
    totalBatches: number,
  ): Promise<boolean> {
    const analysisRecord = await this.contextAnalysisRepository.findOne({
      where: { id: analysisRecordId },
    });

    if (!analysisRecord || !analysisRecord.stats) {
      writeAnalysisLog(
        `[BATCH-CHECK] Analysis record ${analysisRecordId} not found or has no stats`,
        "warn",
      );
      return false;
    }

    const { stats } = analysisRecord;
    const batchResults = (stats.batchResults as Record<string, unknown>) || {};
    const failedBatches = (stats.failedBatches as number[]) || [];

    // CRITICAL: If totalBatches is 0, batches haven't been enqueued yet
    if (totalBatches === 0 || !totalBatches) {
      this.logger.warn(
        `[BATCH-CHECK] totalBatches is ${totalBatches} - batches haven't been enqueued yet. Cannot be complete.`,
      );
      writeAnalysisLog(
        `[BATCH-CHECK] totalBatches is ${totalBatches} - batches not enqueued yet`,
        "warn",
      );
      return false;
    }

    const completedCount = Object.keys(batchResults).length;
    const failedCount = failedBatches.length;
    const totalProcessed = completedCount + failedCount;

    this.logger.log(
      `[BATCH-CHECK] Analysis ${analysisRecordId}: ${completedCount} completed + ${failedCount} failed = ${totalProcessed}/${totalBatches}`,
    );
    writeAnalysisLog(
      `[BATCH-CHECK] ${completedCount} completed + ${failedCount} failed = ${totalProcessed}/${totalBatches}`,
      "log",
    );

    return totalProcessed >= totalBatches;
  }

  /**
   * Update analysis status
   */
  async updateAnalysisStatus(
    analysisId: string,
    status: "pending" | "running" | "completed" | "failed",
    errorMessage?: string,
  ): Promise<void> {
    const updates: Partial<ContextAnalysis> = { status };
    if (errorMessage) {
      updates.errorMessage = errorMessage;
    }
    await this.contextAnalysisRepository.update({ id: analysisId }, updates);
  }

  /**
   * Update analysis stats
   */
  async updateAnalysisStats(
    analysisId: string,
    stats: Record<string, unknown>,
  ): Promise<void> {
    const record = await this.contextAnalysisRepository.findOne({
      where: { id: analysisId },
    });
    if (record) {
      await this.contextAnalysisRepository.update(
        { id: analysisId },
        {
          stats: {
            ...record.stats,
            ...stats,
          },
        },
      );
    }
  }
}

import { Injectable, OnModuleInit, Logger, Inject } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import * as os from "os";
import PgBoss = require("pg-boss");
import { LLMService } from "../llm/llm.service";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { ContextAnalysis } from "../database/entities/context-analysis.entity";
import { writeAnalysisLog } from "./context-analysis-logger";
import { getErrorMessage } from "../types/common";
import { ContextGmailDataService } from "./context-gmail-data.service";
import { cleanEmailContent } from "../llm/email-content-cleaner";
import { GMAIL_LABELS } from "../constants/email-labels";
import { UsersService } from "../users/users.service";
import { PERFORMANCE_BUDGETS } from "../constants/performance-budgets";
import { JobPerformanceTracker } from "../queue/job-performance-tracker";
import { PERCENTAGES } from "../constants/percentages";
import { CloudWatchService } from "../aws/cloudwatch.service";

interface BatchAnalysisJob {
  userId: string;
  batchIndex: number;
  threadIds?: string[]; // New: thread IDs to fetch and process
  batch?: Array<{
    threadId?: string;
    from: string;
    fromName?: string;
    subject: string;
    body: string;
    receivedAt: string;
    isRead?: boolean;
    timeToReply?: number | null;
    readAt?: string | null;
    repliedAt?: string | null;
    starCount?: number;
    isArchived?: boolean;
  }>; // Legacy: pre-processed payloads
  sentPayload: Array<{
    emailId?: string;
    to: string;
    subject: string;
    body: string;
    sentAt: string;
  }>;
  userEmail?: string;
  currentContextForPrompt: Array<{
    key: string;
    value: string;
    source: string;
  }>;
  analysisRecordId: string;
  totalBatches: number;
  after?: string; // Date range for fetching threads
  before?: string;
}

/**
 * Calculate exponential backoff delay with jitter
 */
function calculateBackoffDelay(
  attemptNumber: number,
  baseDelay: number = 1000,
  maxDelay: number = 60000,
  jitterFactor: number = 0.3,
): number {
  // Exponential backoff: baseDelay * 2^attemptNumber
  const exponentialDelay = baseDelay * Math.pow(2, attemptNumber);

  // Cap at max delay
  const cappedDelay = Math.min(exponentialDelay, maxDelay);

  // Add jitter: random(0, jitterFactor) * cappedDelay
  const jitter = Math.random() * jitterFactor * cappedDelay;

  return Math.floor(cappedDelay + jitter);
}

@Injectable()
export class ContextBatchAnalysisProcessor implements OnModuleInit {
  private readonly logger = new Logger(ContextBatchAnalysisProcessor.name);
  private readonly batchConcurrency: number;

  // eslint-disable-next-line max-params
  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    private llmService: LLMService,
    @InjectRepository(ContextAnalysis)
    private contextAnalysisRepository: Repository<ContextAnalysis>,
    private configService: ConfigService,
    private gmailDataService: ContextGmailDataService,
    private usersService: UsersService,
    private cloudWatchService: CloudWatchService,
  ) {
    // Get CPU cores for optimal concurrency
    const cpuCores = os.cpus().length;
    // For batch analysis (LLM bound), use moderate concurrency to avoid rate limits
    // Allow more parallelism than full analysis since batches are smaller
    const defaultConcurrency = Math.max(3, Math.min(cpuCores * 2, 10));

    this.batchConcurrency = parseInt(
      this.configService.get<string>("JOB_BATCH_ANALYSIS_CONCURRENCY") ||
        String(defaultConcurrency),
      10,
    );

    this.logger.log(
      `CPU cores: ${cpuCores}, analyze-context-batch concurrency: ${this.batchConcurrency}`,
    );
  }

  async onModuleInit() {
    // Worker for batch analysis - process multiple batches in parallel
    this.logger.log(
      `Registering batch-analysis worker with concurrency: ${this.batchConcurrency}`,
    );
    writeAnalysisLog(
      `===== Batch Analysis Worker Registered ===== (concurrency: ${this.batchConcurrency})`,
      "log",
    );

    await this.boss.work(
      "analyze-context-batch",
      { teamSize: this.batchConcurrency },
      async (job) => {
        const jobData = job.data as BatchAnalysisJob;
        const {
          userId,
          batchIndex,
          threadIds,
          batch: legacyBatch,
          sentPayload,
          userEmail,
          currentContextForPrompt,
          analysisRecordId,
          totalBatches,
        } = jobData;
        const workerId = job.id || "unknown";
        const tracker = new JobPerformanceTracker(
          "analyze-context-batch",
          workerId,
          this.cloudWatchService,
        );
        tracker.setMetadata({ userId, threadId: analysisRecordId });

        // Log job received with detailed information
        const jobReceivedTime = new Date().toISOString();
        this.logger.log(
          `[Worker ${workerId}] ✅ JOB RECEIVED at ${jobReceivedTime}: batch ${batchIndex + 1}/${totalBatches} for user ${userId} (analysis ${analysisRecordId}, ${threadIds?.length || legacyBatch?.length || 0} threads)`,
        );
        writeAnalysisLog(
          `[Worker ${workerId}] ✅ JOB RECEIVED: batch ${batchIndex + 1}/${totalBatches} for analysis ${analysisRecordId}`,
          "log",
        );

        this.logger.log(
          `[Worker ${workerId}] 🚀 STARTING batch ${batchIndex + 1}/${totalBatches} for user ${userId} (${threadIds?.length || legacyBatch?.length || 0} threads)`,
        );
        writeAnalysisLog(
          `[Worker ${workerId}] 🚀 STARTING batch ${batchIndex + 1}/${totalBatches} for user ${userId}`,
          "log",
        );

        let attemptNumber = 0;
        const maxRetries = 5;
        // 1 second
        const baseDelay = 1000;
        // 60 seconds
        const maxDelay = 60000;

        while (attemptNumber <= maxRetries) {
          try {
            if (attemptNumber > 0) {
              const backoffDelay = calculateBackoffDelay(
                attemptNumber - 1,
                baseDelay,
                maxDelay,
              );
              this.logger.log(
                `[Worker ${workerId}] Retry attempt ${attemptNumber}/${maxRetries} after ${backoffDelay}ms backoff`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] Retry attempt ${attemptNumber}/${maxRetries} after ${backoffDelay}ms backoff`,
                "log",
              );
              await new Promise((resolve) => setTimeout(resolve, backoffDelay));
            }

            this.logger.log(
              `[Worker ${workerId}] Processing batch ${batchIndex + 1}/${totalBatches} (attempt ${attemptNumber + 1})`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] Processing batch ${batchIndex + 1}/${totalBatches} (attempt ${attemptNumber + 1})`,
              "log",
            );

            // If threadIds provided, fetch and process threads; otherwise use legacy batch
            let batch: Array<{
              threadId?: string;
              from: string;
              fromName?: string;
              subject: string;
              body: string;
              receivedAt: string;
              isRead?: boolean;
              timeToReply?: number | null;
              starCount?: number;
              isArchived?: boolean;
              userReplied?: boolean;
              emailCount?: number;
              readCount?: number;
              receivedHour?: number;
            }>;

            // Track timing for performance budgets
            let fetchDuration = 0;
            let processDuration = 0;

            if (threadIds && threadIds.length > 0) {
              // New approach: fetch threads by IDs and process them
              const fetchStartTime = Date.now();
              this.logger.log(
                `[Worker ${workerId}] 📥 Step 1/4: Fetching ${threadIds.length} threads by ID...`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] 📥 Step 1/4: Fetching ${threadIds.length} threads by ID...`,
                "log",
              );

              const threads = await this.gmailDataService.fetchThreadsByIds(
                userId,
                threadIds,
              );
              fetchDuration = Date.now() - fetchStartTime;
              const fetchExceeded =
                fetchDuration > PERFORMANCE_BUDGETS.BATCH_FETCH_THREADS;

              // Emit CloudWatch metric for batch fetch threads
              this.cloudWatchService
                .putPerformanceBudgetMetric({
                  budgetName: "BATCH_FETCH_THREADS",
                  budgetType: "batch",
                  durationMs: fetchDuration,
                  budgetMs: PERFORMANCE_BUDGETS.BATCH_FETCH_THREADS,
                  exceeded: fetchExceeded,
                  metadata: {
                    WorkerId: workerId,
                    UserId: userId,
                    ThreadCount: String(threads.length),
                  },
                })
                .catch((err) => {
                  this.logger.error("Failed to emit CloudWatch metric:", err);
                });

              this.logger.log(
                `[Worker ${workerId}] ✅ Fetched ${threads.length} threads in ${Math.round(fetchDuration / 1000)}s (budget: ${PERFORMANCE_BUDGETS.BATCH_FETCH_THREADS / 1000}s)${fetchExceeded ? " ⚠️ OVER BUDGET" : ""}`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] ✅ Fetched ${threads.length} threads in ${Math.round(fetchDuration / 1000)}s`,
                "log",
              );

              // Process threads into payloads
              const processStartTime = Date.now();
              this.logger.log(
                `[Worker ${workerId}] 🔄 Step 2/4: Processing ${threads.length} threads into analysis payloads...`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] 🔄 Step 2/4: Processing ${threads.length} threads into analysis payloads...`,
                "log",
              );

              batch = threads
                .map((thread) => {
                  const firstEmail = thread.emails?.sort(
                    (a, b) => a.receivedAt.getTime() - b.receivedAt.getTime(),
                  )[0];
                  if (!firstEmail) {
                    return null;
                  }

                  const userReplied = thread.emails?.some(
                    (email) =>
                      email.labelIds?.includes(GMAIL_LABELS.SENT) ||
                      (userEmail && email.from.toLowerCase() === userEmail),
                  );

                  let quickestReply: number | null = null;
                  if (userReplied) {
                    const sentEmails = thread.emails.filter(
                      (email) =>
                        email.labelIds?.includes(GMAIL_LABELS.SENT) ||
                        (userEmail && email.from.toLowerCase() === userEmail),
                    );
                    const receivedEmails = thread.emails.filter(
                      (email) =>
                        !email.labelIds?.includes(GMAIL_LABELS.SENT) &&
                        (!userEmail || email.from.toLowerCase() !== userEmail),
                    );

                    if (sentEmails.length > 0 && receivedEmails.length > 0) {
                      const firstReceived = receivedEmails[0].receivedAt;
                      const firstSent = sentEmails[0].receivedAt;
                      const replyTimeHours =
                        (firstSent.getTime() - firstReceived.getTime()) /
                        (1000 * 60 * 60);
                      if (replyTimeHours >= 0) {
                        quickestReply = replyTimeHours;
                      }
                    }
                  }

                  return {
                    threadId: thread.id,
                    from: firstEmail.from,
                    fromName: firstEmail.fromName,
                    subject: firstEmail.subject,
                    body: cleanEmailContent(
                      firstEmail.body,
                      firstEmail.htmlBody,
                      1000,
                    ),
                    receivedAt: firstEmail.receivedAt.toISOString(),
                    isRead: firstEmail.isRead,
                    timeToReply: quickestReply ? quickestReply * 60 : null,
                    starCount: thread.starCount || 0,
                    isArchived: thread.isArchived || false,
                    userReplied,
                    emailCount: thread.emails?.length || 0,
                    readCount:
                      thread.emails?.filter((e) => e.isRead).length || 0,
                    receivedHour: firstEmail.receivedAt.getHours(),
                  };
                })
                .filter((t) => t !== null) as Array<{
                threadId?: string;
                from: string;
                fromName?: string;
                subject: string;
                body: string;
                receivedAt: string;
                isRead?: boolean;
                timeToReply?: number | null;
                starCount?: number;
                isArchived?: boolean;
                userReplied?: boolean;
                emailCount?: number;
                readCount?: number;
                receivedHour?: number;
              }>;
              processDuration = Date.now() - processStartTime;
              const processExceeded =
                processDuration > PERFORMANCE_BUDGETS.BATCH_PROCESS_THREADS;

              // Emit CloudWatch metric for batch process threads
              this.cloudWatchService
                .putPerformanceBudgetMetric({
                  budgetName: "BATCH_PROCESS_THREADS",
                  budgetType: "batch",
                  durationMs: processDuration,
                  budgetMs: PERFORMANCE_BUDGETS.BATCH_PROCESS_THREADS,
                  exceeded: processExceeded,
                  metadata: {
                    WorkerId: workerId,
                    UserId: userId,
                    BatchSize: String(batch.length),
                  },
                })
                .catch((err) => {
                  this.logger.error("Failed to emit CloudWatch metric:", err);
                });

              this.logger.log(
                `[Worker ${workerId}] ✅ Processed ${batch.length} threads into payloads in ${Math.round(processDuration / 1000)}s (budget: ${PERFORMANCE_BUDGETS.BATCH_PROCESS_THREADS / 1000}s)${processExceeded ? " ⚠️ OVER BUDGET" : ""}`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] ✅ Processed ${batch.length} threads into payloads in ${Math.round(processDuration / 1000)}s`,
                "log",
              );
            } else if (legacyBatch) {
              // Pre-processed batch (fetched upfront in main job - no Gmail API calls needed)
              batch = legacyBatch;

              this.logger.log(
                `[Worker ${workerId}] ✅ Using pre-processed batch (${legacyBatch.length} threads) - skipping fetch/process steps (0s)`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] ✅ Using pre-processed batch (${legacyBatch.length} threads) - skipping fetch/process steps`,
                "log",
              );
              // fetchDuration and processDuration remain 0 (already initialized)
            } else {
              throw new Error("No threadIds or batch provided");
            }

            // Call LLM service to analyze the batch
            const llmStartTime = Date.now();
            this.logger.log(
              `[Worker ${workerId}] 🤖 Step 3/4: Calling LLM to analyze ${batch.length} email patterns...`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] 🤖 Step 3/4: Calling LLM to analyze ${batch.length} email patterns...`,
              "log",
            );

            const batchAnalysis = await this.llmService.analyzeEmailPatterns(
              batch,
              sentPayload, // Only first batch has sent emails, others get empty array
              undefined,
              userId,
              userEmail || undefined,
              currentContextForPrompt,
            );
            const llmDuration = Date.now() - llmStartTime;
            const llmExceeded =
              llmDuration > PERFORMANCE_BUDGETS.BATCH_LLM_ANALYSIS;

            // Emit CloudWatch metric for batch LLM analysis
            this.cloudWatchService
              .putPerformanceBudgetMetric({
                budgetName: "BATCH_LLM_ANALYSIS",
                budgetType: "batch",
                durationMs: llmDuration,
                budgetMs: PERFORMANCE_BUDGETS.BATCH_LLM_ANALYSIS,
                exceeded: llmExceeded,
                metadata: {
                  WorkerId: workerId,
                  UserId: userId,
                },
              })
              .catch((err) => {
                this.logger.error("Failed to emit CloudWatch metric:", err);
              });

            this.logger.log(
              `[Worker ${workerId}] ✅ LLM analysis completed in ${Math.round(llmDuration / 1000)}s (budget: ${PERFORMANCE_BUDGETS.BATCH_LLM_ANALYSIS / 1000}s)${llmExceeded ? " ⚠️ OVER BUDGET" : ""}`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] ✅ LLM analysis completed in ${Math.round(llmDuration / 1000)}s`,
              "log",
            );

            // Store result in ContextAnalysis.stats field (keyed by batch index)
            const saveStartTime = Date.now();
            this.logger.log(
              `[Worker ${workerId}] 💾 Step 4/4: Saving batch results to database...`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] 💾 Step 4/4: Saving batch results to database...`,
              "log",
            );

            const findRecordStartTime = Date.now();
            let analysisRecord = await this.contextAnalysisRepository.findOne({
              where: { id: analysisRecordId },
            });
            const findRecordDuration = Date.now() - findRecordStartTime;

            if (!analysisRecord) {
              throw new Error(
                `Analysis record ${analysisRecordId} not found for batch ${batchIndex}`,
              );
            }

            // Get existing stats or initialize
            const stats = analysisRecord.stats || {
              totalThreads: 0,
              outboundEmails: 0,
              threadsNeverOpened: 0,
              threadsReadButNotReplied: 0,
              vipContactsEvaluated: 0,
            };
            const batchResults =
              (stats.batchResults as Record<string, unknown>) || {};

            // Check if this batch was already completed (retry scenario)
            const batchWasAlreadyCompleted =
              batchResults[String(batchIndex)] !== undefined;

            // Extract thread IDs from batch for source linking
            const batchThreadIds = batch
              .map((t: { threadId?: string }) => t.threadId)
              .filter((id): id is string => !!id);

            // Store this batch's result (including thread IDs for fact-checking)
            batchResults[String(batchIndex)] = {
              context: batchAnalysis.context || [],
              writingStyle: batchAnalysis.writingStyle || null,
              completedAt: new Date().toISOString(),
              threadIds: batchThreadIds, // Store thread IDs for source linking
            };

            // Update stats with batch results
            stats.batchResults = batchResults;

            // Update analyzed count only if this batch wasn't already completed (prevent double counting on retries)
            const batchSize = batch.length;
            const currentAnalyzedCount = analysisRecord.analyzedCount || 0;
            if (!batchWasAlreadyCompleted) {
              analysisRecord.analyzedCount = currentAnalyzedCount + batchSize;
              this.logger.log(
                `[Worker ${workerId}] ✅ Batch ${batchIndex} completed for the first time. Incrementing analyzedCount by ${batchSize} (was ${currentAnalyzedCount}, now ${analysisRecord.analyzedCount})`,
              );
            } else {
              this.logger.warn(
                `[Worker ${workerId}] ⚠️ Batch ${batchIndex} was already completed (retry detected). Not incrementing analyzedCount to prevent double counting.`,
              );
            }

            // Re-read the latest stats to preserve concurrent updates from main job
            // This minimizes the race window - we read again right before saving
            const latestRecord = await this.contextAnalysisRepository.findOne({
              where: { id: analysisRecordId },
            });
            if (latestRecord && latestRecord.stats) {
              // Merge our batchResults into the latest stats (preserving fetchingStatus, totalBatches, etc.)
              const latestBatchResults =
                (latestRecord.stats.batchResults as Record<string, unknown>) ||
                {};
              latestBatchResults[String(batchIndex)] =
                batchResults[String(batchIndex)];
              latestRecord.stats.batchResults = latestBatchResults;
              latestRecord.analyzedCount = analysisRecord.analyzedCount;
              analysisRecord = latestRecord;
            } else {
              // Fallback: use our version
              analysisRecord.stats = stats;
            }

            const saveDbStartTime = Date.now();
            await this.contextAnalysisRepository.save(analysisRecord);
            const saveDbDuration = Date.now() - saveDbStartTime;
            const saveDuration = Date.now() - saveStartTime;
            const saveExceeded =
              saveDuration > PERFORMANCE_BUDGETS.BATCH_SAVE_RESULTS;

            // Emit CloudWatch metric for batch save results
            this.cloudWatchService
              .putPerformanceBudgetMetric({
                budgetName: "BATCH_SAVE_RESULTS",
                budgetType: "batch",
                durationMs: saveDuration,
                budgetMs: PERFORMANCE_BUDGETS.BATCH_SAVE_RESULTS,
                exceeded: saveExceeded,
                metadata: {
                  WorkerId: workerId,
                  UserId: userId,
                },
              })
              .catch((err) => {
                this.logger.error("Failed to emit CloudWatch metric:", err);
              });

            this.logger.log(
              `[Worker ${workerId}] ✅ Saved batch results in ${Math.round(saveDuration / 1000)}s (find: ${Math.round(findRecordDuration / 1000)}s, save: ${Math.round(saveDbDuration / 1000)}s, budget: ${PERFORMANCE_BUDGETS.BATCH_SAVE_RESULTS / 1000}s)${saveExceeded ? " ⚠️ OVER BUDGET" : ""}`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] ✅ Saved batch results in ${Math.round(saveDuration / 1000)}s`,
              "log",
            );

            // Calculate total time so far
            const totalTimeSoFar =
              saveDuration + llmDuration + processDuration + fetchDuration;

            const totalExceeded =
              totalTimeSoFar > PERFORMANCE_BUDGETS.BATCH_TOTAL;

            // Emit CloudWatch metric for batch total
            this.cloudWatchService
              .putPerformanceBudgetMetric({
                budgetName: "BATCH_TOTAL",
                budgetType: "batch",
                durationMs: totalTimeSoFar,
                budgetMs: PERFORMANCE_BUDGETS.BATCH_TOTAL,
                exceeded: totalExceeded,
                metadata: {
                  WorkerId: workerId,
                  UserId: userId,
                  FetchDuration: String(fetchDuration),
                  ProcessDuration: String(processDuration),
                  LlmDuration: String(llmDuration),
                  SaveDuration: String(saveDuration),
                },
              })
              .catch((err) => {
                this.logger.error("Failed to emit CloudWatch metric:", err);
              });

            if (totalExceeded) {
              this.logger.warn(
                `[Worker ${workerId}] ⚠️ BATCH OVER TOTAL BUDGET: ${Math.round(totalTimeSoFar / 1000)}s (budget: ${PERFORMANCE_BUDGETS.BATCH_TOTAL / 1000}s). Breakdown: fetch=${Math.round(fetchDuration / 1000)}s, process=${Math.round(processDuration / 1000)}s, llm=${Math.round(llmDuration / 1000)}s, save=${Math.round(saveDuration / 1000)}s`,
              );
            }

            // Update user progress (30-70% during LLM analysis, distributed across batches)
            const completedBatches = Object.keys(batchResults).length;
            const progressPercent =
              PERCENTAGES.THIRTY +
              Math.floor(
                (completedBatches / totalBatches) *
                  (PERCENTAGES.SEVENTY - PERCENTAGES.THIRTY),
              );

            try {
              await this.usersService.update(userId, {
                scanProgress: progressPercent,
                scanTotal: 100,
              });
              this.logger.log(
                `[Worker ${workerId}] Updated user progress to ${progressPercent}% (${completedBatches}/${totalBatches} batches completed)`,
              );
            } catch (progressError) {
              this.logger.warn(
                `[Worker ${workerId}] Failed to update user progress: ${getErrorMessage(progressError)}`,
              );
              // Don't fail the batch if progress update fails
            }

            const duration = Math.round(
              (Date.now() - tracker.startTime) / 1000,
            );
            this.logger.log(
              `[Worker ${workerId}] ✅ COMPLETED batch ${batchIndex + 1}/${totalBatches} in ${duration}s. Analyzed ${batchSize} threads.`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] ✅ COMPLETED batch ${batchIndex + 1}/${totalBatches} in ${duration}s. Analyzed ${batchSize} threads.`,
              "log",
            );

            // Success - break out of retry loop
            tracker.finish();
            return;
          } catch (error: unknown) {
            attemptNumber++;
            const errorMessage =
              error instanceof Error ? error.message : String(error);
            const errorStack = error instanceof Error ? error.stack : undefined;

            if (attemptNumber > maxRetries) {
              // Max retries exceeded - mark batch as failed
              this.logger.error(
                `[Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} failed after ${maxRetries} retries: ${errorMessage}`,
                errorStack || error,
              );
              console.error(
                `[BATCH-PROCESSOR] [Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} failed after ${maxRetries} retries: ${errorMessage}`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} failed after ${maxRetries} retries: ${errorMessage}`,
                "error",
              );

              // Store failure in stats
              try {
                const analysisRecord =
                  await this.contextAnalysisRepository.findOne({
                    where: { id: analysisRecordId },
                  });
                if (analysisRecord) {
                  const stats = analysisRecord.stats || {
                    totalThreads: 0,
                    outboundEmails: 0,
                    threadsNeverOpened: 0,
                    threadsReadButNotReplied: 0,
                    vipContactsEvaluated: 0,
                  };
                  const batchResults =
                    (stats.batchResults as Record<string, unknown>) || {};
                  const failedBatches = (stats.failedBatches as number[]) || [];
                  if (!failedBatches.includes(batchIndex)) {
                    failedBatches.push(batchIndex);
                  }
                  batchResults[String(batchIndex)] = {
                    error: errorMessage,
                    failedAt: new Date().toISOString(),
                  };
                  stats.batchResults = batchResults;
                  stats.failedBatches = failedBatches;
                  analysisRecord.stats = stats;
                  await this.contextAnalysisRepository.save(analysisRecord);
                }
              } catch (saveError) {
                this.logger.error(
                  `[Worker ${workerId}] Failed to save batch failure status: ${getErrorMessage(saveError)}`,
                );
              }

              // Re-throw to mark job as failed in PgBoss
              tracker.finish(error as Error);
              throw error;
            } else {
              // Will retry - log but continue
              this.logger.warn(
                `[Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} attempt ${attemptNumber} failed: ${errorMessage}. Will retry.`,
              );
              console.warn(
                `[BATCH-PROCESSOR] [Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} attempt ${attemptNumber} failed: ${errorMessage}. Will retry.`,
              );
              writeAnalysisLog(
                `[Worker ${workerId}] Batch ${batchIndex + 1}/${totalBatches} attempt ${attemptNumber} failed: ${errorMessage}. Will retry.`,
                "warn",
              );
            }
          }
        }
      },
    );

    this.logger.log("Batch analysis worker registered successfully");
    writeAnalysisLog("Batch analysis worker registered successfully", "log");
  }
}

import { Injectable, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import {
  UserContext,
  ContextKey,
  Source,
} from "../database/entities/user-context.entity";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { getErrorMessage } from "../types/common";
import { LLMService } from "../llm/llm.service";
import { cleanEmailContent } from "../llm/email-content-cleaner";
import { QUERY_LIMITS } from "../constants/query-limits";
import { BODY_PREVIEW_LENGTHS } from "../constants/llm-constants";
import { getJobPriority } from "../queue/job-priorities";
import PgBoss = require("pg-boss");

/**
 * Service for managing email category consolidation and generation.
 * Handles LLM-powered category management operations.
 */
@Injectable()
export class ContextCategoryService {
  private readonly logger = new Logger(ContextCategoryService.name);

  constructor(
    @InjectRepository(UserContext)
    private contextRepository: Repository<UserContext>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    private llmService: LLMService,
    @Inject("PG_BOSS") private boss: PgBoss,
  ) {}

  /**
   * Consolidate existing email categories in the database using LLM.
   * This is called manually via the "Consolidate Categories" button.
   */
  async consolidateExistingCategories(userId: string): Promise<{
    originalCount: number;
    consolidatedCount: number;
    userAddedCount: number;
    categories: Array<{
      name: string;
      description: string;
      isUserAdded: boolean;
    }>;
  }> {
    this.logger.log(
      `[CATEGORY-CONSOLIDATION] Starting manual consolidation for user ${userId}`,
    );

    // Fetch all existing EMAIL_CATEGORY context items
    const existingCategories = await this.contextRepository.find({
      where: {
        userId,
        contextKey: ContextKey.EMAIL_CATEGORY,
      },
    });

    this.logger.log(
      `[CATEGORY-CONSOLIDATION] Found ${existingCategories.length} existing categories`,
    );

    if (existingCategories.length === 0) {
      return {
        originalCount: 0,
        consolidatedCount: 0,
        userAddedCount: 0,
        categories: [],
      };
    }

    // Separate user-added and auto-generated categories
    const userAddedContexts = existingCategories.filter(
      (ctx) => ctx.source === Source.USER_EDITED,
    );
    const autoGeneratedContexts = existingCategories.filter(
      (ctx) => ctx.source !== Source.USER_EDITED,
    );

    this.logger.log(
      `[CATEGORY-CONSOLIDATION] ${autoGeneratedContexts.length} auto-generated, ${userAddedContexts.length} user-added`,
    );

    // Parse categories into name/description format
    const autoGeneratedCategories = autoGeneratedContexts.map((ctx) => {
      const parts = ctx.contextValue.split(" - ");
      return {
        name: parts[0].trim(),
        description: parts.length > 1 ? parts.slice(1).join(" - ").trim() : "",
      };
    });

    const userAddedCategories = userAddedContexts.map((ctx) => {
      const parts = ctx.contextValue.split(" - ");
      return {
        name: parts[0].trim(),
        description: parts.length > 1 ? parts.slice(1).join(" - ").trim() : "",
      };
    });

    // Call LLM to consolidate
    this.logger.log(
      `[CATEGORY-CONSOLIDATION] Calling LLM to consolidate ${autoGeneratedCategories.length} auto-generated categories...`,
    );

    const consolidatedCategories =
      await this.llmService.consolidateEmailCategories(
        autoGeneratedCategories,
        userAddedCategories,
        undefined,
        userId,
      );

    this.logger.log(
      `[CATEGORY-CONSOLIDATION] LLM returned ${consolidatedCategories.length} consolidated categories`,
    );

    // Delete all existing auto-generated categories
    const autoGeneratedIds = autoGeneratedContexts.map((ctx) => ctx.contextId);
    if (autoGeneratedIds.length > 0) {
      this.logger.log(
        `[CATEGORY-CONSOLIDATION] Deleting ${autoGeneratedIds.length} old auto-generated categories`,
      );
      await this.contextRepository.delete(autoGeneratedIds);
    }

    // Save the new consolidated categories (only auto-generated ones, user-added are preserved)
    const newAutoGeneratedCategories = consolidatedCategories.filter(
      (cat) => !cat.isUserAdded,
    );

    this.logger.log(
      `[CATEGORY-CONSOLIDATION] Saving ${newAutoGeneratedCategories.length} new consolidated categories`,
    );

    for (const cat of newAutoGeneratedCategories) {
      const contextValue = `${cat.name} - ${cat.description}`;
      const newContext = this.contextRepository.create({
        userId,
        contextKey: ContextKey.EMAIL_CATEGORY,
        contextValue,
        source: Source.AUTOGENERATED,
      });
      await this.contextRepository.save(newContext);
    }

    const result = {
      originalCount: existingCategories.length,
      consolidatedCount:
        newAutoGeneratedCategories.length + userAddedContexts.length,
      userAddedCount: userAddedContexts.length,
      categories: consolidatedCategories,
    };

    this.logger.log(
      `[CATEGORY-CONSOLIDATION] Consolidation complete: ${result.originalCount} -> ${result.consolidatedCount} categories (${result.userAddedCount} user-added preserved)`,
    );

    return result;
  }

  /**
   * Generate new categories from emails currently in "Other" category.
   * This analyzes the emails and suggests more specific categories that would better organize them.
   */
  async generateCategoriesFromOther(userId: string): Promise<{
    newCategoriesCount: number;
    totalCategoriesCount: number;
    newCategories: Array<{ name: string; description: string }>;
    reclassifyJobsQueued: number;
  }> {
    this.logger.log(
      `[GENERATE-CATEGORIES] Starting category generation from Other emails for user ${userId}`,
    );

    // Fetch thread IDs in "Other" category (category is encrypted, so filter in code)
    const threads = await this.emailThreadRepository.find({
      where: { userId, isArchived: false },
      select: ["id", "category"],
    });
    const otherThreadIds = threads
      .filter((t) => t.category === "Other" || !t.category)
      .map((t) => t.id);

    if (otherThreadIds.length === 0) {
      return {
        newCategoriesCount: 0,
        totalCategoriesCount: 0,
        newCategories: [],
        reclassifyJobsQueued: 0,
      };
    }

    const otherEmails = await this.emailRepository
      .createQueryBuilder("email")
      .where("email.userId = :userId", { userId })
      .andWhere("email.emailThreadId IN (:...threadIds)", {
        threadIds: otherThreadIds,
      })
      .select([
        "email.id",
        "email.from",
        "email.fromName",
        "email.subject",
        "email.body",
      ])
      .orderBy("email.receivedAt", "DESC")
      .limit(QUERY_LIMITS.PROVIDER_BATCH_SIZE)
      .getMany();

    this.logger.log(
      `[GENERATE-CATEGORIES] Found ${otherEmails.length} emails in "Other" category`,
    );

    if (otherEmails.length === 0) {
      return {
        newCategoriesCount: 0,
        totalCategoriesCount: 0,
        newCategories: [],
        reclassifyJobsQueued: 0,
      };
    }

    // Fetch existing categories
    const existingCategoryContexts = await this.contextRepository.find({
      where: {
        userId,
        contextKey: ContextKey.EMAIL_CATEGORY,
      },
    });

    const existingCategories = existingCategoryContexts.map((ctx) => {
      const parts = ctx.contextValue.split(" - ");
      return {
        name: parts[0].trim(),
        description: parts.length > 1 ? parts.slice(1).join(" - ").trim() : "",
      };
    });

    this.logger.log(
      `[GENERATE-CATEGORIES] Found ${existingCategories.length} existing categories`,
    );

    // Call LLM to generate new categories
    const newCategories = await this.llmService.generateCategoriesFromOther(
      otherEmails.map((e) => ({
        from: e.from || "",
        fromName: e.fromName,
        subject: e.subject || "",
        body: cleanEmailContent(
          e.body,
          null,
          BODY_PREVIEW_LENGTHS.BATCH_PREVIEW,
        ),
      })),
      existingCategories,
      undefined,
      userId,
    );

    if (newCategories.length === 0) {
      this.logger.log(
        `[GENERATE-CATEGORIES] No new categories generated from Other emails`,
      );
      return {
        newCategoriesCount: 0,
        totalCategoriesCount: existingCategories.length,
        newCategories: [],
        reclassifyJobsQueued: 0,
      };
    }

    // Save the new categories
    this.logger.log(
      `[GENERATE-CATEGORIES] Saving ${newCategories.length} new categories`,
    );

    for (const cat of newCategories) {
      const contextValue = `${cat.name} - ${cat.description}`;
      const newContext = this.contextRepository.create({
        userId,
        contextKey: ContextKey.EMAIL_CATEGORY,
        contextValue,
        source: Source.AUTOGENERATED,
      });
      await this.contextRepository.save(newContext);
    }

    // Queue refine-priority jobs for all emails in "Other" to reclassify them
    // with the new categories available
    this.logger.log(
      `[GENERATE-CATEGORIES] Queueing reclassification jobs for ${otherEmails.length} emails in "Other"`,
    );

    let reclassifyJobsQueued = 0;
    for (const email of otherEmails) {
      try {
        await this.boss.send(
          "refine-priority",
          { userId, emailId: email.id, forceRecalculate: true },
          {
            priority: getJobPriority("refine-priority-background", false),
            singletonKey: `refine-priority-reclassify-${email.id}`,
          },
        );
        reclassifyJobsQueued++;
      } catch (error) {
        this.logger.warn(
          `[GENERATE-CATEGORIES] Failed to queue reclassification job for email ${email.id}: ${getErrorMessage(error)}`,
        );
      }
    }

    this.logger.log(
      `[GENERATE-CATEGORIES] Queued ${reclassifyJobsQueued} reclassification jobs`,
    );

    const result = {
      newCategoriesCount: newCategories.length,
      totalCategoriesCount: existingCategories.length + newCategories.length,
      newCategories,
      reclassifyJobsQueued,
    };

    this.logger.log(
      `[GENERATE-CATEGORIES] Category generation complete: ${result.newCategoriesCount} new categories added (total: ${result.totalCategoriesCount}), ${reclassifyJobsQueued} emails queued for reclassification`,
    );

    return result;
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import {
  UserContext,
  ContextKey,
  Source,
} from "../database/entities/user-context.entity";
import { getErrorMessage } from "../types/common";
import { QUERY_LIMITS } from "../constants/query-limits";
import { ContextPiiRedactionService } from "./context-pii-redaction.service";

/**
 * Service for managing user context CRUD operations.
 * Handles creating, reading, updating, and deleting user context items.
 */
@Injectable()
export class ContextCrudService {
  private readonly logger = new Logger(ContextCrudService.name);

  constructor(
    @InjectRepository(UserContext)
    private contextRepository: Repository<UserContext>,
    private piiRedactionService: ContextPiiRedactionService,
  ) {}

  /**
   * Get all context items for a user
   */
  async getUserContext(userId: string): Promise<UserContext[]> {
    return this.contextRepository.find({
      where: { userId },
      order: { lastModified: "DESC" },
    });
  }

  /**
   * Create or update a context item
   */
  async createOrUpdateContext(
    userId: string,
    contextKey: ContextKey,
    contextValue: string,
    source: Source,
    priority?: number,
    explanation?: string,
    sourceThreadIds?: string[],
  ): Promise<UserContext> {
    const existing = await this.contextRepository.findOne({
      where: { userId, contextKey, contextValue },
    });

    // Validate context value is not blank
    const trimmedValue = (contextValue || "").trim();
    if (!trimmedValue || trimmedValue === "") {
      this.logger.warn(
        `[CONTEXT-ANALYSIS] Skipping blank context item: key=${contextKey}, value="${contextValue}"`,
      );
      throw new Error(`Context value cannot be blank for key ${contextKey}`);
    }

    // Apply PII redaction to protect user privacy
    const redactedValue = this.piiRedactionService.redactPII(trimmedValue);

    if (existing) {
      existing.lastModified = new Date();
      // Update with redacted value
      existing.contextValue = redactedValue;
      if (source === Source.USER_EDITED) {
        existing.source = Source.USER_EDITED;
      }
      if (priority !== undefined) {
        existing.priority = priority;
      }
      if (explanation !== undefined) {
        existing.explanation = explanation;
      }
      // Merge source thread IDs (don't replace, add new ones)
      if (sourceThreadIds && sourceThreadIds.length > 0) {
        const existingIds = existing.sourceThreadIds || [];
        const mergedIds = [...new Set([...existingIds, ...sourceThreadIds])];
        existing.sourceThreadIds = mergedIds;
      }
      return await this.contextRepository.save(existing);
    }

    const newContext = this.contextRepository.create({
      userId,
      contextKey,
      contextValue: redactedValue, // Use PII-redacted value
      source,
      priority,
      explanation,
      sourceThreadIds: sourceThreadIds || [],
    });
    return await this.contextRepository.save(newContext);
  }

  /**
   * Update an existing context item
   */
  async updateContext(
    contextId: string,
    userId: string,
    updates: Partial<UserContext>,
  ): Promise<UserContext | null> {
    updates.source = Source.USER_EDITED;
    await this.contextRepository.update({ contextId, userId }, updates);
    return this.contextRepository.findOne({ where: { contextId, userId } });
  }

  /**
   * Delete a context item
   */
  async deleteContext(contextId: string, userId: string): Promise<void> {
    await this.contextRepository.delete({ contextId, userId });
  }

  /**
   * Deduplicate existing autogenerated context by consolidating similar entries
   */
  async deduplicateExistingContext(userId: string): Promise<void> {
    try {
      const existingContext = await this.contextRepository.find({
        where: { userId, source: Source.AUTOGENERATED },
        order: { lastModified: "DESC" },
      });

      if (existingContext.length <= 1) {
        this.logger.log(
          `[CONTEXT-ANALYSIS] No duplicates to consolidate (${existingContext.length} autogenerated items)`,
        );
        return;
      }

      // Group by contextKey and deduplicate within each group
      const grouped = new Map<ContextKey, UserContext[]>();
      for (const ctx of existingContext) {
        if (!grouped.has(ctx.contextKey)) {
          grouped.set(ctx.contextKey, []);
        }
        grouped.get(ctx.contextKey)!.push(ctx);
      }

      let duplicatesRemoved = 0;
      const toDelete: string[] = [];

      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      for (const [key, contexts] of grouped.entries()) {
        if (contexts.length <= 1) continue;

        // Sort by lastModified (keep newest)
        contexts.sort(
          (a, b) => b.lastModified.getTime() - a.lastModified.getTime(),
        );

        // Keep the first (newest) and check others for similarity
        const keep = contexts[0];
        for (let i = 1; i < contexts.length; i++) {
          const current = contexts[i];
          try {
            if (
              this.piiRedactionService.areContextValuesSimilar(
                keep.contextValue,
                current.contextValue,
              )
            ) {
              this.logger.log(
                `[CONTEXT-ANALYSIS] Consolidating duplicate: "${current.contextValue.substring(0, QUERY_LIMITS.SUBSTRING_PREVIEW_LENGTH)}..." (keeping newer: "${keep.contextValue.substring(0, QUERY_LIMITS.SUBSTRING_PREVIEW_LENGTH)}...")`,
              );
              toDelete.push(current.contextId);
              duplicatesRemoved++;
            }
          } catch (similarityError) {
            this.logger.warn(
              `[CONTEXT-ANALYSIS] Error checking similarity during deduplication: ${getErrorMessage(similarityError)}`,
            );
            // Continue without marking as duplicate if similarity check fails
          }
        }
      }

      if (toDelete.length > 0) {
        await this.contextRepository.delete(toDelete);
        this.logger.log(
          `[CONTEXT-ANALYSIS] Removed ${duplicatesRemoved} duplicate context items`,
        );
      } else {
        this.logger.log(
          `[CONTEXT-ANALYSIS] No duplicates found in existing context`,
        );
      }
    } catch (error) {
      this.logger.error("Error deduplicating existing context:", error);
      // Don't fail the entire analysis if deduplication fails
    }
  }
}

import { isApiError, ApiError } from "../types/common";
import { HTTP_STATUS } from "../constants/http-status";

/**
 * Classifies errors and generates user-friendly error messages
 */
export function classifyContextAnalysisError(error: unknown): string {
  // Check for API errors (Gmail API, etc.)
  if (isApiError(error)) {
    const status =
      (error as any).response?.status || (error as any).status || error.code;

    // Authentication errors (401, 403)
    if (
      status === 401 ||
      status === 403 ||
      status === "401" ||
      status === "403"
    ) {
      return "Your email account needs to be reconnected. Please go to Settings and reconnect your account.";
    }

    // Rate limit errors (429)
    if (status === HTTP_STATUS.TOO_MANY_REQUESTS || status === "429") {
      return "Too many requests. Please try again in a few minutes.";
    }

    // Server errors (502, 503, 504) - Gmail API temporarily unavailable
    if (
      status === HTTP_STATUS.BAD_GATEWAY ||
      status === HTTP_STATUS.SERVICE_UNAVAILABLE ||
      status === HTTP_STATUS.GATEWAY_TIMEOUT ||
      status === "502" ||
      status === "503" ||
      status === "504"
    ) {
      return "Email API is temporarily unavailable. Please try again in a few minutes.";
    }

    // Other API errors
    const apiError = error as ApiError;
    const errorMessage =
      apiError.message || apiError.error || "Unknown API error";

    // Check for common Gmail API error patterns
    if (
      errorMessage.toLowerCase().includes("token") ||
      errorMessage.toLowerCase().includes("authentication") ||
      errorMessage.toLowerCase().includes("unauthorized")
    ) {
      return "Your email account needs to be reconnected. Please go to Settings and reconnect your account.";
    }

    if (
      errorMessage.toLowerCase().includes("rate limit") ||
      errorMessage.toLowerCase().includes("quota")
    ) {
      return "Too many requests. Please try again in a few minutes.";
    }

    // Generic API error
    return `Email API error: ${errorMessage}. Please try again later.`;
  }

  // Check for standard Error objects
  if (error instanceof Error) {
    const errorMessage = error.message.toLowerCase();

    // Check for authentication/token errors
    if (
      errorMessage.includes("token") ||
      errorMessage.includes("authentication") ||
      errorMessage.includes("unauthorized") ||
      (errorMessage.includes("missing") && errorMessage.includes("token")) ||
      errorMessage.includes("access token missing") ||
      errorMessage.includes("please log in again")
    ) {
      return "Your email account needs to be reconnected. Please go to Settings and reconnect your account.";
    }

    // Check for network errors
    if (
      errorMessage.includes("network") ||
      errorMessage.includes("connection") ||
      errorMessage.includes("timeout") ||
      errorMessage.includes("econnrefused") ||
      errorMessage.includes("enotfound")
    ) {
      return "Connection error. Please check your internet connection and try again.";
    }

    // Check for rate limit errors
    if (
      errorMessage.includes("rate limit") ||
      errorMessage.includes("quota") ||
      errorMessage.includes("too many requests")
    ) {
      return "Too many requests. Please try again in a few minutes.";
    }

    // Generic error message
    return `An unexpected error occurred: ${error.message}. Please try again later or contact support if the problem persists.`;
  }

  // Fallback for unknown error types
  return "An unexpected error occurred. Please try again later or contact support if the problem persists.";
}

import { Injectable, OnModuleInit, Logger, Inject } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import * as os from "os";
import PgBoss = require("pg-boss");
import { ContextService } from "./context.service";
import { getJobPriority } from "../queue/job-priorities";
import { writeAnalysisLog } from "./context-analysis-logger";
import { JobPerformanceTracker } from "../queue/job-performance-tracker";
import { CloudWatchService } from "../aws/cloudwatch.service";
import { MILLISECONDS } from "../constants/time-constants";
import { RETRY_CONSTANTS } from "../constants/service-constants";

interface FinalizationJob {
  userId: string;
  analysisRecordId: string;
  totalBatches: number;
  threadsInRange: number;
  sentEmailsData: number;
  analysisStats: {
    totalThreads: number;
    outboundEmails: number;
    threadsNeverOpened: number;
    threadsReadButNotReplied: number;
    vipContactsEvaluated: number;
  };
  trueVipContacts: Array<{
    emailKey: string;
    from: string;
    fromName?: string;
    threadCount: number;
  }>;
  userEmail?: string;
}

@Injectable()
export class ContextFinalizationProcessor implements OnModuleInit {
  private readonly logger = new Logger(ContextFinalizationProcessor.name);
  private readonly finalizationConcurrency: number;

  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    private contextService: ContextService,
    private configService: ConfigService,
    private cloudWatchService: CloudWatchService,
  ) {
    // Get CPU cores for optimal concurrency
    const cpuCores = os.cpus().length;
    // For finalization (mostly DB writes), use moderate concurrency
    const defaultConcurrency = Math.max(2, Math.min(cpuCores, 3));

    this.finalizationConcurrency = parseInt(
      this.configService.get<string>("JOB_FINALIZATION_CONCURRENCY") ||
        String(defaultConcurrency),
      10,
    );

    this.logger.log(
      `CPU cores: ${cpuCores}, finalize-context-analysis concurrency: ${this.finalizationConcurrency}`,
    );
  }

  async onModuleInit() {
    // Worker for finalizing context analysis - checks if batches are done and does post-processing
    this.logger.log(
      `Registering context-finalization worker with concurrency: ${this.finalizationConcurrency}`,
    );
    writeAnalysisLog(
      `===== Context Finalization Worker Registered ===== (concurrency: ${this.finalizationConcurrency})`,
      "log",
    );

    await this.boss.work(
      "finalize-context-analysis",
      { teamSize: this.finalizationConcurrency } as { teamSize: number },
      async (job) => {
        const jobData = job.data as FinalizationJob;
        const {
          userId,
          analysisRecordId,
          totalBatches,
          threadsInRange,
          sentEmailsData,
          analysisStats,
          trueVipContacts,
        } = jobData;
        const workerId = job.id || "unknown";
        const tracker = new JobPerformanceTracker(
          "finalize-context-analysis",
          workerId,
          this.cloudWatchService,
        );
        tracker.setMetadata({ userId, threadId: analysisRecordId });

        this.logger.log(
          `[Worker ${workerId}] Finalization job received for analysis ${analysisRecordId} (totalBatches from job data: ${totalBatches})`,
        );
        writeAnalysisLog(
          `[Worker ${workerId}] Finalization job received for analysis ${analysisRecordId} (totalBatches from job data: ${totalBatches})`,
          "log",
        );

        // CRITICAL: Get actual totalBatches from analysis record stats, not from job data
        // Job data might be stale or incorrect - always use the source of truth (DB stats)
        // Load analysis record first to get the actual totalBatches
        const analysisRecord =
          await this.contextService.getAnalysisRecordById(analysisRecordId);
        let actualTotalBatches = totalBatches;

        if (
          analysisRecord &&
          analysisRecord.stats &&
          analysisRecord.stats.totalBatches
        ) {
          actualTotalBatches = analysisRecord.stats.totalBatches as number;
          if (actualTotalBatches !== totalBatches) {
            this.logger.warn(
              `[Worker ${workerId}] ⚠️ totalBatches mismatch: job data says ${totalBatches}, but analysis stats says ${actualTotalBatches}. Using stats value.`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] ⚠️ totalBatches mismatch: job=${totalBatches}, stats=${actualTotalBatches}. Using stats.`,
              "warn",
            );
          }
        } else if (!analysisRecord || !analysisRecord.stats) {
          this.logger.error(
            `[Worker ${workerId}] ❌ ERROR: Analysis record ${analysisRecordId} not found or has no stats! Cannot proceed.`,
          );
          writeAnalysisLog(
            `[Worker ${workerId}] ❌ ERROR: Analysis record ${analysisRecordId} not found or has no stats!`,
            "error",
          );
          tracker.finish(
            new Error(
              `Analysis record ${analysisRecordId} not found or has no stats`,
            ),
          );
          return;
        } else {
          this.logger.warn(
            `[Worker ${workerId}] ⚠️ Analysis record exists but totalBatches not in stats. Using job data value: ${totalBatches}`,
          );
        }

        // CRITICAL: If totalBatches is 0, this is an invalid finalization job - batches were never enqueued
        // checkBatchesComplete will also check this, but we should fail fast here
        if (!actualTotalBatches || actualTotalBatches === 0) {
          this.logger.error(
            `[Worker ${workerId}] ❌ ERROR: Finalization job received with totalBatches = ${actualTotalBatches} (job data: ${totalBatches}). This should never happen - batches were never enqueued. checkBatchesComplete will return false.`,
          );
          writeAnalysisLog(
            `[Worker ${workerId}] ❌ ERROR: Finalization job with totalBatches = ${actualTotalBatches}. Batches were never enqueued.`,
            "error",
          );

          // Don't proceed - checkBatchesComplete will return false, and we'll re-queue
          // But log this as an error since it shouldn't happen
          tracker.finish(
            new Error(
              `Invalid finalization job: totalBatches is ${actualTotalBatches}`,
            ),
          );
          // Exit early - don't process (checkBatchesComplete will handle re-queueing)
          return;
        }

        try {
          // Check if all batches are complete using actual totalBatches from stats
          // CRITICAL: Use actualTotalBatches from stats, not from job data
          const allBatchesComplete =
            await this.contextService.checkBatchesComplete(
              analysisRecordId,
              actualTotalBatches, // Use actual value from stats, not job data
            );

          if (!allBatchesComplete) {
            // Not all batches are done yet - re-queue this job with a delay
            const completedBatches =
              await this.contextService.getCompletedBatchCount(
                analysisRecordId,
              );
            this.logger.log(
              `[Worker ${workerId}] Not all batches complete yet (${completedBatches}/${actualTotalBatches}). Re-queuing finalization job in 30 seconds.`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] Not all batches complete yet (${completedBatches}/${actualTotalBatches}). Re-queuing finalization job in 30 seconds.`,
              "log",
            );

            // Update job data with correct totalBatches before re-queuing
            const updatedJobData = {
              ...jobData,
              totalBatches: actualTotalBatches,
            };

            // Use a unique key with timestamp to avoid singleton conflict with current job
            const retryJobId = await this.boss.send(
              "finalize-context-analysis",
              updatedJobData,
              {
                priority: getJobPriority("finalize-context-analysis", false),
                singletonKey: `finalize-context-analysis-${analysisRecordId}-retry-${Date.now()}`,
                singletonMinutes: 1, // Short duration for retry jobs
                startAfter: new Date(
                  Date.now() +
                    RETRY_CONSTANTS.FINALIZATION_RETRY_DELAY_SECONDS *
                      MILLISECONDS.SECOND,
                ), // Retry in 10 seconds (faster retry)
              },
            );
            this.logger.log(
              `[Worker ${workerId}] Re-queued finalization job with ID: ${retryJobId}`,
            );
            writeAnalysisLog(
              `[Worker ${workerId}] Re-queued finalization job with ID: ${retryJobId}`,
              "log",
            );
            // Log even when re-queuing
            tracker.finish();
            return;
          }

          // All batches are complete - do the post-processing
          const completedBatches =
            await this.contextService.getCompletedBatchCount(analysisRecordId);
          this.logger.log(
            `[Worker ${workerId}] ✅ All batches complete (${completedBatches}/${actualTotalBatches}). Starting post-processing.`,
          );
          writeAnalysisLog(
            `[Worker ${workerId}] ✅ All batches complete (${completedBatches}/${actualTotalBatches}). Starting post-processing.`,
            "log",
          );

          await this.contextService.finalizeContextAnalysis(
            userId,
            analysisRecordId,
            actualTotalBatches, // Use actual value from stats
            threadsInRange,
            sentEmailsData,
            analysisStats,
            trueVipContacts,
          );

          this.logger.log(
            `[Worker ${workerId}] ✅ Completed context analysis for user ${userId} (analysis ${analysisRecordId}). All ${totalBatches} batches processed.`,
          );
          writeAnalysisLog(
            `[Worker ${workerId}] ✅ Completed context analysis for user ${userId} (analysis ${analysisRecordId}). All ${totalBatches} batches processed.`,
            "log",
          );
          tracker.finish();
        } catch (error: unknown) {
          const errorMessage =
            error instanceof Error ? error.message : String(error);
          const errorStack = error instanceof Error ? error.stack : undefined;
          this.logger.error(
            `[Worker ${workerId}] Failed to finalize context analysis for ${analysisRecordId}: ${errorMessage}`,
            errorStack || error,
          );
          writeAnalysisLog(
            `[Worker ${workerId}] Failed to finalize context analysis for ${analysisRecordId}: ${errorMessage}`,
            "error",
          );
          tracker.finish(error as Error);
          throw error;
        }
      },
    );

    this.logger.log("Context finalization worker registered successfully");
    writeAnalysisLog(
      "Context finalization worker registered successfully",
      "log",
    );
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { UsersService } from "../users/users.service";
import { EmailProviderManager } from "../emails/email-provider-manager.service";
import {
  EmailProvider,
  RawEmailMessage,
} from "../emails/interfaces/email-provider.interface";
import { QUERY_LIMITS } from "../constants/query-limits";
import { DAYS } from "../constants/time-constants";
import { GmailProvider } from "../emails/providers/gmail.provider";
import { GMAIL_LABELS } from "../constants/email-labels";
import {
  getErrorMessage,
  formatGaxiosError,
  getGaxiosErrorDetails,
} from "../types/common";
import { google, gmail_v1 } from "googleapis";

export interface ThreadEmail {
  id: string;
  from: string;
  fromName?: string;
  subject: string;
  body: string;
  htmlBody?: string;
  receivedAt: Date;
  isRead: boolean;
  labelIds?: string[];
}

export interface ThreadData {
  id: string;
  emails: ThreadEmail[];
  updatedAt: Date;
  starCount: number;
  isArchived: boolean;
}

export interface SentEmailData {
  id: string;
  body: string;
  htmlBody?: string;
  subject: string;
  receivedAt: Date;
}

/**
 * Service for fetching email data from email providers for context analysis.
 * Supports Gmail, Office365, and Zoho.
 * Handles provider-specific queries, pagination, and batch fetching of threads and sent emails.
 */
@Injectable()
export class ContextEmailDataService {
  private readonly logger = new Logger(ContextEmailDataService.name);

  constructor(
    private readonly usersService: UsersService,
    private readonly emailProviderManager: EmailProviderManager,
  ) {}

  /**
   * Get the primary email provider for a user
   */
  private async getProviderForUser(userId: string): Promise<EmailProvider> {
    const provider = await this.emailProviderManager.getPrimaryProvider(userId);
    if (!provider) {
      throw new Error(
        "No email provider connected - please connect Gmail, Office365, or Zoho",
      );
    }
    return provider;
  }

  /**
   * Get the provider type name for logging
   */
  private getProviderTypeName(provider: EmailProvider): string {
    // Use constructor name to identify provider type without instanceof checks
    const providerName = provider.constructor.name;
    if (providerName.includes("Gmail")) return "Gmail";
    if (providerName.includes("Office365") || providerName.includes("Office"))
      return "Office365";
    if (providerName.includes("Zoho")) return "Zoho";
    return providerName;
  }

  /**
   * Format date for Gmail search query (YYYY/MM/DD format)
   */
  private formatGmailDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}/${month}/${day}`;
  }

  /**
   * Format date for Office365 filter (ISO 8601 format)
   */
  private formatOffice365Date(date: Date): string {
    return date.toISOString();
  }

  /**
   * Format date for Zoho search (Unix timestamp in seconds)
   */
  private formatZohoDate(date: Date): string {
    return Math.floor(date.getTime() / 1000).toString();
  }

  /**
   * Build date range query for a provider
   */
  private buildDateRangeQuery(
    provider: EmailProvider,
    after: Date,
    before: Date,
  ): string {
    const providerName = provider.constructor.name;

    if (providerName.includes("Gmail")) {
      const gmailAfter = this.formatGmailDate(after);
      const gmailBefore = this.formatGmailDate(before);
      return `after:${gmailAfter} before:${gmailBefore}`;
    } else if (
      providerName.includes("Office365") ||
      providerName.includes("Office")
    ) {
      // Office365 uses $filter with receivedDateTime
      // Format: receivedDateTime ge {ISO_DATE} and receivedDateTime le {ISO_DATE}
      const afterISO = this.formatOffice365Date(after);
      const beforeISO = this.formatOffice365Date(before);
      // Note: searchEmails uses $search, but we'll pass the filter format
      // The Office365 provider will need to handle this
      // For now, return a format that Office365 can understand
      return `receivedDateTime ge ${afterISO} and receivedDateTime le ${beforeISO}`;
    } else if (providerName.includes("Zoho")) {
      // Zoho uses Unix timestamps
      const afterUnix = this.formatZohoDate(after);
      const beforeUnix = this.formatZohoDate(before);
      return `receivedTime >= ${afterUnix} AND receivedTime <= ${beforeUnix}`;
    }
    // Fallback: try Gmail format
    const gmailAfter = this.formatGmailDate(after);
    const gmailBefore = this.formatGmailDate(before);
    return `after:${gmailAfter} before:${gmailBefore}`;
  }

  /**
   * Build sent folder query for a provider
   */
  private buildSentFolderQuery(
    provider: EmailProvider,
    after: Date,
    before: Date,
  ): string {
    const providerName = provider.constructor.name;

    if (providerName.includes("Gmail")) {
      const gmailAfter = this.formatGmailDate(after);
      const gmailBefore = this.formatGmailDate(before);
      return `after:${gmailAfter} before:${gmailBefore} in:sent`;
    } else if (
      providerName.includes("Office365") ||
      providerName.includes("Office")
    ) {
      // Office365 sent items folder
      const afterISO = this.formatOffice365Date(after);
      const beforeISO = this.formatOffice365Date(before);
      return `receivedDateTime ge ${afterISO} and receivedDateTime le ${beforeISO} and isSent eq true`;
    } else if (providerName.includes("Zoho")) {
      // Zoho sent folder
      const afterUnix = this.formatZohoDate(after);
      const beforeUnix = this.formatZohoDate(before);
      return `receivedTime >= ${afterUnix} AND receivedTime <= ${beforeUnix} AND folderid:sent`;
    }
    // Fallback
    const gmailAfter = this.formatGmailDate(after);
    const gmailBefore = this.formatGmailDate(before);
    return `after:${gmailAfter} before:${gmailBefore} in:sent`;
  }

  /**
   * Group messages by threadId and convert to ThreadData[]
   */
  private groupMessagesByThread(
    messages: RawEmailMessage[],
    provider: EmailProvider,
  ): ThreadData[] {
    // Group messages by threadId
    const threadMap = new Map<string, RawEmailMessage[]>();
    for (const message of messages) {
      const { threadId } = message;
      if (!threadMap.has(threadId)) {
        threadMap.set(threadId, []);
      }
      threadMap.get(threadId)!.push(message);
    }

    // Convert to ThreadData[]
    const threads: ThreadData[] = [];
    for (const [threadId, threadMessages] of threadMap.entries()) {
      // Sort messages by receivedAt
      threadMessages.sort(
        (a, b) => a.receivedAt.getTime() - b.receivedAt.getTime(),
      );

      // Get thread-level info from the last message
      const lastMessage = threadMessages[threadMessages.length - 1];
      const updatedAt = lastMessage.receivedAt;
      const starCount = lastMessage.starCount || 0;

      // Determine if archived (for Gmail, check labelIds; for others, assume not archived if in inbox)
      let isArchived = false;
      const providerName = provider.constructor.name;
      if (providerName.includes("Gmail")) {
        const labelIds = lastMessage.labelIds || [];
        isArchived = !labelIds.includes(GMAIL_LABELS.INBOX);
      } else {
        // For Office365 and Zoho, we assume messages are not archived if they're in the search results
        // (this is a simplification - in reality, we'd need to check folderId)
        isArchived = false;
      }

      // Convert RawEmailMessage[] to ThreadEmail[]
      const threadEmails: ThreadEmail[] = threadMessages.map((msg) => ({
        id: msg.messageId,
        from: msg.from,
        fromName: msg.fromName,
        subject: msg.subject,
        body: msg.body,
        htmlBody: msg.htmlBody,
        receivedAt: msg.receivedAt,
        isRead: msg.isRead || false,
        labelIds: msg.labelIds,
      }));

      threads.push({
        id: threadId,
        emails: threadEmails,
        updatedAt,
        starCount,
        isArchived,
      });
    }

    return threads;
  }

  /**
   * Fetch threads from email provider for analysis
   * Supports Gmail, Office365, and Zoho
   */
  async fetchThreadsFromProvider(
    userId: string,
    after: Date,
    before: Date,
    limit: number = 400,
    onProgress?: (progress: {
      stage: "searching" | "fetching";
      progress: number; // 0-10 (out of 100 total)
      threadsFound?: number;
      threadsFetched?: number;
      totalToFetch?: number;
      findings?: string[];
    }) => Promise<void>,
  ): Promise<ThreadData[]> {
    const provider = await this.getProviderForUser(userId);
    const providerType = this.getProviderTypeName(provider);

    this.logger.log(
      `[CONTEXT-ANALYSIS] Fetching threads from ${providerType} for user ${userId}`,
    );

    // For Gmail, use the thread API directly (more efficient and reliable)
    if (provider instanceof GmailProvider) {
      return await this.fetchGmailThreads(
        userId,
        after,
        before,
        limit,
        onProgress,
      );
    }

    // For Office365 and Zoho, use searchEmails and group by threadId
    const dateQuery = this.buildDateRangeQuery(provider, after, before);
    this.logger.log(
      `[CONTEXT-ANALYSIS] ${providerType} search query: "${dateQuery}"`,
    );

    // Fetch more messages to account for filtering and grouping by thread
    const messages = await provider.searchEmails(userId, dateQuery, limit * 2);

    this.logger.log(
      `[CONTEXT-ANALYSIS] ${providerType} returned ${messages.length} messages`,
    );

    // Filter messages by date range (in case provider doesn't fully support date queries)
    const filteredMessages = messages.filter((msg) => {
      const { receivedAt } = msg;
      return receivedAt >= after && receivedAt <= before;
    });

    if (filteredMessages.length < messages.length) {
      this.logger.log(
        `[CONTEXT-ANALYSIS] ${providerType} filtered to ${filteredMessages.length} messages in date range (from ${messages.length} total)`,
      );
    }

    // Group messages by threadId
    const threads = this.groupMessagesByThread(filteredMessages, provider);

    // Limit to requested number of threads
    const limitedThreads = threads.slice(0, limit);

    this.logger.log(
      `[CONTEXT-ANALYSIS] Successfully fetched ${limitedThreads.length} threads from ${providerType}`,
    );

    return limitedThreads;
  }

  /**
   * Get just thread IDs from Gmail (quick operation for batching)
   * Returns thread IDs without fetching full thread data
   */
  async getThreadIdsFromGmail(
    userId: string,
    after: Date,
    before: Date,
    limit: number = 400,
  ): Promise<string[]> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken || !user?.googleCalendarRefreshToken) {
      throw new Error("Gmail access token missing - please log in again");
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const gmail = google.gmail({ version: "v1", auth: oauth2Client });

    const gmailAfter = this.formatGmailDate(after);
    const gmailBefore = this.formatGmailDate(before);
    const gmailQuery = `after:${gmailAfter} before:${gmailBefore}`;

    this.logger.log(
      `[CONTEXT-ANALYSIS] Gmail search query for thread IDs: "${gmailQuery}"`,
    );

    // Query Gmail for threads (just IDs, no full data)
    let allThreadIds: string[] = [];
    let nextPageToken: string | undefined = undefined;
    let pageCount = 0;
    const maxPages = 10;

    try {
      do {
        const response = await gmail.users.threads.list({
          userId: "me",
          maxResults: 400,
          q: gmailQuery,
          pageToken: nextPageToken,
        });

        const threads = response.data.threads || [];
        allThreadIds.push(
          ...threads.map((thread: { id: string }) => thread.id),
        );
        const { nextPageToken: newNextPageToken } = response.data;
        nextPageToken = newNextPageToken || undefined;
        pageCount++;

        if (pageCount >= maxPages) {
          this.logger.log(
            `[CONTEXT-ANALYSIS] Reached max pages (${maxPages}), stopping pagination`,
          );
          break;
        }
      } while (nextPageToken && allThreadIds.length < limit);
    } catch (error) {
      // Log detailed error info for Gmail API errors
      const errorDetails = getGaxiosErrorDetails(error);
      const formattedError = formatGaxiosError(error);
      this.logger.error(
        `[CONTEXT-ANALYSIS] Gmail API error in getThreadIdsFromGmail: ${formattedError}`,
      );
      this.logger.error(
        `[CONTEXT-ANALYSIS] Gmail API error details: ${JSON.stringify(errorDetails)}`,
      );
      // Re-throw with more context
      throw new Error(`Gmail API error fetching thread IDs: ${formattedError}`);
    }

    // Limit to requested number of threads
    allThreadIds = allThreadIds.slice(0, limit);

    this.logger.log(
      `[CONTEXT-ANALYSIS] Gmail returned ${allThreadIds.length} thread IDs`,
    );

    return allThreadIds;
  }

  /**
   * Get sent thread IDs (no date filter, most recent first)
   * Returns thread IDs for user-initiated sent threads
   * Works with Gmail, Office365, and Zoho
   */
  async getSentThreadIds(
    userId: string,
    limit: number = 100,
  ): Promise<string[]> {
    const provider = await this.getProviderForUser(userId);
    const providerType = this.getProviderTypeName(provider);

    // For Gmail, use the Gmail API directly
    if (providerType === "Gmail") {
      const user = await this.usersService.findOne(userId);
      if (
        !user?.googleCalendarAccessToken ||
        !user?.googleCalendarRefreshToken
      ) {
        throw new Error("Gmail access token missing - please log in again");
      }

      const oauth2Client = new google.auth.OAuth2(
        process.env.GOOGLE_CLIENT_ID,
        process.env.GOOGLE_CLIENT_SECRET,
        process.env.GOOGLE_REDIRECT_URI,
      );

      oauth2Client.setCredentials({
        access_token: user.googleCalendarAccessToken,
        refresh_token: user.googleCalendarRefreshToken,
      });

      const gmail = google.gmail({ version: "v1", auth: oauth2Client });

      // Query for sent threads (no date filter, sorted by most recent)
      const sentGmailQuery = "in:sent";

      this.logger.log(
        `[CONTEXT-ANALYSIS] Gmail sent threads query (no date filter): "${sentGmailQuery}"`,
      );

      // Query Gmail for sent threads (just IDs, no full data)
      let allSentThreadIds: string[] = [];
      let sentNextPageToken: string | undefined = undefined;
      let sentPageCount = 0;
      const maxPages = 10;

      try {
        do {
          const sentResponse = await gmail.users.threads.list({
            userId: "me",
            maxResults: 100,
            q: sentGmailQuery,
            pageToken: sentNextPageToken,
          });

          const threads = sentResponse.data.threads || [];
          allSentThreadIds.push(
            ...threads.map((thread: { id: string }) => thread.id),
          );
          sentNextPageToken = sentResponse.data.nextPageToken;
          sentPageCount++;

          this.logger.log(
            `[CONTEXT-ANALYSIS] Gmail sent threads page ${sentPageCount}: found ${threads.length} threads (total so far: ${allSentThreadIds.length})`,
          );

          // Stop when we have enough threads
          if (allSentThreadIds.length >= limit) break;
          // Max 10 pages
          if (sentPageCount >= maxPages) break;
        } while (sentNextPageToken && allSentThreadIds.length < limit);
      } catch (error) {
        // Log detailed error info for Gmail API errors
        const errorDetails = getGaxiosErrorDetails(error);
        const formattedError = formatGaxiosError(error);
        this.logger.error(
          `[CONTEXT-ANALYSIS] Gmail API error in getSentThreadIds: ${formattedError}`,
        );
        this.logger.error(
          `[CONTEXT-ANALYSIS] Gmail API error details: ${JSON.stringify(errorDetails)}`,
        );
        // Re-throw with more context
        throw new Error(
          `Gmail API error fetching sent thread IDs: ${formattedError}`,
        );
      }

      // Limit to requested number of sent threads
      allSentThreadIds = allSentThreadIds.slice(0, limit);

      this.logger.log(
        `[CONTEXT-ANALYSIS] Gmail returned ${allSentThreadIds.length} sent thread IDs (most recent)`,
      );

      return allSentThreadIds;
    }

    // For Office365 and Zoho, use searchEmails and extract thread IDs
    // Note: These providers may not support thread-based queries, so we'll use message-based approach
    const userForSentThreads = await this.usersService.findOne(userId);
    const userEmailForSentThreads = userForSentThreads?.email
      ? userForSentThreads.email.toLowerCase()
      : null;

    if (!userEmailForSentThreads) {
      this.logger.warn(
        `[CONTEXT-ANALYSIS] Cannot fetch sent threads - user email not found for ${providerType}`,
      );
      return [];
    }

    try {
      // Use searchEmails to find sent messages (no date filter)
      const sentMessages = await provider.searchEmails(
        userId,
        `from:${userEmailForSentThreads}`, // Search for emails from user (sent emails)
        limit * 2, // Get more messages to ensure we have enough threads
      );

      // Extract thread IDs from sent messages
      const threadIds = new Set<string>();
      sentMessages.forEach((msg: RawEmailMessage) => {
        if (msg.threadId) {
          threadIds.add(msg.threadId);
        }
      });

      const sentThreadIds = Array.from(threadIds).slice(0, limit);

      this.logger.log(
        `[CONTEXT-ANALYSIS] ${providerType} returned ${sentThreadIds.length} sent thread IDs (most recent) from ${sentMessages.length} messages`,
      );

      return sentThreadIds;
    } catch (error) {
      const errorMessage = getErrorMessage(error);
      this.logger.error(
        `[CONTEXT-ANALYSIS] Error fetching sent thread IDs from ${providerType}: ${errorMessage}`,
      );
      throw error;
    }
  }

  /**
   * Fetch full thread data for specific thread IDs
   */
  async fetchThreadsByIds(
    userId: string,
    threadIds: string[],
  ): Promise<ThreadData[]> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken || !user?.googleCalendarRefreshToken) {
      throw new Error("Gmail access token missing - please log in again");
    }

    const oauth2Client = new google.auth.OAuth2(
      process.env.GOOGLE_CLIENT_ID,
      process.env.GOOGLE_CLIENT_SECRET,
      process.env.GOOGLE_REDIRECT_URI,
    );

    oauth2Client.setCredentials({
      access_token: user.googleCalendarAccessToken,
      refresh_token: user.googleCalendarRefreshToken,
    });

    const gmail = google.gmail({ version: "v1", auth: oauth2Client });

    const threadsInRange: ThreadData[] = [];
    // Fetch 50 threads at a time
    const BATCH_SIZE = 50;

    for (let i = 0; i < threadIds.length; i += BATCH_SIZE) {
      const batch = threadIds.slice(i, i + BATCH_SIZE);
      const batchPromises = batch.map(async (threadId) => {
        try {
          const threadResponse = await gmail.users.threads.get({
            userId: "me",
            id: threadId,
            format: "full",
          });

          const thread = threadResponse.data;
          const messages = thread.messages || [];

          if (messages.length === 0) {
            return null;
          }

          // Convert Gmail thread to ThreadData
          const threadEmails: ThreadEmail[] = messages.map(
            (msg: gmail_v1.Schema$Message) => {
              const { payload } = msg;
              const headers = payload?.headers || [];
              const getHeader = (name: string) =>
                headers.find(
                  (h) => h.name?.toLowerCase() === name.toLowerCase(),
                )?.value || "";

              const from = getHeader("From");
              const fromMatch = from.match(/^(.+?)\s*<(.+?)>$/) || [
                null,
                from,
                from,
              ];
              const fromName = fromMatch[1]?.trim() || "";
              const fromEmail = fromMatch[2]?.trim() || from;

              // Extract body
              let body = "";
              let htmlBody = "";
              if (payload?.body?.data) {
                body = Buffer.from(payload.body.data, "base64").toString(
                  "utf-8",
                );
              } else if (payload?.parts) {
                for (const part of payload.parts) {
                  if (part.mimeType === "text/plain" && part.body?.data) {
                    body = Buffer.from(part.body.data, "base64").toString(
                      "utf-8",
                    );
                  } else if (part.mimeType === "text/html" && part.body?.data) {
                    htmlBody = Buffer.from(part.body.data, "base64").toString(
                      "utf-8",
                    );
                  }
                }
              }

              const labelIds = msg.labelIds || [];
              // isRead = true if the UNREAD label is NOT present
              // (Fixed: previously required INBOX label, but archived emails would show as unread)
              const isRead = !labelIds.includes("UNREAD");

              return {
                id: msg.id || "",
                from: fromEmail,
                fromName: fromName || undefined,
                subject: getHeader("Subject") || "",
                body,
                htmlBody: htmlBody || undefined,
                receivedAt: new Date(parseInt(msg.internalDate || "0")),
                isRead,
                labelIds,
              };
            },
          );

          // Sort by receivedAt
          threadEmails.sort(
            (a, b) => a.receivedAt.getTime() - b.receivedAt.getTime(),
          );

          const lastMessage = threadEmails[threadEmails.length - 1];
          const labelIds = lastMessage.labelIds || [];
          const isArchived = !labelIds.includes(GMAIL_LABELS.INBOX);
          const starCount = labelIds.filter((id) =>
            id.startsWith("STARRED"),
          ).length;

          return {
            id: threadId,
            emails: threadEmails,
            updatedAt: lastMessage.receivedAt,
            starCount,
            isArchived,
          };
        } catch (error) {
          this.logger.warn(
            `[CONTEXT-ANALYSIS] Failed to fetch thread ${threadId}: ${getErrorMessage(error)}`,
          );
          return null;
        }
      });

      const batchResults = await Promise.all(batchPromises);
      threadsInRange.push(
        ...(batchResults.filter((t) => t !== null) as ThreadData[]),
      );
    }

    return threadsInRange;
  }

