@Index(["userId", "threadId"], { unique: true })
// For inbox filtering
@Index(["userId", "starCount", "isArchived"])
// For triage/process filtering
@Index(["userId", "isArchived", "starCount"])
// For urgency-based queries
@Index(["userId", "urgencyScore"])
// For priority-based sorting
@Index(["userId", "priorityScore"])
export class EmailThread {
  @PrimaryGeneratedColumn("uuid")
  id: string;

  @Column({ type: "uuid" })
  userId: string;

  @Column({ comment: "Gmail thread ID" })
  threadId: string;

  @Column({
    type: "int",
    default: 0,
    comment:
      "0 = not starred, 1 = low importance, 2 = medium importance, 3 = high importance",
  })
  starCount: number;

  @Column({ default: false })
  isArchived: boolean;

  @Column({
    type: "float",
    default: 0,
    comment: "0-100 urgency score determined by LLM",
  })
  urgencyScore: number;

  @Column({
    type: "float",
    default: 0,
    nullable: true,
    comment:
      "Denormalized priority score for efficient sorting (calculated from priorityExplanation breakdown)",
  })
  priorityScore: number | null;

  @Column("text", {
    nullable: true,
    transformer: encryptedColumnTransformer,
    comment: "Explanation of why it's urgent",
  })
  urgencyExplanation: string | null;

  @Column("text", {
    nullable: true,
    transformer: encryptedColumnTransformer,
    comment: "User override reason",
  })
  urgencyOverrideReason: string | null;

  @Column({
    type: "text",
    nullable: true,
    transformer: encryptedJsonTransformer,
    comment: "Precomputed priority explanation (thread-level)",
  })
  priorityExplanation: {
    score: number;
    dimensions: {
      urgency: { score: number; reasons: string[] };
      goalAlignment: { score: number; reasons: string[] };
      vipContact: { score: number; reasons: string[] };
      sentiment: { score: number; type: string; reasons: string[] };
    };
    breakdown: Array<{ factor: string; value: number; description: string }>;
    calculatedAt?: string; // ISO timestamp when priority was last calculated
  } | null;

  @Column({
    default: false,
    comment:
      "Flag to indicate LLM priority is being calculated for this thread",
  })
  isProcessingPriority: boolean;

  @Column("text", { nullable: true, transformer: encryptedJsonTransformer })
  githubMetadata: {
    links: Array<{
      type: "issue" | "pr";
      repo: string;
      owner: string;
      number: number;
      url: string;
      status?: {
        state: string;
        title?: string;
        labels?: Array<{ name: string; color: string }>;
        assignees?: Array<{ login: string; avatar_url: string }>;
        project?: string;
        reviewStatus?: "approved" | "changes_requested" | "pending" | null;
        commentsCount?: number;
        mergeable?: boolean;
        merged?: boolean;
      };
      fetchedAt?: string;
    }>;
    // GitHub issue/PR metadata
  } | null;

  @CreateDateColumn()
  createdAt: Date;

  @UpdateDateColumn()
  updatedAt: Date;

  @Column({
    type: "timestamp",
    nullable: true,
    comment: "Last time this thread was checked against Gmail",
  })
  lastCheckedAt: Date | null;

  @Column({ default: false })
  isSnoozed: boolean;

  @Column({ type: "timestamp", nullable: true })
  snoozeUntil: Date | null;

  @Column({
    type: "timestamp",
    nullable: true,
    comment:
      "Last time user performed an operation (archive, snooze, star) on this thread in BearlyMail. " +
      "Used to prevent sync from overriding user actions - sync should only update status if new emails arrived after this timestamp.",
  })
  lastUserOperationAt: Date | null;

  @Column("text", {
    nullable: true,
    transformer: encryptedColumnTransformer,
    comment:
      "Email category for grouping (e.g., Newsletters, Customer Support)",
  })
  category: string | null;

  @Column("text", {
    nullable: true,
    transformer: encryptedColumnTransformer,
    comment:
      "Explanation of why this category was chosen (especially useful for Other)",
  })
  categoryExplanation: string | null;

  @Column({
    type: "uuid",
    nullable: true,
    comment:
      "Proto category ID for emails in Other that have a proto category suggestion",
  })
  protoCategoryId: string | null;

  @ManyToOne(() => ProtoCategory, { nullable: true })
  @JoinColumn({ name: "protoCategoryId" })
  protoCategory: ProtoCategory | null;

  @ManyToOne(() => User)
  @JoinColumn({ name: "userId" })
  user: User;

  @OneToMany(() => Email, (email) => email.thread)
  emails: Email[];
}

import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, IsNull, Not } from "typeorm";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { EmailProviderManager } from "./email-provider-manager.service";
import { BlockedSendersService } from "../blocked-senders/blocked-senders.service";
import { QUERY_LIMITS } from "../constants/query-limits";
import { isError } from "../types/common";
import PgBoss = require("pg-boss");
import { getJobPriority } from "../queue/job-priorities";

export interface ThreadLookupResult {
  found: boolean;
  threadId: string;
  thread: {
    id: string;
    threadId: string;
    starCount: number;
    isArchived: boolean;
    priorityScore: number | null;
    updatedAt: Date;
  } | null;
  emails: Array<{
    id: string;
    subject: string;
    from: string;
    receivedAt: Date;
    isSnoozed: boolean;
    snoozeUntil: Date | null;
    isBatched: boolean;
    batchReleaseAt: Date | null;
  }>;
  visibility: {
    wouldShowInTriage: boolean;
    wouldShowInAction: boolean;
    wouldShowInFollowUp: boolean;
  };
  reasons: string[];
}

@Injectable()
export class EmailDebugService {
  private readonly logger = new Logger(EmailDebugService.name);

  constructor(
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @Inject(forwardRef(() => EmailProviderManager))
    private emailProviderManager: EmailProviderManager,
    @Inject("PG_BOSS") private readonly boss: PgBoss,
    private blockedSendersService: BlockedSendersService,
  ) {}

  /**
   * Debug endpoint to find missing starred threads
   * Compares Gmail starred emails with what's in our DB
   */
  // eslint-disable-next-line max-lines-per-function
  async debugStarredThreads(
    userId: string,
    getInbox: (
      userId: string,
      includeBatched: boolean,
      mode: "triage" | "action" | "follow-up",
    ) => Promise<Email[]>,
  ): Promise<{
    gmail: {
      starredThreadCount: number;
      starredThreadIds: string[];
      error?: string;
    };
    database: {
      starredThreadCount: number;
      starredEmailCount: number;
    };
    actionTabResults: number;
    comparison: {
      inGmailNotInDb: string[];
      inDbNotInGmail: string[];
      inDbButArchived: string[];
    };
    starredThreads: Array<{
      threadId: string;
      starCount: number;
      isArchived: boolean;
      isSnoozed: boolean;
      emailCount: number;
      latestSubject: string;
      latestFrom: string;
      issues: string[];
      inGmail: boolean;
    }>;
    missingFromProcessTab: Array<{
      threadId: string;
      reason: string;
      details: Record<string, unknown>;
    }>;
  }> {
    // 1. Search Gmail for starred emails in inbox
    let gmailStarredThreadIds: string[] = [];
    let gmailError: string | undefined;

    try {
      const provider =
        await this.emailProviderManager.getPrimaryProvider(userId);
      if (provider) {
        // Search for starred emails in inbox
        const starredEmails = await provider.searchEmails(
          userId,
          "is:starred is:inbox",
          100,
        );
        // Get unique thread IDs
        gmailStarredThreadIds = [
          ...new Set(starredEmails.map((e) => e.threadId)),
        ];
        this.logger.debug(
          `Gmail search found ${starredEmails.length} starred emails in ${gmailStarredThreadIds.length} threads`,
        );
      } else {
        gmailError = "No email provider connected";
      }
    } catch (error: unknown) {
      gmailError = isError(error) ? error.message : "Failed to search Gmail";
      this.logger.error("Error searching Gmail for starred emails:", error);
    }

    // 2. Get all starred threads from email_threads table
    const allStarredThreads = await this.emailThreadRepository
      .createQueryBuilder("thread")
      .select(["thread.threadId", "thread.starCount", "thread.isArchived"])
      .where("thread.userId = :userId", { userId })
      .andWhere("thread.starCount > 0")
      .getMany();

    // dbStarredThreadIds used for comparison below via dbThreadIds

    // 3. Get emails in starred threads
    const starredThreadIds = allStarredThreads.map((t) => t.id);
    const emailsInStarredThreads: Email[] =
      starredThreadIds.length > 0
        ? await this.emailRepository
            .createQueryBuilder("email")
            .where("email.userId = :userId", { userId })
            .andWhere('email."emailThreadId" IN (:...threadIds)', {
              threadIds: starredThreadIds,
            })
            .getMany()
        : [];

    // 4. Run the actual getInbox query for action mode to see what's returned
    const actionTabEmails: Email[] = await getInbox(userId, false, "action");

    // 6. Compare Gmail vs DB
    const dbThreadIds = allStarredThreads.map((t) => t.threadId);
    const inGmailNotInDb = gmailStarredThreadIds.filter(
      (id) => !dbThreadIds.includes(id),
    );
    const inDbNotInGmail = dbThreadIds.filter(
      (id) => !gmailStarredThreadIds.includes(id),
    );
    const inDbButArchived = allStarredThreads
      .filter((t) => t.isArchived)
      .map((t) => t.threadId);

    // 7. Identify issues for each starred thread
    const threadDetails = await Promise.all(
      allStarredThreads.map(async (thread) => {
        const threadEmails = emailsInStarredThreads.filter(
          (e) => e.emailThreadId === thread.id,
        );
        const latestEmail = threadEmails.sort(
          (a, b) =>
            new Date(b.receivedAt).getTime() - new Date(a.receivedAt).getTime(),
        )[0];

        const issues: string[] = [];
        const inGmail = gmailStarredThreadIds.includes(thread.threadId);

        // Check if archived
        if (thread.isArchived) {
          issues.push("Thread is ARCHIVED");
        }

        // Check if in Gmail
        if (!inGmail && !gmailError) {
          issues.push("NOT STARRED IN GMAIL (or not in inbox)");
        }

        // Check if all emails are snoozed
        const allSnoozed = threadEmails.every(
          (e) =>
            e.isSnoozed &&
            e.snoozeUntil &&
            new Date(e.snoozeUntil) > new Date(),
        );
        if (allSnoozed && threadEmails.length > 0) {
          issues.push("All emails in thread are SNOOZED");
        }

        // Check if thread appears in action tab results
        const inActionTab = actionTabEmails.some(
          (e) => e.threadId === thread.threadId,
        );
        if (!inActionTab && issues.length === 0) {
          issues.push("NOT IN ACTION TAB (unknown reason)");
        }

        return {
          threadId: `${thread.threadId.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
          starCount: thread.starCount,
          isArchived: thread.isArchived,
          isSnoozed: allSnoozed,
          emailCount: threadEmails.length,
          latestSubject:
            latestEmail?.subject?.substring(
              0,
              QUERY_LIMITS.SUBSTRING_PREVIEW_LENGTH,
            ) || "N/A",
          latestFrom: latestEmail?.fromName || latestEmail?.from || "N/A",
          issues,
          inGmail,
        };
      }),
    );

    // 8. Identify threads missing from process tab
    const missingFromProcessTab = threadDetails
      .filter((t) => t.issues.length > 0)
      .map((t) => ({
        threadId: t.threadId,
        reason: t.issues.join(", "),
        details: {
          starCount: t.starCount,
          isArchived: t.isArchived,
          isSnoozed: t.isSnoozed,
          emailCount: t.emailCount,
          subject: t.latestSubject,
          from: t.latestFrom,
          inGmail: t.inGmail,
        },
      }));

    return {
      gmail: {
        starredThreadCount: gmailStarredThreadIds.length,
        starredThreadIds: gmailStarredThreadIds.map(
          (id) => `${id.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        ),
        error: gmailError,
      },
      database: {
        starredThreadCount: allStarredThreads.length,
        starredEmailCount: emailsInStarredThreads.length,
      },
      actionTabResults: actionTabEmails.length,
      comparison: {
        inGmailNotInDb: inGmailNotInDb.map(
          (id) => `${id.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        ),
        inDbNotInGmail: inDbNotInGmail.map(
          (id) => `${id.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        ),
        inDbButArchived: inDbButArchived.map(
          (id) => `${id.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        ),
      },
      starredThreads: threadDetails,
      missingFromProcessTab,
    };
  }

  /**
   * Debug endpoint to find emails without emailThreadId (orphan emails)
   */
  async debugOrphanEmails(userId: string): Promise<{
    totalEmailsInDb: number;
    emailsWithThreadId: number;
    orphanEmails: number;
    orphanEmailDetails: Array<{
      id: string;
      threadId: string;
      emailThreadId: string | null;
      subject: string;
      from: string;
      receivedAt: Date;
    }>;
    threadsInDb: number;
    threadsWithoutEmails: Array<{
      id: string;
      threadId: string;
      starCount: number;
      isArchived: boolean;
    }>;
  }> {
    // Count total emails
    const totalEmailsInDb = await this.emailRepository.count({
      where: { userId },
    });

    // Count emails with emailThreadId set
    const emailsWithThreadId = await this.emailRepository.count({
      where: { userId, emailThreadId: Not(IsNull()) },
    });

    // Get orphan emails (no emailThreadId)
    const orphanEmailsList = await this.emailRepository.find({
      where: { userId, emailThreadId: IsNull() },
      select: [
        "id",
        "threadId",
        "emailThreadId",
        "subject",
        "from",
        "receivedAt",
      ],
      // Limit to 50 for performance
      take: QUERY_LIMITS.MAX_RESULTS_DEFAULT,
    });

    // Get all threads
    const allThreads = await this.emailThreadRepository.find({
      where: { userId },
    });

    // Find threads that have no emails pointing to them
    const threadIdsWithEmails = await this.emailRepository
      .createQueryBuilder("email")
      .select('DISTINCT email."emailThreadId"', "emailThreadId")
      .where("email.userId = :userId", { userId })
      .andWhere('email."emailThreadId" IS NOT NULL')
      .getRawMany();

    const threadIdsWithEmailsSet = new Set(
      threadIdsWithEmails.map((r) => r.emailThreadId),
    );

    const threadsWithoutEmails = allThreads
      .filter((t) => !threadIdsWithEmailsSet.has(t.id))
      .map((t) => ({
        id: `${t.id.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        threadId: `${t.threadId.substring(0, QUERY_LIMITS.THREAD_ID_PREVIEW)}...`,
        starCount: t.starCount,
        isArchived: t.isArchived,
      }));

    return {
      totalEmailsInDb,
      emailsWithThreadId,
      orphanEmails: totalEmailsInDb - emailsWithThreadId,
      orphanEmailDetails: orphanEmailsList.map((e) => ({
        id: e.id,
        threadId: e.threadId || "",
        emailThreadId: e.emailThreadId,
        subject: e.subject || "",
        from: e.from || "",
        receivedAt: e.receivedAt,
      })),
      threadsInDb: allThreads.length,
      threadsWithoutEmails,
    };
  }

  /**
   * Fix orphan emails by linking them to their threads
   */
  async fixOrphanEmails(userId: string): Promise<{
    fixed: number;
    errors: string[];
  }> {
    const errors: string[] = [];
    let fixed = 0;

    // Get all orphan emails
    const orphanEmails = await this.emailRepository.find({
      where: { userId, emailThreadId: IsNull() },
    });

    this.logger.log(`Found ${orphanEmails.length} orphan emails to fix`);

    for (const email of orphanEmails) {
      try {
        // Check if a thread already exists for this Gmail threadId
        let thread = await this.emailThreadRepository.findOne({
          where: { userId, threadId: email.threadId },
        });

        if (!thread) {
          // Create a new thread
          thread = this.emailThreadRepository.create({
            userId,
            threadId: email.threadId,
            starCount: 0,
            isArchived: false,
          });
          thread = await this.emailThreadRepository.save(thread);
          this.logger.log(
            `Created new thread ${thread.id} for Gmail thread ${email.threadId}`,
          );
        }

        // Link email to thread
        await this.emailRepository.update(email.id, {
          emailThreadId: thread.id,
        });
        fixed++;
      } catch (err) {
        const errorMsg = `Failed to fix email ${email.id}: ${isError(err) ? err.message : "Unknown error"}`;
        this.logger.error(errorMsg);
        errors.push(errorMsg);
      }
    }

    this.logger.log(`Fixed ${fixed} orphan emails, ${errors.length} errors`);

    return { fixed, errors };
  }

  /**
   * Fix stuck calculating threads by resetting the flag and re-queuing jobs
   */
  async fixStuckCalculatingThreads(userId: string): Promise<{
    fixed: number;
    requeued: number;
    errors: string[];
  }> {
    this.logger.log(
      `Checking for stuck calculating threads for user ${userId}`,
    );

    // Find threads that have been in "calculating" state for more than 10 minutes
    // Priority is now thread-level, so check threads instead of emails
    const stuckThreads = await this.emailThreadRepository.find({
      where: {
        userId,
        isProcessingPriority: true,
      },
      select: ["id", "threadId", "updatedAt", "priorityExplanation"],
    });

    // Filter to only those that are actually stuck (older than 10 minutes or no breakdown)
    const actuallyStuck = stuckThreads.filter((thread) => {
      const threadAge = Date.now() - new Date(thread.updatedAt).getTime();
      const hasBreakdown =
        thread.priorityExplanation?.breakdown &&
        thread.priorityExplanation.breakdown.length > 0;
      return threadAge > 10 * 60 * 1000 || !hasBreakdown;
    });

    this.logger.log(
      `Found ${actuallyStuck.length} stuck calculating threads (out of ${stuckThreads.length} total)`,
    );

    let fixed = 0;
    let requeued = 0;
    const errors: string[] = [];

    for (const thread of actuallyStuck) {
      try {
        // Get an email from this thread to use for the job
        const email = await this.emailRepository.findOne({
          where: { emailThreadId: thread.id, userId },
          select: ["id"],
        });

        if (!email) {
          // No email found for this thread, just reset the flag
          await this.emailThreadRepository.update(
            { id: thread.id },
            { isProcessingPriority: false },
          );
          fixed++;
          continue;
        }

        // Reset the flag first
        await this.emailThreadRepository.update(
          { id: thread.id },
          { isProcessingPriority: false },
        );

        // Re-queue priority calculation job
        await this.boss.send(
          "refine-priority",
          { userId, emailId: email.id },
          {
            priority: getJobPriority("refine-priority-background", false),
            singletonKey: `refine-priority-thread-${thread.id}`,
            singletonMinutes: 1,
          },
        );

        fixed++;
        requeued++;
      } catch (error) {
        const errorMsg = `Failed to fix thread ${thread.threadId}: ${isError(error) ? error.message : "Unknown error"}`;
        this.logger.error(errorMsg);
        errors.push(errorMsg);
      }
    }

    this.logger.log(
      `Fixed ${fixed} stuck threads, re-queued ${requeued} jobs, ${errors.length} errors`,
    );

    return { fixed, requeued, errors };
  }

  /**
   * Look up a thread by its Gmail threadId and explain why it may not be showing
   * in the current inbox view
   */
  async lookupThread(
    userId: string,
    threadId: string,
  ): Promise<ThreadLookupResult> {
    this.logger.log(`Looking up thread ${threadId} for user ${userId}`);

    const reasons: string[] = [];

    // 1. Find the thread in the database
    const thread = await this.emailThreadRepository.findOne({
      where: { userId, threadId },
    });

    if (!thread) {
      return {
        found: false,
        threadId,
        thread: null,
        emails: [],
        visibility: {
          wouldShowInTriage: false,
          wouldShowInAction: false,
          wouldShowInFollowUp: false,
        },
        reasons: [
          "Thread not found in database - it may not have been synced yet",
        ],
      };
    }

    // 2. Get all emails in this thread
    const emails = await this.emailRepository.find({
      where: { userId, emailThreadId: thread.id },
      order: { receivedAt: "DESC" },
    });

    if (emails.length === 0) {
      reasons.push(
        "Thread exists but has no emails linked to it (orphan thread)",
      );
    }

    // 3. Check thread-level conditions
    if (thread.isArchived) {
      reasons.push(
        "Thread is ARCHIVED - archived threads don't show in any inbox view",
      );
    }

    // 4. Check email-level conditions for the latest email
    const latestEmail = emails[0];
    if (latestEmail) {
      // Check if sender is blocked
      const isBlocked = await this.blockedSendersService.isSenderBlocked(
        userId,
        latestEmail.from || "",
      );
      if (isBlocked) {
        reasons.push(`Sender "${latestEmail.from}" is BLOCKED`);
      }

      // Check if snoozed
      if (
        latestEmail.isSnoozed &&
        latestEmail.snoozeUntil &&
        new Date(latestEmail.snoozeUntil) > new Date()
      ) {
        reasons.push(
          `Email is SNOOZED until ${new Date(latestEmail.snoozeUntil).toISOString()}`,
        );
      }

      // Check if batched
      if (
        latestEmail.isBatched &&
        latestEmail.batchReleaseAt &&
        new Date(latestEmail.batchReleaseAt) > new Date()
      ) {
        reasons.push(
          `Email is BATCHED and will be released at ${new Date(latestEmail.batchReleaseAt).toISOString()}`,
        );
      }
    }

    // 5. Determine visibility in each mode
    const isNotArchived = !thread.isArchived;
    const hasNoBlockedSender =
      !latestEmail ||
      !(await this.blockedSendersService.isSenderBlocked(
        userId,
        latestEmail.from || "",
      ));
    const isNotSnoozed =
      !latestEmail ||
      !latestEmail.isSnoozed ||
      !latestEmail.snoozeUntil ||
      new Date(latestEmail.snoozeUntil) <= new Date();
    const isNotBatched =
      !latestEmail ||
      !latestEmail.isBatched ||
      !latestEmail.batchReleaseAt ||
      new Date(latestEmail.batchReleaseAt) <= new Date();

    const baseConditionsMet =
      isNotArchived && hasNoBlockedSender && isNotSnoozed && isNotBatched;

    // Triage: starCount = 0
    const wouldShowInTriage = baseConditionsMet && thread.starCount === 0;

    // Action: starCount > 0
    const wouldShowInAction = baseConditionsMet && thread.starCount > 0;

    // Follow-up: starCount > 0 (additional filtering for user_sent_last happens elsewhere)
    const wouldShowInFollowUp = baseConditionsMet && thread.starCount > 0;

    // 6. Add mode-specific reasons
    if (baseConditionsMet) {
      if (thread.starCount === 0) {
        reasons.push(
          "Thread has starCount=0, so it would appear in TRIAGE mode (not Action/Follow-up)",
        );
      } else {
        reasons.push(
          `Thread has starCount=${thread.starCount}, so it would appear in ACTION/FOLLOW-UP mode (not Triage)`,
        );
      }
    }

    if (reasons.length === 0) {
      reasons.push("Thread should be visible - no issues detected");
    }

    return {
      found: true,
      threadId,
      thread: {
        id: thread.id,
        threadId: thread.threadId,
        starCount: thread.starCount,
        isArchived: thread.isArchived,
        priorityScore: thread.priorityScore,
        updatedAt: thread.updatedAt,
      },
      emails: emails.map((e) => ({
        id: e.id,
        subject: e.subject || "",
        from: e.from || "",
        receivedAt: e.receivedAt,
        isSnoozed: e.isSnoozed,
        snoozeUntil: e.snoozeUntil,
        isBatched: e.isBatched,
        batchReleaseAt: e.batchReleaseAt,
      })),
      visibility: {
        wouldShowInTriage,
        wouldShowInAction,
        wouldShowInFollowUp,
      },
      reasons,
    };
  }
}

import { Injectable, Inject, forwardRef, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { google } from "googleapis";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { EmailProviderManager } from "./email-provider-manager.service";
import { UsersService } from "../users/users.service";
import { EncryptionHelper } from "../encryption/encryption.helper";
import { isError } from "../types/common";

@Injectable()
export class EmailGmailService {
  private readonly logger = new Logger(EmailGmailService.name);

  constructor(
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @Inject(forwardRef(() => EmailProviderManager))
    private emailProviderManager: EmailProviderManager,
    private usersService: UsersService,
  ) {}

  /**
   * Fetch current star status from Gmail for debugging
   * Returns both DB starCount and Gmail star status for comparison
   */
  async getGmailStarStatus(
    userId: string,
    emailId: string,
    getEmailById: (userId: string, emailId: string) => Promise<Email>,
  ): Promise<{
    dbStarCount: number;
    gmailStarStatus: {
      isStarred: boolean;
      starCount: number;
      threadId: string;
      latestMessageLabelIds: string[];
      messageStarStatuses: Array<{
        messageIndex: number;
        messageId: string;
        isStarred: boolean;
        labelIds: string[];
      }>;
      isAnyStarred: boolean;
      starredMessageCount: number;
      error?: string;
    };
    threadInfo: {
      threadId: string;
      emailThreadId: string | null;
    };
  }> {
    const email = await getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Get thread info from DB
    let dbStarCount = 0;
    if (email.emailThreadId) {
      const thread = await this.emailThreadRepository.findOne({
        where: { id: email.emailThreadId, userId },
      });
      dbStarCount = thread?.starCount || 0;
    }

    // Fetch from Gmail
    let gmailStarStatus = {
      isStarred: false,
      starCount: 0,
      threadId: email.threadId,
      latestMessageLabelIds: [] as string[],
      messageStarStatuses: [] as Array<{
        messageIndex: number;
        messageId: string;
        isStarred: boolean;
        labelIds: string[];
      }>,
      isAnyStarred: false,
      starredMessageCount: 0,
      error: undefined as string | undefined,
    };

    try {
      const user = await this.usersService.findOne(userId);
      if (!user?.googleCalendarAccessToken) {
        gmailStarStatus.error = "User not connected to Gmail";
        return {
          dbStarCount,
          gmailStarStatus,
          threadInfo: {
            threadId: email.threadId,
            emailThreadId: email.emailThreadId,
          },
        };
      }

      const oauth2Client = new google.auth.OAuth2(
        process.env.GOOGLE_CLIENT_ID,
        process.env.GOOGLE_CLIENT_SECRET,
        process.env.GOOGLE_REDIRECT_URI,
      );
      oauth2Client.setCredentials({
        access_token: user.googleCalendarAccessToken,
        refresh_token: user.googleCalendarRefreshToken,
      });

      const gmail = google.gmail({ version: "v1", auth: oauth2Client });

      // Get thread from Gmail
      const threadData = await gmail.users.threads.get({
        userId: "me",
        id: email.threadId,
        format: "metadata",
        metadataHeaders: ["Subject", "From"],
      });

      const thread = threadData.data;
      if (thread.messages && thread.messages.length > 0) {
        // Check all messages in the thread for STARRED label
        const messageStarStatuses = thread.messages.map((msg, idx) => {
          const labelIds = msg.labelIds || [];
          const isStarred = labelIds.includes("STARRED");
          return {
            messageIndex: idx,
            messageId: msg.id || "",
            isStarred,
            labelIds,
          };
        });

        const isAnyStarred = messageStarStatuses.some((m) => m.isStarred);
        const starredMessageCount = messageStarStatuses.filter(
          (m) => m.isStarred,
        ).length;

        // Get the latest message (last in array) for backward compatibility
        const latestMessage = thread.messages[thread.messages.length - 1];
        const latestLabelIds = latestMessage.labelIds || [];

        gmailStarStatus = {
          isStarred: isAnyStarred, // Use isAnyStarred instead of just latest message
          starCount: isAnyStarred ? 3 : 0,
          threadId: email.threadId,
          latestMessageLabelIds: latestLabelIds,
          messageStarStatuses,
          isAnyStarred,
          starredMessageCount,
          error: undefined,
        };
      } else {
        gmailStarStatus.error = "Thread has no messages";
      }
    } catch (error) {
      gmailStarStatus.error = isError(error)
        ? error.message
        : "Unknown error fetching from Gmail";
      this.logger.error("Error fetching Gmail star status:", error);
    }

    return {
      dbStarCount,
      gmailStarStatus,
      threadInfo: {
        threadId: email.threadId,
        emailThreadId: email.emailThreadId,
      },
    };
  }

  /**
   * Fetch current labels from Gmail for a specific message for debugging
   * Returns both DB labels and Gmail labels for comparison
   */
  async getGmailLabels(
    userId: string,
    emailId: string,
    getEmailById: (userId: string, emailId: string) => Promise<Email>,
  ): Promise<{
    dbLabels: {
      raw: string[] | null;
      names: string[] | null;
    };
    gmailLabels: {
      labelIds: string[];
      labelNames: string[];
      messageId: string;
      error?: string;
    };
    labelMapping: Array<{ id: string; name: string }>;
    emailInfo: {
      id: string;
      messageId: string;
      threadId: string;
    };
  }> {
    const email = await getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Get labels from DB (need to query raw encrypted value)
    // TypeORM automatically decrypts when using findOne, so we need to use raw query
    let dbLabelsRaw: string[] | null = null;
    const emailWithLabels = await this.emailRepository.query(
      `SELECT labels FROM emails WHERE id = $1 AND "userId" = $2`,
      [email.id, userId],
    );

    if (
      emailWithLabels &&
      emailWithLabels.length > 0 &&
      emailWithLabels[0].labels
    ) {
      try {
        const decryptedLabels = EncryptionHelper.decrypt(
          emailWithLabels[0].labels,
        );
        if (decryptedLabels) {
          dbLabelsRaw = JSON.parse(decryptedLabels);
        }
      } catch (error) {
        this.logger.warn(
          `Failed to decrypt/parse labels for email ${email.id}:`,
          error,
        );
        dbLabelsRaw = null;
      }
    }

    // Fetch from Gmail
    let gmailLabelIds: string[] = [];
    let gmailLabelNames: string[] = [];
    let labelMapping: Array<{ id: string; name: string }> = [];
    let gmailError: string | undefined;

    try {
      const user = await this.usersService.findOne(userId);
      if (!user?.googleCalendarAccessToken) {
        gmailError = "User not connected to Gmail";
        return {
          dbLabels: {
            raw: dbLabelsRaw,
            names: dbLabelsRaw, // If stored as names, they're already names
          },
          gmailLabels: {
            labelIds: [],
            labelNames: [],
            messageId: email.messageId,
            error: gmailError,
          },
          labelMapping: [],
          emailInfo: {
            id: email.id,
            messageId: email.messageId,
            threadId: email.threadId,
          },
        };
      }

      const oauth2Client = new google.auth.OAuth2(
        process.env.GOOGLE_CLIENT_ID,
        process.env.GOOGLE_CLIENT_SECRET,
        process.env.GOOGLE_REDIRECT_URI,
      );
      oauth2Client.setCredentials({
        access_token: user.googleCalendarAccessToken,
        refresh_token: user.googleCalendarRefreshToken,
      });

      const gmail = google.gmail({ version: "v1", auth: oauth2Client });

      // Fetch specific message from Gmail (not thread)
      const messageData = await gmail.users.messages.get({
        userId: "me",
        id: email.messageId,
        format: "metadata",
      });

      const message = messageData.data;
      if (message.labelIds) {
        gmailLabelIds = message.labelIds;

        // Convert label IDs to names (this will filter system labels and deduplicate)
        gmailLabelNames =
          await this.emailProviderManager.convertLabelIdsToNames(
            userId,
            gmailLabelIds,
          );

        // Get the label map to show ID -> Name mapping
        // Access GmailProvider through EmailProviderManager to get the raw label map
        const provider = await this.emailProviderManager.getProvider(
          userId,
          "gmail",
        );
        if (provider && "getGmailLabels" in provider) {
          const labelMap = await (provider as any).getGmailLabels(userId);
          // Create mapping for all label IDs (including system labels for debugging)
          labelMapping = gmailLabelIds.map((id) => ({
            id,
            name: labelMap.get(id) || id,
          }));
        } else {
          // Fallback: build mapping from convertLabelIdsToNames result
          // Note: convertLabelIdsToNames filters system labels, so we need to get raw map
          const provider = await this.emailProviderManager.getProvider(
            userId,
            "gmail",
          );
          if (provider && "getGmailLabels" in provider) {
            const labelMap = await (provider as any).getGmailLabels(userId);
            labelMapping = gmailLabelIds.map((id) => ({
              id,
              name: labelMap.get(id) || id,
            }));
          } else {
            labelMapping = gmailLabelIds.map((id) => ({
              id,
              name: id, // Fallback to ID if we can't get the map
            }));
          }
        }
      } else {
        gmailError = "Message has no labelIds";
      }
    } catch (error) {
      gmailError = isError(error)
        ? error.message
        : "Unknown error fetching from Gmail";
      this.logger.error("Error fetching Gmail labels:", error);
    }

    return {
      dbLabels: {
        raw: dbLabelsRaw,
        names: dbLabelsRaw, // DB stores converted names (or IDs if not yet converted)
      },
      gmailLabels: {
        labelIds: gmailLabelIds,
        labelNames: gmailLabelNames,
        messageId: email.messageId,
        error: gmailError,
      },
      labelMapping,
      emailInfo: {
        id: email.id,
        messageId: email.messageId,
        threadId: email.threadId,
      },
    };
  }
}

import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, In } from "typeorm";
import { Email } from "../database/entities/email.entity";
import { EmailProviderManager } from "./email-provider-manager.service";
import { LLMService } from "../llm/llm.service";
import { searchLogger } from "../utils/search-logger";
import { QUERY_LIMITS } from "../constants/query-limits";
import {
  PRIORITY_BOOSTS,
  PRIORITY_SCORES,
} from "../constants/priority-constants";
import { DAYS } from "../constants/time-constants";

// Type for emails with search metadata
// Note: We use a type intersection instead of extends to avoid getPriorityScore requirement issues
export type EmailWithMetadata = Email & {
  searchExplanation?: string;
  relevanceScore?: number;
  debugInfo?: Record<string, unknown>;
};

/**
 * Note: Search returns a "no-results" marker object when no results are found.
 * The marker has shape: { id: "no-results", subject: "", from: "", body: "",
 * receivedAt: string, debugInfo: { originalQuery, queriesTried, message } }
 * Cast through `unknown` to EmailWithMetadata for type compatibility.
 */

@Injectable()
export class EmailSearchService {
  private readonly logger = new Logger(EmailSearchService.name);

  constructor(
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @Inject(forwardRef(() => EmailProviderManager))
    private emailProviderManager: EmailProviderManager,
    private llmService: LLMService,
  ) {}

  /**
   * Search emails using natural language query
   * Converts query to Gmail syntax, searches, and ranks results using AI
   */
  async searchEmails(
    userId: string,
    query: string,
    maxResults: number = QUERY_LIMITS.MAX_SENT_EMAILS_FOR_STYLE,
    onProgress?: (step: string, message: string) => void,
    calculateDaysSinceLastEmail?: (
      userId: string,
      email: Partial<Email>,
    ) => Promise<number | undefined>,
  ): Promise<
    Array<
      Email & {
        searchExplanation?: string;
        relevanceScore?: number;
        debugInfo?: Record<string, unknown>;
      }
    >
  > {
    const originalQuery = query;
    const queriesTried: Array<{ query: string; resultCount: number }> = [];
    const searchStartTime = Date.now();

    // Log search start
    searchLogger.logSearchStart(userId, originalQuery);

    try {
      // Use the injected EmailProviderManager
      const provider =
        await this.emailProviderManager.getPrimaryProvider(userId);
      if (!provider) {
        this.logger.warn(`No email provider connected for user ${userId}`);
        searchLogger.logSearchError(
          userId,
          originalQuery,
          "No email provider connected",
        );
        return [
          {
            id: "no-results",
            subject: "",
            from: "",
            body: "",
            receivedAt: new Date().toISOString(),
            debugInfo: {
              originalQuery,
              queriesTried: [],
              message: "No email provider connected",
            },
          } as unknown as EmailWithMetadata,
        ];
      }

      // Step 1: Generate query variations and try them in order
      onProgress?.("converting", "Crafting search query for Gmail...");

      // Generate natural language variations first
      // Simple implementation: use query as-is
      const naturalVariations = [query];
      this.logger.log(
        `[SEARCH] Generated ${naturalVariations.length} variations: ${naturalVariations.join(", ")}`,
      );
      searchLogger.logQueryVariations(userId, originalQuery, naturalVariations);

      // Convert each variation to Gmail syntax
      const gmailQueries: string[] = [];
      for (const naturalVar of naturalVariations) {
        try {
          const gmailQuery = await this.convertQueryToGmailSearch(
            userId,
            naturalVar,
          );
          if (gmailQuery && !gmailQueries.includes(gmailQuery)) {
            gmailQueries.push(gmailQuery);
          }
        } catch (error) {
          this.logger.warn(
            `Failed to convert variation "${naturalVar}"`,
            error,
          );
        }
      }

      // If no variations were generated, use the original conversion
      if (gmailQueries.length === 0) {
        const gmailQuery = await this.convertQueryToGmailSearch(userId, query);
        gmailQueries.push(gmailQuery);
      }

      this.logger.log(
        `[SEARCH] Will try ${gmailQueries.length} Gmail queries: ${gmailQueries.join(", ")}`,
      );
      searchLogger.logGmailQueries(userId, originalQuery, gmailQueries);

      // Step 2: Try each query variation until we get results
      onProgress?.("searching", "Searching for emails in Gmail...");
      const initialMaxResults = QUERY_LIMITS.MAX_SENT_EMAILS_FOR_STYLE;
      let rawEmails: Array<{
        receivedAt: Date;
        from?: string;
        fromName?: string;
        subject?: string;
        [key: string]: unknown;
      }> = [];
      let successfulQuery: string | null = null;

      for (const gmailQuery of gmailQueries) {
        try {
          const searchResults = await provider.searchEmails(
            userId,
            gmailQuery,
            initialMaxResults,
          );
          queriesTried.push({
            query: gmailQuery,
            resultCount: searchResults.length,
          });

          if (searchResults.length > 0) {
            rawEmails = searchResults as unknown as Array<{
              receivedAt: Date;
              from?: string;
              fromName?: string;
              subject?: string;
              messageId?: string;
              [key: string]: unknown;
            }>;
            successfulQuery = gmailQuery;
            this.logger.log(
              `[SEARCH] Query "${gmailQuery}" returned ${searchResults.length} results`,
            );
            break;
          }
        } catch (error) {
          this.logger.warn(`Search query "${gmailQuery}" failed:`, error);
          queriesTried.push({
            query: gmailQuery,
            resultCount: 0,
          });
        }
      }

      if (rawEmails.length === 0) {
        searchLogger.logSearchComplete(
          userId,
          originalQuery,
          0,
          Date.now() - searchStartTime,
        );
        // Return a special "no-results" marker with debug info including queries tried
        return [
          {
            id: "no-results",
            subject: "",
            from: "",
            body: "",
            receivedAt: new Date().toISOString(),
            debugInfo: {
              originalQuery,
              queriesTried,
              message: "No emails found matching your search",
            },
          } as unknown as EmailWithMetadata,
        ];
      }

      // Step 3: Fetch full email data from our database
      onProgress?.("fetching", "Fetching email details...");
      const messageIds = rawEmails
        .map((e) => e.messageId as string | undefined)
        .filter((id): id is string => id !== null && id !== undefined);

      if (messageIds.length === 0) {
        // Return a special "no-results" marker with debug info including queries tried
        return [
          {
            id: "no-results",
            subject: "",
            from: "",
            body: "",
            receivedAt: new Date().toISOString(),
            debugInfo: {
              originalQuery,
              queriesTried,
              message: "Emails found in Gmail but not yet synced to BearlyMail",
            },
          } as unknown as EmailWithMetadata,
        ];
      }

      // Fetch emails from our database
      const dbEmails = await this.emailRepository.find({
        where: {
          userId,
          messageId: In(messageIds as string[]),
        },
        order: { receivedAt: "DESC" },
      });

      // Create a map for quick lookup
      const emailMap = new Map(dbEmails.map((e) => [e.messageId, e]));

      // Match raw emails with database emails and preserve order
      const matchedEmails: Email[] = [];
      for (const rawEmail of rawEmails) {
        const messageId = rawEmail.messageId as string | undefined;
        if (messageId && emailMap.has(messageId)) {
          matchedEmails.push(emailMap.get(messageId)!);
        }
      }

      if (matchedEmails.length === 0) {
        searchLogger.logSearchComplete(
          userId,
          originalQuery,
          0,
          Date.now() - searchStartTime,
        );
        // Return a special "no-results" marker with debug info including queries tried
        return [
          {
            id: "no-results",
            subject: "",
            from: "",
            body: "",
            receivedAt: new Date().toISOString(),
            debugInfo: {
              originalQuery,
              queriesTried,
              message: "Emails found in Gmail but not yet synced to BearlyMail",
            },
          } as unknown as EmailWithMetadata,
        ];
      }

      // Step 4: Calculate days since last email for each email (for recency scoring)
      onProgress?.("analyzing", "Analyzing email relevance...");
      const now = new Date();
      const emailSummaries = await Promise.all(
        matchedEmails.map(async (email) => {
          const receivedDate = new Date(email.receivedAt);
          const daysAgo = Math.floor(
            (now.getTime() - receivedDate.getTime()) / (1000 * 60 * 60 * 24),
          );
          const daysSinceLastEmail = calculateDaysSinceLastEmail
            ? await calculateDaysSinceLastEmail(userId, email)
            : undefined;

          return {
            index: matchedEmails.indexOf(email),
            from: email.fromName || email.from || "",
            subject: email.subject || "",
            snippet: email.body?.substring(0, 200) || "",
            daysAgo,
            isRecent: daysAgo <= DAYS.WEEK,
            daysSinceLastEmail,
          };
        }),
      );

      // Find the most recent email's daysSinceLastEmail for context
      const mostRecentEmail = matchedEmails[0];
      const daysSinceLastEmail = calculateDaysSinceLastEmail
        ? await calculateDaysSinceLastEmail(userId, mostRecentEmail)
        : undefined;

      // Use AI to filter and rank results if we have multiple results
      let filteredEmails = matchedEmails;
      // Track scores for all emails (for debug)
      const allScores: Map<number, number> = new Map();

      // Always score emails, even if we don't need to filter
      if (matchedEmails.length > 0) {
        try {
          searchLogger.logAIScoringStart(
            userId,
            originalQuery,
            matchedEmails.length,
          );

          // Detect if query is time-sensitive
          const isTimeSensitive = this.isTimeSensitiveQuery(originalQuery);

          // Adjust recency penalties based on time-sensitivity
          // For time-sensitive queries (e.g., "Is Jay coming to the meeting?"),
          // older emails are much less relevant
          const recencyToday = PRIORITY_BOOSTS.RECENCY_TODAY;
          const recency24H = PRIORITY_BOOSTS.RECENCY_24H;
          const recency7D = PRIORITY_BOOSTS.RECENCY_7D;
          const recency30D = PRIORITY_BOOSTS.RECENCY_30D;
          // Stronger penalties for old emails in time-sensitive queries
          const recency30DPenalty = isTimeSensitive
            ? PRIORITY_BOOSTS.RECENCY_30D_PENALTY *
              QUERY_LIMITS.SEARCH_RELEVANCE_MULTIPLIER // 50% stronger penalty
            : PRIORITY_BOOSTS.RECENCY_30D_PENALTY;
          const recency60DPenalty = isTimeSensitive
            ? PRIORITY_BOOSTS.RECENCY_60D_PENALTY *
              QUERY_LIMITS.SEARCH_RELEVANCE_MULTIPLIER // 50% stronger penalty
            : PRIORITY_BOOSTS.RECENCY_60D_PENALTY;

          const timeSensitivityNote = isTimeSensitive
            ? "\n\n⚠️ TIME-SENSITIVE QUERY DETECTED: This query appears to be about a meeting, event, or time-sensitive question. OLDER emails should be penalized MORE HEAVILY as they are likely about past events, not the current question. Emails older than 30 days should receive significantly lower scores unless they are extremely relevant."
            : "";

          // Use AI to rank ALL emails by relevance to the ORIGINAL query (prioritizing newer emails) with scores
          const rankingPrompt = `You are an email search assistant. Rank these ${emailSummaries.length} emails by relevance to the search query: "${originalQuery}"

IMPORTANT CONTEXT:
- The most recent email in this set was received ${daysSinceLastEmail} days ago (daysSinceLastEmail: ${daysSinceLastEmail})
- Prioritize RECENT emails heavily - if two emails are equally relevant, the more recent one should rank much higher${timeSensitivityNote}

CRITICAL RELEVANCE RULES:
1. If the query asks about a specific person (e.g., "Is Jay coming?"), emails MUST be from that person or mention them prominently to be relevant
2. Emails that don't mention the person at all should get a score of 0-20 (not relevant)
3. Emails from automated services (like "Fireflies.ai", "noreply", etc.) that don't mention the person should get very low scores (0-15)
4. Only emails that directly relate to the query should score above ${PRIORITY_SCORES.MEDIUM_THRESHOLD}

CRITICAL RECENCY RULES (apply these bonuses/penalties):
- Emails from TODAY (0 days ago) should get a +${recencyToday} bonus (STRONG priority for today's emails)
- Emails from the last 24 hours (0-1 days ago) should get a +${recency24H} bonus
- Emails from the last ${DAYS.WEEK} days should get a +${recency7D} bonus
- Emails from ${DAYS.WEEK + 1}-${DAYS.MONTH} days ago should get a +${recency30D} bonus
- Emails older than ${DAYS.MONTH} days should get a ${recency30DPenalty} penalty (${isTimeSensitive ? "VERY STRONG" : "STRONG"} penalty for old emails${isTimeSensitive ? " - time-sensitive query" : ""})
- Emails older than 60 days should get a ${recency60DPenalty} penalty (${isTimeSensitive ? "EXTREMELY STRONG" : "VERY STRONG"} penalty${isTimeSensitive ? " - time-sensitive query" : ""})

RELEVANCE SCORING (base score before recency adjustment):
- 100 = Perfect match, directly answers the question (e.g., email from Jay about the meeting)
- 80-99 = Very relevant, strong connection to query
- 60-79 = Moderately relevant, some connection
- 40-59 = Somewhat relevant, weak connection
- 20-39 = Barely relevant, minimal connection
- 0-19 = Not relevant at all (e.g., automated emails that don't mention the person)

Then apply the recency bonus/penalty above. Final score = base score + recency adjustment (capped at 0-100).

STRICT FILTERING: Only include emails with final score >= ${PRIORITY_BOOSTS.RELEVANCE_THRESHOLD} in the top results. Emails scoring below ${PRIORITY_BOOSTS.RELEVANCE_THRESHOLD} should be excluded even if they're recent.

Return a JSON array of objects with index and relevanceScore for ALL ${emailSummaries.length} emails, sorted by relevanceScore (highest first).

Format: [{"index": 2, "relevanceScore": 95}, {"index": 5, "relevanceScore": 87}, ...]

Emails:
${emailSummaries
  .map((e, index) => {
    let recencyLabel = "";
    if (e.daysAgo === 0) {
      recencyLabel = " (TODAY!)";
    } else if (e.daysAgo <= 1) {
      recencyLabel = " (LAST 24 HOURS!)";
    } else if (e.isRecent) {
      recencyLabel = " (RECENT)";
    }
    return `${index}. From: ${e.from}, Subject: ${e.subject}, Received: ${e.daysAgo} days ago${recencyLabel}, Preview: ${e.snippet.substring(0, QUERY_LIMITS.SUBSTRING_PREVIEW_LONG)}...`;
  })
  .join("\n")}

Return ONLY a JSON array of objects.`;

          const rankingResponse = await this.llmService.generateText(
            {
              prompt: rankingPrompt,
              systemPrompt:
                "You are a helpful email search assistant. Return only valid JSON arrays.",
              temperature: QUERY_LIMITS.LLM_TEMPERATURE,
              maxTokens: QUERY_LIMITS.LLM_MAX_TOKENS_LARGE,
            },
            undefined,
            userId,
          );

          searchLogger.logAIScoringComplete(
            userId,
            originalQuery,
            matchedEmails.length,
            filteredEmails.length,
            matchedEmails.length - filteredEmails.length,
          );

          // Parse ranking response
          try {
            const jsonMatch = rankingResponse.match(/\{[\s\S]*\}|\[[\s\S]*\]/);
            if (jsonMatch) {
              const rankings: Array<{
                index: number;
                relevanceScore: number;
              }> = JSON.parse(jsonMatch[0]);

              // Validate rankings
              if (Array.isArray(rankings)) {
                // Store scores for all emails
                rankings.forEach((rank) => {
                  allScores.set(rank.index, rank.relevanceScore);
                });

                // Filter emails by relevance threshold
                filteredEmails = matchedEmails.filter((email, index) => {
                  const score = allScores.get(index) ?? 0;
                  return score >= PRIORITY_BOOSTS.RELEVANCE_THRESHOLD;
                });

                // Sort by relevance score (highest first)
                filteredEmails.sort((a, b) => {
                  const indexA = matchedEmails.indexOf(a);
                  const indexB = matchedEmails.indexOf(b);
                  const scoreA = allScores.get(indexA) ?? 0;
                  const scoreB = allScores.get(indexB) ?? 0;
                  return scoreB - scoreA;
                });

                // Limit to maxResults
                filteredEmails = filteredEmails.slice(0, maxResults);
              }
            }
          } catch (parseError) {
            this.logger.warn(
              "Failed to parse AI ranking response, using all results:",
              parseError,
            );
            // Fall back to all results, sorted by date
            filteredEmails = matchedEmails.slice(0, maxResults);
          }
        } catch (error) {
          this.logger.error("AI ranking failed, using all results:", error);
          // Fall back to all results, sorted by date
          filteredEmails = matchedEmails.slice(0, maxResults);
        }
      } else {
        // No need for AI ranking if we have few results
        filteredEmails = matchedEmails.slice(0, maxResults);
      }

      // Generate search relevance explanations in a single batch LLM call
      onProgress?.("explaining", "Generating explanations...");
      let explanationsMap = new Map<number, string>();
      if (filteredEmails.length > 0) {
        try {
          const emailsForExplanation = filteredEmails.map((email, idx) => ({
            index: idx,
            from: email.fromName || email.from || "",
            subject: email.subject || "",
            body: email.body || "",
            receivedAt: email.receivedAt
              ? email.receivedAt.toISOString()
              : new Date().toISOString(),
          }));
          explanationsMap =
            await this.llmService.generateSearchRelevanceExplanationsBatch(
              originalQuery,
              emailsForExplanation,
              userId,
            );
        } catch (error) {
          this.logger.warn(
            "Batch explanation generation failed, using fallback:",
            error,
          );
        }
      }

      // Add search explanation and relevance scores to emails
      const emailsWithMetadata: EmailWithMetadata[] = filteredEmails.map(
        (email, idx) => {
          const emailIndex = matchedEmails.indexOf(email);
          const relevanceScore = allScores.get(emailIndex) ?? undefined;

          const emailWithMeta = {
            ...email,
            searchExplanation:
              explanationsMap.get(idx) ||
              (successfulQuery
                ? `Found using query: "${successfulQuery}"`
                : "Search completed"),
            relevanceScore,
          } as EmailWithMetadata;

          return emailWithMeta;
        },
      );

      // Build debug info
      const debugInfo = {
        originalQuery,
        gmailQuery: successfulQuery || gmailQueries[0] || query,
        queriesTried,
        totalRawEmails: rawEmails.length,
        maxResultsRequested: maxResults,
        filteredCount: filteredEmails.length,
        allRawEmails: rawEmails.map((rawEmail, index) => {
          const receivedDate = new Date(rawEmail.receivedAt);
          const daysAgo = Math.floor(
            (now.getTime() - receivedDate.getTime()) / (1000 * 60 * 60 * 24),
          );
          return {
            index,
            from: rawEmail.fromName || rawEmail.from,
            subject: rawEmail.subject,
            receivedAt: rawEmail.receivedAt,
            daysAgo,
            aiScore: allScores.get(index) ?? null,
            includedInResults: filteredEmails.some(
              (e) =>
                (e as { messageId?: string }).messageId ===
                (rawEmail.messageId as string),
            ),
          };
        }),
      };

      // Sort results by relevance score (highest first) before returning
      emailsWithMetadata.sort((a, b) => {
        const scoreA = a.relevanceScore ?? 0;
        const scoreB = b.relevanceScore ?? 0;
        // Descending order
        return scoreB - scoreA;
      });

      // Return emails with metadata (explanations and relevance scores)
      // Add debug info to first email only (to avoid bloating response)
      const result = emailsWithMetadata.map((email, index) => {
        // Email already has getPriorityScore method, just add debug info if needed
        const emailWithMeta = email as EmailWithMetadata;
        if (index === 0) {
          emailWithMeta.debugInfo = debugInfo;
        }
        return emailWithMeta;
      });

      const searchDuration = Date.now() - searchStartTime;
      searchLogger.logSearchComplete(
        userId,
        originalQuery,
        result.length,
        searchDuration,
      );

      return result as Array<
        Email & {
          searchExplanation?: string;
          relevanceScore?: number;
          debugInfo?: Record<string, unknown>;
        }
      >;
    } catch (error) {
      this.logger.error("Search failed:", error);
      searchLogger.logSearchError(userId, originalQuery, String(error));
      throw error;
    }
  }

  /**
   * Check if a query is time-sensitive (e.g., about meetings, events, future plans)
   */
  private isTimeSensitiveQuery(query: string): boolean {
    const lowerQuery = query.toLowerCase();

    // Patterns that indicate time-sensitive queries
    const timeSensitivePatterns = [
      // Questions about attendance/participation
      /\b(is|are|will|coming|going|attending|joining|participating)\b/i,
      // Meeting-related
      /\b(meeting|appointment|call|conference|event|gathering|session)\b/i,
      // Time-related questions
      /\b(when|what time|what day|which day|tomorrow|today|this week|next week)\b/i,
      // Status questions
      /\b(status|confirmed|cancel|reschedule|postpone)\b/i,
      // Questions about future plans
      /\b(plan|schedule|arrange|organize|set up)\b/i,
    ];

    // Check if query contains question words AND time-sensitive patterns
    const hasQuestionWord = /\b(is|are|will|when|what|where|who|how)\b/i.test(
      lowerQuery,
    );
    const hasTimeSensitivePattern = timeSensitivePatterns.some((pattern) =>
      pattern.test(lowerQuery),
    );

    // Also check for direct questions (starts with question word or contains "?")
    const isDirectQuestion =
      /\b(is|are|will|when|what|where|who|how)\b/i.test(
        lowerQuery.trim().split(/\s+/)[0],
      ) || lowerQuery.includes("?");

    return (
      (hasQuestionWord && hasTimeSensitivePattern) ||
      (isDirectQuestion && hasTimeSensitivePattern)
    );
  }

  /**
   * Convert natural language query to Gmail search syntax using AI
   */
  private async convertQueryToGmailSearch(
    userId: string,
    query: string,
  ): Promise<string> {
    // Check if query already looks like Gmail syntax (contains operators like from:, to:, subject:, etc.)
    const gmailOperators = [
      "from:",
      "to:",
      "subject:",
      "has:",
      "in:",
      "is:",
      "before:",
      "after:",
      "older:",
      "newer:",
    ];

    const hasGmailOperator = gmailOperators.some((op) =>
      query.toLowerCase().includes(op),
    );

    if (hasGmailOperator) {
      // Query already contains Gmail operators, return as-is
      return query;
    }

    // Use AI to convert natural language to Gmail search syntax
    const conversionPrompt = `Convert this natural language email search query to Gmail search syntax: "${query}"

Gmail search syntax rules:
- Use "from:" for sender (e.g., "from:john@example.com")
- Use "subject:" for subject line (e.g., "subject:meeting")
- Use "has:" for attachments (e.g., "has:attachment")
- Use "in:" for labels/folders (e.g., "in:inbox")
- Use "is:" for flags (e.g., "is:read", "is:unread", "is:starred")
- Use "before:" and "after:" for dates (e.g., "after:2024/1/1")
- Combine terms with spaces (AND) or use OR for alternatives
- Use quotes for exact phrases (e.g., "subject:\"team meeting\"")

Return ONLY the Gmail search query, nothing else.`;

    try {
      const response = await this.llmService.generateText(
        {
          prompt: conversionPrompt,
          systemPrompt:
            "You are a helpful assistant that converts natural language to Gmail search syntax. Return only the search query.",
          temperature: 0.3,
          maxTokens: 200,
        },
        undefined,
        userId,
      );

      // Extract the query (remove any markdown formatting or extra text)
      const cleaned = response
        .trim()
        .replace(/^```[\w]*\n?/g, "")
        .replace(/\n?```$/g, "")
        .trim();

      // If the response looks valid, use it; otherwise fall back to simple keyword search
      if (cleaned.length > 0 && cleaned.length < 500) {
        return cleaned;
      }
    } catch (error) {
      this.logger.warn("Failed to convert query using AI:", error);
    }

    // Fallback: simple keyword-based search
    // Split query into words and search in subject and body
    const words = query
      .split(/\s+/)
      .filter((w) => w.length > 0)
      .map((w) => `"${w}"`)
      .join(" OR ");
    return `subject:(${words}) OR ${words}`;
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { QUERY_LIMITS } from "../constants/query-limits";
import { PRIORITY_SCORES } from "../constants/priority-constants";

@Injectable()
export class EmailStatusService {
  private readonly logger = new Logger(EmailStatusService.name);

  constructor(
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
  ) {}

  /**
   * Get sync status for a user
   */
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  async getSyncStatus(_userId: string): Promise<{
    lastSyncAt: Date | null;
    isSyncing: boolean;
  }> {
    // TODO: Add lastEmailSyncAt property to User entity
    // TODO: Track active sync jobs
    return {
      lastSyncAt: null,
      isSyncing: false,
    };
  }

  /**
   * Force check for new emails by unbatting all pending batched emails
   */
  async forceCheckNewEmails(
    userId: string,
    getInbox: (
      userId: string,
      includeBatched: boolean,
      mode: "triage" | "action" | "follow-up",
    ) => Promise<Email[]>,
  ): Promise<Email[]> {
    await this.emailRepository.update(
      {
        userId,
        isBatched: true,
      },
      { isBatched: false, batchDecisionReason: "Force-checked by user" },
    );

    // Return Triage inbox by default after force check
    return getInbox(userId, true, "triage");
  }

  /**
   * Get the next batch release time for a user
   */
  async getNextBatchReleaseTime(userId: string): Promise<Date | null> {
    const nextBatch = await this.emailRepository.findOne({
      where: { userId, isBatched: true },
      order: { batchReleaseAt: "ASC" },
      select: ["batchReleaseAt"],
    });
    return nextBatch?.batchReleaseAt || null;
  }

  /**
   * Check for urgent emails that are currently batched
   */
  async checkForUrgentEmails(userId: string): Promise<{
    hasUrgent: boolean;
    urgentCount: number;
    urgentEmails: Array<{
      subject: string;
      from: string;
      priorityScore: number;
    }>;
  }> {
    // Get all batched emails that are marked as urgent AND have very high priority score
    // Require BOTH conditions to be more strict about what counts as urgent
    // Priority threshold raised to 90+ (was 80+) to reduce false positives
    // Join with email_threads to check isArchived and get priority (now thread-level)
    const urgentBatchedEmails = await this.emailRepository
      .createQueryBuilder("email")
      .innerJoin("email_threads", "thread", "thread.id = email.emailThreadId")
      .where("email.userId = :userId", { userId })
      .andWhere("thread.userId = :userId", { userId })
      .andWhere("email.isBatched = true")
      .andWhere("thread.isArchived = false")
      // Must have high urgency score (90+)
      .andWhere("thread.urgencyScore >= 90")
      // AND must have very high priority (90+) - calculated from thread priorityExplanation
      .andWhere(
        `COALESCE(
          (SELECT (jsonb_extract_path_text(thread."priorityExplanation"::jsonb, 'score')::int))
          , 0
        ) >= ${PRIORITY_SCORES.VERY_HIGH}`,
      )
      .select([
        "email.subject",
        "email.from",
        "email.fromName",
        "thread.urgencyScore",
      ])
      .limit(QUERY_LIMITS.MAX_RESULTS_DEFAULT)
      .getMany();

    const urgentEmails = urgentBatchedEmails.map((email) => {
      // Calculate priority score from thread (if available)
      // For now, use urgencyScore as a proxy
      const priorityScore = (email as any).urgencyScore || 0;

      return {
        subject: email.subject || "No subject",
        from: email.fromName || email.from || "Unknown",
        priorityScore,
      };
    });

    return {
      hasUrgent: urgentEmails.length > 0,
      urgentCount: urgentEmails.length,
      urgentEmails,
    };
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, MoreThan, In } from "typeorm";
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { QUERY_LIMITS } from "../constants/query-limits";
import { isError, isDatabaseError } from "../types/common";

/**
 * Service for managing email threads
 * Extracted from EmailsService to keep files focused and maintainable
 */
@Injectable()
export class EmailThreadService {
  private readonly logger = new Logger(EmailThreadService.name);

  constructor(
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
  ) {}

  /**
   * Get all emails in a thread, sorted by date
   */
  async getThreadEmails(
    userId: string,
    threadId: string,
    options?: { limit?: number; order?: "ASC" | "DESC" },
  ): Promise<Email[]> {
    // CRITICAL: Use query builder with explicit select to avoid decrypting body/htmlBody
    // These are large encrypted fields that cause significant slowdown
    // The frontend can fetch body/htmlBody separately if needed for individual emails
    const queryBuilder = this.emailRepository
      .createQueryBuilder("email")
      .select([
        "email.id",
        "email.userId",
        "email.threadId",
        "email.messageId",
        "email.from",
        "email.fromName",
        "email.senderJobTitle",
        "email.subject",
        "email.isSnoozed",
        "email.snoozeUntil",
        "email.isBatched",
        "email.batchReleaseAt",
        "email.isRead",
        "email.summary",
        "email.receivedAt",
        "email.labels", // Include labels field
        // Only include body/htmlBody if explicitly needed - they're large and encrypted
        // For thread view, we can fetch them separately for expanded emails
        "email.body",
        "email.htmlBody",
        "email.attachments",
      ])
      .where("email.userId = :userId", { userId })
      .andWhere("email.threadId = :threadId", { threadId });

    // Apply ordering (default to ASC for chronological processing, DESC for thread view display)
    const order = options?.order || "ASC";
    queryBuilder.orderBy("email.receivedAt", order);

    // Apply limit if specified
    if (options?.limit) {
      queryBuilder.take(options.limit);
    }

    // TypeORM will automatically decrypt labels field due to the transformer
    return queryBuilder.getMany();
  }

  /**
   * Get recent thread IDs that are not archived (for checking archived status in Gmail)
   */
  async getRecentNonArchivedThreadIds(
    userId: string,
    days: number = 7,
  ): Promise<string[]> {
    const cutoffDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
    const results = await this.emailThreadRepository
      .createQueryBuilder("thread")
      .select("thread.threadId", "threadId")
      .where("thread.userId = :userId", { userId })
      .andWhere("thread.isArchived = false")
      .innerJoin("emails", "email", "email.emailThreadId = thread.id")
      .andWhere("email.receivedAt >= :cutoffDate", { cutoffDate })
      .limit(QUERY_LIMITS.MAX_SENT_EMAILS_FOR_STYLE)
      // Limit to avoid rate limits
      .getRawMany();

    // Filter out any null/undefined
    return results
      .map((r: { threadId: string }) => r.threadId)
      .filter((id: string) => id);
  }

  /**
   * Get all non-archived thread IDs for a user
   */
  async getAllNonArchivedThreadIds(userId: string): Promise<string[]> {
    const threads = await this.emailThreadRepository.find({
      where: { userId, isArchived: false },
      select: ["threadId"],
    });
    return threads.map((t) => t.threadId);
  }

  /**
   * Get non-archived threads that need status verification
   * Prioritizes threads that haven't been checked recently (oldest lastCheckedAt first)
   * Limits to a reasonable number per user per run to spread work across sync cycles
   */
  async getNonArchivedThreadsNeedingCheck(
    userId: string,
    limit: number = 50,
  ): Promise<string[]> {
    const results = await this.emailThreadRepository
      .createQueryBuilder("thread")
      .select("thread.threadId", "threadId")
      .where("thread.userId = :userId", { userId })
      .andWhere("thread.isArchived = false")
      .orderBy("thread.lastCheckedAt", "ASC", "NULLS FIRST")
      // Prioritize threads that haven't been checked or were checked longest ago
      .limit(limit)
      .getRawMany();

    // Filter out any null/undefined
    return results
      .map((r: { threadId: string }) => r.threadId)
      .filter((id: string) => id);
  }

  /**
   * Get ALL threads for sync comparison (returns threadId, isArchived, starCount)
   * Used by Gmail sync to compare with Gmail search results
   */
  async getAllThreadsForSync(
    userId: string,
  ): Promise<
    Array<{ threadId: string; isArchived: boolean; starCount: number }>
  > {
    const results = await this.emailThreadRepository
      .createQueryBuilder("thread")
      .select(["thread.threadId", "thread.isArchived", "thread.starCount"])
      .where("thread.userId = :userId", { userId })
      .limit(500)
      // Reasonable limit for sync
      .getMany();

    return results
      .map((t) => ({
        threadId: t.threadId,
        isArchived: t.isArchived,
        starCount: t.starCount,
      }))
      .filter((t) => t.threadId);
    // Filter out any null/undefined threadIds
  }

  /**
   * Update archived status for a single thread
   * @param setLastUserOperation - If true, sets lastUserOperationAt to now (for user-initiated actions)
   */
  async updateThreadArchivedStatus(
    userId: string,
    threadId: string,
    isArchived: boolean,
    setLastUserOperation: boolean = false,
  ): Promise<void> {
    const thread = await this.emailThreadRepository.findOne({
      where: { userId, threadId },
    });

    if (thread) {
      // Only update if status changed to avoid unnecessary DB writes
      const needsUpdate =
        thread.isArchived !== isArchived || setLastUserOperation;
      if (needsUpdate) {
        thread.isArchived = isArchived;
        if (setLastUserOperation) {
          thread.lastUserOperationAt = new Date();
        }
        await this.emailThreadRepository.save(thread);
        this.logger.debug(
          `Updated thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... archived status to ${isArchived}${setLastUserOperation ? " (user operation)" : ""}`,
        );
      }
    } else {
      // Thread doesn't exist yet, create it
      await this.getOrCreateEmailThread(userId, threadId, 0, isArchived);
    }
  }

  /**
   * Update lastCheckedAt for multiple threads (used to track verification without status changes)
   */
  async updateThreadsLastCheckedAt(
    userId: string,
    threadIds: string[],
  ): Promise<void> {
    if (threadIds.length === 0) return;

    const now = new Date();
    await this.emailThreadRepository
      .createQueryBuilder()
      .update()
      .set({ lastCheckedAt: now })
      .where("userId = :userId", { userId })
      .andWhere("threadId IN (:...threadIds)", { threadIds })
      .execute();
  }

  /**
   * Batch update thread archived statuses (more efficient than individual updates)
   * IMPORTANT: This method respects lastUserOperationAt - it will NOT override
   * a user's recent archive/unarchive action unless there's a new email in the thread.
   * This is called by sync processes, not by user actions.
   */
  async batchUpdateThreadArchivedStatuses(
    userId: string,
    updates: Array<{ threadId: string; isArchived: boolean }>,
  ): Promise<void> {
    if (updates.length === 0) return;

    const now = new Date();

    // Get all threads that might be updated to check lastUserOperationAt
    const threadIds = updates.map((u) => u.threadId);
    const existingThreads = await this.emailThreadRepository.find({
      where: { userId, threadId: In(threadIds) },
      select: ["id", "threadId", "isArchived", "lastUserOperationAt"],
    });
    const existingThreadMap = new Map(
      existingThreads.map((t) => [t.threadId, t]),
    );

    // Filter out updates that would override a recent user operation
    // A user operation should be respected unless there's a new email (which would be handled separately)
    const filteredUpdates = updates.filter((update) => {
      const existingThread = existingThreadMap.get(update.threadId);
      if (!existingThread) {
        // New thread, allow update
        return true;
      }

      // If user recently performed an operation, don't override their action
      // The sync should only update if the status in Gmail matches what we expect
      // If user archived in BearlyMail but Gmail shows unarchived, we should NOT unarchive
      if (existingThread.lastUserOperationAt) {
        // Skip this update - user's action takes precedence
        this.logger.debug(
          `Skipping sync update for thread ${update.threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... - user operation at ${existingThread.lastUserOperationAt.toISOString()} takes precedence`,
        );
        return false;
      }

      return true;
    });

    if (filteredUpdates.length === 0) {
      this.logger.debug(
        `All ${updates.length} thread updates skipped due to recent user operations`,
      );
      return;
    }

    // Group by status for more efficient updates
    const archivedThreadIds = filteredUpdates
      .filter((update) => update.isArchived)
      .map((update) => update.threadId);
    const unarchivedThreadIds = filteredUpdates
      .filter((update) => !update.isArchived)
      .map((update) => update.threadId);

    // Batch update archived threads (only those without recent user operations)
    if (archivedThreadIds.length > 0) {
      await this.emailThreadRepository
        .createQueryBuilder()
        .update()
        .set({ isArchived: true, lastCheckedAt: now })
        .where("userId = :userId", { userId })
        .andWhere("threadId IN (:...threadIds)", {
          threadIds: archivedThreadIds,
        })
        .andWhere("lastUserOperationAt IS NULL")
        .execute();
    }

    // Batch update unarchived threads (only those without recent user operations)
    if (unarchivedThreadIds.length > 0) {
      await this.emailThreadRepository
        .createQueryBuilder()
        .update()
        .set({ isArchived: false, lastCheckedAt: now })
        .where("userId = :userId", { userId })
        .andWhere("threadId IN (:...threadIds)", {
          threadIds: unarchivedThreadIds,
        })
        .andWhere("lastUserOperationAt IS NULL")
        .execute();
    }

    this.logger.debug(
      `Batch updated ${filteredUpdates.length} thread archived statuses (${updates.length - filteredUpdates.length} skipped due to user operations)`,
    );
  }

  /**
   * Update star count for a thread (updates EmailThread)
   * For bulk updates, use batchUpdateThreadStarCount instead
   */
  async updateThreadStarCount(
    userId: string,
    threadId: string,
    starCount: number,
  ): Promise<void> {
    const thread = await this.emailThreadRepository.findOne({
      where: { userId, threadId },
    });

    if (thread) {
      // Only update if starCount changed to avoid unnecessary DB writes
      const normalizedStarCount = Math.max(0, Math.min(3, starCount));
      if (thread.starCount !== normalizedStarCount) {
        thread.starCount = normalizedStarCount;
        await this.emailThreadRepository.save(thread);
        this.logger.debug(
          `Updated thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... star count to ${normalizedStarCount}`,
        );
      }
    } else {
      // Thread doesn't exist yet, create it
      await this.getOrCreateEmailThread(userId, threadId, starCount, false);
    }
  }

  /**
   * Bulk update star counts for multiple threads in a single query
   * Performance budget: 200ms per thread (but bulk update makes this much faster)
   */
  async batchUpdateThreadStarCount(
    userId: string,
    updates: { threadId: string; starCount: number }[],
  ): Promise<void> {
    if (updates.length === 0) return;

    const startTime = Date.now();

    // Query current starCount values to filter out unchanged updates
    const threadIds = updates.map((update) => update.threadId);
    const currentThreads = await this.emailThreadRepository.find({
      where: { userId, threadId: In(threadIds) },
      select: ["threadId", "starCount"],
    });

    const currentStarCounts = new Map<string, number>();
    for (const thread of currentThreads) {
      currentStarCounts.set(thread.threadId, thread.starCount);
    }

    // Filter out updates where starCount hasn't changed
    const filteredUpdates = updates.filter((update) => {
      const normalizedStarCount = Math.max(0, Math.min(3, update.starCount));
      const currentStarCount = currentStarCounts.get(update.threadId) ?? 0;
      return normalizedStarCount !== currentStarCount;
    });

    if (filteredUpdates.length === 0) {
      this.logger.debug(
        `batchUpdateThreadStarCount: All ${updates.length} threads already have correct starCount, skipping update`,
      );
      return;
    }

    // Use raw SQL for efficient bulk update
    // Group updates by starCount to minimize queries
    const updatesByStarCount = new Map<number, string[]>();
    for (const update of filteredUpdates) {
      const starCount = Math.max(0, Math.min(3, update.starCount));
      if (!updatesByStarCount.has(starCount)) {
        updatesByStarCount.set(starCount, []);
      }
      updatesByStarCount.get(starCount)!.push(update.threadId);
    }

    const now = new Date();
    // Execute bulk updates for each starCount value
    await this.emailThreadRepository.manager.transaction(async (manager) => {
      for (const [
        starCount,
        threadIdsToUpdate,
      ] of updatesByStarCount.entries()) {
        if (threadIdsToUpdate.length > 0) {
          await manager.query(
            `UPDATE email_threads 
             SET "starCount" = $1, "updatedAt" = CURRENT_TIMESTAMP, "lastCheckedAt" = $4
             WHERE "userId" = $2 AND "threadId" = ANY($3::text[])`,
            [starCount, userId, threadIdsToUpdate, now],
          );
        }
      }
    });

    const duration = Date.now() - startTime;
    const perThreadTime = duration / filteredUpdates.length;
    const skippedCount = updates.length - filteredUpdates.length;
    if (skippedCount > 0) {
      this.logger.debug(
        `batchUpdateThreadStarCount: Updated ${filteredUpdates.length} threads, skipped ${skippedCount} unchanged (${duration}ms)`,
      );
    }
    if (perThreadTime > 200) {
      this.logger.warn(
        `batchUpdateThreadStarCount took ${duration}ms for ${filteredUpdates.length} threads (${perThreadTime.toFixed(1)}ms/thread, budget: 200ms)`,
      );
    } else {
      this.logger.debug(
        `batchUpdateThreadStarCount: ${filteredUpdates.length} threads in ${duration}ms (${perThreadTime.toFixed(1)}ms/thread)`,
      );
    }
  }

