    filename: string;
    mimeType: string;
    size: number;
  }> {
    const gmail = await this.createGmailClient(userId);
    if (!gmail) throw new Error("User not connected to Gmail");

    const response = await gmail.users.messages.attachments.get({
      userId: "me",
      messageId,
