import { Logger } from "@nestjs/common";
import { gmail_v1 } from "googleapis";
import { isApiError, isError } from "../../../types/common";
import { logErrorToFile } from "../../../utils/error-logger";
import { HTTP_STATUS } from "../../../constants/http-status";

const logger = new Logger("GmailOperations");

/**
 * Archive a thread in Gmail by removing the INBOX label
 */
export async function archiveThreadInGmail(
  userId: string,
  threadId: string,
  gmail: gmail_v1.Gmail,
): Promise<void> {
  logger.log(
    `[Gmail Archive] Archiving thread: userId=${userId}, threadId=${threadId}`,
  );

  // Get thread with messages
  const threadData = await gmail.users.threads.get({
    userId: "me",
    id: threadId,
    format: "full",
  });

  const thread = threadData.data;
  const messages = thread.messages || [];
  logger.log(`[Gmail Archive] Found ${messages.length} messages in thread`);

  // Mark all messages as read
  for (const message of messages) {
    if (!message.id) continue;
    const messageLabelIds = message.labelIds || [];

    if (messageLabelIds.includes("UNREAD")) {
      await gmail.users.messages.modify({
        userId: "me",
        id: message.id,
        requestBody: {
          removeLabelIds: ["UNREAD"],
        },
      });
    }
  }

  // Remove INBOX label from thread (archive it)
  await gmail.users.threads.modify({
    userId: "me",
    id: threadId,
    requestBody: {
      removeLabelIds: ["INBOX"],
    },
  });

  logger.log(`[Gmail Archive] Thread archived successfully`);
}

/**
 * Unarchive a thread in Gmail by adding the INBOX label back
 */
export async function unarchiveThreadInGmail(
  userId: string,
  threadId: string,
  gmail: gmail_v1.Gmail,
): Promise<void> {
  logger.log(
    `[Gmail Unarchive] Unarchiving thread: userId=${userId}, threadId=${threadId}`,
  );

  await gmail.users.threads.modify({
    userId: "me",
    id: threadId,
    requestBody: {
      addLabelIds: ["INBOX"],
    },
  });

  logger.log(`[Gmail Unarchive] Thread unarchived successfully`);
}

/**
 * Trash all messages in a thread
 */
export async function trashThreadInGmail(
  userId: string,
  threadId: string,
  gmail: gmail_v1.Gmail,
): Promise<void> {
  const threadData = await gmail.users.threads.get({
    userId: "me",
    id: threadId,
    format: "full",
  });

  const thread = threadData.data;
  const messages = thread.messages || [];

  for (const message of messages) {
    if (!message.id) continue;
    await gmail.users.messages.trash({
      userId: "me",
      id: message.id,
    });
  }
}

/**
 * Sync star status to Gmail
 */
export async function syncStarStatusToGmail(
  userId: string,
  threadId: string,
  starCount: number,
  gmail: gmail_v1.Gmail,
): Promise<void> {
  const shouldBeStarred = starCount > 0;

  logger.log(
    `[Gmail Star Sync] threadId=${threadId}, targetStarCount=${starCount}, shouldBeStarred=${shouldBeStarred}`,
  );

  const threadData = await gmail.users.threads.get({
    userId: "me",
    id: threadId,
    format: "metadata",
    metadataHeaders: ["Subject", "From"],
  });

  const thread = threadData.data;
  const messages = thread.messages || [];

  for (const message of messages) {
    if (!message.id) continue;
    const messageLabelIds = message.labelIds || [];
    const isCurrentlyStarred = messageLabelIds.includes("STARRED");

    if (shouldBeStarred && !isCurrentlyStarred) {
      await gmail.users.messages.modify({
        userId: "me",
        id: message.id,
        requestBody: {
          addLabelIds: ["STARRED"],
        },
      });
    } else if (!shouldBeStarred && isCurrentlyStarred) {
      await gmail.users.messages.modify({
        userId: "me",
        id: message.id,
        requestBody: {
          removeLabelIds: ["STARRED"],
        },
      });
    }
  }
}

/**
 * Sync read status to Gmail
 */
export async function syncReadStatusToGmail(
  userId: string,
  messageId: string,
  isRead: boolean,
  gmail: gmail_v1.Gmail,
): Promise<void> {
  try {
    await gmail.users.messages.modify({
      userId: "me",
      id: messageId,
      requestBody: {
        addLabelIds: isRead ? [] : ["UNREAD"],
        removeLabelIds: isRead ? ["UNREAD"] : [],
      },
    });
  } catch (error: unknown) {
    const apiError = isApiError(error) ? error : null;
    const errorMsg = isError(error) ? error.message : apiError?.message || "";
    const isPermissionError =
      apiError?.code === 403 ||
      (apiError?.response && (apiError.response as any).status === 403) ||
      errorMsg?.includes("Insufficient Permission");

    if (isPermissionError) {
      logger.warn(
        `Permission denied syncing read status to Gmail for message ${messageId}.`,
      );
    } else {
      logger.error(
        `Error syncing read status to Gmail for message ${messageId}:`,
        error,
      );
    }
    // Don't throw - allow operation to continue
  }
}

/**
 * Snooze a thread in Gmail by adding a custom label and removing INBOX
 */
export async function snoozeThreadInGmail(
  userId: string,
  threadId: string,
  snoozeLabelId: string,
  gmail: gmail_v1.Gmail,
): Promise<{ labeledCount: number }> {
  logger.log(`[Gmail Snooze] Starting snooze: threadId=${threadId}`);

  const threadData = await gmail.users.threads.get({
    userId: "me",
    id: threadId,
    format: "full",
  });

  const thread = threadData.data;
  const messages = thread.messages || [];
  let labeledCount = 0;

  for (const message of messages) {
    if (!message.id) continue;

    const messageLabelIds = message.labelIds || [];
    const isCurrentlySnoozed = messageLabelIds.includes(snoozeLabelId);
    const hasInboxLabel = messageLabelIds.includes("INBOX");

    const addLabelIds: string[] = [];
    const removeLabelIds: string[] = [];

    if (!isCurrentlySnoozed) {
      addLabelIds.push(snoozeLabelId);
    }
    if (hasInboxLabel) {
      removeLabelIds.push("INBOX");
    }

    if (addLabelIds.length > 0 || removeLabelIds.length > 0) {
      await gmail.users.messages.modify({
        userId: "me",
        id: message.id,
        requestBody: {
          ...(addLabelIds.length > 0 && { addLabelIds }),
          ...(removeLabelIds.length > 0 && { removeLabelIds }),
        },
      });
      labeledCount++;
    }
  }

  logger.log(`[Gmail Snooze] Thread snoozed: labeledCount=${labeledCount}`);
  return { labeledCount };
}

/**
 * Unsnooze a thread in Gmail by removing custom label and adding INBOX back
 */
export async function unsnoozeThreadInGmail(
  userId: string,
  threadId: string,
  snoozeLabelId: string,
  gmail: gmail_v1.Gmail,
): Promise<{ modifiedCount: number }> {
  logger.log(`[Gmail Unsnooze] Starting unsnooze: threadId=${threadId}`);

  const threadData = await gmail.users.threads.get({
    userId: "me",
    id: threadId,
    format: "full",
  });

  const thread = threadData.data;
  const messages = thread.messages || [];
  let modifiedCount = 0;

  for (const message of messages) {
    if (!message.id) continue;

    const messageLabelIds = message.labelIds || [];
    const hasSnoozedLabel = messageLabelIds.includes(snoozeLabelId);
    const hasInboxLabel = messageLabelIds.includes("INBOX");

    const addLabelIds: string[] = [];
    const removeLabelIds: string[] = [];

    if (hasSnoozedLabel) {
      removeLabelIds.push(snoozeLabelId);
    }
    if (!hasInboxLabel) {
      addLabelIds.push("INBOX");
    }

    if (addLabelIds.length > 0 || removeLabelIds.length > 0) {
      await gmail.users.messages.modify({
        userId: "me",
        id: message.id,
        requestBody: {
          ...(addLabelIds.length > 0 && { addLabelIds }),
          ...(removeLabelIds.length > 0 && { removeLabelIds }),
        },
      });
      modifiedCount++;
    }
  }

  logger.log(
    `[Gmail Unsnooze] Thread unsnoozed: modifiedCount=${modifiedCount}`,
  );
  return { modifiedCount };
}

/**
 * Ensure a custom label exists in Gmail, creating it if necessary
 */
export async function ensureLabelExists(
  gmail: gmail_v1.Gmail,
  labelName: string,
  labelCache: Map<string, Map<string, string>>,
  bearlyMailLabelCache: Map<string, string>,
  userId: string,
): Promise<string> {
  const cacheKey = `${userId}_${labelName}`;
  const cachedLabelId = bearlyMailLabelCache.get(cacheKey);
  if (cachedLabelId) {
    return cachedLabelId;
  }

  try {
    // First, try to find the label in existing labels
    const response = await gmail.users.labels.list({ userId: "me" });
    const labels = response.data.labels || [];

    for (const label of labels) {
      if (label.name === labelName && label.id) {
        bearlyMailLabelCache.set(cacheKey, label.id);
        return label.id;
      }
    }

    // Label doesn't exist, create it
    logger.log(`Creating ${labelName} label for user ${userId}`);
    const createResponse = await gmail.users.labels.create({
      userId: "me",
      requestBody: {
        name: labelName,
        labelListVisibility: "labelShow",
        messageListVisibility: "show",
      },
    });

    const labelId = createResponse.data.id;
    if (labelId) {
      bearlyMailLabelCache.set(cacheKey, labelId);
      labelCache.delete(userId);
      return labelId;
    }

    throw new Error("Failed to create label: no ID returned");
  } catch (error: unknown) {
    if (isApiError(error) && error.code === HTTP_STATUS.CONFLICT) {
      // Label already exists
      const response = await gmail.users.labels.list({ userId: "me" });
      const labels = response.data.labels || [];
      for (const label of labels) {
        if (label.name === labelName && label.id) {
          bearlyMailLabelCache.set(cacheKey, label.id);
          return label.id;
        }
      }
    }

    logger.error(`Failed to ensure ${labelName} label exists:`, error);
    logErrorToFile(
      `Failed to ensure ${labelName} label exists (userId: ${userId})`,
      error,
      "GmailProvider",
    );
    throw error;
  }
}

import {
  EmailRecipient,
  EmailAttachmentData,
} from "../../interfaces/email-provider.interface";
import { QUERY_LIMITS } from "../../../constants/query-limits";

/**
 * Build email content with support for attachments and HTML using multipart MIME
 */
export function buildEmailContent(options: {
  to: EmailRecipient[];
  subject: string;
  body: string;
  htmlBody?: string;
  cc?: EmailRecipient[];
  bcc?: EmailRecipient[];
  attachments?: EmailAttachmentData[];
  headers?: Record<string, string>;
}): string {
  const formatRecipient = (r: EmailRecipient) =>
    r.name ? `${r.name} <${r.email}>` : r.email;

  const toHeader = options.to.map(formatRecipient).join(", ");
  const ccHeader =
    options.cc && options.cc.length > 0
      ? options.cc.map(formatRecipient).join(", ")
      : null;
  const bccHeader =
    options.bcc && options.bcc.length > 0
      ? options.bcc.map(formatRecipient).join(", ")
      : null;

  const hasAttachments = options.attachments && options.attachments.length > 0;
  const hasHtmlBody = !!options.htmlBody;

  // Build email headers
  const headerLines: string[] = [
    `To: ${toHeader}`,
    `Subject: ${options.subject}`,
    "MIME-Version: 1.0",
  ];

  if (ccHeader) {
    headerLines.push(`Cc: ${ccHeader}`);
  }
  if (bccHeader) {
    headerLines.push(`Bcc: ${bccHeader}`);
  }

  // Add custom headers if provided
  if (options.headers) {
    for (const [key, value] of Object.entries(options.headers)) {
      headerLines.push(`${key}: ${value}`);
    }
  }

  let bodyContent: string;

  if (hasAttachments) {
    bodyContent = buildMultipartMixedBody(options, headerLines);
  } else if (hasHtmlBody) {
    bodyContent = buildMultipartAlternativeBody(options, headerLines);
  } else {
    // Simple text email
    headerLines.push("Content-Type: text/plain; charset=UTF-8");
    bodyContent = options.body;
  }

  return [...headerLines, "", bodyContent].join("\r\n");
}

function buildMultipartMixedBody(
  options: {
    body: string;
    htmlBody?: string;
    attachments?: EmailAttachmentData[];
  },
  headerLines: string[],
): string {
  const mixedBoundary = `----=_Part_${Date.now()}_${Math.random().toString(QUERY_LIMITS.RANDOM_BASE_36).substring(QUERY_LIMITS.RANDOM_STRING_START, QUERY_LIMITS.MESSAGE_ID_SUFFIX)}`;
  headerLines.push(
    `Content-Type: multipart/mixed; boundary="${mixedBoundary}"`,
  );

  const parts: string[] = [];

  if (options.htmlBody) {
    // Use multipart/alternative for text + HTML
    const altBoundary = `----=_Alt_${Date.now()}_${Math.random().toString(QUERY_LIMITS.RANDOM_BASE_36).substring(QUERY_LIMITS.RANDOM_STRING_START, QUERY_LIMITS.MESSAGE_ID_SUFFIX)}`;
    parts.push(`--${mixedBoundary}`);
    parts.push(
      `Content-Type: multipart/alternative; boundary="${altBoundary}"`,
    );
    parts.push("");

    // Plain text part
    parts.push(`--${altBoundary}`);
    parts.push("Content-Type: text/plain; charset=UTF-8");
    parts.push("Content-Transfer-Encoding: 7bit");
    parts.push("");
    parts.push(options.body);

    // HTML part
    parts.push(`--${altBoundary}`);
    parts.push("Content-Type: text/html; charset=UTF-8");
    parts.push("Content-Transfer-Encoding: 7bit");
    parts.push("");
    parts.push(options.htmlBody);

    parts.push(`--${altBoundary}--`);
  } else {
    // Text body part only
    parts.push(`--${mixedBoundary}`);
    parts.push("Content-Type: text/plain; charset=UTF-8");
    parts.push("Content-Transfer-Encoding: 7bit");
    parts.push("");
    parts.push(options.body);
  }

  // Attachment parts
  if (options.attachments) {
    for (const attachment of options.attachments) {
      parts.push(`--${mixedBoundary}`);
      parts.push(
        `Content-Type: ${attachment.mimeType}; name="${attachment.filename}"`,
      );
      parts.push("Content-Transfer-Encoding: base64");
      parts.push(
        `Content-Disposition: attachment; filename="${attachment.filename}"`,
      );
      parts.push("");
      // Encode attachment content as base64, split into 76-character lines
      const base64Content = attachment.content.toString("base64");
      const chunkedContent =
        base64Content.match(/.{1,76}/g)?.join("\r\n") || base64Content;
      parts.push(chunkedContent);
    }
  }

  parts.push(`--${mixedBoundary}--`);
  return parts.join("\r\n");
}

function buildMultipartAlternativeBody(
  options: {
    body: string;
    htmlBody?: string;
  },
  headerLines: string[],
): string {
  const altBoundary = `----=_Alt_${Date.now()}_${Math.random().toString(QUERY_LIMITS.RANDOM_BASE_36).substring(QUERY_LIMITS.RANDOM_STRING_START, QUERY_LIMITS.MESSAGE_ID_SUFFIX)}`;
  headerLines.push(
    `Content-Type: multipart/alternative; boundary="${altBoundary}"`,
  );

  const parts: string[] = [];

  // Plain text part
  parts.push(`--${altBoundary}`);
  parts.push("Content-Type: text/plain; charset=UTF-8");
  parts.push("Content-Transfer-Encoding: 7bit");
  parts.push("");
  parts.push(options.body);

  // HTML part
  if (options.htmlBody) {
    parts.push(`--${altBoundary}`);
    parts.push("Content-Type: text/html; charset=UTF-8");
    parts.push("Content-Transfer-Encoding: 7bit");
    parts.push("");
    parts.push(options.htmlBody);
  }

  parts.push(`--${altBoundary}--`);
  return parts.join("\r\n");
}

/**
 * Encode email content for Gmail API
 */
export function encodeEmailForGmail(emailContent: string): string {
  return Buffer.from(emailContent)
    .toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

import { Logger } from "@nestjs/common";
import { gmail_v1 } from "googleapis";
import { QUERY_LIMITS } from "../../../constants/query-limits";
import { isApiError, isError } from "../../../types/common";
import { logErrorToFile } from "../../../utils/error-logger";

const logger = new Logger("GmailSync");

/**
 * Verify thread statuses in Gmail API in batches with concurrency limits
 * Returns array of updates: { threadId, starCount, isArchived }[]
 */
export async function verifyThreadStatusesInGmail(
  userId: string,
  threadIds: string[],
  gmail: gmail_v1.Gmail,
): Promise<
  Array<{ threadId: string; starCount: number; isArchived: boolean }>
> {
  const updates: Array<{
    threadId: string;
    starCount: number;
    isArchived: boolean;
  }> = [];

  const BATCH_SIZE = 50;
  const CONCURRENCY_LIMIT = 10;

  for (let i = 0; i < threadIds.length; i += BATCH_SIZE) {
    const batch = threadIds.slice(i, i + BATCH_SIZE);
    logger.debug(
      `Processing batch ${Math.floor(i / BATCH_SIZE) + 1} of ${Math.ceil(threadIds.length / BATCH_SIZE)} (${batch.length} threads)`,
    );

    const batchPromises: Promise<void>[] = [];
    for (let j = 0; j < batch.length; j += CONCURRENCY_LIMIT) {
      const concurrentBatch = batch.slice(j, j + CONCURRENCY_LIMIT);
      const concurrentPromises = concurrentBatch.map(async (threadId) => {
        if (!threadId) return;

        try {
          const threadData = await gmail.users.threads.get({
            userId: "me",
            id: threadId,
            format: "metadata",
            metadataHeaders: ["Subject", "From"],
          });

          const thread = threadData.data;
          if (!thread.messages || thread.messages.length === 0) {
            updates.push({ threadId, starCount: 0, isArchived: true });
            return;
          }

          const latestMessage = thread.messages[thread.messages.length - 1];
          const latestLabelIds = latestMessage.labelIds || [];

          updates.push({
            threadId,
            starCount: latestLabelIds.includes("STARRED") ? 3 : 0,
            isArchived: !latestLabelIds.includes("INBOX"),
          });
        } catch (threadError: unknown) {
          if (isApiError(threadError) && threadError.code === 404) {
            logger.debug(
              `Thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... not found in Gmail (may be deleted)`,
            );
            updates.push({ threadId, starCount: 0, isArchived: true });
          } else {
            const errorMsg = isError(threadError)
              ? threadError.message
              : isApiError(threadError)
                ? threadError.message
                : "Unknown error";
            logger.warn(
              `Error checking thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...:`,
              errorMsg,
            );
            logErrorToFile(
              `Error checking thread in verifyThreadStatusesInGmail (userId: ${userId}, threadId: ${threadId})`,
              threadError,
              "GmailProvider",
            );
          }
        }
      });

      batchPromises.push(...concurrentPromises);
      await Promise.all(concurrentPromises);
    }

    await Promise.all(batchPromises);
  }

  return updates;
}

/**
 * Get thread status updates for existing starred threads
 */
export async function getExistingThreadUpdates(
  userId: string,
  threadsToCheck: Array<{ threadId: string }>,
  processedThreadIds: Set<string>,
  gmail: gmail_v1.Gmail,
): Promise<
  Array<{ threadId: string; starCount: number; isArchived: boolean }>
> {
  const updates: Array<{
    threadId: string;
    starCount: number;
    isArchived: boolean;
  }> = [];

  for (const dbThread of threadsToCheck) {
    if (processedThreadIds.has(dbThread.threadId)) continue;

    try {
      const threadData = await gmail.users.threads.get({
        userId: "me",
        id: dbThread.threadId,
        format: "metadata",
        metadataHeaders: ["Subject", "From"],
      });

      const thread = threadData.data;
      if (!thread.messages || thread.messages.length === 0) {
        updates.push({
          threadId: dbThread.threadId,
          starCount: 0,
          isArchived: true,
        });
        continue;
      }

      const latestMessage = thread.messages[thread.messages.length - 1];
      const latestLabelIds = latestMessage.labelIds || [];

      updates.push({
        threadId: dbThread.threadId,
        starCount: latestLabelIds.includes("STARRED") ? 3 : 0,
        isArchived: !latestLabelIds.includes("INBOX"),
      });
    } catch (threadError: unknown) {
      if (isApiError(threadError) && threadError.code === 404) {
        logger.debug(
          `Existing thread ${dbThread.threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... not found in Gmail`,
        );
        updates.push({
          threadId: dbThread.threadId,
          starCount: 0,
          isArchived: true,
        });
      } else {
        const errorMsg = isError(threadError)
          ? threadError.message
          : isApiError(threadError)
            ? threadError.message
            : "Unknown error";
        logger.warn(
          `Error checking existing thread ${dbThread.threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...:`,
          errorMsg,
        );
        logErrorToFile(
          `Error checking existing starred thread (userId: ${userId}, threadId: ${dbThread.threadId})`,
          threadError,
          "GmailProvider",
        );
      }
    }
  }

  return updates;
}

/**
 * Check if error is an auth error
 */
export function isGmailAuthError(error: unknown): boolean {
  const apiError = isApiError(error) ? error : null;
  const errorMsg = isError(error) ? error.message : apiError?.message || "";
  return (
    apiError?.code === 401 ||
    (apiError?.response && (apiError.response as any).status === 401) ||
    (errorMsg && errorMsg.includes("invalid_grant"))
  );
}

import { Injectable, Inject, forwardRef, Logger } from "@nestjs/common";
import { UsersService } from "../../users/users.service";
import { EmailsService } from "../emails.service";
import { ScanEmailService } from "../scan-email.service";
import {
  EmailProvider,
  RawEmailMessage,
  EmailRecipient,
  EmailAttachmentData,
} from "../interfaces/email-provider.interface";
import PgBoss = require("pg-boss");
import { getJobPriority } from "../../queue/job-priorities";
import { QUERY_LIMITS } from "../../constants/query-limits";
import { BODY_PREVIEW_LENGTHS } from "../../constants/llm-constants";
import { DAYS } from "../../constants/time-constants";
import { isApiError, isError } from "../../types/common";
import { Office365AccountsService } from "../../office365-accounts/office365-accounts.service";
import { ConfigService } from "@nestjs/config";
import {
  parseOffice365Message,
  MicrosoftGraphMessage,
} from "./office365/office365-message-parser";
import { Office365Client } from "./office365/office365-client";
import {
  isWithinGracePeriod,
  logOffice365AuthFailure as logAuthFailure,
} from "./office365/office365-auth";
import {
  verifyThreadStatusesInOffice365,
  getExistingThreadUpdates,
} from "./office365/office365-sync";
import {
  archiveThreadInOffice365,
  unarchiveThreadInOffice365,
  sendReplyViaOffice365,
  sendEmailViaOffice365,
  searchEmailsViaOffice365,
  isAuthError,
} from "./office365/office365-operations";

@Injectable()
export class Office365Provider implements EmailProvider {
  private readonly logger = new Logger(Office365Provider.name);
  private readonly progressUpdateCounters = new Map<string, number>();
  private readonly client: Office365Client;

  constructor(
    private usersService: UsersService,
    @Inject(forwardRef(() => EmailsService))
    private emailsService: EmailsService,
    private scanEmailService: ScanEmailService,
    @Inject("PG_BOSS") private readonly boss: PgBoss,
    private office365AccountsService: Office365AccountsService,
    private configService: ConfigService,
  ) {
    this.client = new Office365Client(office365AccountsService, configService);
  }

  async isConnected(userId: string): Promise<boolean> {
    return this.office365AccountsService.hasConnectedOffice365(userId);
  }

  async syncEmails(userId: string): Promise<void> {
    const primaryAccount =
      await this.office365AccountsService.findPrimary(userId);
    if (!primaryAccount) {
      this.logger.log(
        `User ${userId} not connected to Office 365, skipping email sync.`,
      );
      return;
    }

    const user = await this.usersService.findOne(userId);
    if (!user) {
      this.logger.warn(`User ${userId} not found`);
      return;
    }

    const isInitialSync = !user.lastEmailSyncAt;
    const isRecentLogin = isWithinGracePeriod(user);

    // Validate refresh token
    if (!primaryAccount.refreshToken) {
      await this.handleMissingRefreshToken(
        userId,
        user,
        primaryAccount,
        isRecentLogin,
      );
    }

    const { accessToken } = primaryAccount;
    const graphClient = this.client.createGraphClient(accessToken);

    // Validate token
    try {
      await graphClient.get("/me", { params: { $select: "id" } });
      this.logger.debug(`Token validated for user ${userId}`);
    } catch (refreshError: unknown) {
      await this.handleTokenValidationError(
        userId,
        user,
        primaryAccount,
        refreshError,
      );
    }

    try {
      await this.performSync(userId, graphClient, isInitialSync);
      await this.usersService.update(userId, {
        lastEmailSyncAt: new Date(),
      });
    } catch (error: unknown) {
      await this.handleSyncError(userId, user, primaryAccount, error);
    }
  }

  private async handleMissingRefreshToken(
    userId: string,
    user: any,
    primaryAccount: any,
    isRecentLogin: boolean,
  ): Promise<never> {
    await logAuthFailure(
      userId,
      user.email || null,
      "syncEmails-missingRefreshToken",
      new Error("Refresh token missing"),
      {
        hasAccessToken: !!primaryAccount.accessToken,
        isRecentLogin,
        userUpdatedAt: user?.updatedAt?.toISOString() || null,
      },
    );

    if (!isRecentLogin && !primaryAccount.needsRelogin) {
      await this.office365AccountsService.updateTokens(
        primaryAccount.id,
        userId,
        primaryAccount.accessToken,
        undefined,
      );
      throw new Error("Refresh token missing - please log in again");
    } else if (isRecentLogin) {
      this.logger.warn(
        `⚠️ Refresh token missing for recently logged-in user ${userId}, but within grace period.`,
      );
      throw new Error(
        "Refresh token missing (within grace period - will retry)",
      );
    }
    throw new Error("Refresh token missing - please log in again");
  }

  private async handleTokenValidationError(
    userId: string,
    user: any,
    primaryAccount: any,
    refreshError: unknown,
  ): Promise<never> {
    let currentAccount = primaryAccount;
    try {
      currentAccount = await this.office365AccountsService.findPrimary(userId);
    } catch (accountError) {
      this.logger.error(
        `Could not re-fetch account for grace period check:`,
        accountError,
      );
    }

    const isRecentLoginNow = isWithinGracePeriod(user);
    await logAuthFailure(
      userId,
      user.email || null,
      "syncEmails-tokenValidation",
      refreshError,
      {
        hasRefreshToken: !!currentAccount?.refreshToken,
        hasAccessToken: !!currentAccount?.accessToken,
        isRecentLogin: isRecentLoginNow,
        gracePeriodActive: isRecentLoginNow,
      },
    );

    if (!isRecentLoginNow) {
      await this.office365AccountsService.updateTokens(
        currentAccount.id,
        userId,
        currentAccount.accessToken,
        undefined,
      );
      throw new Error("Token validation failed - please log in again");
    }
    throw new Error(
      "Token validation failed (within grace period - will retry)",
    );
  }

  private async performSync(
    userId: string,
    graphClient: any,
    isInitialSync: boolean,
  ): Promise<void> {
    const [inboxResponse, importantResponse] = await Promise.all([
      graphClient.get("/me/mailFolders/inbox/messages", {
        params: {
          $filter: "isRead eq false",
          $orderby: "receivedDateTime desc",
          $top: 500,
          $select:
            "id,conversationId,subject,from,receivedDateTime,isRead,importance",
        },
      }),
      graphClient.get("/me/messages", {
        params: {
          $filter: "importance eq 'high'",
          $orderby: "receivedDateTime desc",
          $top: 500,
          $select:
            "id,conversationId,subject,from,receivedDateTime,isRead,importance",
        },
      }),
    ]);

    const inboxMessages = inboxResponse.data.value || [];
    const importantMessages = importantResponse.data.value || [];

    const conversationMap = new Map<string, MicrosoftGraphMessage[]>();
    for (const msg of [...inboxMessages, ...importantMessages]) {
      if (!msg.id) continue;
      const conversationId = msg.conversationId || msg.id;
      if (!conversationMap.has(conversationId)) {
        conversationMap.set(conversationId, []);
      }
      conversationMap.get(conversationId)!.push(msg);
    }

    this.logger.debug(
      `Found ${inboxMessages.length} inbox and ${importantMessages.length} important messages (${conversationMap.size} unique conversations)`,
    );

    const threadUpdates = await this.processConversations(
      userId,
      conversationMap,
      inboxMessages,
      graphClient,
      isInitialSync,
    );

    await this.applyThreadUpdates(userId, threadUpdates);
    await this.checkExistingStarredThreads(
      userId,
      conversationMap,
      graphClient,
    );
    await this.checkNonArchivedThreads(userId, conversationMap, graphClient);
  }

  private async processConversations(
    userId: string,
    conversationMap: Map<string, MicrosoftGraphMessage[]>,
    inboxMessages: any[],
    graphClient: any,
    isInitialSync: boolean,
  ): Promise<{
    starUpdates: { threadId: string; starCount: number }[];
    archivedUpdates: { threadId: string; isArchived: boolean }[];
  }> {
    const starUpdates: { threadId: string; starCount: number }[] = [];
    const archivedUpdates: { threadId: string; isArchived: boolean }[] = [];

    for (const [conversationId, messages] of conversationMap.entries()) {
      if (!conversationId || messages.length === 0) continue;

      try {
        const latestMessage = messages.sort(
          (a, b) =>
            new Date(b.receivedDateTime || 0).getTime() -
            new Date(a.receivedDateTime || 0).getTime(),
        )[0];

        const isInInbox = inboxMessages.some(
          (m) => m.conversationId === conversationId || m.id === conversationId,
        );
        const isImportant = latestMessage.importance === "high";

        starUpdates.push({
          threadId: conversationId,
          starCount: isImportant ? 3 : 0,
        });
        archivedUpdates.push({
          threadId: conversationId,
          isArchived: !isInInbox,
        });

        for (const message of messages) {
          if (!message.id) continue;
          await this.processMessage(
            userId,
            message,
            conversationId,
            graphClient,
            isImportant ? 3 : 0,
            isInitialSync,
          );
        }
      } catch (threadError: unknown) {
        this.handleThreadProcessingError(conversationId, threadError);
      }
    }

    return { starUpdates, archivedUpdates };
  }

  private async processMessage(
    userId: string,
    message: any,
    conversationId: string,
    graphClient: any,
    starCount: number,
    isInitialSync: boolean,
  ): Promise<void> {
    const fullMsg = await graphClient.get(`/me/messages/${message.id}`, {
      params: {
        $select:
          "id,subject,from,receivedDateTime,isRead,body,bodyPreview,conversationId,importance,parentFolderId",
      },
    });

    const messageData = fullMsg.data as MicrosoftGraphMessage;
    const rawEmail = parseOffice365Message(messageData);
    if (!rawEmail) return;

    const existing = await this.emailsService.getEmailByMessageId(
      userId,
      message.id,
    );
    if (existing) {
      if (existing.isRead !== messageData.isRead) {
        await this.emailsService.updateEmail(existing.id, {
          isRead: messageData.isRead || false,
        });
      }
      return;
    }

    await this.emailsService.createEmail(
      userId,
      { ...rawEmail, starCount } as RawEmailMessage,
      { skipBatching: isInitialSync },
    );
  }

  private handleThreadProcessingError(
    conversationId: string,
    error: unknown,
  ): void {
    if (isApiError(error) && error.code === 404) {
      this.logger.debug(
        `Conversation ${conversationId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... not found`,
      );
    } else {
      const errorMsg = isError(error)
        ? error.message
        : isApiError(error)
          ? error.message
          : "Unknown error";
      this.logger.warn(
        `Error processing conversation ${conversationId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...`,
        errorMsg,
      );
    }
  }

  private async applyThreadUpdates(
    userId: string,
    updates: {
      starUpdates: { threadId: string; starCount: number }[];
      archivedUpdates: { threadId: string; isArchived: boolean }[];
    },
  ): Promise<void> {
    if (updates.starUpdates.length > 0) {
      await this.emailsService.batchUpdateThreadStarCount(
        userId,
        updates.starUpdates,
      );
    }
    if (updates.archivedUpdates.length > 0) {
      await this.emailsService.batchUpdateThreadArchivedStatuses(
        userId,
        updates.archivedUpdates,
      );
    }
  }

  private async checkExistingStarredThreads(
    userId: string,
    conversationMap: Map<string, any>,
    graphClient: any,
  ): Promise<void> {
    const existingStarredThreads =
      await this.emailsService.getExistingStarredThreads(userId);
    const threadMapKeys = new Set(conversationMap.keys());
    const existingThreadUpdates = await getExistingThreadUpdates(
      userId,
      existingStarredThreads,
      threadMapKeys,
      graphClient,
    );

    if (existingThreadUpdates.length > 0) {
      await this.emailsService.batchUpdateThreadStarCount(
        userId,
        existingThreadUpdates.map((u) => ({
          threadId: u.threadId,
          starCount: u.starCount,
        })),
      );
      await this.emailsService.batchUpdateThreadArchivedStatuses(
        userId,
        existingThreadUpdates.map((u) => ({
          threadId: u.threadId,
          isArchived: u.isArchived,
        })),
      );
    }
  }

  private async checkNonArchivedThreads(
    userId: string,
    conversationMap: Map<string, any>,
    graphClient: any,
  ): Promise<void> {
    const threadsNeedingCheck =
      await this.emailsService.getNonArchivedThreadsNeedingCheck(
        userId,
        QUERY_LIMITS.PROVIDER_BATCH_SIZE,
      );
    const threadsToCheck = threadsNeedingCheck.filter(
      (threadId) => !conversationMap.has(threadId),
    );

    if (threadsToCheck.length > 0) {
      const updates = await verifyThreadStatusesInOffice365(
        userId,
        threadsToCheck,
        graphClient,
      );

      if (updates.length > 0) {
        await this.emailsService.batchUpdateThreadStarCount(
          userId,
          updates.map((u) => ({
            threadId: u.threadId,
            starCount: u.starCount,
          })),
        );
        await this.emailsService.batchUpdateThreadArchivedStatuses(
          userId,
          updates.map((u) => ({
            threadId: u.threadId,
            isArchived: u.isArchived,
          })),
        );
        await this.emailsService.updateThreadsLastCheckedAt(
          userId,
          updates.map((u) => u.threadId),
        );
      }
    }
  }

  private async handleSyncError(
    userId: string,
    user: any,
    primaryAccount: any,
    error: unknown,
  ): Promise<never> {
    const apiError = isApiError(error) ? error : null;
    const errorMsg = isError(error) ? error.message : apiError?.message || "";
    const isAuthErrorFlag =
      apiError?.code === 401 ||
      (apiError?.response && (apiError.response as any).status === 401) ||
      errorMsg.includes("Token refresh failed");

    if (isAuthErrorFlag) {
      let currentUser = user;
      try {
        currentUser = await this.usersService.findOne(userId);
      } catch {}

      const isRecentLogin = isWithinGracePeriod(currentUser);
      await logAuthFailure(
        userId,
        currentUser?.email || null,
        "syncEmails-office365Api",
        error,
        {
          hasRefreshToken: !!primaryAccount.refreshToken,
          isRecentLogin,
          gracePeriodActive: isRecentLogin,
        },
      );

      if (!isRecentLogin) {
        await this.office365AccountsService.updateTokens(
          primaryAccount.id,
          userId,
          primaryAccount.accessToken,
          undefined,
        );
      }
    }
    throw error;
  }

  async processScanEmail(userId: string, messageId: string): Promise<void> {
    const startTime = Date.now();
    const primaryAccount =
      await this.office365AccountsService.findPrimary(userId);
    if (!primaryAccount) return;

    const existing = await this.scanEmailService.findByMessageId(
      userId,
      messageId,
    );
    if (existing) {
      await this.updateScanProgress(userId);
      return;
    }

    const { accessToken } = primaryAccount;
    const graphClient = this.client.createGraphClient(accessToken);

    try {
      const fullMsg = await graphClient.get(`/me/messages/${messageId}`, {
        params: {
          $select:
            "id,subject,from,receivedDateTime,isRead,body,bodyPreview,conversationId,importance,parentFolderId",
        },
      });

      const messageData = fullMsg.data as MicrosoftGraphMessage;
      const rawEmail = parseOffice365Message(messageData);
      if (!rawEmail) {
        await this.updateScanProgress(userId);
        return;
      }

      const isArchived = messageData.parentFolderId !== "inbox";
      await this.scanEmailService.createScanEmail(userId, {
        ...rawEmail,
        isArchived,
      });
      await this.updateScanProgress(userId);
      this.logger.log(
        `[processScanEmail] Completed email ${messageId} in ${Date.now() - startTime}ms`,
      );
    } catch (error: unknown) {
      await this.updateScanProgress(userId);
      if (isAuthError(error)) {
        try {
          await this.client.refreshTokenIfNeeded(userId, primaryAccount.id);
          await this.processScanEmail(userId, messageId);
        } catch {}
      }
    }
  }

  private async updateScanProgress(userId: string): Promise<void> {
    const currentCount = (this.progressUpdateCounters.get(userId) || 0) + 1;
    this.progressUpdateCounters.set(userId, currentCount);

    if (currentCount % 10 === 0) {
      const result = await this.usersService.incrementScanProgress(userId, 10);
      this.progressUpdateCounters.set(userId, 0);
      if (result.isComplete) {
        this.progressUpdateCounters.delete(userId);
        await this.boss.send(
          "analyze-scan-results",
          { userId },
          {
            priority: getJobPriority("analyze-scan-results", false),
          },
        );
      }
    }
  }

  async scanHistory(userId: string): Promise<void> {
    const primaryAccount =
      await this.office365AccountsService.findPrimary(userId);
    if (!primaryAccount) return;

    let { accessToken } = primaryAccount;
    const graphClient = this.client.createGraphClient(accessToken);

    try {
      const sevenDaysAgo = new Date();
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - DAYS.WEEK);

      const response = await graphClient.get("/me/mailFolders/inbox/messages", {
        params: {
          $filter: `receivedDateTime ge ${sevenDaysAgo.toISOString()}`,
          $orderby: "receivedDateTime desc",
          $top: 300,
          $select: "id",
        },
      });

      const messages = response.data.value || [];
      const total = Math.min(
        messages.length,
        BODY_PREVIEW_LENGTHS.BATCH_PREVIEW,
      );

      await this.usersService.update(userId, {
        scanTotal: total,
        scanProgress: 0,
      });
      this.progressUpdateCounters.set(userId, 0);

      for (let i = 0; i < total; i++) {
        if (!messages[i].id) continue;
        try {
          await this.processScanEmail(userId, messages[i].id);
        } catch {}
      }

      const finalProgress = await this.usersService.incrementScanProgress(
        userId,
        this.progressUpdateCounters.get(userId) || 0,
      );
      this.progressUpdateCounters.delete(userId);

      if (finalProgress.isComplete) {
        await this.boss.send(
          "analyze-scan-results",
          { userId },
          { priority: getJobPriority("analyze-scan-results", false) },
        );
      }
      await this.usersService.update(userId, { hasScannedHistory: true });
    } catch (error: unknown) {
      if (isAuthError(error)) {
        try {
          accessToken = await this.client.refreshTokenIfNeeded(
            userId,
            primaryAccount.id,
          );
          await this.scanHistory(userId);
          return;
        } catch {}
        throw new Error("Token refresh failed - please reconnect");
      }
      throw error;
    }
  }

