import { RawEmailMessage } from "../../interfaces/email-provider.interface";

/**
 * Zoho Mail API message interface
 */
export interface ZohoMailMessage {
  uid?: string;
  threadId?: string;
  subject?: string;
  from?: {
    address?: string;
    personal?: string;
  };
  replyTo?: {
    address?: string;
    personal?: string;
  };
  receivedTime?: number;
  isRead?: boolean;
  content?: {
    html?: string;
    text?: string;
  };
  body?: string;
  importance?: "low" | "normal" | "high";
  folderId?: string;
  folderName?: string;
}

/**
 * Parse Zoho Mail message to RawEmailMessage format
 */
export function parseZohoMessage(
  messageData: ZohoMailMessage,
): RawEmailMessage | null {
  if (!messageData.uid || !messageData.threadId) {
    return null;
  }

  const from = messageData.from?.address || "";
  const fromName = messageData.from?.personal || "";
  const replyTo = messageData.replyTo?.address || undefined;
  const subject = messageData.subject || "(No Subject)";
  const { threadId } = messageData;
  const importance = messageData.importance || "normal";
  const starCount = importance === "high" ? 3 : importance === "low" ? 1 : 0;

  // Extract body content
  const htmlBody = messageData.content?.html || messageData.body || "";
  const bodyText = messageData.content?.text || "";
  const body =
    bodyText ||
    (htmlBody ? htmlBody.replace(/<[^>]*>/g, "").trim() : "") ||
    "(No content)";

  return {
    messageId: messageData.uid,
    threadId,
    subject,
    from,
    fromName,
    replyTo,
    body,
    htmlBody: htmlBody || undefined,
    starCount,
    receivedAt: messageData.receivedTime
      ? new Date(messageData.receivedTime * 1000)
      : new Date(),
    isRead: messageData.isRead || false,
  };
}

/**
 * Extract body content from Zoho Mail message
 */
export function extractBodyFromZohoMessage(messageData: ZohoMailMessage): {
  body: string;
  htmlBody?: string;
} {
  const htmlBody = messageData.content?.html || messageData.body || "";
  const bodyText = messageData.content?.text || "";

  let body = "";
  let htmlBodyResult: string | undefined;

  if (htmlBody) {
    htmlBodyResult = htmlBody;
    body = bodyText || htmlBody.replace(/<[^>]*>/g, "").trim();
  } else {
    body = bodyText;
  }

  // Ensure body is never empty (required by DB constraint)
  if (!body || body.trim() === "") {
    if (htmlBodyResult) {
      body = htmlBodyResult.replace(/<[^>]*>/g, "").trim();
    }
    if (!body || body.trim() === "") {
      body = "(No content)";
    }
  }

  return { body, htmlBody: htmlBodyResult };
}

import { Logger } from "@nestjs/common";
import { AxiosInstance } from "axios";
import { isApiError } from "../../../types/common";

const logger = new Logger("ZohoOperations");

/**
 * Archive a thread in Zoho by marking messages as read and moving to archive
 */
export async function archiveThreadInZoho(
  userId: string,
  threadId: string,
  zohoClient: AxiosInstance,
  zohoAccountId: string,
): Promise<{ success: boolean; archivedCount: number; totalCount: number }> {
  logger.log(
    `[Zoho Archive] Fetching messages for thread: userId=${userId}, threadId=${threadId}`,
  );

  const response = await zohoClient.get(`/accounts/${zohoAccountId}/messages`, {
    params: { threadId },
  });

  const messages = response.data.data || [];
  logger.log(`[Zoho Archive] Found ${messages.length} messages in thread`);

  let archivedCount = 0;
  for (const msg of messages) {
    try {
      await zohoClient.put(
        `/accounts/${zohoAccountId}/messages/${msg.uid}/markAsRead`,
        {},
      );
      await zohoClient.post(
        `/accounts/${zohoAccountId}/messages/${msg.uid}/move`,
        { folderid: "archive" },
      );
      archivedCount++;
    } catch (error) {
      logger.error(
        `[Zoho Archive] Failed to archive message ${msg.uid}:`,
        error,
      );
    }
  }

  logger.log(
    `[Zoho Archive] Archived ${archivedCount}/${messages.length} messages`,
  );
  return {
    success: archivedCount > 0 || messages.length === 0,
    archivedCount,
    totalCount: messages.length,
  };
}

/**
 * Unarchive a thread in Zoho by moving messages back to inbox
 */
export async function unarchiveThreadInZoho(
  userId: string,
  threadId: string,
  zohoClient: AxiosInstance,
  zohoAccountId: string,
): Promise<{ success: boolean; movedCount: number; totalCount: number }> {
  const response = await zohoClient.get(`/accounts/${zohoAccountId}/messages`, {
    params: { threadId, folderid: "archive" },
  });

  const messages = response.data.data || [];
  let movedCount = 0;

  for (const msg of messages) {
    try {
      await zohoClient.post(
        `/accounts/${zohoAccountId}/messages/${msg.uid}/move`,
        { folderid: "inbox" },
      );
      movedCount++;
    } catch (error) {
      logger.error(`Failed to unarchive message ${msg.uid}:`, error);
    }
  }

  return {
    success: movedCount > 0 || messages.length === 0,
    movedCount,
    totalCount: messages.length,
  };
}

/**
 * Send a reply email via Zoho
 */
export async function sendReplyViaZoho(
  zohoClient: AxiosInstance,
  zohoAccountId: string,
  to: string,
  subject: string,
  htmlBody: string,
  threadId: string,
): Promise<{ messageId: string }> {
  const response = await zohoClient.post(
    `/accounts/${zohoAccountId}/messages`,
    {
      to: [{ address: to }],
      subject: subject.startsWith("Re:") ? subject : `Re: ${subject}`,
      content: { html: htmlBody },
      inReplyTo: threadId,
    },
  );

  return { messageId: response?.data?.messageId || `zoho-${Date.now()}` };
}

/**
 * Send a new email via Zoho
 */
export async function sendEmailViaZoho(
  zohoClient: AxiosInstance,
  zohoAccountId: string,
  to: Array<{ email: string; name?: string }>,
  subject: string,
  htmlBody: string,
  cc?: Array<{ email: string; name?: string }>,
  bcc?: Array<{ email: string; name?: string }>,
): Promise<{ messageId: string; threadId: string }> {
  const message: any = {
    to: to.map((r) => ({ address: r.email, personal: r.name })),
    subject,
    content: { html: htmlBody },
  };

  if (cc?.length)
    message.cc = cc.map((r) => ({ address: r.email, personal: r.name }));
  if (bcc?.length)
    message.bcc = bcc.map((r) => ({ address: r.email, personal: r.name }));

  const response = await zohoClient.post(
    `/accounts/${zohoAccountId}/messages`,
    message,
  );
  const messageId = response.data.data?.uid || `msg-${Date.now()}`;

  return { messageId, threadId: response.data.data?.threadId || messageId };
}

/**
 * Search emails via Zoho
 */
export async function searchEmailsViaZoho(
  zohoClient: AxiosInstance,
  zohoAccountId: string,
  query: string,
  maxResults: number,
): Promise<any[]> {
  const response = await zohoClient.get(
    `/accounts/${zohoAccountId}/messages/search`,
    {
      params: { query, limit: maxResults },
    },
  );
  return response.data.data || [];
}

/**
 * Check if error is an auth error
 */
export function isAuthError(error: unknown): boolean {
  const apiError = isApiError(error) ? error : null;
  return (
    apiError?.code === 401 ||
    (apiError?.response && (apiError.response as any).status === 401)
  );
}

import { Logger } from "@nestjs/common";
import { AxiosInstance } from "axios";
import { QUERY_LIMITS } from "../../../constants/query-limits";
import { isApiError, isError } from "../../../types/common";

const logger = new Logger("ZohoSync");

/**
 * Verify thread statuses in Zoho API in batches with concurrency limits
 * Returns array of updates: { threadId, starCount, isArchived }[]
 */
export async function verifyThreadStatusesInZoho(
  userId: string,
  threadIds: string[],
  zohoClient: AxiosInstance,
  zohoAccountId: string,
): Promise<
  Array<{ threadId: string; starCount: number; isArchived: boolean }>
> {
  const updates: Array<{
    threadId: string;
    starCount: number;
    isArchived: boolean;
  }> = [];

  const BATCH_SIZE = 50;
  const CONCURRENCY_LIMIT = 10;

  for (let i = 0; i < threadIds.length; i += BATCH_SIZE) {
    const batch = threadIds.slice(i, i + BATCH_SIZE);
    logger.debug(
      `Processing batch ${Math.floor(i / BATCH_SIZE) + 1} of ${Math.ceil(threadIds.length / BATCH_SIZE)} (${batch.length} threads)`,
    );

    const batchPromises: Promise<void>[] = [];
    for (let j = 0; j < batch.length; j += CONCURRENCY_LIMIT) {
      const concurrentBatch = batch.slice(j, j + CONCURRENCY_LIMIT);
      const concurrentPromises = concurrentBatch.map(async (threadId) => {
        if (!threadId) return;

        try {
          const threadResponse = await zohoClient.get(
            `/accounts/${zohoAccountId}/messages`,
            { params: { threadId, limit: 1 } },
          );

          const threadMessages = threadResponse.data.data || [];
          if (threadMessages.length === 0) {
            updates.push({ threadId, starCount: 0, isArchived: true });
            return;
          }

          const latestMessage = threadMessages[0];
          const isImportant = latestMessage.importance === "high";
          const isInInbox = latestMessage.folderId === "inbox";

          updates.push({
            threadId,
            starCount: isImportant ? 3 : 0,
            isArchived: !isInInbox,
          });
        } catch (threadError: unknown) {
          if (isApiError(threadError) && threadError.code === 404) {
            logger.debug(
              `Thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}... not found in Zoho`,
            );
            updates.push({ threadId, starCount: 0, isArchived: true });
          } else {
            const errorMsg = isError(threadError)
              ? threadError.message
              : isApiError(threadError)
                ? threadError.message
                : "Unknown error";
            logger.warn(
              `Error checking thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...:`,
              errorMsg,
            );
          }
        }
      });

      batchPromises.push(...concurrentPromises);
      await Promise.all(concurrentPromises);
    }

    await Promise.all(batchPromises);
  }

  return updates;
}

/**
 * Get thread status updates for existing starred threads
 */
export async function getExistingThreadUpdates(
  userId: string,
  threadsToCheck: Array<{ threadId: string }>,
  threadMapKeys: Set<string>,
  zohoClient: AxiosInstance,
  zohoAccountId: string,
): Promise<
  Array<{ threadId: string; starCount: number; isArchived: boolean }>
> {
  const updates: Array<{
    threadId: string;
    starCount: number;
    isArchived: boolean;
  }> = [];

  for (const dbThread of threadsToCheck) {
    if (threadMapKeys.has(dbThread.threadId)) continue;

    try {
      const threadResponse = await zohoClient.get(
        `/accounts/${zohoAccountId}/messages`,
        { params: { threadId: dbThread.threadId, limit: 1 } },
      );

      const threadMessages = threadResponse.data.data || [];
      if (threadMessages.length === 0) {
        updates.push({
          threadId: dbThread.threadId,
          starCount: 0,
          isArchived: true,
        });
        continue;
      }

      const latestMessage = threadMessages[0];
      updates.push({
        threadId: dbThread.threadId,
        starCount: latestMessage.importance === "high" ? 3 : 0,
        isArchived: latestMessage.folderId !== "inbox",
      });
    } catch (threadError: unknown) {
      if (isApiError(threadError) && threadError.code === 404) {
        updates.push({
          threadId: dbThread.threadId,
          starCount: 0,
          isArchived: true,
        });
      }
    }
  }

  return updates;
}

