    // Set a test encryption key
    process.env.ENCRYPTION_KEY = "test-encryption-key-32-chars-long!!";
  });

  afterEach(() => {
    // Restore original env
    if (originalEnv) {
      process.env.ENCRYPTION_KEY = originalEnv;
