    it("should return null for undefined input", () => {
      expect(encryptedJsonTransformer.to(undefined)).toBeNull();
      expect(encryptedJsonTransformer.from(undefined)).toBeNull();
    });

    it("should return null if decrypted value is not valid JSON", () => {
      // Create invalid JSON by encrypting non-JSON string
      const plaintext = "not json";
      const encrypted = EncryptionHelper.encrypt(plaintext);
      const result = encryptedJsonTransformer.from(encrypted!);
      // Should return null when JSON parse fails
      expect(result).toBeNull();
    });

    it("should handle arrays", () => {
      const arr = [1, 2, 3, "test", { nested: "value" }];
      const encrypted = encryptedJsonTransformer.to(arr);
      const decrypted = encryptedJsonTransformer.from(encrypted);
      expect(decrypted).toEqual(arr);
    });

    it("should handle primitive values", () => {
      const number = 42;
      const encrypted = encryptedJsonTransformer.to(number);
      const decrypted = encryptedJsonTransformer.from(encrypted);
      expect(decrypted).toBe(number);
    });
  });
});

import { Test, TestingModule } from "@nestjs/testing";
import { ConfigService } from "@nestjs/config";
import { EncryptionService } from "./encryption.service";

describe("EncryptionService", () => {
  let service: EncryptionService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EncryptionService,
        {
          provide: ConfigService,
          useValue: {
            get: jest.fn((key: string) => {
              if (key === "ENCRYPTION_KEY") {
                return "test-encryption-key-32-chars!!";
              }
              return undefined;
            }),
          },
        },
      ],
    }).compile();

    service = module.get<EncryptionService>(EncryptionService);
  });

  describe("encrypt", () => {
    it("should encrypt a string value", () => {
      const plaintext = "Hello, World!";
      const encrypted = service.encrypt(plaintext);
      expect(encrypted).toBeTruthy();
      expect(encrypted).not.toBe(plaintext);
      expect(encrypted).toContain(":"); // Format: IV:authTag:encrypted
    });

    it("should return empty string for empty input", () => {
      const result = service.encrypt("");
      expect(result).toBe("");
    });

    it("should produce different encrypted values for same input (due to random IV)", () => {
      const plaintext = "Hello, World!";
      const encrypted1 = service.encrypt(plaintext);
      const encrypted2 = service.encrypt(plaintext);
      // Should be different due to random IV
      expect(encrypted1).not.toBe(encrypted2);
    });

    it("should encrypt special characters correctly", () => {
      const plaintext = "Special chars: !@#$%^&*()_+-=[]{}|;:,.<>?";
      const encrypted = service.encrypt(plaintext);
      expect(encrypted).toBeTruthy();
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(plaintext);
    });

    it("should encrypt unicode characters correctly", () => {
      const plaintext = "Hello 世界 🌍";
      const encrypted = service.encrypt(plaintext);
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(plaintext);
    });

    it("should encrypt long strings", () => {
      const plaintext = "A".repeat(10000);
      const encrypted = service.encrypt(plaintext);
      expect(encrypted).toBeTruthy();
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(plaintext);
    });

    it("should encrypt email addresses", () => {
      const email = "test@example.com";
      const encrypted = service.encrypt(email);
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(email);
    });

    it("should produce encrypted output in correct format (IV:authTag:encrypted)", () => {
      const plaintext = "test";
      const encrypted = service.encrypt(plaintext);
      const parts = encrypted.split(":");
      expect(parts.length).toBe(3);
      expect(parts[0].length).toBe(32); // IV in hex (16 bytes = 32 hex chars)
      expect(parts[1].length).toBe(32); // Auth tag in hex (16 bytes = 32 hex chars)
      expect(parts[2].length).toBeGreaterThan(0); // Encrypted data
    });
  });

  describe("decrypt", () => {
    it("should decrypt encrypted string back to original", () => {
      const plaintext = "Hello, World!";
      const encrypted = service.encrypt(plaintext);
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(plaintext);
    });

    it("should return empty string for empty input", () => {
      const result = service.decrypt("");
      expect(result).toBe("");
    });

    it("should return plaintext for already decrypted text (backwards compatibility)", () => {
      const plaintext = "Already decrypted text";
      const result = service.decrypt(plaintext);
      expect(result).toBe(plaintext);
    });

    it("should return plaintext for text without colons (backwards compatibility)", () => {
      const plaintext = "Plain text without colons";
      const result = service.decrypt(plaintext);
      expect(result).toBe(plaintext);
    });

    it("should return plaintext for invalid format (not 3 parts)", () => {
      const invalidFormat = "part1:part2"; // Only 2 parts, need 3
      const result = service.decrypt(invalidFormat);
      expect(result).toBe(invalidFormat);
    });

    it("should handle decryption of different encrypted versions of same text", () => {
      const plaintext = "Same text, different IVs";
      const encrypted1 = service.encrypt(plaintext);
      const encrypted2 = service.encrypt(plaintext);
      const decrypted1 = service.decrypt(encrypted1);
      const decrypted2 = service.decrypt(encrypted2);
      expect(decrypted1).toBe(plaintext);
      expect(decrypted2).toBe(plaintext);
    });

    it("should return original text if decryption fails (for backwards compatibility)", () => {
      // Create invalid encrypted format
      const invalidEncrypted = "invalid:format:data";
      // This should fail to decrypt and return original
      const result = service.decrypt(invalidEncrypted);
      expect(result).toBe(invalidEncrypted);
    });

    it("should decrypt special characters correctly", () => {
      const plaintext = "Special: !@#$%";
      const encrypted = service.encrypt(plaintext);
      const decrypted = service.decrypt(encrypted);
      expect(decrypted).toBe(plaintext);
    });
  });

  describe("hashEmail", () => {
    it("should hash an email address", () => {
      const email = "test@example.com";
      const hash = service.hashEmail(email);
      expect(hash).toBeTruthy();
      expect(hash.length).toBe(64); // SHA-256 produces 64 hex characters
    });

    it("should return empty string for empty email", () => {
      const result = service.hashEmail("");
      expect(result).toBe("");
    });

    it("should return empty string for null/undefined email", () => {
      expect(service.hashEmail(null as any)).toBe("");
      expect(service.hashEmail(undefined as any)).toBe("");
    });

    it("should normalize email to lowercase before hashing", () => {
      const email1 = "Test@Example.com";
      const email2 = "test@example.com";
      const hash1 = service.hashEmail(email1);
      const hash2 = service.hashEmail(email2);
      expect(hash1).toBe(hash2);
    });

    it("should trim whitespace before hashing", () => {
      const email1 = "test@example.com";
      const email2 = "  test@example.com  ";
      const hash1 = service.hashEmail(email1);
      const hash2 = service.hashEmail(email2);
      expect(hash1).toBe(hash2);
    });

    it("should produce consistent hashes for same email", () => {
      const email = "test@example.com";
      const hash1 = service.hashEmail(email);
      const hash2 = service.hashEmail(email);
      expect(hash1).toBe(hash2);
    });

    it("should produce different hashes for different emails", () => {
      const hash1 = service.hashEmail("test1@example.com");
      const hash2 = service.hashEmail("test2@example.com");
      expect(hash1).not.toBe(hash2);
    });

    it("should handle emails with special characters", () => {
      const email = "test+tag@example.com";
      const hash = service.hashEmail(email);
      expect(hash).toBeTruthy();
      expect(hash.length).toBe(64);
    });
  });

  describe("createTransformer", () => {
    it("should create a transformer with to and from methods", () => {
      const transformer = service.createTransformer();
      expect(transformer).toHaveProperty("to");
      expect(transformer).toHaveProperty("from");
      expect(typeof transformer.to).toBe("function");
      expect(typeof transformer.from).toBe("function");
    });

    it("should encrypt value in to method", () => {
      const transformer = service.createTransformer();
      const plaintext = "test value";
      const encrypted = transformer.to(plaintext);
      expect(encrypted).toBeTruthy();
      expect(encrypted).not.toBe(plaintext);
      expect(encrypted).toContain(":");
    });

    it("should decrypt value in from method", () => {
      const transformer = service.createTransformer();
      const plaintext = "test value";
      const encrypted = transformer.to(plaintext);
      const decrypted = transformer.from(encrypted);
      expect(decrypted).toBe(plaintext);
    });

    it("should return null for null value in to method", () => {
      const transformer = service.createTransformer();
      const result = transformer.to(null);
      expect(result).toBeNull();
    });

    it("should return null for undefined value in to method", () => {
      const transformer = service.createTransformer();
      const result = transformer.to(undefined);
      expect(result).toBeNull();
    });

    it("should return null for null value in from method", () => {
      const transformer = service.createTransformer();
      const result = transformer.from(null);
      expect(result).toBeNull();
    });

    it("should return null for undefined value in from method", () => {
      const transformer = service.createTransformer();
      const result = transformer.from(undefined);
      expect(result).toBeNull();
    });

    it("should handle round-trip transformation", () => {
      const transformer = service.createTransformer();
      const plaintext = "Original value";
      const encrypted = transformer.to(plaintext);
      const decrypted = transformer.from(encrypted);
      expect(decrypted).toBe(plaintext);
    });
  });

  describe("Integration Tests", () => {
    it("should encrypt and decrypt email addresses correctly", () => {
      const emails = [
        "user@example.com",
        "test.user+tag@subdomain.example.com",
        "user@example.co.uk",
      ];
      emails.forEach((email) => {
        const encrypted = service.encrypt(email);
        const decrypted = service.decrypt(encrypted);
        expect(decrypted).toBe(email);
      });
    });

    it("should handle encrypt/decrypt for various data types as strings", () => {
      const testCases = [
        "123",
        "true",
        "false",
        "null",
        '{"json": "data"}',
        "Multi\nline\nstring",
        'String with "quotes"',
      ];
      testCases.forEach((testCase) => {
        const encrypted = service.encrypt(testCase);
        const decrypted = service.decrypt(encrypted);
        expect(decrypted).toBe(testCase);
      });
    });
  });
});

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Request,
  UseGuards,
  BadRequestException,
} from "@nestjs/common";
import { JwtAuthGuard } from "../auth/jwt-auth.guard";
import { FollowUpsService } from "./follow-ups.service";
import { Inject } from "@nestjs/common";
import PgBoss = require("pg-boss");
import { QUERY_LIMITS } from "../constants/query-limits";
import { Email } from "../database/entities/email.entity";

/**
 * Email with follow-up tracking properties added by the inbox query
 */
interface EmailWithFollowUpMetadata extends Email {
  lastTheirReplyAt?: Date;
  lastMyReplyAt?: Date;
  otherPersonName?: string;
  otherPersonEmail?: string;
}

@Controller("follow-ups")
@UseGuards(JwtAuthGuard)
export class FollowUpsController {
  constructor(
    private followUpsService: FollowUpsService,
    @Inject("PG_BOSS") private boss: PgBoss,
  ) {}

  /**
   * Get all follow-ups that need action (due for follow-up)
   */
  @Get("due")
  async getDueFollowUps(@Request() req) {
    return this.followUpsService.getDueFollowUps(req.user.userId);
  }

  /**
   * Get all follow-ups that are awaiting reply (not yet due)
   */
  @Get("awaiting")
  async getAwaitingFollowUps(@Request() req) {
    return this.followUpsService.getAwaitingReplyFollowUps(req.user.userId);
  }

  /**
   * Generate follow-up drafts for all due follow-ups
   */
  @Post("generate-drafts")
  async generateDrafts(@Request() req) {
    return this.followUpsService.generateFollowUpDrafts(req.user.userId);
  }

  /**
   * Create a new follow-up reminder
   */
  @Post()
  async createFollowUp(
    @Request() req,
    @Body()
    body: { threadId: string; followUpDays: number; sentEmailId?: string },
  ) {
    return this.followUpsService.createFollowUp(
      req.user.userId,
      body.threadId,
      body.followUpDays,
      body.sentEmailId,
    );
  }

  /**
   * Update a follow-up draft
   */
  @Put(":id/draft")
  async updateDraft(
    @Request() req,
    @Param("id") id: string,
    @Body() body: { draft: string },
  ) {
    return this.followUpsService.updateDraft(id, req.user.userId, body.draft);
  }

  /**
   * Review and clean up a follow-up draft before sending
   */
  @Post(":id/review-draft")
  async reviewDraft(
    @Request() req,
    @Param("id") id: string,
    @Body() body: { draft: string; recipientName?: string },
  ) {
    const reviewedDraft = await this.followUpsService.reviewAndCleanupDraft(
      id,
      req.user.userId,
      body.draft,
      body.recipientName,
    );
    return reviewedDraft;
  }

  /**
   * Mark a follow-up as completed (sent)
   */
  @Post(":id/complete")
  async completeFollowUp(@Request() req, @Param("id") id: string) {
    await this.followUpsService.completeFollowUp(id, req.user.userId);
    return { success: true };
  }

  /**
   * Cancel a follow-up
   */
  @Delete(":id")
  async cancelFollowUp(@Request() req, @Param("id") id: string) {
    await this.followUpsService.cancelFollowUp(id, req.user.userId);
    return { success: true };
  }

  /**
   * Generate drafts for threads in view
   */
  @Post("generate-drafts-for-threads")
  async generateDraftsForThreads(
    @Request() req,
    @Body() body: { threadIds: string[] },
  ) {
    if (!body.threadIds || !Array.isArray(body.threadIds)) {
      throw new BadRequestException("threadIds must be an array");
    }

    await this.followUpsService.generateDraftsForThreads(
      req.user.userId,
      body.threadIds,
    );
    return { success: true, message: "Draft generation queued" };
  }

  /**
   * Bulk send follow-ups (max 20)
   */
  @Post("bulk-send")
  async bulkSend(@Request() req, @Body() body: { followUpIds: string[] }) {
    if (!body.followUpIds || !Array.isArray(body.followUpIds)) {
      throw new BadRequestException("followUpIds must be an array");
    }

    if (body.followUpIds.length > QUERY_LIMITS.MAX_RESULTS_DEFAULT) {
      throw new BadRequestException(
        `Maximum ${QUERY_LIMITS.MAX_RESULTS_DEFAULT} follow-ups allowed per bulk send`,
      );
    }

    if (body.followUpIds.length === 0) {
      throw new BadRequestException("At least one follow-up ID required");
    }

    // Queue background job
    const job = await this.boss.send("bulk-send-follow-ups", {
      userId: req.user.userId,
      followUpIds: body.followUpIds,
    });

    return {
      success: true,
      jobId: job,
      message: "Bulk send queued",
    };
  }

  /**
   * Get threads in follow-up mode with draft status
   * NOTE: This route must come BEFORE @Get(":id") to avoid route conflicts
   */
  @Get("threads")
  async getThreadsWithDrafts(@Request() req) {
    const threads = await this.followUpsService.getThreadsForFollowUp(
      req.user.userId,
    );

    // Get follow-ups for these threads
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const threadIds = threads.map((t) => t.threadId);
    const followUps = await this.followUpsService.getDueFollowUps(
      req.user.userId,
    );

    // Map follow-ups by threadId
    const followUpMap = new Map(followUps.map((fu) => [fu.threadId, fu]));

    // Combine threads with follow-up data
    // Cast to interface with optional follow-up metadata properties
    return threads.map((thread) => {
      const threadWithMeta = thread as EmailWithFollowUpMetadata;
      const followUp = followUpMap.get(thread.threadId);
      return {
        ...thread,
        // Include follow-up metadata from email object (added by inbox query)
        lastTheirReplyAt: threadWithMeta.lastTheirReplyAt,
        lastMyReplyAt: threadWithMeta.lastMyReplyAt,
        otherPersonName: threadWithMeta.otherPersonName,
        otherPersonEmail: threadWithMeta.otherPersonEmail,
        followUp: followUp
          ? {
              id: followUp.id,
              draftFollowUp: followUp.draftFollowUp,
              generationStatus: followUp.generationStatus,
              generationError: followUp.generationError,
              sendStatus: followUp.sendStatus,
              sendError: followUp.sendError,
            }
          : null,
      };
    });
  }

  /**
   * Get a single follow-up
   * NOTE: This route must come AFTER specific routes like @Get("threads")
   */
  @Get(":id")
  async getFollowUp(@Request() req, @Param("id") id: string) {
    return this.followUpsService.getFollowUp(id, req.user.userId);
  } /**
   * Get generation/send status for a follow-up
   */
  @Get(":id/status")
  async getFollowUpStatus(@Request() req, @Param("id") id: string) {
    const followUp = await this.followUpsService.getFollowUp(
      id,
      req.user.userId,
    );
    if (!followUp) {
      throw new BadRequestException("Follow-up not found");
    }
    return {
      generationStatus: followUp.generationStatus,
      generationError: followUp.generationError,
      sendStatus: followUp.sendStatus,
      sendError: followUp.sendError,
    };
  }
}

