import { Injectable, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, LessThanOrEqual } from "typeorm";
import {
  FollowUp,
  FollowUpStatus,
} from "../database/entities/follow-up.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { LLMService } from "../llm/llm.service";
import { UsersService } from "../users/users.service";
import { ContextService } from "../context/context.service";
import { ContextKey } from "../database/entities/user-context.entity";
import { EmailsService } from "../emails/emails.service";
import { calculateBusinessDays } from "../utils/business-days.util";
import PgBoss = require("pg-boss");
import { EncryptionHelper } from "../encryption/encryption.helper";

@Injectable()
export class FollowUpsService {
  private readonly logger = new Logger(FollowUpsService.name);

  // eslint-disable-next-line max-params
  constructor(
    @InjectRepository(FollowUp)
    private followUpRepository: Repository<FollowUp>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    private llmService: LLMService,
    private usersService: UsersService,
    private contextService: ContextService,
    private emailsService: EmailsService,
    @Inject("PG_BOSS") private boss: PgBoss,
  ) {}

  /**
   * Create a follow-up reminder after sending an email
   */
  async createFollowUp(
    userId: string,
    threadId: string,
    followUpDays: number,
    sentEmailId?: string,
  ): Promise<FollowUp> {
    // Find the email thread
    const emailThread = await this.emailThreadRepository.findOne({
      where: { userId, threadId },
    });

    // Get the latest emails in the thread to capture context
    const emails = await this.emailRepository.find({
      where: { userId, threadId },
      order: { receivedAt: "DESC" },
      take: 10,
    });

    // Find the last email from "them" (not from user) and from user
    const userEmails: Email[] = [];
    const myEmails: Email[] = [];

    for (const email of emails) {
      if (await this.isFromUser(email, userId)) {
        myEmails.push(email);
      } else {
        userEmails.push(email);
      }
    }

    const lastTheirEmail = userEmails[0];
    const lastMyEmail = myEmails[0];

    const followUpDueAt = new Date();
    followUpDueAt.setDate(followUpDueAt.getDate() + followUpDays);

    const followUp = this.followUpRepository.create({
      userId,
      threadId,
      emailThreadId: emailThread?.id,
      sentEmailId,
      status: FollowUpStatus.AWAITING_REPLY,
      followUpDueAt,
      followUpDays,
      lastTheirReply: lastTheirEmail?.body?.substring(0, 2000),
      lastTheirReplyFrom: lastTheirEmail?.fromName || lastTheirEmail?.from,
      lastTheirReplyAt: lastTheirEmail?.receivedAt,
      lastMyReply: lastMyEmail?.body?.substring(0, 2000),
      lastMyReplyAt: lastMyEmail?.receivedAt,
      subject: emails[0]?.subject,
    });

    return this.followUpRepository.save(followUp);
  }

  /**
   * Get all follow-ups for a user that are due (awaiting reply tab)
   */
  async getDueFollowUps(userId: string): Promise<FollowUp[]> {
    const now = new Date();

    return this.followUpRepository.find({
      where: [
        {
          userId,
          status: FollowUpStatus.FOLLOW_UP_DUE,
        },
        {
          userId,
          status: FollowUpStatus.AWAITING_REPLY,
          followUpDueAt: LessThanOrEqual(now),
        },
      ],
      order: { followUpDueAt: "ASC" },
    });
  }

  /**
   * Get all active follow-ups (awaiting reply, not yet due)
   */
  async getAwaitingReplyFollowUps(userId: string): Promise<FollowUp[]> {
    return this.followUpRepository.find({
      where: {
        userId,
        status: FollowUpStatus.AWAITING_REPLY,
      },
      order: { followUpDueAt: "ASC" },
    });
  }

  /**
   * Update follow-up status when a reply is received
   */
  async markAsReplied(userId: string, threadId: string): Promise<void> {
    await this.followUpRepository.update(
      { userId, threadId, status: FollowUpStatus.AWAITING_REPLY },
      { status: FollowUpStatus.COMPLETED },
    );
    await this.followUpRepository.update(
      { userId, threadId, status: FollowUpStatus.FOLLOW_UP_DUE },
      { status: FollowUpStatus.COMPLETED },
    );
  }

  /**
   * Generate follow-up draft messages for all due follow-ups
   */
  async generateFollowUpDrafts(userId: string): Promise<FollowUp[]> {
    const dueFollowUps = await this.getDueFollowUps(userId);

    for (const followUp of dueFollowUps) {
      if (!followUp.draftFollowUp) {
        try {
          // Build thread messages array from follow-up data
          const threadMessages: Array<{
            from: string;
            fromName?: string;
            body: string;
            receivedAt: Date;
            isFromUser: boolean;
          }> = [];

          // Add their last reply if available
          if (followUp.lastTheirReply) {
            threadMessages.push({
              from: followUp.lastTheirReplyFrom || "them",
              body: followUp.lastTheirReply,
              receivedAt: followUp.lastTheirReplyAt || new Date(),
              isFromUser: false,
            });
          }

          // Add user's last reply if available
          if (followUp.lastMyReply) {
            threadMessages.push({
              from: "me",
              body: followUp.lastMyReply,
              receivedAt: followUp.lastMyReplyAt || new Date(),
              isFromUser: true,
            });
          }

          const draft = await this.llmService.generateFollowUpDraft(
            followUp.subject || "Follow up",
            threadMessages,
            followUp.lastTheirReplyFrom || "them",
            followUp.followUpDays,
          );
          followUp.draftFollowUp = draft;
          await this.followUpRepository.save(followUp);
        } catch (error) {
          this.logger.error(
            `Error generating follow-up draft for ${followUp.id}:`,
            error,
          );
        }
      }

      // Update status to FOLLOW_UP_DUE if past due date
      if (
        followUp.status === FollowUpStatus.AWAITING_REPLY &&
        followUp.followUpDueAt <= new Date()
      ) {
        followUp.status = FollowUpStatus.FOLLOW_UP_DUE;
        await this.followUpRepository.save(followUp);
      }
    }

    return dueFollowUps;
  }

  /**
   * Update a follow-up draft
   */
  async updateDraft(
    followUpId: string,
    userId: string,
    draft: string,
  ): Promise<FollowUp> {
    const followUp = await this.followUpRepository.findOne({
      where: { id: followUpId, userId },
    });

    if (!followUp) {
      throw new Error("Follow-up not found");
    }

    followUp.draftFollowUp = draft;
    return this.followUpRepository.save(followUp);
  }

  /**
   * Mark a follow-up as completed (sent or cancelled)
   */
  async completeFollowUp(
    followUpId: string,
    userId: string,
    cancelled = false,
  ): Promise<void> {
    await this.followUpRepository.update(
      { id: followUpId, userId },
      {
        status: cancelled ? FollowUpStatus.CANCELLED : FollowUpStatus.COMPLETED,
      },
    );
  }

  /**
   * Cancel a follow-up
   */
  async cancelFollowUp(followUpId: string, userId: string): Promise<void> {
    await this.completeFollowUp(followUpId, userId, true);
  }

  /**
   * Check if an email is from the user (sent by them)
   */
  private async isFromUser(email: Email, userId: string): Promise<boolean> {
    // Check if email has SENT label
    if (email.labels?.includes("SENT")) {
      return true;
    }

    // Fallback: compare with user's email address
    try {
      const user = await this.usersService.findOne(userId);
      if (user?.email) {
        const userEmail = EncryptionHelper.decrypt(user.email);
        const emailFrom = EncryptionHelper.decrypt(email.from);
        return emailFrom.toLowerCase() === userEmail.toLowerCase();
      }
    } catch (error) {
      this.logger.warn(`Error checking if email is from user: ${error}`);
    }

    return false;
  }

  /**
   * Review and clean up a follow-up draft before sending
   * Checks user's tone, adds greeting if missing, and ensures it matches their writing style
   */
  async reviewAndCleanupDraft(
    followUpId: string,
    userId: string,
    draft: string,
    recipientName?: string,
  ): Promise<string> {
    const followUp = await this.getFollowUp(followUpId, userId);
    if (!followUp) {
      throw new Error("Follow-up not found");
    }

    // Get user's communication style
    const contexts = await this.contextService.getUserContext(userId);
    const tone =
      contexts.find((c) => c.contextKey === ContextKey.WRITING_STYLE_TONE)
        ?.contextValue || "professional";
    const commonPhrases = contexts
      .filter((c) => c.contextKey === ContextKey.COMMON_PHRASE)
      .map((c) => c.contextValue);

    // Check if user has preference to skip greeting
    const skipGreeting =
      tone.toLowerCase().includes("no greeting") ||
      tone.toLowerCase().includes("skip greeting");

    // Check if draft already has a greeting
    const hasGreeting =
      /^(hi|hey|hello|dear|greetings|good morning|good afternoon|good evening)[\s,]/i.test(
        draft.trim(),
      );

    // Build review prompt
    let systemPrompt = `You are a helpful assistant that reviews and cleans up email drafts.
Your job is to ensure the draft:
1. Matches the user's preferred tone and writing style
2. Includes a greeting (unless user explicitly prefers no greeting)
3. Is clear, concise, and professional
4. Uses the user's common phrases when appropriate`;

    if (tone) {
      systemPrompt += `\n\nUser's preferred tone: ${tone}`;
    }

    if (commonPhrases.length > 0) {
      systemPrompt += `\n\nUser commonly uses these phrases: ${commonPhrases.join(", ")}`;
    }

    const prompt = `Review and clean up this follow-up email draft:

Draft:
${draft}

${recipientName ? `Recipient: ${recipientName}` : ""}

${(() => {
  if (!hasGreeting && !skipGreeting && recipientName) {
    return `IMPORTANT: The draft is missing a greeting. Add an appropriate greeting at the start (e.g., "Hi ${recipientName}," or "Hey ${recipientName},") based on the user's tone.`;
  } else if (skipGreeting) {
    return "Note: User prefers no greeting - don't add one.";
  } else {
    return "";
  }
})()}

Clean up the draft to match the user's tone and writing style. Keep it concise (2-3 sentences). Return only the cleaned up draft text, no explanations.`;

    try {
      const reviewedDraft = await this.llmService.generateText(
        {
          prompt,
          systemPrompt,
          temperature: 0.3,
          maxTokens: 300,
          userId,
        },
        undefined,
        userId,
      );

      return reviewedDraft.trim();
    } catch (error) {
      this.logger.error("Error reviewing draft:", error);
      // If review fails, return original draft
      return draft;
    }
  }

  /**
   * Get a single follow-up by ID
   */
  async getFollowUp(
    followUpId: string,
    userId: string,
  ): Promise<FollowUp | null> {
    return this.followUpRepository.findOne({
      where: { id: followUpId, userId },
    });
  }

  /**
   * Get threads in follow-up mode (user sent last, no reply received)
   */
  async getThreadsForFollowUp(userId: string): Promise<Email[]> {
    return this.emailsService.getInbox(userId, false, "follow-up");
  }

  /**
   * Calculate business days waiting since last user message in thread
   */
  async calculateWaitingDuration(
    userId: string,
    threadId: string,
  ): Promise<number> {
    const user = await this.usersService.findOne(userId);
    if (!user?.googleCalendarAccessToken) {
      throw new Error("User not connected to Gmail");
    }

    // Get thread emails
    const threadEmails = await this.emailRepository.find({
      where: { userId, threadId },
      order: { receivedAt: "DESC" },
    });

    // Find last email from user
    let lastUserMessageDate: Date | null = null;
    for (const email of threadEmails) {
      if (await this.isFromUser(email, userId)) {
        lastUserMessageDate = email.receivedAt;
        break;
      }
    }

    if (!lastUserMessageDate) {
      return 0;
    }

    // Calculate business days from last user message to now
    const now = new Date();
    return calculateBusinessDays(lastUserMessageDate, now);
  }

  /**
   * Queue background jobs to generate drafts for multiple threads
   */
  async generateDraftsForThreads(
    userId: string,
    threadIds: string[],
  ): Promise<void> {
    for (const threadId of threadIds) {
      // Check if follow-up already exists
      let followUp = await this.followUpRepository.findOne({
        where: { userId, threadId },
      });

      // If no follow-up exists, create one
      if (!followUp) {
        // Get thread info
        const threadEmails = await this.emailRepository.find({
          where: { userId, threadId },
          order: { receivedAt: "DESC" },
          take: 1,
        });

        if (threadEmails.length === 0) {
          this.logger.warn(`No emails found for thread ${threadId}`);
          continue;
        }

        const emailThread = await this.emailThreadRepository.findOne({
          where: { userId, threadId },
        });

        followUp = this.followUpRepository.create({
          userId,
          threadId,
          emailThreadId: emailThread?.id,
          status: FollowUpStatus.FOLLOW_UP_DUE,
          followUpDueAt: new Date(),
          followUpDays: 0,
          subject: threadEmails[0].subject,
          generationStatus: "pending",
        });
        followUp = await this.followUpRepository.save(followUp);
      }

      // Skip if already has draft or is currently generating
      if (
        followUp.draftFollowUp ||
        followUp.generationStatus === "generating"
      ) {
        continue;
      } // Update status to pending
      followUp.generationStatus = "pending";
      await this.followUpRepository.save(followUp); // Queue background job
      await this.boss.send(
        "generate-follow-up-draft",
        {
          userId,
          followUpId: followUp.id,
          threadId,
        },
        {
          singletonKey: `generate-draft-${followUp.id}`,
          singletonMinutes: 5,
        },
      );
    }
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { Octokit } from "@octokit/rest";
import { ParsedGitHubLink } from "./github.service";
import { isApiError, getErrorMessage } from "../types/common";

/**
 * GraphQL response for project items query
 * This is a complex nested structure from GitHub's GraphQL API
 */
interface ProjectItemsGraphQLResponse {
  repository?: {
    issue?: {
      projectItems?: {
        nodes?: Array<{
          project?: { title?: string };
          fieldValues?: {
            nodes?: Array<{
              field?: { name?: string };
              name?: string;
            } | null>;
          };
        } | null>;
      };
    };
  };
}

/**
 * GraphQL error with optional response data
 * GitHub's GraphQL can return partial data even with errors
 */
interface GraphQLErrorWithData {
  responseData?: ProjectItemsGraphQLResponse;
  data?: ProjectItemsGraphQLResponse;
  response?: { data?: ProjectItemsGraphQLResponse };
}

/**
 * Search result item from Octokit REST API
 */
interface SearchResultItem {
  number: number;
  title: string;
  state: string;
  html_url: string;
  repository_url: string;
  body?: string | null;
  labels: Array<{ name?: string; color?: string }>;
  created_at: string;
  updated_at: string;
}

export interface GitHubIssueStatus {
  state: "open" | "closed";
  title: string;
  labels: Array<{ name: string; color: string }>;
  assignees: Array<{ login: string; avatar_url: string }>;
  projects?: Array<{
    name: string;
    status?: string; // Status field value (e.g., "In Progress", "Backlog")
  }>;
}

export interface GitHubPRStatus {
  state: "open" | "closed" | "merged";
  title: string;
  labels: Array<{ name: string; color: string }>;
  assignees: Array<{ login: string; avatar_url: string }>;
  reviewStatus: "approved" | "changes_requested" | "pending" | null;
  commentsCount: number;
  mergeable: boolean | null;
  merged: boolean;
  projects?: Array<{
    name: string;
    status?: string; // Status field value (e.g., "In Progress", "Backlog")
  }>;
}

@Injectable()
export class GitHubApiService {
  private readonly logger = new Logger(GitHubApiService.name);

  /**
   * Create an authenticated Octokit client
   */
  private createClient(token: string): Octokit {
    return new Octokit({
      auth: token,
    });
  }

  /**
   * Check if we can access a repository (helps distinguish 404 between "doesn't exist" and "no access")
   */
  private async checkRepositoryAccess(
    octokit: Octokit,
    owner: string,
    repo: string,
  ): Promise<{ accessible: boolean; isPrivate?: boolean }> {
    try {
      const response = await octokit.rest.repos.get({
        owner,
        repo,
      });
      return {
        accessible: true,
        isPrivate: response.data.private,
      };
    } catch (error: unknown) {
      if (isApiError(error) && error.code === 404) {
        // Could be "doesn't exist" or "no access" - we can't distinguish
        return { accessible: false };
      }
      // Other errors (401, 403) indicate permission issues
      return { accessible: false };
    }
  }

  /**
   * Fetch projects that an issue/PR is part of using GraphQL API
   */
  private async fetchIssueProjects(
    token: string,
    owner: string,
    repo: string,
    issueNumber: number,
  ): Promise<Array<{ name: string; status?: string }>> {
    try {
      const octokit = this.createClient(token);

      const query = `
        query($owner: String!, $repo: String!, $issueNumber: Int!) {
          repository(owner: $owner, name: $repo) {
            issue(number: $issueNumber) {
              projectItems(first: 20) {
                nodes {
                  project {
                    ... on ProjectV2 {
                      title
                    }
                  }
                  fieldValues(first: 10) {
                    nodes {
                      ... on ProjectV2ItemFieldSingleSelectValue {
                        field {
                          ... on ProjectV2FieldCommon {
                            name
                          }
                        }
                        name
                      }
                    }
                  }
                }
              }
            }
          }
        }
      `;

      let response: ProjectItemsGraphQLResponse | undefined;
      try {
        response = await octokit.graphql<ProjectItemsGraphQLResponse>(query, {
          owner,
          repo,
          issueNumber,
        });
      } catch (error: unknown) {
        // GraphQL can return errors but still have data in the response
        // Check multiple possible locations for the data
        const graphqlError = error as GraphQLErrorWithData;
        if (graphqlError?.responseData) {
          response = graphqlError.responseData;
        } else if (graphqlError?.data) {
          response = graphqlError.data;
        } else if (graphqlError?.response?.data) {
          response = graphqlError.response.data;
        } else {
          // No data in error - return empty (don't throw to avoid breaking the flow)
          return [];
        }
      }

      if (!response?.repository?.issue?.projectItems?.nodes) {
        return [];
      }

      const projects: Array<{ name: string; status?: string }> = [];

      // Check if we have null items (indicates permission issue with read:project scope)
      const nullItemCount = response.repository.issue.projectItems.nodes.filter(
        (item) => item === null,
      ).length;
      if (
        nullItemCount > 0 &&
        response.repository.issue.projectItems.nodes.length === nullItemCount
      ) {
        // All items are null - token may be missing 'read:project' permission
        this.logger.warn(
          `GitHub token may need 'Projects' permission - project items returned as null for ${owner}/${repo}#${issueNumber}`,
        );
      }

      for (const item of response.repository.issue.projectItems.nodes) {
        // Skip null items (GitHub API returns null when token lacks project permissions)
        if (!item) continue;

        const projectName = item?.project?.title;
        let status: string | undefined;

        // Find the status field value
        if (item.fieldValues?.nodes) {
          for (const fieldValue of item.fieldValues.nodes) {
            if (!fieldValue) continue;
            const fieldName = fieldValue.field?.name?.toLowerCase();
            if (fieldName === "status") {
              status = fieldValue.name;
              break;
            }
          }
        }

        // Only add project if we have a name or status
        if (projectName || status) {
          projects.push({
            name: projectName || "Unknown Project",
            ...(status && { status }),
          });
        }
      }

      return projects;
    } catch (error: unknown) {
      // Log error but don't throw - we want to continue even if project fetching fails
      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;

      this.logger.warn(
        `Failed to fetch projects for ${owner}/${repo}#${issueNumber}`,
        {
          message: errorMessage,
          status: errorStatus,
          responseData: apiError?.response?.data,
        },
      );
      return [];
    }
  }

  /**
   * Fetch issue details from GitHub API
   */
  async fetchIssueStatus(
    token: string,
    owner: string,
    repo: string,
    issueNumber: number,
  ): Promise<GitHubIssueStatus | null> {
    try {
      const octokit = this.createClient(token);

      const response = await octokit.rest.issues.get({
        owner,
        repo,
        issue_number: issueNumber,
      });

      const issue = response.data;

      // Fetch project information using GraphQL
      const projects = await this.fetchIssueProjects(
        token,
        owner,
        repo,
        issueNumber,
      );

      return {
        state: issue.state as "open" | "closed",
        title: issue.title,
        labels: issue.labels.map(
          (label: { name?: string; color?: string } | string) => ({
            name: typeof label === "string" ? label : label.name,
            color:
              typeof label === "string" ? "000000" : label.color || "000000",
          }),
        ),
        assignees: issue.assignees.map((assignee) => ({
          login: assignee.login,
          avatar_url: assignee.avatar_url,
        })),
        projects: projects.length > 0 ? projects : undefined,
      };
    } catch (error: unknown) {
      const apiUrl = `GET /repos/${owner}/${repo}/issues/${issueNumber}`;
      const fullUrl = `https://api.github.com/repos/${owner}/${repo}/issues/${issueNumber}`;

      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;
      const errorResponse = apiError?.response;

      this.logger.error(
        `Failed to fetch issue ${owner}/${repo}#${issueNumber}`,
        {
          message: errorMessage,
          status: errorStatus,
          url: fullUrl,
          apiEndpoint: apiUrl,
          owner,
          repo,
          issueNumber,
          // Log response details if available
          responseData: errorResponse?.data,
          // Check if it's a permissions issue
          isPermissionError: errorStatus === 401 || errorStatus === 403,
          isNotFound: errorStatus === 404,
        },
      );

      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }

      // Log additional context for 404 errors
      if (errorStatus === 404) {
        // Try to check if we can access the repository at all
        try {
          const repoAccess = await this.checkRepositoryAccess(
            this.createClient(token),
            owner,
            repo,
          );

          if (!repoAccess.accessible) {
            this.logger.warn(
              `Issue ${owner}/${repo}#${issueNumber} returned 404. Repository ${owner}/${repo} is not accessible with the current token. This likely means the repository is private and the token lacks access, or the repository doesn't exist.`,
            );
          } else {
            this.logger.warn(
              `Issue ${owner}/${repo}#${issueNumber} not found, but repository ${owner}/${repo} is accessible. The issue may not exist or may have been deleted.`,
            );
          }
        } catch (repoCheckError: unknown) {
          this.logger.warn(
            `Issue ${owner}/${repo}#${issueNumber} not found. Could not verify repository access: ${getErrorMessage(repoCheckError)}. Possible reasons: Issue doesn't exist, repository is private and token lacks access, or repository/issue was deleted.`,
          );
        }
      }

      return null;
    }
  }

  /**
   * Fetch pull request details from GitHub API
   */
  // eslint-disable-next-line max-lines-per-function, complexity, max-statements
  async fetchPRStatus(
    token: string,
    owner: string,
    repo: string,
    prNumber: number,
  ): Promise<GitHubPRStatus | null> {
    try {
      const octokit = this.createClient(token);

      // Fetch PR details
      const [prResponse, reviewsResponse, commentsResponse] = await Promise.all(
        [
          octokit.rest.pulls.get({
            owner,
            repo,
            pull_number: prNumber,
          }),
          octokit.rest.pulls
            .listReviews({
              owner,
              repo,
              pull_number: prNumber,
            })
            // eslint-disable-next-line id-denylist
            .catch(() => ({ data: [] })),
          // Ignore errors, default to empty
          octokit.rest.issues
            .listComments({
              owner,
              repo,
              issue_number: prNumber,
            })
            // eslint-disable-next-line id-denylist
            .catch(() => ({ data: [] })),
          // Ignore errors, default to empty
        ],
      );

      const pr = prResponse.data;
      const reviews = reviewsResponse.data;
      const comments = commentsResponse.data;

      // Determine review status
      let reviewStatus: "approved" | "changes_requested" | "pending" | null =
        null;
      const latestReviews = new Map<string, string>();

      // Get the latest review state for each reviewer
      for (const review of reviews) {
        if (
          review.state === "APPROVED" ||
          review.state === "CHANGES_REQUESTED"
        ) {
          const existing = latestReviews.get(review.user.login);
          if (
            !existing ||
            new Date(review.submitted_at || "") > new Date(existing)
          ) {
            latestReviews.set(review.user.login, review.state);
          }
        }
      }

      // Determine overall review status
      const hasApproval = Array.from(latestReviews.values()).some(
        (state) => state === "APPROVED",
      );
      const hasChangesRequested = Array.from(latestReviews.values()).some(
        (state) => state === "CHANGES_REQUESTED",
      );

      if (hasApproval && !hasChangesRequested) {
        reviewStatus = "approved";
      } else if (hasChangesRequested) {
        reviewStatus = "changes_requested";
      } else if (reviews.length > 0) {
        reviewStatus = "pending";
      }

      // Fetch project information using GraphQL (PRs use the same issue endpoint)
      const projects = await this.fetchIssueProjects(
        token,
        owner,
        repo,
        prNumber,
      );

      return {
        state: pr.merged ? "merged" : (pr.state as "open" | "closed"),
        title: pr.title,
        labels: pr.labels.map(
          (label: { name?: string; color?: string } | string) => ({
            name: typeof label === "string" ? label : label.name,
            color:
              typeof label === "string" ? "000000" : label.color || "000000",
          }),
        ),
        assignees: pr.assignees.map((assignee) => ({
          login: assignee.login,
          avatar_url: assignee.avatar_url,
        })),
        reviewStatus,
        commentsCount: comments.length,
        mergeable: pr.mergeable,
        merged: pr.merged || false,
        projects: projects.length > 0 ? projects : undefined,
      };
    } catch (error: unknown) {
      const apiUrl = `GET /repos/${owner}/${repo}/pulls/${prNumber}`;
      const fullUrl = `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`;

      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;
      const errorResponse = apiError?.response;

      this.logger.error(`Failed to fetch PR ${owner}/${repo}#${prNumber}`, {
        message: errorMessage,
        status: errorStatus,
        statusText: errorResponse?.statusText,
        url: fullUrl,
        apiEndpoint: apiUrl,
        owner,
        repo,
        prNumber,
        // Log response details if available
        responseData: errorResponse?.data,
        // Check if it's a permissions issue
        isPermissionError: errorStatus === 401 || errorStatus === 403,
        isNotFound: errorStatus === 404,
      });

      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }

      // Log additional context for 404 errors
      if (errorStatus === 404) {
        // Try to check if we can access the repository at all
        try {
          const repoAccess = await this.checkRepositoryAccess(
            this.createClient(token),
            owner,
            repo,
          );

          if (!repoAccess.accessible) {
            this.logger.warn(
              `PR ${owner}/${repo}#${prNumber} returned 404. Repository ${owner}/${repo} is not accessible with the current token. This likely means the repository is private and the token lacks access, or the repository doesn't exist.`,
            );
          } else {
            this.logger.warn(
              `PR ${owner}/${repo}#${prNumber} not found, but repository ${owner}/${repo} is accessible. The PR may not exist or may have been deleted.`,
            );
          }
        } catch (repoCheckError: unknown) {
          this.logger.warn(
            `PR ${owner}/${repo}#${prNumber} not found. Could not verify repository access: ${getErrorMessage(repoCheckError)}. Possible reasons: PR doesn't exist, repository is private and token lacks access, or repository/PR was deleted.`,
          );
        }
      }

      return null;
    }
  }

  /**
   * Fetch status for multiple GitHub links
   */
  async fetchMultipleStatuses(
    token: string,
    links: ParsedGitHubLink[],
  ): Promise<Map<string, GitHubIssueStatus | GitHubPRStatus>> {
    const results = new Map<string, GitHubIssueStatus | GitHubPRStatus>();

    // Fetch all in parallel with rate limiting consideration
    const promises = links.map(async (link) => {
      try {
        let status: GitHubIssueStatus | GitHubPRStatus | null = null;

        if (link.type === "issue") {
          status = await this.fetchIssueStatus(
            token,
            link.owner,
            link.repo,
            link.number,
          );
        } else {
          status = await this.fetchPRStatus(
            token,
            link.owner,
            link.repo,
            link.number,
          );
        }

        if (status) {
          results.set(link.url, status);
        }
      } catch (error: unknown) {
        this.logger.error(
          `Error fetching status for ${link.url}: ${getErrorMessage(error)}`,
        );
      }
    });

    await Promise.all(promises);
    return results;
  }

  /**
   * Create a new GitHub issue
   */
  async createIssue(
    token: string,
    owner: string,
    repo: string,
    title: string,
    body: string,
    labels?: string[],
  ): Promise<unknown> {
    try {
      const octokit = this.createClient(token);
      const response = await octokit.rest.issues.create({
        owner,
        repo,
        title,
        body,
        labels,
      });
      return response.data;
    } catch (error: unknown) {
      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;

      this.logger.error(`Failed to create issue in ${owner}/${repo}`, {
        message: errorMessage,
        status: errorStatus,
      });
      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }
      throw error;
    }
  }

  /**
   * Update issue status (open/closed)
   */
  async updateIssueStatus(
    token: string,
    owner: string,
    repo: string,
    issueNumber: number,
    state: "open" | "closed",
  ): Promise<unknown> {
    try {
      const octokit = this.createClient(token);
      const response = await octokit.rest.issues.update({
        owner,
        repo,
        issue_number: issueNumber,
        state,
      });
      return response.data;
    } catch (error: unknown) {
      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;

      this.logger.error(
        `Failed to update issue ${owner}/${repo}#${issueNumber}`,
        {
          message: errorMessage,
          status: errorStatus,
        },
      );
      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }
      throw error;
    }
  }

  /**
   * Add a comment to an issue
   */
  async addIssueComment(
    token: string,
    owner: string,
    repo: string,
    issueNumber: number,
    body: string,
  ): Promise<unknown> {
    try {
      const octokit = this.createClient(token);
      const response = await octokit.rest.issues.createComment({
        owner,
        repo,
        issue_number: issueNumber,
        body,
      });
      return response.data;
    } catch (error: unknown) {
      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;

      this.logger.error(
        `Failed to add comment to ${owner}/${repo}#${issueNumber}`,
        {
          message: errorMessage,
          status: errorStatus,
        },
      );
      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }
      throw error;
    }
  }

  /**
   * Search for issues using GitHub search API
   */
  async searchIssues(
    token: string,
    query: string,
  ): Promise<
    Array<{ number: number; title: string; state: string; url: string }>
  > {
    try {
      const octokit = this.createClient(token);
      const response = await octokit.rest.search.issuesAndPullRequests({
        q: query,
      });
      return response.data.items.map((item: SearchResultItem) => ({
        number: item.number,
        title: item.title,
        state: item.state,
        url: item.html_url,
        repository: item.repository_url.replace(
          "https://api.github.com/repos/",
          "",
        ),
        body: item.body,
        labels: item.labels.map((label) => ({
          name: label.name,
          color: label.color,
        })),
        createdAt: item.created_at,
        updatedAt: item.updated_at,
      }));
    } catch (error: unknown) {
      const errorMessage = getErrorMessage(error);
      const apiError = isApiError(error) ? error : null;
      const errorStatus = apiError?.status || apiError?.code;

      this.logger.error(`Failed to search issues with query: ${query}`, {
        message: errorMessage,
        status: errorStatus,
      });
      if (errorStatus === 401 || errorStatus === 403) {
        throw new Error("GitHub token is invalid or expired");
      }
      throw error;
    }
  }
}

import { Injectable, OnModuleInit, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import PgBoss = require("pg-boss");
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { GitHubService } from "./github.service";
import { GitHubApiService } from "./github-api.service";
import { GitHubRepoMappingService } from "./github-repo-mapping.service";
import { UsersService } from "../users/users.service";
import { EncryptionHelper } from "../encryption/encryption.helper";

interface FetchGitHubMetadataJob {
  userId: string;
  emailId: string;
  threadId: string;
}

@Injectable()
export class GitHubMetadataProcessor implements OnModuleInit {
  private readonly logger = new Logger(GitHubMetadataProcessor.name);

  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    private readonly githubService: GitHubService,
    private readonly githubApiService: GitHubApiService,
    private readonly repoMappingService: GitHubRepoMappingService,
    private readonly usersService: UsersService,
  ) {}

  async onModuleInit() {
    // Register worker for fetching GitHub metadata
    await this.boss.work<FetchGitHubMetadataJob>(
      "fetch-github-metadata",
      { teamConcurrency: 5 },
      async (job) => {
        const { userId, emailId, threadId } = job.data;

        try {
          await this.processJob(userId, emailId, threadId);
        } catch (error) {
          this.logger.error(
            `Failed to fetch GitHub metadata for email ${emailId}:`,
            error,
          );
          // Let pg-boss handle retry
          throw error;
        }
      },
    );

    this.logger.log("GitHub metadata processor initialized");
  }

  private async processJob(
    userId: string,
    emailId: string,
    threadId: string,
  ): Promise<void> {
    // Check if user has GitHub token
    const user = await this.usersService.findOne(userId);
    if (!user?.githubToken) {
      this.logger.debug(`No GitHub token for user ${userId}, skipping`);
      return;
    }

    // Get the email to parse GitHub links
    const email = await this.emailRepository.findOne({
      where: { id: emailId, userId },
    });

    if (!email) {
      this.logger.warn(`Email ${emailId} not found for user ${userId}`);
      return;
    }

    // Parse GitHub links from email body
    const body = email.body ? EncryptionHelper.decrypt(email.body) : "";
    const htmlBody = email.htmlBody
      ? EncryptionHelper.decrypt(email.htmlBody)
      : undefined;

    const links = this.githubService.parseGitHubLinks(body || "", htmlBody);

    if (links.length === 0) {
      this.logger.debug(`No GitHub links found in email ${emailId}`);
      return;
    }

    // Fetch status for all links
    const token = EncryptionHelper.decrypt(user.githubToken);
    if (!token) {
      this.logger.warn(`Failed to decrypt GitHub token for user ${userId}`);
      return;
    }

    const statuses = await this.githubApiService.fetchMultipleStatuses(
      token,
      links,
    );

    // Build metadata
    const metadataLinks = links.map((link) => {
      const status = statuses.get(link.url);
      return {
        type: link.type,
        repo: link.repo,
        owner: link.owner,
        number: link.number,
        url: link.url,
        status: status
          ? {
              ...status,
              fetchedAt: new Date().toISOString(),
            }
          : undefined,
        fetchedAt: status ? new Date().toISOString() : undefined,
      };
    });

    // Get existing thread metadata to merge (avoid overwriting other data)
    const thread = await this.emailThreadRepository.findOne({
      where: { id: threadId, userId },
    });

    if (!thread) {
      this.logger.warn(`Thread ${threadId} not found for user ${userId}`);
      return;
    }

    // Update thread with GitHub metadata
    const existingMetadata = thread.githubMetadata || {};
    const updatedMetadata = {
      ...existingMetadata,
      links: metadataLinks,
      lastFetchedAt: new Date().toISOString(),
    };

    await this.emailThreadRepository.update(
      { id: threadId, userId },
      { githubMetadata: updatedMetadata },
    );

    this.logger.debug(
      `Updated GitHub metadata for thread ${threadId} with ${metadataLinks.length} links`,
    );

    const threadCategory = thread.category || undefined;
    await this.autoDiscoverReposFromLinks(userId, links, threadCategory);
  }

  private async autoDiscoverReposFromLinks(
    userId: string,
    links: Array<{ owner: string; repo: string }>,
    emailCategory?: string,
  ): Promise<void> {
    const seen = new Set<string>();
    for (const link of links) {
      const key = `${link.owner}/${link.repo}`;
      if (seen.has(key)) continue;
      seen.add(key);

      try {
        await this.repoMappingService.autoDiscoverRepo(
          userId,
          link.owner,
          link.repo,
          emailCategory,
        );
      } catch (error) {
        this.logger.warn(
          `Failed to auto-discover repo ${key} for user ${userId}: ${error}`,
        );
      }
    }
  }
}

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { GitHubRepoMapping } from "../database/entities/github-repo-mapping.entity";

@Injectable()
export class GitHubRepoMappingService {
  private readonly logger = new Logger(GitHubRepoMappingService.name);

  constructor(
    @InjectRepository(GitHubRepoMapping)
    private readonly repoMappingRepository: Repository<GitHubRepoMapping>,
  ) {}

  async findAllForUser(userId: string): Promise<GitHubRepoMapping[]> {
    return this.repoMappingRepository.find({
      where: { userId },
      order: { isDefault: "DESC", updatedAt: "DESC" },
    });
  }

  async findOneForUser(
    userId: string,
    id: string,
  ): Promise<GitHubRepoMapping | null> {
    return this.repoMappingRepository.findOne({
      where: { id, userId },
    });
  }

  async create(
    userId: string,
    data: {
      owner: string;
      repo: string;
      emailCategories?: string;
      context?: string;
      isDefault?: boolean;
      isAutoDiscovered?: boolean;
    },
  ): Promise<GitHubRepoMapping> {
    if (data.isDefault) {
      await this.repoMappingRepository.update(
        { userId, isDefault: true },
        { isDefault: false },
      );
    }

    const mapping = this.repoMappingRepository.create({
      userId,
      owner: data.owner,
      repo: data.repo,
      emailCategories: data.emailCategories || null,
      context: data.context || null,
      isDefault: data.isDefault || false,
      isAutoDiscovered: data.isAutoDiscovered || false,
    });

    return this.repoMappingRepository.save(mapping);
  }

  async update(
    userId: string,
    id: string,
    data: {
      emailCategories?: string;
      context?: string;
      isDefault?: boolean;
    },
  ): Promise<GitHubRepoMapping | null> {
    const mapping = await this.repoMappingRepository.findOne({
      where: { id, userId },
    });

    if (!mapping) {
      return null;
    }

    if (data.isDefault) {
      await this.repoMappingRepository.update(
        { userId, isDefault: true },
        { isDefault: false },
      );
    }

    if (data.emailCategories !== undefined) {
      mapping.emailCategories = data.emailCategories || null;
    }
    if (data.context !== undefined) {
      mapping.context = data.context || null;
    }
    if (data.isDefault !== undefined) {
      mapping.isDefault = data.isDefault;
    }

    return this.repoMappingRepository.save(mapping);
  }

  async remove(userId: string, id: string): Promise<boolean> {
    const result = await this.repoMappingRepository.delete({ id, userId });
    return (result.affected ?? 0) > 0;
  }

  async getDefaultForUser(userId: string): Promise<GitHubRepoMapping | null> {
    return this.repoMappingRepository.findOne({
      where: { userId, isDefault: true },
    });
  }

  async findByCategory(
    userId: string,
    category: string,
  ): Promise<GitHubRepoMapping | null> {
    const mappings = await this.repoMappingRepository.find({
      where: { userId },
    });

    for (const mapping of mappings) {
      if (!mapping.emailCategories) continue;
      const categories = mapping.emailCategories
        .split(",")
        .map((c) => c.trim().toLowerCase());
      if (categories.includes(category.toLowerCase())) {
        return mapping;
      }
    }

    return null;
  }

  async getRepoForEmail(
    userId: string,
    emailCategory?: string | null,
  ): Promise<{ owner: string; repo: string } | null> {
    if (emailCategory) {
      const categoryMapping = await this.findByCategory(userId, emailCategory);
      if (categoryMapping) {
        return { owner: categoryMapping.owner, repo: categoryMapping.repo };
      }
    }

    const defaultMapping = await this.getDefaultForUser(userId);
    if (defaultMapping) {
      return { owner: defaultMapping.owner, repo: defaultMapping.repo };
    }

    return null;
  }

  async autoDiscoverRepo(
    userId: string,
    owner: string,
    repo: string,
    emailCategory?: string,
  ): Promise<GitHubRepoMapping | null> {
    const existing = await this.repoMappingRepository.findOne({
      where: { userId, owner, repo },
    });

    if (existing) {
      if (
        emailCategory &&
        existing.emailCategories &&
        !existing.emailCategories
          .split(",")
          .map((c) => c.trim().toLowerCase())
          .includes(emailCategory.toLowerCase())
      ) {
        existing.emailCategories = `${existing.emailCategories},${emailCategory}`;
        return this.repoMappingRepository.save(existing);
      }

      if (emailCategory && !existing.emailCategories) {
        existing.emailCategories = emailCategory;
        return this.repoMappingRepository.save(existing);
      }

      return existing;
    }

    this.logger.log(
      `Auto-discovering GitHub repo ${owner}/${repo} for user ${userId}`,
    );

    const hasAny = await this.repoMappingRepository.count({
      where: { userId },
    });

    const mapping = this.repoMappingRepository.create({
      userId,
      owner,
      repo,
      emailCategories: emailCategory || null,
      isAutoDiscovered: true,
      isDefault: hasAny === 0,
    });

    return this.repoMappingRepository.save(mapping);
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  UseGuards,
  Request,
  Logger,
  Res,
  Query,
  Inject,
  NotFoundException,
} from "@nestjs/common";
import { In } from "typeorm";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { Response } from "express";
import PgBoss = require("pg-boss");
import { JwtAuthGuard } from "../auth/jwt-auth.guard";
import { GitHubService, ParsedGitHubLink } from "./github.service";
import { GitHubApiService } from "./github-api.service";
import { GitHubAppService } from "./github-app.service";
import { UsersService } from "../users/users.service";
import { isError } from "../types/common";
import { EmailsService } from "../emails/emails.service";
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { EncryptionHelper } from "../encryption/encryption.helper";
import { GitHubRepoMappingService } from "./github-repo-mapping.service";

@Controller("github")
@UseGuards(JwtAuthGuard)
export class GitHubController {
  private readonly logger = new Logger(GitHubController.name);

  constructor(
    private readonly githubService: GitHubService,
    private readonly githubApiService: GitHubApiService,
    private readonly githubAppService: GitHubAppService,
    private readonly usersService: UsersService,
    private readonly emailsService: EmailsService,
    @InjectRepository(EmailThread)
    private readonly emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private readonly emailRepository: Repository<Email>,
    @Inject("PG_BOSS") private readonly boss: PgBoss,
    private readonly repoMappingService: GitHubRepoMappingService,
  ) {}

  @Get("emails/:id")
  // eslint-disable-next-line max-statements
  async getEmailGitHubInfo(@Request() req, @Param("id") emailId: string) {
    const { userId } = req.user;

    // Get email
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email || !email.emailThreadId) {
      throw new Error("Email not found");
    }

    // Get thread
    const thread = await this.emailThreadRepository.findOne({
      where: { id: email.emailThreadId, userId },
    });
    if (!thread) {
      throw new Error("Thread not found");
    }

    // Get user's GitHub token
    const user = await this.usersService.findOne(userId);
    if (!user || !user.githubToken) {
      return { links: [], hasToken: false };
    }

    const token = EncryptionHelper.decrypt(user.githubToken);

    // Get all emails in thread to parse GitHub links from all of them
    const threadEmails = await this.emailRepository.find({
      where: { userId, emailThreadId: email.emailThreadId },
    });

    // Parse GitHub links from all emails in thread
    const allLinks = new Map<string, ParsedGitHubLink>();
    // Use Map to deduplicate by URL
    for (const threadEmail of threadEmails) {
      const links = this.githubService.parseGitHubLinks(
        threadEmail.body || "",
        threadEmail.htmlBody || undefined,
      );
      for (const link of links) {
        allLinks.set(link.url, link);
      }
    }

    const uniqueLinks = Array.from(allLinks.values());

    if (uniqueLinks.length === 0) {
      return { links: [], hasToken: true };
    }

    // Check if we already have cached metadata that's less than 1 hour old
    if (thread.githubMetadata && thread.githubMetadata.links.length > 0) {
      const now = new Date();
      const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

      // Check if all links in the cache match current links and have been fetched recently
      const cachedLinksMap = new Map(
        thread.githubMetadata.links.map((link) => [link.url, link]),
      );

      // Check if all current links are in cache and fresh
      const allLinksCachedAndFresh = uniqueLinks.every((link) => {
        const cachedLink = cachedLinksMap.get(link.url);
        if (!cachedLink || !cachedLink.status || !cachedLink.fetchedAt) {
          return false;
        }
        const fetchedAt = new Date(cachedLink.fetchedAt);
        return fetchedAt > oneHourAgo;
      });

      // If all links are cached and fresh, return cached data
      if (allLinksCachedAndFresh) {
        // Return cached links that match current links (already deduplicated via uniqueLinks)
        const cachedLinksToReturn = uniqueLinks
          .map((link) => cachedLinksMap.get(link.url))
          .filter((link) => link !== undefined);

        // Double-check deduplication before returning
        const seenUrls = new Set<string>();
        const dedupedLinks = cachedLinksToReturn.filter((link) => {
          const key = link.url || `${link.owner}-${link.repo}-${link.number}`;
          if (seenUrls.has(key)) {
            return false;
          }
          seenUrls.add(key);
          return true;
        });

        return {
          links: dedupedLinks,
          hasToken: true,
        };
      }
    }

    // Fetch fresh status for all links
    try {
      const statuses = await this.githubApiService.fetchMultipleStatuses(
        token,
        uniqueLinks,
      );

      const metadataLinks = uniqueLinks.map((link) => {
        const status = statuses.get(link.url);
        return {
          type: link.type,
          repo: link.repo,
          owner: link.owner,
          number: link.number,
          url: link.url,
          status: status
            ? {
                ...status,
                fetchedAt: new Date().toISOString(),
              }
            : undefined,
          fetchedAt: status ? new Date().toISOString() : undefined,
        };
      });

      // Update thread with GitHub metadata
      thread.githubMetadata = {
        links: metadataLinks,
      };
      await this.emailThreadRepository.save(thread);

      return {
        links: metadataLinks,
        hasToken: true,
      };
    } catch (error: unknown) {
      const errorMessage = isError(error) ? error.message : "Unknown error";
      this.logger.error(`Error fetching GitHub statuses: ${errorMessage}`);
      throw error;
    }
  }

  @Post("emails/:id/refresh")
  async refreshEmailGitHubInfo(@Request() req, @Param("id") emailId: string) {
    const { userId } = req.user;

    // Get email
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email || !email.emailThreadId) {
      throw new Error("Email not found");
    }

    // Get thread
    const thread = await this.emailThreadRepository.findOne({
      where: { id: email.emailThreadId, userId },
    });
    if (!thread) {
      throw new Error("Thread not found");
    }

    // Get user's GitHub token
    const user = await this.usersService.findOne(userId);
    if (!user || !user.githubToken) {
      throw new Error("GitHub token not configured");
    }

    const token = EncryptionHelper.decrypt(user.githubToken);

    // Get all emails in thread to parse GitHub links from all of them
    const threadEmails = await this.emailRepository.find({
      where: { userId, emailThreadId: email.emailThreadId },
    });

    // Parse GitHub links from all emails in thread
    const allLinks = new Map<string, ParsedGitHubLink>();
    // Use Map to deduplicate by URL
    for (const threadEmail of threadEmails) {
      const links = this.githubService.parseGitHubLinks(
        threadEmail.body || "",
        threadEmail.htmlBody || undefined,
      );
      for (const link of links) {
        allLinks.set(link.url, link);
      }
    }

    const uniqueLinks = Array.from(allLinks.values());

    if (uniqueLinks.length === 0) {
      return { links: [], message: "No GitHub links found in thread" };
    }

    // Fetch fresh status for all links
    try {
      const statuses = await this.githubApiService.fetchMultipleStatuses(
        token,
        uniqueLinks,
      );

      const metadataLinks = uniqueLinks.map((link) => {
        const status = statuses.get(link.url);
        return {
          type: link.type,
          repo: link.repo,
          owner: link.owner,
          number: link.number,
          url: link.url,
          status: status
            ? {
                ...status,
                fetchedAt: new Date().toISOString(),
              }
            : undefined,
          fetchedAt: status ? new Date().toISOString() : undefined,
        };
      });

      // Update thread with GitHub metadata
      thread.githubMetadata = {
        links: metadataLinks,
      };
      await this.emailThreadRepository.save(thread);

      return {
        links: metadataLinks,
        message: "GitHub status refreshed successfully",
      };
    } catch (error: unknown) {
      const errorMessage = isError(error) ? error.message : "Unknown error";
      this.logger.error(`Error refreshing GitHub statuses: ${errorMessage}`);
      throw error;
    }
  }

  @Post("batch-status")
  async batchGetGitHubStatus(
    @Request() req,
    @Body() body: { emailIds: string[] },
  ) {
    const { userId } = req.user;
    const { emailIds } = body;

    if (!emailIds || emailIds.length === 0) {
      return {};
    }

    const emails = await this.emailRepository.find({
      where: { id: In(emailIds), userId },
      select: ["id", "emailThreadId"],
    });

    if (emails.length === 0) {
      return {};
    }

    const threadIds = [
      ...new Set(
        emails.map((e) => e.emailThreadId).filter((id): id is string => !!id),
      ),
    ];

    const threads = await this.emailThreadRepository.find({
      where: { id: In(threadIds), userId },
    });

    const threadMap = new Map(threads.map((t) => [t.id, t]));

    const result: Record<
      string,
      { links: Array<Record<string, unknown>>; pending?: boolean } | null
    > = {};

    for (const email of emails) {
      if (!email.emailThreadId) {
        result[email.id] = null;
        continue;
      }

      const thread = threadMap.get(email.emailThreadId);
      if (!thread) {
        result[email.id] = null;
        continue;
      }

      if (
        thread.githubMetadata &&
        thread.githubMetadata.links &&
        thread.githubMetadata.links.length > 0 &&
        thread.githubMetadata.links.some((link) => link.status)
      ) {
        result[email.id] = { links: thread.githubMetadata.links };
      } else {
        result[email.id] = { links: [], pending: true };
        this.boss
          .send(
            "fetch-github-metadata",
            { userId, emailId: email.id, threadId: email.emailThreadId },
            {
              singletonKey: `github-metadata-${email.emailThreadId}`,
              singletonMinutes: 60,
            },
          )
          .catch((err: unknown) => {
            const errMsg = isError(err) ? err.message : "Unknown error";
            this.logger.error(
              `Failed to queue GitHub metadata job for email ${email.id}: ${errMsg}`,
            );
          });
      }
    }

    return result;
  }

  @Get("repo-mappings")
  async getRepoMappings(@Request() req) {
    const { userId } = req.user;
    return this.repoMappingService.findAllForUser(userId);
  }

  @Post("repo-mappings")
  async createRepoMapping(
    @Request() req,
    @Body()
    body: {
      owner: string;
      repo: string;
      emailCategories?: string;
      context?: string;
      isDefault?: boolean;
    },
  ) {
    const { userId } = req.user;
    return this.repoMappingService.create(userId, body);
  }

  @Put("repo-mappings/:id")
  async updateRepoMapping(
    @Request() req,
    @Param("id") id: string,
    @Body()
    body: {
      emailCategories?: string;
      context?: string;
      isDefault?: boolean;
    },
  ) {
    const { userId } = req.user;
    const mapping = await this.repoMappingService.update(userId, id, body);
    if (!mapping) {
      throw new NotFoundException("Repo mapping not found");
    }
    return mapping;
  }

  @Delete("repo-mappings/:id")
  async deleteRepoMapping(@Request() req, @Param("id") id: string) {
    const { userId } = req.user;
    const deleted = await this.repoMappingService.remove(userId, id);
    if (!deleted) {
      throw new NotFoundException("Repo mapping not found");
    }
    return { success: true };
  }

  @Get("repo-mappings/default")
  async getDefaultRepoMapping(@Request() req) {
    const { userId } = req.user;
    return this.repoMappingService.getDefaultForUser(userId);
  }

  @Get("connect")
  @UseGuards(JwtAuthGuard)
  async connect(@Request() req, @Res() res: Response) {
    const { userId } = req.user;
    const authUrl = this.githubAppService.getAuthorizationUrl(userId);
    return res.redirect(authUrl);
  }

  @Get("callback")
  async callback(
    @Query("code") code: string,
    @Query("state") state: string,
    @Res() res: Response,
  ) {
    const frontendUrl = this.githubAppService.getFrontendUrl();
    const settingsUrl = `${frontendUrl}/settings?github=connected`;

    try {
      if (!code) {
        this.logger.error("GitHub OAuth callback missing authorization code");
        return res.redirect(`${frontendUrl}/settings?github=error`);
      }

      // Decode state to get userId
      let userId: string;
      try {
        const stateData = JSON.parse(Buffer.from(state, "base64").toString());
        userId = stateData.userId;
      } catch (error) {
        this.logger.error("Failed to decode state parameter:", error);
        return res.redirect(`${frontendUrl}/settings?github=error`);
      }

      // Exchange code for access token
      const accessToken =
        await this.githubAppService.exchangeCodeForToken(code);

      // Store token for user
      await this.githubAppService.storeTokenForUser(userId, accessToken);

      this.logger.log(`GitHub OAuth successful for user ${userId}`);
      return res.redirect(settingsUrl);
    } catch (error) {
      const errorMessage = isError(error) ? error.message : "Unknown error";
      this.logger.error(`GitHub OAuth callback error: ${errorMessage}`, error);
      return res.redirect(`${frontendUrl}/settings?github=error`);
    }
  }
}

import { Test, TestingModule } from "@nestjs/testing";
import { GitHubService } from "./github.service";

describe("GitHubService", () => {
  let service: GitHubService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [GitHubService],
    }).compile();

    service = module.get<GitHubService>(GitHubService);
  });

  describe("parseGitHubLinks", () => {
    it("should parse issue URL from plain text", () => {
      const emailBody =
        "Check out this issue: https://github.com/owner/repo/issues/123";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0]).toEqual({
        type: "issue",
        owner: "owner",
        repo: "repo",
        number: 123,
        url: "https://github.com/owner/repo/issues/123",
      });
    });

    it("should parse pull request URL from plain text", () => {
      const emailBody =
        "Check out this PR: https://github.com/owner/repo/pull/456";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0]).toEqual({
        type: "pr",
        owner: "owner",
        repo: "repo",
        number: 456,
        url: "https://github.com/owner/repo/pull/456",
      });
    });

    it("should parse multiple links from plain text", () => {
      const emailBody = `
        Issue 1: https://github.com/owner/repo/issues/123
        PR 1: https://github.com/owner/repo/pull/456
        Issue 2: https://github.com/other/repo/issues/789
      `;
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(3);
      expect(links[0].number).toBe(123);
      expect(links[1].number).toBe(456);
      expect(links[2].number).toBe(789);
    });

    it("should deduplicate identical URLs", () => {
      const emailBody = `
        https://github.com/owner/repo/issues/123
        https://github.com/owner/repo/issues/123
        https://github.com/owner/repo/issues/123
      `;
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });

    it("should remove URL fragments and query params", () => {
      const emailBody =
        "https://github.com/owner/repo/issues/123#comment-456?param=value";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].url).toBe("https://github.com/owner/repo/issues/123");
    });

    it("should parse links from HTML body", () => {
      const htmlBody =
        '<p>Check out <a href="https://github.com/owner/repo/issues/123">this issue</a></p>';
      const links = service.parseGitHubLinks("", htmlBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });

    it("should parse links from HTML text content", () => {
      const htmlBody =
        "<p>Check out https://github.com/owner/repo/issues/123</p>";
      const links = service.parseGitHubLinks("", htmlBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });

    it("should parse both plain text and HTML body", () => {
      const emailBody = "Plain: https://github.com/owner/repo/issues/123";
      const htmlBody =
        '<p>HTML: <a href="https://github.com/owner/repo/pull/456">PR</a></p>';
      const links = service.parseGitHubLinks(emailBody, htmlBody);

      expect(links.length).toBe(2);
      expect(links.find((l) => l.type === "issue")?.number).toBe(123);
      expect(links.find((l) => l.type === "pr")?.number).toBe(456);
    });

    it("should deduplicate between plain text and HTML", () => {
      const emailBody = "https://github.com/owner/repo/issues/123";
      const htmlBody =
        '<p><a href="https://github.com/owner/repo/issues/123">Same issue</a></p>';
      const links = service.parseGitHubLinks(emailBody, htmlBody);

      expect(links.length).toBe(1);
    });

    it("should handle HTTP URLs", () => {
      const emailBody = "http://github.com/owner/repo/issues/123";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].url).toContain("http://");
    });

    it("should handle URLs with trailing slashes", () => {
      const emailBody = "https://github.com/owner/repo/issues/123/";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      // URL may or may not have trailing slash depending on implementation
      expect(links[0].url).toMatch(
        /^https:\/\/github\.com\/owner\/repo\/issues\/123\/?$/,
      );
    });

    it("should return empty array for email with no GitHub links", () => {
      const emailBody = "This is a regular email with no GitHub links.";
      const links = service.parseGitHubLinks(emailBody);

      expect(links).toEqual([]);
    });

    it("should return empty array for empty email body", () => {
      const links = service.parseGitHubLinks("");

      expect(links).toEqual([]);
    });

    it("should handle complex HTML with multiple links", () => {
      const htmlBody = `
        <div>
          <p>Issue: <a href="https://github.com/owner/repo/issues/123">#123</a></p>
          <p>PR: <a href="https://github.com/owner/repo/pull/456">#456</a></p>
          <p>Another: https://github.com/other/repo/issues/789</p>
        </div>
      `;
      const links = service.parseGitHubLinks("", htmlBody);

      expect(links.length).toBe(3);
    });

    it("should handle URLs with special characters in owner/repo names", () => {
      const emailBody = "https://github.com/user-name/repo.name/issues/123";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].owner).toBe("user-name");
      expect(links[0].repo).toBe("repo.name");
    });

    it("should handle case-insensitive matching in href attributes", () => {
      const htmlBody =
        '<a href="HTTPS://GITHUB.COM/OWNER/REPO/ISSUES/123">Link</a>';
      const links = service.parseGitHubLinks("", htmlBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });

    it("should handle single quotes in href attributes", () => {
      const htmlBody =
        "<a href='https://github.com/owner/repo/issues/123'>Link</a>";
      const links = service.parseGitHubLinks("", htmlBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });

    it("should parse large issue numbers", () => {
      const emailBody = "https://github.com/owner/repo/issues/99999";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(99999);
    });

    it("should handle URLs in markdown-style links", () => {
      const emailBody =
        "[Issue #123](https://github.com/owner/repo/issues/123)";
      const links = service.parseGitHubLinks(emailBody);

      expect(links.length).toBe(1);
      expect(links[0].number).toBe(123);
    });
  });
});

import { Test, TestingModule } from "@nestjs/testing";
import { getRepositoryToken } from "@nestjs/typeorm";
import { NotFoundException } from "@nestjs/common";
import { GoogleAccountsService } from "./google-accounts.service";
import { GoogleAccount } from "../database/entities/google-account.entity";
import { UsersService } from "../users/users.service";

describe("GoogleAccountsService", () => {
  let service: GoogleAccountsService;
  let repository: any;

  const mockGoogleAccount: GoogleAccount = {
    id: "account-1",
    userId: "user-1",
    googleId: "google-id-1",
    email: "user@gmail.com",
    name: "Test User",
    accessToken: "access-token-1",
    refreshToken: "refresh-token-1",
    isPrimary: false,
    isActive: true,
    needsRelogin: false,
    createdAt: new Date("2024-01-01"),
    updatedAt: new Date("2024-01-01"),
  } as GoogleAccount;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        GoogleAccountsService,
        {
          provide: getRepositoryToken(GoogleAccount),
          useValue: {
            create: jest.fn(),
            save: jest.fn(),
            find: jest.fn(),
            findOne: jest.fn(),
            update: jest.fn(),
            count: jest.fn(),
          },
        },
        {
          provide: UsersService,
          useValue: {},
        },
      ],
    }).compile();

    service = module.get<GoogleAccountsService>(GoogleAccountsService);
    repository = module.get(getRepositoryToken(GoogleAccount));
    jest.clearAllMocks();
  });

  describe("create", () => {
    it("should create a new Google account", async () => {
      repository.update.mockResolvedValue({ affected: 0 } as any);
      repository.create.mockReturnValue(mockGoogleAccount as GoogleAccount);
      repository.save.mockResolvedValue(mockGoogleAccount);

      const result = await service.create(
        "user-1",
        "google-id-1",
        "user@gmail.com",
        "Test User",
        "access-token-1",
        "refresh-token-1",
        false,
      );

      expect(repository.create).toHaveBeenCalledWith({
        userId: "user-1",
        googleId: "google-id-1",
        email: "user@gmail.com",
        name: "Test User",
        accessToken: "access-token-1",
        refreshToken: "refresh-token-1",
        isPrimary: false,
        isActive: true,
        needsRelogin: false,
      });
      expect(repository.save).toHaveBeenCalledWith(mockGoogleAccount);
      expect(result).toEqual(mockGoogleAccount);
    });

    it("should unset other primary accounts when creating primary account", async () => {
      repository.update.mockResolvedValue({ affected: 1 } as any);
      const primaryAccount = { ...mockGoogleAccount, isPrimary: true };
      repository.create.mockReturnValue(primaryAccount as GoogleAccount);
      repository.save.mockResolvedValue(primaryAccount);

      await service.create(
        "user-1",
        "google-id-1",
        "user@gmail.com",
        "Test User",
        "access-token-1",
        "refresh-token-1",
        true, // isPrimary
      );

      expect(repository.update).toHaveBeenCalledWith(
        { userId: "user-1", isPrimary: true },
        { isPrimary: false },
      );
      expect(repository.create).toHaveBeenCalledWith(
        expect.objectContaining({ isPrimary: true }),
      );
    });

    it("should create account with default isPrimary false", async () => {
      repository.update.mockResolvedValue({ affected: 0 } as any);
      repository.create.mockReturnValue(mockGoogleAccount as GoogleAccount);
      repository.save.mockResolvedValue(mockGoogleAccount);

      await service.create(
        "user-1",
        "google-id-1",
        "user@gmail.com",
        "Test User",
        "access-token-1",
        "refresh-token-1",
      );

      expect(repository.create).toHaveBeenCalledWith(
        expect.objectContaining({ isPrimary: false }),
      );
    });
  });

  describe("findAllByUser", () => {
    it("should return all active accounts for a user ordered by primary first", async () => {
      const mockAccounts = [
        { ...mockGoogleAccount, isPrimary: true },
        { ...mockGoogleAccount, id: "account-2", isPrimary: false },
      ];
      repository.find.mockResolvedValue(mockAccounts);

      const result = await service.findAllByUser("user-1");

      expect(repository.find).toHaveBeenCalledWith({
        where: { userId: "user-1", isActive: true },
        order: { isPrimary: "DESC", createdAt: "ASC" },
      });
      expect(result).toEqual(mockAccounts);
    });

    it("should return empty array when user has no active accounts", async () => {
      repository.find.mockResolvedValue([]);

      const result = await service.findAllByUser("user-1");

      expect(result).toEqual([]);
    });

    it("should only return active accounts", async () => {
      const activeAccount = { ...mockGoogleAccount, isActive: true };
      repository.find.mockResolvedValue([activeAccount]);

      await service.findAllByUser("user-1");

      expect(repository.find).toHaveBeenCalledWith({
        where: { userId: "user-1", isActive: true },
        order: { isPrimary: "DESC", createdAt: "ASC" },
      });
    });
  });

  describe("findPrimary", () => {
    it("should return primary active account for a user", async () => {
      const primaryAccount = { ...mockGoogleAccount, isPrimary: true };
      repository.findOne.mockResolvedValue(primaryAccount);

      const result = await service.findPrimary("user-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { userId: "user-1", isPrimary: true, isActive: true },
      });
      expect(result).toEqual(primaryAccount);
    });

    it("should return null when user has no primary account", async () => {
      repository.findOne.mockResolvedValue(null);

      const result = await service.findPrimary("user-1");

      expect(result).toBeNull();
    });

    it("should only return active primary accounts", async () => {
      repository.findOne.mockResolvedValue(null);

      await service.findPrimary("user-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { userId: "user-1", isPrimary: true, isActive: true },
      });
    });
  });

  describe("findById", () => {
    it("should return account by id and userId", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);

      const result = await service.findById("account-1", "user-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { id: "account-1", userId: "user-1", isActive: true },
      });
      expect(result).toEqual(mockGoogleAccount);
    });

    it("should return null when account not found", async () => {
      repository.findOne.mockResolvedValue(null);

      const result = await service.findById("nonexistent-id", "user-1");

      expect(result).toBeNull();
    });

    it("should only return active accounts", async () => {
      repository.findOne.mockResolvedValue(null);

      await service.findById("account-1", "user-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { id: "account-1", userId: "user-1", isActive: true },
      });
    });
  });

  describe("updateTokens", () => {
    it("should update access token", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      const updatedAccount = {
        ...mockGoogleAccount,
        accessToken: "new-access-token",
      };
      repository.save.mockResolvedValue(updatedAccount);

      const result = await service.updateTokens(
        "account-1",
        "user-1",
        "new-access-token",
      );

      expect(mockGoogleAccount.accessToken).toBe("new-access-token");
      expect(mockGoogleAccount.needsRelogin).toBe(false);
      expect(repository.save).toHaveBeenCalledWith(mockGoogleAccount);
      expect(result).toEqual(updatedAccount);
    });

    it("should update refresh token when provided", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      const updatedAccount = {
        ...mockGoogleAccount,
        accessToken: "new-access-token",
        refreshToken: "new-refresh-token",
      };
      repository.save.mockResolvedValue(updatedAccount);

      const result = await service.updateTokens(
        "account-1",
        "user-1",
        "new-access-token",
        "new-refresh-token",
      );

      expect(mockGoogleAccount.refreshToken).toBe("new-refresh-token");
      expect(result).toEqual(updatedAccount);
    });

    it("should not update refresh token when not provided", async () => {
      const freshAccount = {
        ...mockGoogleAccount,
        refreshToken: "original-refresh-token",
      };
      repository.findOne.mockResolvedValue(freshAccount);
      const updatedAccount = {
        ...freshAccount,
        accessToken: "new-access-token",
      };
      repository.save.mockResolvedValue(updatedAccount);

      await service.updateTokens("account-1", "user-1", "new-access-token");

      expect(freshAccount.refreshToken).toBe("original-refresh-token"); // Original value
    });

    it("should throw NotFoundException when account not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(
        service.updateTokens("nonexistent-id", "user-1", "new-access-token"),
      ).rejects.toThrow(NotFoundException);
      expect(repository.findOne).toHaveBeenCalledWith({
        where: { id: "nonexistent-id", userId: "user-1", isActive: true },
      });
    });

    it("should set needsRelogin to false after token update", async () => {
      const accountWithRelogin = { ...mockGoogleAccount, needsRelogin: true };
      repository.findOne.mockResolvedValue(accountWithRelogin);
      repository.save.mockResolvedValue({
        ...accountWithRelogin,
        needsRelogin: false,
      });

      await service.updateTokens("account-1", "user-1", "new-access-token");

      expect(accountWithRelogin.needsRelogin).toBe(false);
    });
  });

  describe("setPrimary", () => {
    it("should set account as primary and unset others", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      repository.update.mockResolvedValue({ affected: 1 } as any);
      const primaryAccount = { ...mockGoogleAccount, isPrimary: true };
      repository.save.mockResolvedValue(primaryAccount);

      const result = await service.setPrimary("account-1", "user-1");

      expect(repository.update).toHaveBeenCalledWith(
        { userId: "user-1", isPrimary: true },
        { isPrimary: false },
      );
      expect(mockGoogleAccount.isPrimary).toBe(true);
      expect(repository.save).toHaveBeenCalledWith(mockGoogleAccount);
      expect(result).toEqual(primaryAccount);
    });

    it("should throw NotFoundException when account not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(
        service.setPrimary("nonexistent-id", "user-1"),
      ).rejects.toThrow(NotFoundException);
    });

    it("should unset other primary accounts before setting new primary", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      repository.update.mockResolvedValue({ affected: 2 } as any);
      repository.save.mockResolvedValue({
        ...mockGoogleAccount,
        isPrimary: true,
      });

      await service.setPrimary("account-1", "user-1");

      // Verify both methods were called
      expect(repository.update).toHaveBeenCalled();
      expect(repository.save).toHaveBeenCalled();
    });
  });

  describe("deactivate", () => {
    it("should deactivate an account", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      const deactivatedAccount = { ...mockGoogleAccount, isActive: false };
      repository.save.mockResolvedValue(deactivatedAccount);

      await service.deactivate("account-1", "user-1");

      expect(mockGoogleAccount.isActive).toBe(false);
      expect(repository.save).toHaveBeenCalledWith(mockGoogleAccount);
    });

    it("should throw NotFoundException when account not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(
        service.deactivate("nonexistent-id", "user-1"),
      ).rejects.toThrow(NotFoundException);
    });

    it("should only deactivate accounts for the specified user", async () => {
      repository.findOne.mockResolvedValue(mockGoogleAccount);
      repository.save.mockResolvedValue({
        ...mockGoogleAccount,
        isActive: false,
      });

      await service.deactivate("account-1", "user-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { id: "account-1", userId: "user-1", isActive: true },
      });
    });
  });

  describe("hasConnectedGmail", () => {
    it("should return true when user has active accounts", async () => {
      repository.count.mockResolvedValue(1);

      const result = await service.hasConnectedGmail("user-1");

      expect(repository.count).toHaveBeenCalledWith({
        where: { userId: "user-1", isActive: true },
      });
      expect(result).toBe(true);
    });

    it("should return false when user has no active accounts", async () => {
      repository.count.mockResolvedValue(0);

      const result = await service.hasConnectedGmail("user-1");

      expect(result).toBe(false);
    });

    it("should only count active accounts", async () => {
      repository.count.mockResolvedValue(0);

      await service.hasConnectedGmail("user-1");

      expect(repository.count).toHaveBeenCalledWith({
        where: { userId: "user-1", isActive: true },
      });
    });
  });
});

import {
  cleanEmailContent,
  cleanEmailForThread,
  getEmailPreview,
} from "./email-content-cleaner";

describe("EmailContentCleaner", () => {
  describe("cleanEmailContent", () => {
    it("should return empty string for null body", () => {
      const result = cleanEmailContent(null);
      expect(result).toBe("");
    });

    it("should return empty string for undefined body", () => {
      const result = cleanEmailContent(undefined);
      expect(result).toBe("");
    });

    it("should return empty string for empty string", () => {
      const result = cleanEmailContent("");
      expect(result).toBe("");
    });

    it("should trim whitespace", () => {
      const result = cleanEmailContent("  Hello World  ");
      expect(result).toBe("Hello World");
    });

    it("should strip HTML tags", () => {
      const result = cleanEmailContent("<p>Hello <strong>World</strong></p>");
      expect(result).toBe("Hello World");
    });

    it("should remove style blocks", () => {
      const html = "<style>body { color: red; }</style>Hello World";
      const result = cleanEmailContent(html);
      expect(result).toBe("Hello World");
    });

    it("should remove script blocks", () => {
      const html = '<script>alert("xss")</script>Hello World';
      const result = cleanEmailContent(html);
      expect(result).toBe("Hello World");
    });

    it("should convert block elements to newlines", () => {
      const html = "<p>Line 1</p><div>Line 2</div>";
      const result = cleanEmailContent(html);
      expect(result).toContain("Line 1");
      expect(result).toContain("Line 2");
    });

    it("should decode HTML entities", () => {
      // Note: The actual implementation only decodes in stripHtml, not in cleanEmailContent directly
      // This test checks that HTML entities in HTML content get decoded
      const html = "<p>Hello &amp; World</p>";
      const result = cleanEmailContent(html);
      expect(result).toContain("Hello");
      expect(result).toContain("World");
    });

    it("should decode numeric HTML entities in HTML content", () => {
      const html = "<p>Hello &#65; World</p>"; // &#65; is 'A'
      const result = cleanEmailContent(html);
      // The implementation should decode when processing HTML
      expect(result).toContain("Hello");
      expect(result).toContain("World");
    });

    it("should remove email signatures with -- when there is sufficient content", () => {
      // Signature removal only works if there's >50 chars before the signature
      const longPrefix = "A".repeat(60);
      const text = `${longPrefix}\n\n--\nJohn Doe`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("--");
    });

    it('should remove email signatures with "Best regards" when there is sufficient content', () => {
      const longPrefix = "A".repeat(60);
      const text = `${longPrefix}\n\nBest regards,\nJohn Doe`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("Best regards");
    });

    it('should remove quoted replies starting with "On ... wrote:" when there is sufficient content', () => {
      const longPrefix = "A".repeat(110);
      const text = `${longPrefix}\n\nOn Jan 1, 2024, John wrote:\n> Previous message`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("On Jan 1, 2024");
    });

    it("should remove lines starting with >", () => {
      const text = "Hello World\n\n> Quoted text\n> More quoted text";
      const result = cleanEmailContent(text);
      expect(result).not.toContain("> Quoted");
    });

    it('should remove Outlook-style "Original Message" blocks when there is sufficient content', () => {
      const longPrefix = "A".repeat(110);
      const text = `${longPrefix}\n\n-----Original Message-----\nFrom: test@example.com`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("Original Message");
    });

    it("should remove Outlook forwarded headers when there is sufficient content", () => {
      const longPrefix = "A".repeat(110);
      const text = `${longPrefix}\n\nFrom: test@example.com\nSent: Jan 1\nTo: you@example.com\nSubject: Test`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("From: test@example.com");
    });

    it("should normalize whitespace", () => {
      const text = "Hello    World\n\n\n\nTest";
      const result = cleanEmailContent(text);
      expect(result).not.toContain("    "); // Multiple spaces
      expect(result.split("\n\n\n").length).toBe(1); // No triple newlines
    });

    it("should normalize line endings (CRLF to LF)", () => {
      const text = "Hello World\r\nTest Line";
      const result = cleanEmailContent(text);
      expect(result).not.toContain("\r\n");
    });

    it("should truncate text longer than maxLength", () => {
      const longText = "A".repeat(3000);
      const result = cleanEmailContent(longText, undefined, 1000);
      expect(result.length).toBeLessThanOrEqual(1000 + 3); // +3 for "..."
    });

    it("should prefer htmlBody with proper stripping over plain text body", () => {
      const plainText = "Plain text content";
      const htmlBody = "<p>HTML content</p>";
      const result = cleanEmailContent(plainText, htmlBody);
      expect(result).toBe("HTML content");
    });

    it("should use htmlBody when body is empty", () => {
      const htmlBody = "<p>HTML content</p>";
      const result = cleanEmailContent("", htmlBody);
      expect(result).toContain("HTML content");
    });

    it("should use htmlBody when body starts with <", () => {
      const body = "<html><body>Content</body></html>";
      const htmlBody = "<p>HTML content</p>";
      const result = cleanEmailContent(body, htmlBody);
      expect(result).toContain("HTML content");
    });

    it("should not remove short content before signature markers", () => {
      // Signature should only be removed if there's meaningful content (>50 chars) before it
      const shortText = "Hi\n\n--\nJohn";
      const result = cleanEmailContent(shortText);
      expect(result).toContain("Hi");
    });

    it('should remove "Sent from my iPhone" signatures when there is sufficient content', () => {
      const longPrefix = "A".repeat(60);
      const text = `${longPrefix}\n\nSent from my iPhone`;
      const result = cleanEmailContent(text);
      expect(result).not.toContain("Sent from my iPhone");
    });

    it("should handle smart truncation at sentence boundary", () => {
      const text = `First sentence. Second sentence. Third sentence. ${"A".repeat(2000)}`;
      const result = cleanEmailContent(text, undefined, 100);
      // Should end at a sentence boundary or add "..."
      expect(result).toMatch(/(\.|\.\.\.)$/);
    });

    it("should handle truncation at word boundary when no sentence boundary", () => {
      const text = `${"A".repeat(3000)} word`;
      const result = cleanEmailContent(text, undefined, 100);
      expect(result).toMatch(/(\.\.\.|word)$/);
    });
  });

  describe("cleanEmailForThread", () => {
    it("should use smaller maxLength per message", () => {
      const longText = "A".repeat(2000);
      const result = cleanEmailForThread(longText, undefined, 500);
      expect(result.length).toBeLessThanOrEqual(503); // +3 for "..."
    });

    it("should default to 500 maxLength", () => {
      const longText = "A".repeat(2000);
      const result = cleanEmailForThread(longText);
      expect(result.length).toBeLessThanOrEqual(503);
    });

    it("should process content same as cleanEmailContent", () => {
      const html = "<p>Hello <strong>World</strong></p>";
      const result = cleanEmailForThread(html);
      expect(result).toBe("Hello World");
    });
  });

  describe("getEmailPreview", () => {
    it("should return preview limited to maxLength", () => {
      const longText = "A".repeat(500);
      const result = getEmailPreview(longText, undefined, 150);
      expect(result.length).toBeLessThanOrEqual(150);
    });

    it("should default to 150 maxLength", () => {
      const longText = "A".repeat(500);
      const result = getEmailPreview(longText);
      expect(result.length).toBeLessThanOrEqual(150);
    });

    it("should remove newlines from preview", () => {
      const text = "Line 1\nLine 2\nLine 3";
      const result = getEmailPreview(text);
      expect(result).not.toContain("\n");
    });

    it("should clean HTML from preview", () => {
      const html = "<p>Hello <strong>World</strong></p>";
      const result = getEmailPreview(html);
      expect(result).toBe("Hello World");
    });

    it("should handle empty input", () => {
      const result = getEmailPreview("");
      expect(result).toBe("");
    });

    it("should handle null input", () => {
      const result = getEmailPreview(null);
      expect(result).toBe("");
    });
  });

  describe("Edge Cases", () => {
    it("should handle very long HTML content", () => {
      const html = `<div>${"A".repeat(10000)}</div>`;
      const result = cleanEmailContent(html, undefined, 1000);
      expect(result.length).toBeLessThanOrEqual(1003);
    });

    it("should handle content with only HTML tags", () => {
      const html = "<p></p><div></div><span></span>";
      const result = cleanEmailContent(html);
      expect(result.trim()).toBe("");
    });

    it("should handle content with only signatures", () => {
      const text = "--\nJohn Doe";
      const result = cleanEmailContent(text);
      // Should not be empty if content is too short (< 50 chars before signature)
      expect(result).toBeTruthy();
    });

    it("should handle multiple signature markers", () => {
      const text = `${"A".repeat(100)}\n\nBest regards,\n--\nJohn Doe`;
      const result = cleanEmailContent(text);
      // Should remove from first signature marker
      expect(result).not.toContain("Best regards");
    });

    it("should handle nested HTML tags", () => {
      const html = "<div><p><span>Nested content</span></p></div>";
      const result = cleanEmailContent(html);
      expect(result).toContain("Nested content");
    });

    it("should handle malformed HTML", () => {
      const html = "<p>Hello</div><span>World";
      const result = cleanEmailContent(html);
      expect(result).toContain("Hello");
      expect(result).toContain("World");
    });

    it("should handle content with only whitespace", () => {
      const text = "   \n\n   \t  ";
      const result = cleanEmailContent(text);
      expect(result).toBe("");
    });

    it("should handle unicode characters", () => {
      const text = "Hello 世界 🌍";
      const result = cleanEmailContent(text);
      expect(result).toBe("Hello 世界 🌍");
    });

    it("should handle mixed content with HTML, signatures, and quoted replies", () => {
      const longPrefix = "A".repeat(60);
      const text = `<p>${longPrefix} Hello World</p>\n\n--\nJohn\n\nOn Jan 1 wrote:\n> Previous`;
      const result = cleanEmailContent(text);
      expect(result).toContain("Hello World");
      // Signature removal requires >50 chars before it
      expect(result).not.toContain("On Jan 1 wrote");
    });
  });
});

/**
 * Utility to clean email content before LLM analysis.
 *
 * - Strips HTML tags (prefers plain text)
 * - Removes email signatures
 * - Truncates quoted replies
 * - Limits character count to avoid token waste
 */

import { CONTENT_CLEANER } from "../constants/llm-constants";

// Common signature markers
const SIGNATURE_PATTERNS = [
  // Standard "--"
  /^--\s*$/m,
  // "___" line
  /^_{3,}$/m,
  // "---" line
  /^-{3,}$/m,
  /^sent from my (iphone|ipad|android|mobile)/im,
  /^get outlook for/im,
  /^best regards?,?$/im,
  /^kind regards?,?$/im,
  /^regards?,?$/im,
  /^thanks?,?$/im,
  /^thank you,?$/im,
  /^cheers,?$/im,
  /^sincerely,?$/im,
  /^yours truly,?$/im,
  /^warm regards?,?$/im,
  /^best,?$/im,
  /^all the best,?$/im,
];

// HTML tag patterns
const HTML_PATTERNS = {
  style: /<style[^>]*>[\s\S]*?<\/style>/gi,
  script: /<script[^>]*>[\s\S]*?<\/script>/gi,
  tags: /<[^>]+>/g,
  entities: /&(nbsp|amp|lt|gt|quot|#\d+);/gi,
};

/**
 * Clean email content for LLM analysis
 * @param body Email body (plain text or HTML)
 * @param htmlBody Optional HTML body (will use this to extract text if body is empty)
 * @param maxLength Maximum characters to return (default 1000)
 */
export function cleanEmailContent(
  body: string | null | undefined,
  htmlBody?: string | null,
  maxLength: number = 1000,
): string {
  let content = "";

  if (htmlBody && htmlBody.trim()) {
    content = stripHtml(htmlBody);
  }

  if (!content.trim()) {
    content = body?.trim() || "";
  }

  if (
    content.startsWith("<") ||
    content.includes("<html") ||
    content.includes("<body")
  ) {
    content = stripHtml(content);
  }

  if (content.includes("<") && content.includes(">")) {
    content = stripHtml(content);
  }

  // Remove quoted replies (earlier messages in thread)
  content = removeQuotedReplies(content);

  // Remove email signatures
  content = removeSignature(content);

  // Clean up whitespace
  content = normalizeWhitespace(content);

  // Truncate to max length, trying to end at a sentence
  content = smartTruncate(content, maxLength);

  return content;
}

/**
 * Strip HTML tags and decode entities
 */
function stripHtml(html: string): string {
  if (!html) return "";

  let text = html;

  // Remove style and script blocks completely
  text = text.replace(HTML_PATTERNS.style, "");
  text = text.replace(HTML_PATTERNS.script, "");

  // Convert common block elements to newlines
  text = text.replace(/<\/(p|div|br|li|tr|h[1-6])>/gi, "\n");
  text = text.replace(/<(br|hr)\s*\/?>/gi, "\n");

  // Remove all remaining HTML tags
  text = text.replace(HTML_PATTERNS.tags, "");

  // Decode HTML entities
  text = text.replace(/&nbsp;/gi, " ");
  text = text.replace(/&amp;/gi, "&");
  text = text.replace(/&lt;/gi, "<");
  text = text.replace(/&gt;/gi, ">");
  text = text.replace(/&quot;/gi, '"');
  text = text.replace(/&#(\d+);/gi, (_, code) =>
    String.fromCharCode(parseInt(code, 10)),
  );

  return text;
}

/**
 * Remove quoted reply content - detect reply separators and only keep the last reply
 */
function removeQuotedReplies(text: string): string {
  let result = text;

  // Gmail-style "On [date], [person] <email> wrote:" or "On [date] [person] wrote:"
  // Match various formats: "On Jan 1, 2024, John wrote:", "On 1/1/24, John <john@example.com> wrote:"
  const onWroteMatch = result.match(/^On .+wrote:\s*$/im);
  if (onWroteMatch) {
    const index = result.indexOf(onWroteMatch[0]);
    if (index > 100) {
      // Only remove if there's meaningful content before
      result = result.substring(0, index).trim();
    }
  }

  // Gmail forwarded message separator
  const gmailForwardMatch = result.match(/-{5,}\s*Forwarded message\s*-{5,}/i);
  if (gmailForwardMatch) {
    const index = result.indexOf(gmailForwardMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Apple Mail "Begin forwarded message:" separator
  const appleForwardMatch = result.match(/^Begin forwarded message:\s*$/im);
  if (appleForwardMatch) {
    const index = result.indexOf(appleForwardMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Remove lines starting with > (quoted text)
  result = result.replace(/^>+\s*.*$/gm, "");

  // Remove Outlook-style "Original Message" blocks
  const originalMsgMatch = result.match(/-{5,}Original Message-{5,}/i);
  if (originalMsgMatch) {
    const index = result.indexOf(originalMsgMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Remove "From: ... Sent: ... To: ... Subject:" blocks (Outlook forwarded headers)
  const outlookHeaderMatch = result.match(
    /From:.+\nSent:.+\nTo:.+\nSubject:/im,
  );
  if (outlookHeaderMatch) {
    const index = result.indexOf(outlookHeaderMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Remove "On [date] at [time], [person] wrote:" (alternative Gmail format)
  const onAtWroteMatch = result.match(/^On .+ at .+, .+ wrote:\s*$/im);
  if (onAtWroteMatch) {
    const index = result.indexOf(onAtWroteMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Remove "[date] [time] [person] <email>:" format (some email clients)
  const dateTimeEmailMatch = result.match(
    /^\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}\s+\d{1,2}:\d{2}\s*(AM|PM)?\s*.+<.+@.+>:\s*$/im,
  );
  if (dateTimeEmailMatch) {
    const index = result.indexOf(dateTimeEmailMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  // Remove "---- Reply above this line ----" or similar markers
  const replyLineMatch = result.match(
    /-{3,}\s*(Reply|Write|Respond)\s+(above|below)\s+this\s+line\s*-{3,}/i,
  );
  if (replyLineMatch) {
    const index = result.indexOf(replyLineMatch[0]);
    if (index > 100) {
      result = result.substring(0, index).trim();
    }
  }

  return result;
}

/**
 * Remove email signature
 */
function removeSignature(text: string): string {
  let result = text;
  let cutoffIndex = result.length;

  // Find signature markers and cut off at the earliest one
  for (const pattern of SIGNATURE_PATTERNS) {
    const match = result.match(pattern);
    if (match) {
      const index = result.search(pattern);
      // Only cut if there's meaningful content before (at least MIN_CONTENT_BEFORE_SIGNATURE chars)
      // and the signature isn't at the very beginning
      if (
        index > CONTENT_CLEANER.MIN_CONTENT_BEFORE_SIGNATURE &&
        index < cutoffIndex
      ) {
        cutoffIndex = index;
      }
    }
  }

  if (cutoffIndex < result.length) {
    result = result.substring(0, cutoffIndex).trim();
  }

  return result;
}

/**
 * Normalize whitespace
 */
function normalizeWhitespace(text: string): string {
  return (
    text
      // Normalize line endings
      .replace(/\r\n/g, "\n")
      // Max 2 consecutive newlines
      .replace(/\n{3,}/g, "\n\n")
      // Multiple spaces/tabs to single space
      .replace(/[ \t]+/g, " ")
      // Trim each line
      .replace(/^\s+|\s+$/gm, "")
      .trim()
  );
}

/**
 * Smart truncate - try to end at a sentence boundary
 */
function smartTruncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) {
    return text;
  }

  // Try to find a sentence end within the last 200 chars of the limit
  const searchStart = Math.max(0, maxLength - 200);
  const searchEnd = maxLength;
  const searchRegion = text.substring(searchStart, searchEnd);

  // Look for sentence endings (., !, ?)
  const sentenceEndMatch = searchRegion.match(/[.!?]\s+[A-Z]/);
  if (sentenceEndMatch) {
    // Include the punctuation
    const endIndex = searchStart + sentenceEndMatch.index! + 1;
    return text.substring(0, endIndex).trim();
  }

  // Fallback: try to end at a word boundary
  const truncated = text.substring(0, maxLength);
  const lastSpace = truncated.lastIndexOf(" ");
  if (lastSpace > maxLength - CONTENT_CLEANER.WORD_BOUNDARY_THRESHOLD) {
    return `${truncated.substring(0, lastSpace).trim()}...`;
  }

  return `${truncated.trim()}...`;
}

/**
 * Clean email content for thread summarization (multiple messages)
 * Uses a smaller limit per message
 */
export function cleanEmailForThread(
  body: string | null | undefined,
  htmlBody?: string | null,
  maxLengthPerMessage: number = 500,
): string {
  return cleanEmailContent(body, htmlBody, maxLengthPerMessage);
}

/**
 * Get a very short preview of email content (for snippets)
 */
export function getEmailPreview(
  body: string | null | undefined,
  htmlBody?: string | null,
  maxLength: number = 150,
): string {
  const cleaned = cleanEmailContent(
    body,
    htmlBody,
    maxLength + CONTENT_CLEANER.PREVIEW_BUFFER,
  );
  // For previews, also remove newlines
  return cleaned.replace(/\n+/g, " ").substring(0, maxLength).trim();
}

import { Injectable, Logger, Inject, forwardRef } from "@nestjs/common";
import { ConfigService } from "@nestjs/config";
import { GoogleGenerativeAI } from "@google/generative-ai";
import OpenAI from "openai";
import { UsersService } from "../users/users.service";
import { LLMProvider, LLMRequest } from "./llm.types";
import { TokenUsageService } from "./token-usage.service";
import { LLM_OP_UNKNOWN } from "./llm-operations";
import { RATIOS } from "../constants/percentages";
import { QUERY_LIMITS } from "../constants/query-limits";
import { MILLISECONDS } from "../constants/time-constants";

@Injectable()
export class LLMCoreService {
  private readonly logger = new Logger(LLMCoreService.name);
  private geminiClient: GoogleGenerativeAI | null = null;
  private openaiClient: OpenAI | null = null;
  private defaultProvider: LLMProvider;

  constructor(
    private configService: ConfigService,
    @Inject(forwardRef(() => UsersService))
    private usersService: UsersService,
    private tokenUsageService: TokenUsageService,
  ) {
    this.initializeClients();
    this.defaultProvider = (
      this.configService.get<string>("LLM_PROVIDER") || "openai"
    ).toLowerCase() as LLMProvider;
  }

  private initializeClients() {
    // Initialize Gemini
    const geminiApiKey = this.configService.get<string>("GEMINI_API_KEY");
    if (geminiApiKey) {
      try {
        this.geminiClient = new GoogleGenerativeAI(geminiApiKey);
        this.logger.log("Gemini client initialized");
      } catch (error) {
        this.logger.error("Failed to initialize Gemini client", error);
      }
    } else {
      this.logger.warn("GEMINI_API_KEY not found, Gemini will be unavailable");
    }

    // Initialize OpenAI
    const openaiApiKey = this.configService.get<string>("OPENAI_API_KEY");
    if (openaiApiKey) {
      try {
        this.openaiClient = new OpenAI({ apiKey: openaiApiKey });
        this.logger.log("OpenAI client initialized");
      } catch (error) {
        this.logger.error("Failed to initialize OpenAI client", error);
      }
    } else {
      this.logger.warn("OPENAI_API_KEY not found, OpenAI will be unavailable");
    }
  }

  async generateText(
    request: LLMRequest,
    provider?: LLMProvider,
    userId?: string,
  ): Promise<string> {
    const selectedProvider = provider || this.defaultProvider;
    const effectiveUserId = userId || request.userId;

    try {
      switch (selectedProvider) {
        case LLMProvider.GEMINI:
          return await this.generateWithGemini(request, effectiveUserId);
        case LLMProvider.OPENAI:
          return await this.generateWithOpenAI(request, effectiveUserId);
        default:
          throw new Error(`Unsupported LLM provider: ${selectedProvider}`);
      }
    } catch (error) {
      this.logger.error(
        `Error generating text with ${selectedProvider}`,
        error,
      );
      // Fallback to the other provider if available
      if (selectedProvider === LLMProvider.GEMINI) {
        this.logger.log(
          `Gemini failed, falling back to OpenAI (default provider)`,
        );
        return await this.generateWithOpenAI(request, effectiveUserId);
      } else if (selectedProvider === LLMProvider.OPENAI) {
        this.logger.log(`OpenAI failed, falling back to Gemini`);
        return await this.generateWithGemini(request, effectiveUserId);
      }
      throw error;
    }
  }

  private async retryOperation<T>(
    operation: () => Promise<T>,
    maxRetries: number = 3,
  ): Promise<T> {
    for (let i = 0; i < maxRetries; i++) {
      try {
        return await operation();
      } catch (error) {
        if (i === maxRetries - 1) throw error;
        const delay =
          Math.pow(2, i) * MILLISECONDS.SECOND +
          Math.random() * MILLISECONDS.SECOND;
        this.logger.warn(
          `LLM operation failed, retrying in ${Math.round(delay)}ms... (Attempt ${i + 1}/${maxRetries})`,
        );
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
    throw new Error("Max retries exceeded");
  }

  private async generateWithGemini(
    request: LLMRequest,
    userId?: string,
  ): Promise<string> {
    // Note: Gemini doesn't support user-specific API keys, always uses system key
    if (!this.geminiClient) {
      throw new Error("Gemini client not initialized");
    }

    const modelName =
      this.configService.get<string>("GEMINI_MODEL") || "gemini-1.5-flash";
    this.logger.log(`Generating text using Gemini model: ${modelName}`);

    return this.retryOperation(async () => {
      const startTime = Date.now();
      const model = this.geminiClient!.getGenerativeModel({
        model: modelName,
      });

      const fullPrompt = request.systemPrompt
        ? `${request.systemPrompt}\n\n${request.prompt}`
        : request.prompt;

      const result = await model.generateContent({
        contents: [{ role: "user", parts: [{ text: fullPrompt }] }],
        generationConfig: {
          temperature: request.temperature || RATIOS.SEVENTY_PERCENT,
          maxOutputTokens: request.maxTokens || QUERY_LIMITS.LLM_CONTEXT_WINDOW,
        },
      });

      const durationMs = Date.now() - startTime;
      const { response } = result;

      // Log token usage from Gemini response
      // Cast to any to access usageMetadata which may not be in type definitions
      const { usageMetadata } = response as any;
      if (usageMetadata) {
        await this.tokenUsageService.logUsage({
          userId: userId || null,
          operation: request.operation || LLM_OP_UNKNOWN,
          provider: LLMProvider.GEMINI,
          model: modelName,
          promptTokens: usageMetadata.promptTokenCount || 0,
          completionTokens: usageMetadata.candidatesTokenCount || 0,
          totalTokens: usageMetadata.totalTokenCount || 0,
          durationMs,
          // Pass prompt text for example capture
          promptText: request.prompt,
          systemPromptText: request.systemPrompt,
        });
      }

      return response.text();
    });
  }

  private async generateWithOpenAI(
    request: LLMRequest,
    userId?: string,
  ): Promise<string> {
    // Try to get user's API key if userId is provided
    let { openaiClient } = this;
    let apiKeySource = "system";

    if (userId) {
      try {
        const user = await this.usersService.findOneWithApiKey(userId);
        if (user?.openAiApiKey) {
          // User has their own API key - create a client with it
          openaiClient = new OpenAI({ apiKey: user.openAiApiKey });
          apiKeySource = "user";
          this.logger.debug(`Using user's OpenAI API key for user ${userId}`);
        }
      } catch (error) {
        this.logger.warn(
          `Failed to fetch user's API key for ${userId}, using system key`,
          error,
        );
      }
    }

    if (!openaiClient) {
      throw new Error("OpenAI client not initialized");
    }

    const model =
      this.configService.get<string>("OPENAI_MODEL") || "gpt-5-mini";
    const reasoningEffort =
      this.configService.get<string>("OPENAI_REASONING_EFFORT") || "low";

    return this.retryOperation(async () => {
      const startTime = Date.now();
      const messages: Array<{
        role: "system" | "user" | "assistant";
        content: string;
      }> = [];
      if (request.systemPrompt) {
        messages.push({ role: "system", content: request.systemPrompt });
      }
      messages.push({ role: "user", content: request.prompt });

      this.logger.debug(
        `Generating text with OpenAI using ${apiKeySource} API key${request.userId ? ` (userId: ${request.userId})` : ""}`,
      );
      const completion = await openaiClient!.chat.completions.create({
        model,
        messages: messages as any,
        temperature: request.temperature || RATIOS.SEVENTY_PERCENT,
        max_completion_tokens:
          request.maxTokens || QUERY_LIMITS.LLM_CONTEXT_WINDOW,
        reasoning_effort: reasoningEffort as "low" | "medium" | "high",
      } as any);

      const durationMs = Date.now() - startTime;

      // Log token usage from OpenAI response
      if (completion.usage) {
        await this.tokenUsageService.logUsage({
          userId: userId || null,
          operation: request.operation || LLM_OP_UNKNOWN,
          provider: LLMProvider.OPENAI,
          model,
          promptTokens: completion.usage.prompt_tokens || 0,
          completionTokens: completion.usage.completion_tokens || 0,
          totalTokens: completion.usage.total_tokens || 0,
          durationMs,
          // Pass prompt text for example capture
          promptText: request.prompt,
          systemPromptText: request.systemPrompt,
        });
      }

      return completion.choices[0]?.message?.content || "";
    });
  }

  getAvailableProviders(): LLMProvider[] {
    const providers: LLMProvider[] = [];
    if (this.geminiClient) providers.push(LLMProvider.GEMINI);
    if (this.openaiClient) providers.push(LLMProvider.OPENAI);
    return providers;
  }

  getDefaultProvider(): LLMProvider {
    return this.defaultProvider;
  }
}

import { Test, TestingModule } from "@nestjs/testing";
import { INestApplication } from "@nestjs/common";
import request from "supertest";
import { LLMController } from "./llm.controller";
import { LLMService } from "./llm.service";
import { UsersService } from "../users/users.service";
import { JwtAuthGuard } from "../auth/jwt-auth.guard";

describe("LLMController (Integration)", () => {
  let app: INestApplication;

  const mockUser = {
    id: "test-user-id",
    email: "test@example.com",
    name: "Test User",
    displayName: "Test User",
    jobTitle: "Engineer",
    toneSettings: {
      rules: ["Be professional", "Keep it concise"],
    },
    openAiApiKey: null,
  };

  const mockLLMService = {
    getAvailableProviders: jest.fn().mockReturnValue(["openai", "gemini"]),
    getDefaultProvider: jest.fn().mockReturnValue("openai"),
    checkTone: jest.fn().mockResolvedValue({
      isOk: true,
      suggestions: [],
      revisedText: undefined,
    }),
    extractActionItems: jest.fn().mockResolvedValue([
      {
        action: "Review the document",
        assignedTo: "You",
        deadline: "2026-02-15",
      },
    ]),
    generateReplyOptions: jest.fn().mockResolvedValue([
      {
        text: "Thanks for your email. I'll review this.",
        tone: "professional",
      },
      {
        text: "Thank you! I'll take a look at this soon.",
        tone: "friendly",
      },
    ]),
    disputeToneCheck: jest.fn().mockResolvedValue({
      accepted: false,
      explanation: "The suggestion is valid",
      rulesToRemove: [],
    }),
    usersService: {
      findOne: jest.fn().mockResolvedValue(mockUser),
    },
  };

  const mockUsersService = {
    findOne: jest.fn().mockResolvedValue(mockUser),
    update: jest.fn().mockResolvedValue({ ...mockUser }),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [LLMController],
      providers: [
        { provide: LLMService, useValue: mockLLMService },
        { provide: UsersService, useValue: mockUsersService },
      ],
    })
      .overrideGuard(JwtAuthGuard)
      .useValue({
        canActivate: jest.fn((context) => {
          const request = context.switchToHttp().getRequest();
          request.user = { userId: "test-user-id" };
          return true;
        }),
      })
      .compile();

    app = module.createNestApplication();
    await app.init();
  });

  afterEach(async () => {
    await app.close();
  });

  describe("GET /llm/providers", () => {
    it("should return available LLM providers", async () => {
      const response = await request(app.getHttpServer())
        .get("/llm/providers")
        .expect(200);

      expect(response.body).toHaveProperty("available");
      expect(response.body).toHaveProperty("default");
      expect(Array.isArray(response.body.available)).toBe(true);
      expect(response.body.available).toContain("openai");
    });
  });

  describe("POST /llm/check-tone", () => {
    it("should check tone of text with user rules", async () => {
      const response = await request(app.getHttpServer())
        .post("/llm/check-tone")
        .send({
          text: "Hey! What's up?",
          rules: ["Be professional", "Avoid slang"],
        })
        .expect(201);

      expect(response.body).toHaveProperty("isOk");
      expect(response.body).toHaveProperty("suggestions");
      expect(mockLLMService.checkTone).toHaveBeenCalledWith(
        "Hey! What's up?",
        ["Be professional", "Avoid slang"],
        undefined,
        "test-user-id",
      );
    });

    it("should use user tone settings when rules not provided", async () => {
      const response = await request(app.getHttpServer())
        .post("/llm/check-tone")
        .send({
          text: "Test email",
        })
        .expect(201);

      expect(response.body).toHaveProperty("isOk");
      expect(mockUsersService.findOne).toHaveBeenCalledWith("test-user-id");
      expect(mockLLMService.checkTone).toHaveBeenCalledWith(
        "Test email",
        ["Be professional", "Keep it concise"],
        undefined,
        "test-user-id",
      );
