  afterEach(() => {
    // Clean up any running intervals to prevent open handles
    if (service && service["monitoringInterval"]) {
      service.onModuleDestroy();
    }
    jest.restoreAllMocks();
  });

  describe("calculateCpuUsage", () => {
    it("should return 0 on first call", () => {
      const usage = (service as any).calculateCpuUsage();

      expect(usage).toBe(0);
    });

    it("should calculate CPU usage correctly on subsequent calls", () => {
      // First call to initialize
      (service as any).calculateCpuUsage();

      // Mock second CPU reading (higher usage)
      mockCpus.mockReturnValue([
        {
          model: "Intel",
          speed: 2400,
          times: {
            // Increased
            user: 2000,
            nice: 0,
            // Increased
            sys: 1000,
            // Less idle
            idle: 4000,
            irq: 0,
          },
        },
        {
          model: "Intel",
          speed: 2400,
          times: {
            // Increased
            user: 3000,
            nice: 0,
            // Increased
            sys: 2000,
            // Less idle
            idle: 8000,
            irq: 0,
          },
        },
      ]);

      // Advance time
      jest.spyOn(Date, "now").mockReturnValue(1000);

      const usage = (service as any).calculateCpuUsage();

      expect(usage).toBeGreaterThan(0);
      expect(usage).toBeLessThanOrEqual(100);
    });

    it("should clamp CPU usage to 0-100 range", () => {
      // First call to initialize
      (service as any).calculateCpuUsage();

      // Mock extreme values
      mockCpus.mockReturnValue([
        {
          model: "Intel",
          speed: 2400,
          times: {
            user: 999999,
            nice: 0,
            sys: 999999,
            idle: 0,
            irq: 0,
          },
        },
      ]);

      jest.spyOn(Date, "now").mockReturnValue(1000);

      const usage = (service as any).calculateCpuUsage();

      expect(usage).toBeGreaterThanOrEqual(0);
      expect(usage).toBeLessThanOrEqual(100);
    });
  });

  describe("getDatabaseMetrics", () => {
    it("should return database connection metrics", async () => {
      dataSource.query.mockResolvedValue([
        {
          active: "5",
          idle: "10",
          total: "15",
        },
      ]);

      const metrics = await (service as any).getDatabaseMetrics();

      expect(dataSource.query).toHaveBeenCalled();
      expect(metrics).toEqual({
        activeConnections: 5,
        idleConnections: 10,
        totalConnections: 15,
      });
    });

    it("should return zero metrics on error", async () => {
      dataSource.query.mockRejectedValue(new Error("Database error"));

      const loggerWarnSpy = jest
        .spyOn(service["logger"], "warn")
        .mockImplementation();

      const metrics = await (service as any).getDatabaseMetrics();

      expect(metrics).toEqual({
        activeConnections: 0,
        idleConnections: 0,
        totalConnections: 0,
      });

      loggerWarnSpy.mockRestore();
    });

    it("should handle missing result data", async () => {
      dataSource.query.mockResolvedValue([]);

      const metrics = await (service as any).getDatabaseMetrics();

      expect(metrics).toEqual({
        activeConnections: 0,
        idleConnections: 0,
        totalConnections: 0,
      });
    });

    it("should handle null/undefined values in result", async () => {
      dataSource.query.mockResolvedValue([
        {
          active: null,
          idle: undefined,
          total: "",
