  describe("collectMetrics", () => {
    it("should collect and log resource metrics", async () => {
      dataSource.query.mockResolvedValue([
        {
          active: "5",
          idle: "10",
          total: "15",
        },
      ]);

      // Initialize CPU usage calculation
      (service as any).calculateCpuUsage();

      await service.collectMetrics();

      expect(fs.appendFileSync).toHaveBeenCalled();
      const logCall = (fs.appendFileSync as jest.Mock).mock.calls[0];
      const loggedData = JSON.parse(logCall[1].trim());

      expect(loggedData).toHaveProperty("timestamp");
      expect(loggedData).toHaveProperty("cpu");
      expect(loggedData).toHaveProperty("memory");
      expect(loggedData).toHaveProperty("database");
      expect(loggedData.cpu).toHaveProperty("usage");
      expect(loggedData.cpu).toHaveProperty("loadAverage");
      expect(loggedData.memory).toHaveProperty("total");
      expect(loggedData.memory).toHaveProperty("free");
      expect(loggedData.memory).toHaveProperty("used");
      expect(loggedData.memory).toHaveProperty("usagePercent");
    });

    it("should log warning for high CPU usage", async () => {
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);

      // Initialize CPU usage
      (service as any).calculateCpuUsage();

      // Mock high CPU usage
      jest
        .spyOn(service as any, "calculateCpuUsage")
        .mockReturnValue(RESOURCE_MONITOR_CONSTANTS.CPU_CRITICAL + 10);

      const loggerWarnSpy = jest
        .spyOn(service["logger"], "warn")
        .mockImplementation();

      await service.collectMetrics();

      expect(loggerWarnSpy).toHaveBeenCalledWith(
        expect.stringContaining("High CPU usage"),
      );

      loggerWarnSpy.mockRestore();
    });

    it("should log warning for high memory usage", async () => {
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);

      // Mock high memory usage (90% used)
      // 100MB
      mockTotalmem.mockReturnValue(100 * 1024 * 1024);
      // 10MB (90% used)
      mockFreemem.mockReturnValue(10 * 1024 * 1024);

      (service as any).calculateCpuUsage();

      const loggerWarnSpy = jest
        .spyOn(service["logger"], "warn")
        .mockImplementation();

      await service.collectMetrics();

      expect(loggerWarnSpy).toHaveBeenCalledWith(
        expect.stringContaining("High memory usage"),
      );

      loggerWarnSpy.mockRestore();
    });

    it("should log warning for high database connections", async () => {
      dataSource.query.mockResolvedValue([
        {
          active: "50",
          idle: "50",
          total: String(RESOURCE_MONITOR_CONSTANTS.CPU_CRITICAL + 10),
        },
      ]);

      (service as any).calculateCpuUsage();

      const loggerWarnSpy = jest
        .spyOn(service["logger"], "warn")
        .mockImplementation();

      await service.collectMetrics();

      expect(loggerWarnSpy).toHaveBeenCalledWith(
        expect.stringContaining("High database connections"),
      );

      loggerWarnSpy.mockRestore();
    });

    it("should handle file write errors gracefully", async () => {
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);
      (fs.appendFileSync as jest.Mock).mockImplementation(() => {
        throw new Error("File write error");
      });

      (service as any).calculateCpuUsage();

      const loggerErrorSpy = jest
        .spyOn(service["logger"], "error")
        .mockImplementation();

      await service.collectMetrics();

      expect(loggerErrorSpy).toHaveBeenCalledWith(
        "Failed to write resource metrics to file:",
        expect.any(Error),
      );

      loggerErrorSpy.mockRestore();
    });

    it("should handle collection errors gracefully", async () => {
      mockTotalmem.mockImplementation(() => {
        throw new Error("OS error");
      });

      const loggerErrorSpy = jest
        .spyOn(service["logger"], "error")
        .mockImplementation();

      await service.collectMetrics();

      expect(loggerErrorSpy).toHaveBeenCalledWith(
        "Error collecting resource metrics:",
        expect.any(Error),
      );

      loggerErrorSpy.mockRestore();
    });
  });

  describe("getCurrentMetrics", () => {
    it("should return current resource metrics", async () => {
      dataSource.query.mockResolvedValue([
        {
          active: "5",
          idle: "10",
          total: "15",
        },
      ]);

      (service as any).calculateCpuUsage();

      const metrics = await service.getCurrentMetrics();

      expect(metrics).toHaveProperty("timestamp");
      expect(metrics).toHaveProperty("cpu");
      expect(metrics).toHaveProperty("memory");
      expect(metrics).toHaveProperty("database");
      expect(metrics.cpu.usage).toBeGreaterThanOrEqual(0);
      expect(metrics.cpu.usage).toBeLessThanOrEqual(100);
      expect(metrics.memory.usagePercent).toBeGreaterThanOrEqual(0);
      expect(metrics.memory.usagePercent).toBeLessThanOrEqual(100);
    });

    it("should calculate memory usage correctly", async () => {
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);

      // 8GB total, 4GB free = 4GB used = 50% usage
      mockTotalmem.mockReturnValue(8 * 1024 * 1024 * 1024);
      mockFreemem.mockReturnValue(4 * 1024 * 1024 * 1024);

      (service as any).calculateCpuUsage();

      const metrics = await service.getCurrentMetrics();

      expect(metrics.memory.usagePercent).toBeCloseTo(50, 0);
      expect(metrics.memory.used).toBe(4 * 1024 * 1024 * 1024);
    });
  });

  describe("onModuleInit", () => {
    it("should start monitoring interval", async () => {
      jest.useFakeTimers();
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);

      (service as any).calculateCpuUsage();

      await service.onModuleInit();

      // Fast-forward time to trigger interval
      jest.advanceTimersByTime(61000); // 61 seconds

      // Should have called collectMetrics multiple times
      expect(fs.appendFileSync).toHaveBeenCalled();

      // Clean up interval before restoring timers
      service.onModuleDestroy();
      jest.useRealTimers();
    });

    it("should collect initial metrics on init", async () => {
      dataSource.query.mockResolvedValue([
        { active: "0", idle: "0", total: "0" },
      ]);

      (service as any).calculateCpuUsage();

      await service.onModuleInit();

      expect(fs.appendFileSync).toHaveBeenCalled();

      // Clean up interval
      service.onModuleDestroy();
    });
  });

  describe("onModuleDestroy", () => {
    it("should clear monitoring interval", () => {
      jest.useFakeTimers();
      const clearIntervalSpy = jest.spyOn(global, "clearInterval");

      service["monitoringInterval"] = setInterval(() => {}, 1000);
      service.onModuleDestroy();

      expect(clearIntervalSpy).toHaveBeenCalled();
      expect(service["monitoringInterval"]).toBeNull();

      jest.useRealTimers();
      clearIntervalSpy.mockRestore();
    });

    it("should handle destroy when no interval set", () => {
      service["monitoringInterval"] = null;

      expect(() => service.onModuleDestroy()).not.toThrow();
    });
  });
});

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Param,
  Body,
  UseGuards,
  Request,
  UseInterceptors,
  UploadedFiles,
} from "@nestjs/common";
import { FilesInterceptor } from "@nestjs/platform-express";
import { RepliesService, ReplyRule } from "./replies.service";
import { JwtAuthGuard } from "../auth/jwt-auth.guard";

@Controller("replies")
@UseGuards(JwtAuthGuard)
export class RepliesController {
  constructor(private readonly repliesService: RepliesService) {}

  @Post("draft/:id")
  async generateDraft(
    @Request() req,
    @Param("id") id: string,
    @Body() body?: { provider?: "gemini" | "openai" },
  ) {
    return {
      draft: await this.repliesService.generateDraftReply(
        req.user.userId,
        id,
        body?.provider,
      ),
    };
  }

  @Post("learn")
  async learnFromModification(
    @Request() req,
    @Body()
    body: { emailId: string; originalDraft: string; modifiedDraft: string },
  ) {
    return this.repliesService.learnFromModification(
      req.user.userId,
      body.emailId,
      body.originalDraft,
      body.modifiedDraft,
    );
  }

  @Get("rules")
  async getRules(@Request() req) {
    return this.repliesService.getReplyRules(req.user.userId);
  }

  @Post("rules")
  async createRule(@Request() req, @Body() rule: ReplyRule) {
    return this.repliesService.createReplyRule(req.user.userId, rule);
  }

  @Put("rules/:id")
  async updateRule(
    @Request() req,
    @Param("id") id: string,
    @Body() updates: Partial<ReplyRule>,
  ) {
    return this.repliesService.updateReplyRule(req.user.userId, id, updates);
  }

  @Delete("rules/:id")
  async deleteRule(@Request() req, @Param("id") id: string) {
    await this.repliesService.deleteReplyRule(req.user.userId, id);
    return { message: "Rule deleted" };
  }

  @Post("send/:id")
  @UseInterceptors(FilesInterceptor("files", 10))
  async sendReply(
    @Request() req,
    @Param("id") id: string,
    @Body()
    body: {
      reply: string;
      expectedReplyHours?: number | string;
      forwardAttachmentIds?: string | string[];
    },
    @UploadedFiles() files?: Express.Multer.File[],
  ) {
    const attachments =
      files?.map((file) => ({
        filename: file.originalname,
        mimeType: file.mimetype,
        content: file.buffer,
      })) || undefined;

    // Parse forwardAttachmentIds - it may come as JSON string from FormData
    let forwardAttachmentIds: string[] | undefined;
    if (body.forwardAttachmentIds) {
      if (typeof body.forwardAttachmentIds === "string") {
        try {
          forwardAttachmentIds = JSON.parse(body.forwardAttachmentIds);
        } catch {
          forwardAttachmentIds = [body.forwardAttachmentIds];
        }
      } else {
        forwardAttachmentIds = body.forwardAttachmentIds;
      }
    }

    // Parse expectedReplyHours - it may come as string from FormData
    const expectedReplyHours =
      typeof body.expectedReplyHours === "string"
        ? parseInt(body.expectedReplyHours, 10)
        : body.expectedReplyHours;

    await this.repliesService.sendReply(
      req.user.userId,
      id,
      body.reply,
      attachments,
      isNaN(expectedReplyHours as number) ? undefined : expectedReplyHours,
      forwardAttachmentIds,
    );
    return { message: "Reply sent successfully" };
  }
}

