import { Injectable, Inject, forwardRef, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { EmailsService } from "../emails/emails.service";
import { EmailProviderManager } from "../emails/email-provider-manager.service";
import { EmailThreadService } from "../emails/email-thread.service";
import { ContextService } from "../context/context.service";
import { LLMService, LLMProvider } from "../llm/llm.service";
import { UsersService } from "../users/users.service";
import { WritingStyleLearningService } from "../context/writing-style-learning.service";
import { ContextKey } from "../database/entities/user-context.entity";
import { Email } from "../database/entities/email.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { SnoozeService } from "../snooze/snooze.service";
import { FollowUpsService } from "../follow-ups/follow-ups.service";
import { EncryptionHelper } from "../encryption/encryption.helper";
import { STAR_COUNTS } from "../constants/priority-constants";

export interface ReplyRule {
  ruleId?: string;
  // e.g., "subject contains 'meeting'"
  trigger: string;
  // Reply template
  template: string;
  priority: number;
}

@Injectable()
export class RepliesService {
  private readonly logger = new Logger(RepliesService.name);
  private replyRules: Map<string, ReplyRule[]> = new Map();

  constructor(
    private emailsService: EmailsService,
    private emailProviderManager: EmailProviderManager,
    private emailThreadService: EmailThreadService,
    private contextService: ContextService,
    private llmService: LLMService,
    private usersService: UsersService,
    private writingStyleLearningService: WritingStyleLearningService,
    private snoozeService: SnoozeService,
    @Inject(forwardRef(() => FollowUpsService))
    private followUpsService: FollowUpsService,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
  ) {}

  async generateDraftReply(
    userId: string,
    emailId: string,
    provider?: "gemini" | "openai",
  ): Promise<string> {
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Get user context from UserContext entities
    const contexts = await this.contextService.getUserContext(userId);
    const tone =
      contexts.find((c) => c.contextKey === ContextKey.WRITING_STYLE_TONE)
        ?.contextValue || "professional";
    const commonPhrases = contexts
      .filter((c) => c.contextKey === ContextKey.COMMON_PHRASE)
      .map((c) => c.contextValue);
    const writingStyle = contexts.find(
      (c) => c.contextKey === ContextKey.WRITING_STYLE_TONE,
    )?.contextValue;

    // Get writing style examples from user.toneSettings.rules
    const user = await this.usersService.findOne(userId);
    const toneRules = user?.toneSettings?.rules || [];
    // Filter to get email examples (entries that don't start with "Tone:", "Style:", or "Common phrase:")
    const emailExamples = toneRules.filter(
      (rule: string) =>
        !rule.startsWith("Tone:") &&
        !rule.startsWith("Style:") &&
        !rule.startsWith("Common phrase:"),
    );

    // Log for debugging
    if (emailExamples.length > 0) {
      this.logger.debug(
        `Using ${emailExamples.length} email examples for reply generation`,
      );
    } else {
      this.logger.debug(
        `No email examples found in toneSettings.rules (total rules: ${toneRules.length})`,
      );
    }

    // Check for matching reply rules first
    const rules = this.replyRules.get(userId) || [];
    const matchingRule = rules.find((rule) =>
      this.matchesTrigger(email, rule.trigger),
    );

    if (matchingRule) {
      // Use rule template but enhance with LLM if needed
      const baseReply = this.applyTemplate(
        matchingRule.template,
        email,
        tone,
        commonPhrases,
      );
      // Could optionally refine with LLM here
      return baseReply;
    }

    // Use LLM to generate reply
    try {
      // Convert string provider to LLMProvider enum
      const llmProvider: LLMProvider | undefined = provider
        ? provider === "gemini"
          ? LLMProvider.GEMINI
          : LLMProvider.OPENAI
        : undefined;

      return await this.llmService.generateReplyDraft(
        {
          from: email.from,
          fromName: email.fromName,
          subject: email.subject,
          body: email.body,
        },
        {
          tone,
          commonPhrases,
          writingStyle,
          emailExamples,
        },
        llmProvider,
        userId,
      );
    } catch (error) {
      console.error("LLM reply generation failed, using fallback", error);
      // Fallback to default reply
      return this.generateDefaultReply(email, tone, commonPhrases);
    }
  }

  private matchesTrigger(email: Partial<Email>, trigger: string): boolean {
    if (trigger.includes("subject contains")) {
      const keyword = trigger.split("'")[1];
      return (
        email.subject?.toLowerCase().includes(keyword.toLowerCase()) || false
      );
    }
    if (trigger.includes("from contains")) {
      const keyword = trigger.split("'")[1];
      return email.from?.toLowerCase().includes(keyword.toLowerCase()) || false;
    }
    return false;
  }

  private applyTemplate(
    template: string,
    email: Partial<Email>,
    tone: string,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    phrases: string[],
  ): string {
    let reply = template
      .replace("{sender}", email.fromName || email.from || "there")
      .replace("{subject}", email.subject || "");

    // Add greeting based on tone
    let greeting: string;
    if (tone === "casual") {
      greeting = "Hey";
    } else if (tone === "formal") {
      greeting = "Dear";
    } else {
      greeting = "Hi";
    }
    reply = `${greeting} ${email.fromName || "there"},\n\n${reply}`;

    return reply;
  }

  private generateDefaultReply(
    email: Partial<Email>,
    tone: string,
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    phrases: string[],
  ): string {
    let greeting: string;
    if (tone === "casual") {
      greeting = "Hey";
    } else if (tone === "formal") {
      greeting = "Dear";
    } else {
      greeting = "Hi";
    }
    let closing: string;
    if (tone === "casual") {
      closing = "Thanks!";
    } else if (tone === "formal") {
      closing = "Best regards";
    } else {
      closing = "Best";
    }

    return `${greeting} ${email.fromName || "there"},

Thank you for your email regarding "${email.subject || "this matter"}".

I'll review this and get back to you soon.

${closing}`;
  }

  async createReplyRule(userId: string, rule: ReplyRule): Promise<ReplyRule> {
    const rules = this.replyRules.get(userId) || [];
    // Simple ID generation
    rule.ruleId = `${Date.now()}-${Math.random()}`;
    rules.push(rule);
    this.replyRules.set(userId, rules);
    return rule;
  }

  async getReplyRules(userId: string): Promise<ReplyRule[]> {
    return this.replyRules.get(userId) || [];
  }

  async updateReplyRule(
    userId: string,
    ruleId: string,
    updates: Partial<ReplyRule>,
  ): Promise<ReplyRule> {
    const rules = this.replyRules.get(userId) || [];
    const index = rules.findIndex((r) => r.ruleId === ruleId);
    if (index !== -1) {
      rules[index] = { ...rules[index], ...updates };
      this.replyRules.set(userId, rules);
      return rules[index];
    }
    throw new Error("Rule not found");
  }

  async deleteReplyRule(userId: string, ruleId: string): Promise<void> {
    const rules = this.replyRules.get(userId) || [];
    const filtered = rules.filter((r) => r.ruleId !== ruleId);
    this.replyRules.set(userId, filtered);
  }

  async learnFromModification(
    userId: string,
    emailId: string,
    originalDraft: string,
    modifiedDraft: string,
  ): Promise<ReplyRule> {
    // Analyze the modification to create a new rule
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Simple rule generation based on email characteristics
    const trigger = `subject contains '${email.subject.split(" ")[0]}'`;
    const rule: ReplyRule = {
      trigger,
      template: modifiedDraft,
      priority: 1,
    };

    return this.createReplyRule(userId, rule);
  }

  async sendReply(
    userId: string,
    emailId: string,
    body: string,
    attachments?: Array<{
      filename: string;
      mimeType: string;
      content: Buffer;
    }>,
    expectedReplyHours?: number,
    forwardAttachmentIds?: string[],
  ): Promise<void> {
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email) {
      throw new Error("Email not found");
    }

    // Get user's email address for the "from" field
    const user = await this.usersService.findOne(userId);
    if (!user) {
      throw new Error("User not found");
    }
    const userEmail = EncryptionHelper.decrypt(user.email);

    // Determine reply subject (add Re: if not already present)
    let replySubject = email.subject;
    if (!replySubject.toLowerCase().startsWith("re:")) {
      replySubject = `Re: ${replySubject}`;
    }

    // Send reply via email provider (Gmail, Outlook, etc.)
    const provider = await this.emailProviderManager.getPrimaryProvider(userId);
    if (!provider) {
      throw new Error(
        "No email provider connected. Please connect your email account.",
      );
    }

    // Use Reply-To address if available, otherwise fall back to From address
    const replyToAddress = email.replyTo || email.from;

    // Fetch forward attachments if requested
    const allAttachments = attachments ? [...attachments] : [];
    if (
      forwardAttachmentIds &&
      forwardAttachmentIds.length > 0 &&
      email.attachments
    ) {
      const emailAttachments = email.attachments as Array<{
        attachmentId: string;
        filename: string;
        mimeType: string;
        size: number;
      }>;

      for (const attachmentId of forwardAttachmentIds) {
        const attachmentMeta = emailAttachments.find(
          (a) => a.attachmentId === attachmentId,
        );
        if (attachmentMeta) {
          try {
            const attachmentData = await provider.getAttachment(
              userId,
              email.messageId,
              attachmentId,
              {
                filename: attachmentMeta.filename,
                mimeType: attachmentMeta.mimeType,
                size: attachmentMeta.size,
              },
            );
            allAttachments.push({
              filename: attachmentData.filename,
              mimeType: attachmentData.mimeType,
              content: attachmentData.data,
            });
          } catch (error) {
            this.logger.error(
              `Failed to fetch attachment ${attachmentId} for forwarding:`,
              error,
            );
            // Continue with other attachments
          }
        }
      }
    }

    const sentMessage = await provider.sendReply(
      userId,
      email.threadId,
      replyToAddress,
      replySubject,
      body,
      allAttachments.length > 0 ? allAttachments : undefined,
    );

    // Store the sent reply in the database so it appears in the thread view
    try {
      // Get or find the email thread
      const thread = await this.emailThreadRepository.findOne({
        where: { userId, threadId: email.threadId },
      });

      const sentEmail = this.emailRepository.create({
        userId,
        threadId: email.threadId,
        emailThreadId: thread?.id,
        messageId: sentMessage.messageId,
        from: userEmail,
        fromName: user.name || undefined,
        subject: replySubject,
        body,
        isRead: true,
        receivedAt: new Date(),
        labels: ["SENT"],
      });

      await this.emailRepository.save(sentEmail);
      this.logger.log(
        `Stored sent reply in database: messageId=${sentMessage.messageId}, threadId=${email.threadId}`,
      );
    } catch (storeError) {
      // Don't fail the send if storing fails - the email was already sent
      this.logger.error("Failed to store sent reply in database:", storeError);
    }

    // Trigger immediate learning from the sent reply
    // This will add it to toneSettings.rules if we need more examples
    try {
      await this.writingStyleLearningService.learnFromSentEmailBodies(userId, [
        body,
      ]);
    } catch (learningError) {
      // Don't fail the send if learning fails
      console.error("Failed to learn from sent reply:", learningError);
    }

    // If expected reply hours is set, snooze the email and create a follow-up
    if (expectedReplyHours && expectedReplyHours > 0) {
      try {
        // Snooze the email for the expected reply duration
        await this.snoozeService.snoozeEmail(
          userId,
          emailId,
          `${expectedReplyHours}h`,
        );

        // Create a follow-up reminder
        // Convert hours to days (rounding up to at least 1 day for the follow-up)
        const followUpDays = Math.max(1, Math.ceil(expectedReplyHours / 24));
        await this.followUpsService.createFollowUp(
          userId,
          email.threadId,
          followUpDays,
          emailId,
        );

        // Set star count to ensure the thread appears in Follow-Up mode
        // Follow-up mode requires starCount > 0, so set it to LOW (1)
        await this.emailThreadService.updateThreadStarCount(
          userId,
          email.threadId,
          STAR_COUNTS.LOW,
        );

        this.logger.log(
          `Created follow-up for thread ${email.threadId} with ${expectedReplyHours}h expected reply time`,
        );
      } catch (followUpError) {
        // Don't fail the send if follow-up creation fails
        this.logger.error("Failed to create follow-up:", followUpError);
      }
    }
  }
}

/**
 * Script to bulk recalculate priority for threads that don't have priority explanations
 *
 * Usage:
 *   npm run ts-node -r tsconfig-paths/register src/scripts/bulk-recalculate-priority.ts <userId> [--limit N]
 *
 * Example:
 *   npm run ts-node -r tsconfig-paths/register src/scripts/bulk-recalculate-priority.ts user-123 --limit 100
 */

import { DataSource } from "typeorm";
import { config } from "dotenv";
import * as path from "path";
import PgBoss = require("pg-boss");
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { getJobPriority } from "../queue/job-priorities";

config({ path: path.join(__dirname, "../../.env") });

async function bulkRecalculatePriority(userId?: string, limit: number = 100) {
  // Create database connection
  const dataSource = new DataSource({
    type: "postgres",
    host: process.env.DB_HOST || "localhost",
    port: parseInt(process.env.DB_PORT || "5432", 10),
    username: process.env.DB_USERNAME,
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME,
    ssl: process.env.DB_SSL === "true" ? { rejectUnauthorized: false } : false,
    entities: [EmailThread, Email],
  });

  await dataSource.initialize();
  console.log("Database connected");

  // Initialize pg-boss
  const boss = new PgBoss({
    connectionString: `postgres://${process.env.DB_USERNAME}:${process.env.DB_PASSWORD}@${process.env.DB_HOST}:${process.env.DB_PORT}/${process.env.DB_NAME}`,
    ssl: process.env.DB_SSL === "true" ? { rejectUnauthorized: false } : false,
  });

  await boss.start();
  console.log("PgBoss started");

  try {
    const emailThreadRepository = dataSource.getRepository(EmailThread);
    const emailRepository = dataSource.getRepository(Email);

    // Build query to find threads needing recalculation
    const queryBuilder = emailThreadRepository
      .createQueryBuilder("thread")
      .where("thread.priorityExplanation IS NULL")
      .orWhere(
        "(thread.isProcessingPriority = true AND thread.updatedAt < NOW() - INTERVAL '10 minutes')",
      );

    if (userId) {
      queryBuilder.andWhere("thread.userId = :userId", { userId });
    }

    queryBuilder.limit(limit);

    const threads = await queryBuilder.getMany();

    console.log(
      `Found ${threads.length} threads needing priority recalculation`,
    );

    let queued = 0;
    let skipped = 0;
    const errors: string[] = [];

    for (const thread of threads) {
      try {
        // Reset processing flag if stuck
        if (thread.isProcessingPriority) {
          await emailThreadRepository.update(
            { id: thread.id },
            { isProcessingPriority: false },
          );
        }

        // Get an email from this thread to use for the job
        const email = await emailRepository.findOne({
          where: { emailThreadId: thread.id },
          select: ["id", "userId"],
        });

        if (!email) {
          console.log(`Skipping thread ${thread.id} - no emails found`);
          skipped++;
          continue;
        }

        // Queue the job
        await boss.send(
          "refine-priority",
          { userId: email.userId, emailId: email.id },
          {
            priority: getJobPriority("refine-priority-background", false),
            singletonKey: `refine-priority-${email.id}`,
            singletonMinutes: 5,
          },
        );

        queued++;
        if (queued % 10 === 0) {
          console.log(`Queued ${queued} jobs...`);
        }
      } catch (error) {
        const errorMsg = `Failed to queue job for thread ${thread.id}: ${error instanceof Error ? error.message : "Unknown error"}`;
        console.error(errorMsg);
        errors.push(errorMsg);
      }
    }

    console.log("\n=== Summary ===");
    console.log(`Total threads found: ${threads.length}`);
    console.log(`Jobs queued: ${queued}`);
    console.log(`Skipped (no emails): ${skipped}`);
    console.log(`Errors: ${errors.length}`);
    if (errors.length > 0) {
      console.log("\nErrors:");
      errors.forEach((err) => console.log(`  - ${err}`));
    }

    await boss.stop();
    await dataSource.destroy();
  } catch (error) {
    console.error("Error:", error);
    await boss.stop();
    await dataSource.destroy();
    process.exit(1);
  }
}

// Parse command line arguments
const args = process.argv.slice(2);
const userIdArg = args.find((arg) => !arg.startsWith("--"));
const limitArg = args.find((arg) => arg.startsWith("--limit"));
const limit = limitArg ? parseInt(limitArg.split("=")[1] || "100", 10) : 100;

if (!userIdArg) {
  console.error(
    "Usage: npm run ts-node -r tsconfig-paths/register src/scripts/bulk-recalculate-priority.ts <userId> [--limit N]",
  );
  console.error(
    "Example: npm run ts-node -r tsconfig-paths/register src/scripts/bulk-recalculate-priority.ts user-123 --limit 100",
  );
  process.exit(1);
}

bulkRecalculatePriority(userIdArg, limit)
  .then(() => {
    console.log("Done!");
    process.exit(0);
  })
  .catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
  });

import { Injectable, OnModuleInit, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, LessThanOrEqual } from "typeorm";
import PgBoss = require("pg-boss");
import { EmailThread } from "../database/entities/email-thread.entity";
import { Email } from "../database/entities/email.entity";
import { EmailProviderManager } from "../emails/email-provider-manager.service";
import { JobPerformanceTracker } from "../queue/job-performance-tracker";
import { getJobPriority } from "../queue/job-priorities";
import { CloudWatchService } from "../aws/cloudwatch.service";

@Injectable()
export class SnoozeProcessor implements OnModuleInit {
  private readonly logger = new Logger(SnoozeProcessor.name);

  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    @InjectRepository(EmailThread)
    private emailThreadRepository: Repository<EmailThread>,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    private emailProviderManager: EmailProviderManager,
    private cloudWatchService: CloudWatchService,
  ) {}

  async onModuleInit() {
    // Schedule snooze check every minute
    await this.boss.schedule("check-expired-snoozes", "* * * * *");

    // Worker for checking and processing expired snoozes
    await this.boss.work("check-expired-snoozes", async (job) => {
      const workerId = job.id || "unknown";
      const tracker = new JobPerformanceTracker(
        "check-expired-snoozes",
        workerId,
        this.cloudWatchService,
      );

      this.logger.log("[Snooze] Starting expired snooze check");
      try {
        tracker.startPhase("findExpiredSnoozes");
        const now = new Date();

        // Find all threads with expired snoozes
        const expiredThreads = await this.emailThreadRepository.find({
          where: {
            isSnoozed: true,
            snoozeUntil: LessThanOrEqual(now),
          },
        });

        tracker.endPhase("findExpiredSnoozes");
        tracker.startPhase("queueUnsnoozeJobs");

        this.logger.log(
          `[Snooze] Found ${expiredThreads.length} expired snoozed threads`,
        );

        let jobsQueued = 0;
        for (const thread of expiredThreads) {
          try {
            // Queue an unsnooze job for each expired thread
            await this.boss.send(
              "unsnooze-thread",
              { userId: thread.userId, threadId: thread.threadId },
              {
                priority: getJobPriority("fetch-user-emails", false),
                singletonKey: `unsnooze-thread-${thread.threadId}`,
                singletonMinutes: 5,
              },
            );
            jobsQueued++;
          } catch (queueError) {
            this.logger.error(
              `[Snooze] Error queueing unsnooze job for thread ${thread.threadId}:`,
              queueError,
            );
          }
        }

        tracker.endPhase("queueUnsnoozeJobs");
        tracker.finish();

        this.logger.log(
          `[Snooze] Queued ${jobsQueued} unsnooze jobs for expired snoozes`,
        );
      } catch (error) {
        this.logger.error("[Snooze] Error in check-expired-snoozes:", error);
        tracker.finish(error as Error);
        throw error;
      }
    });

    // Worker for unsnoozing individual threads
    await this.boss.work("unsnooze-thread", { teamSize: 3 }, async (job) => {
      const { userId, threadId } = job.data as {
        userId: string;
        threadId: string;
      };
      const workerId = job.id || "unknown";
      const tracker = new JobPerformanceTracker(
        "unsnooze-thread",
        workerId,
        this.cloudWatchService,
      );
      tracker.setMetadata({ userId, threadId });

      this.logger.log(
        `[Worker ${workerId}] Starting unsnooze for thread ${threadId}`,
      );

      try {
        tracker.startPhase("unsnoozeInProvider");

        // Unsnooze in the email provider (Gmail, etc.)
        const provider =
          await this.emailProviderManager.getPrimaryProvider(userId);
        if (provider) {
          await provider.unsnoozeThread(userId, threadId);
          this.logger.log(
            `[Worker ${workerId}] Successfully unsnoozed thread ${threadId} in provider`,
          );
        } else {
          this.logger.warn(
            `[Worker ${workerId}] No email provider connected for user ${userId}`,
          );
        }

        tracker.endPhase("unsnoozeInProvider");
        tracker.startPhase("updateDatabase");

        // Update the thread in the database
        await this.emailThreadRepository.update(
          { userId, threadId },
          { isSnoozed: false, snoozeUntil: null },
        );

        // Also update emails for backward compatibility
        await this.emailRepository.update(
          { userId, threadId },
          { isSnoozed: false, snoozeUntil: null },
        );

        tracker.endPhase("updateDatabase");
        tracker.finish();

        this.logger.log(
          `[Worker ${workerId}] Completed unsnooze for thread ${threadId}`,
        );
      } catch (error) {
        this.logger.error(
          `[Worker ${workerId}] Failed to unsnooze thread ${threadId}:`,
          error,
        );
        tracker.finish(error as Error);
        throw error;
      }
    });

    this.logger.log("Snooze processor initialized - checking every minute");
  }
}

import { Test, TestingModule } from "@nestjs/testing";
import { ExecutionContext, ForbiddenException } from "@nestjs/common";
import { SubscriptionGuard } from "./subscription.guard";
import { SubscriptionsService } from "./subscriptions.service";

describe("SubscriptionGuard", () => {
  let guard: SubscriptionGuard;
  let subscriptionsService: SubscriptionsService;
  let mockExecutionContext: ExecutionContext;

  const mockSubscriptionsService = {
    hasActiveSubscription: jest.fn(),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        SubscriptionGuard,
        {
          provide: SubscriptionsService,
          useValue: mockSubscriptionsService,
        },
      ],
    }).compile();

    guard = module.get<SubscriptionGuard>(SubscriptionGuard);
    subscriptionsService =
      module.get<SubscriptionsService>(SubscriptionsService);

    mockExecutionContext = {
      switchToHttp: jest.fn().mockReturnValue({
        getRequest: jest.fn(),
      }),
    } as unknown as ExecutionContext;
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  describe("canActivate", () => {
    it("should return true when user has active subscription", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockSubscriptionsService.hasActiveSubscription.mockResolvedValue(true);

      const result = await guard.canActivate(mockExecutionContext);

      expect(result).toBe(true);
      expect(subscriptionsService.hasActiveSubscription).toHaveBeenCalledWith(
        userId,
      );
    });

    it("should throw ForbiddenException when user does not have active subscription", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockSubscriptionsService.hasActiveSubscription.mockResolvedValue(false);

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        ForbiddenException,
      );
      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "Active subscription required",
      );
      expect(subscriptionsService.hasActiveSubscription).toHaveBeenCalledWith(
        userId,
      );
    });

    it("should throw ForbiddenException when userId is missing", async () => {
      const mockRequest = {
        user: {}, // No userId
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        ForbiddenException,
      );
      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "User not authenticated",
      );
      expect(subscriptionsService.hasActiveSubscription).not.toHaveBeenCalled();
    });

    it("should throw ForbiddenException when user object is missing", async () => {
      const mockRequest = {}; // No user object

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        ForbiddenException,
      );
      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "User not authenticated",
      );
      expect(subscriptionsService.hasActiveSubscription).not.toHaveBeenCalled();
    });

    it("should handle errors from subscriptionsService", async () => {
      const userId = "user-123";
      const mockRequest = {
        user: { userId },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      mockSubscriptionsService.hasActiveSubscription.mockRejectedValue(
        new Error("Service error"),
      );

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "Service error",
      );
      expect(subscriptionsService.hasActiveSubscription).toHaveBeenCalledWith(
        userId,
      );
    });

    it("should handle null userId", async () => {
      const mockRequest = {
        user: { userId: null },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        ForbiddenException,
      );
      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "User not authenticated",
      );
    });

    it("should handle undefined userId", async () => {
      const mockRequest = {
        user: { userId: undefined },
      };

      (
        mockExecutionContext.switchToHttp().getRequest as jest.Mock
      ).mockReturnValue(mockRequest);

      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        ForbiddenException,
      );
      await expect(guard.canActivate(mockExecutionContext)).rejects.toThrow(
        "User not authenticated",
      );
    });
  });
});

import { Test, TestingModule } from "@nestjs/testing";
import { getRepositoryToken } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { ConfigService } from "@nestjs/config";
import axios from "axios";
import { SubscriptionsService } from "./subscriptions.service";
import { User } from "../database/entities/user.entity";

jest.mock("axios");
const mockedAxios = axios as jest.Mocked<typeof axios>;

describe("SubscriptionsService", () => {
  let service: SubscriptionsService;
  let repository: jest.Mocked<Repository<User>>;
  let configService: jest.Mocked<ConfigService>;

  const mockUser: User = {
    id: "user-1",
    email: "test@example.com",
    subscriptionStatus: null,
    subscriptionExpiresAt: null,
    trialStartedAt: null,
    revenueCatUserId: null,
    createdAt: new Date("2024-01-01"),
  } as User;

  beforeEach(async () => {
    const mockConfigGet = jest.fn().mockImplementation((key: string) => {
      if (key === "REVENUECAT_API_KEY") {
        return "test-api-key";
      }
      return null;
    });

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        SubscriptionsService,
        {
          provide: getRepositoryToken(User),
          useValue: {
            findOne: jest.fn(),
            update: jest.fn(),
            find: jest.fn(),
          },
        },
        {
          provide: ConfigService,
          useValue: {
            get: mockConfigGet,
          },
        },
      ],
    }).compile();

    service = module.get<SubscriptionsService>(SubscriptionsService);
    repository = module.get(getRepositoryToken(User));
    configService = module.get(ConfigService);
    jest.clearAllMocks();
    // Re-setup the mock after clearAllMocks
    configService.get = mockConfigGet;
  });

  describe("startTrial", () => {
    it("should start a 7-day trial for user without subscription", async () => {
      const userWithoutSubscription = { ...mockUser, subscriptionStatus: null };
      repository.findOne.mockResolvedValue(userWithoutSubscription);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const result = await service.startTrial("user-1");

      expect(result.success).toBe(true);
      expect(result.expiresAt).toBeDefined();
      expect(repository.update).toHaveBeenCalledWith(
        "user-1",
        expect.objectContaining({
          subscriptionStatus: "trial",
          trialStartedAt: expect.any(Date),
          subscriptionExpiresAt: expect.any(Date),
        }),
      );

      // Check that expiration is 7 days from now
      const updateCall = repository.update.mock.calls[0][1];
      const expiresAt = updateCall.subscriptionExpiresAt as Date;
      const trialStart = updateCall.trialStartedAt as Date;
      const daysDiff =
        (expiresAt.getTime() - trialStart.getTime()) / (1000 * 60 * 60 * 24);
      expect(daysDiff).toBeCloseTo(7, 0);
    });

    it("should not start trial if user already has active subscription", async () => {
      const activeUser = { ...mockUser, subscriptionStatus: "active" };
      repository.findOne.mockResolvedValue(activeUser);

      const result = await service.startTrial("user-1");

      expect(result.success).toBe(false);
      expect(repository.update).not.toHaveBeenCalled();
    });

    it("should not start trial if user already has trial", async () => {
      const trialUser = { ...mockUser, subscriptionStatus: "trial" };
      repository.findOne.mockResolvedValue(trialUser);

      const result = await service.startTrial("user-1");

      expect(result.success).toBe(false);
      expect(repository.update).not.toHaveBeenCalled();
    });

    it("should throw error if user not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(service.startTrial("nonexistent")).rejects.toThrow(
        "User not found",
      );
    });
  });

  describe("checkSubscriptionStatus", () => {
    it("should return active status for user with active subscription", async () => {
      const activeUser = {
        ...mockUser,
        subscriptionStatus: "active",
        subscriptionExpiresAt: new Date("2027-01-01"),
      };
      repository.findOne.mockResolvedValue(activeUser);

      const result = await service.checkSubscriptionStatus("user-1");

      expect(result.status).toBe("active");
      expect(result.isActive).toBe(true);
    });

    it("should return expired status when subscription has expired", async () => {
      const expiredUser = {
        ...mockUser,
        subscriptionStatus: "active",
        subscriptionExpiresAt: new Date("2020-01-01"),
      };
      repository.findOne
        .mockResolvedValueOnce(expiredUser)
        .mockResolvedValueOnce({
          ...expiredUser,
          subscriptionStatus: "expired",
        });
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const result = await service.checkSubscriptionStatus("user-1");

      expect(result.status).toBe("expired");
      expect(result.isActive).toBe(false);
      expect(repository.update).toHaveBeenCalledWith("user-1", {
        subscriptionStatus: "expired",
      });
    });

    it("should check RevenueCat when user has RevenueCat ID and API key", async () => {
      configService.get.mockReturnValue("test-api-key");
      const revenueCatUser = {
        ...mockUser,
        revenueCatUserId: "rc-user-123",
        subscriptionStatus: "active",
      };
      repository.findOne.mockResolvedValue(revenueCatUser);
      (mockedAxios as unknown as jest.Mock).mockResolvedValue({
        data: {
          subscriber: {
            entitlements: {
              premium: {
                expires_date: "2025-01-01T00:00:00Z",
                will_renew: true,
              },
            },
          },
        },
      } as any);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const result = await service.checkSubscriptionStatus("user-1");

      expect(mockedAxios).toHaveBeenCalledWith({
        method: "GET",
        url: "https://api.revenuecat.com/v1/subscribers/rc-user-123",
        headers: {
          Authorization: "Bearer test-api-key",
          "Content-Type": "application/json",
        },
        data: undefined,
      });
      expect(result.isActive).toBe(true);
    });

    it("should fall back to database status when RevenueCat check fails", async () => {
      configService.get.mockReturnValue("test-api-key");
      const revenueCatUser = {
        ...mockUser,
        revenueCatUserId: "rc-user-123",
        subscriptionStatus: "active",
        subscriptionExpiresAt: new Date("2027-01-01"),
      };
      repository.findOne.mockResolvedValue(revenueCatUser);
      (mockedAxios as unknown as jest.Mock).mockRejectedValue(
        new Error("API Error"),
      );

      const result = await service.checkSubscriptionStatus("user-1");

      expect(result.status).toBe("active");
      expect(result.isActive).toBe(true);
    });

    it("should throw error if user not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(
        service.checkSubscriptionStatus("nonexistent"),
      ).rejects.toThrow("User not found");
    });
  });

  describe("hasActiveSubscription", () => {
    it("should return true for active subscription", async () => {
      const activeUser = {
        ...mockUser,
        subscriptionStatus: "active",
        subscriptionExpiresAt: new Date("2027-01-01"),
      };
      repository.findOne.mockResolvedValue(activeUser);

      const result = await service.hasActiveSubscription("user-1");

      expect(result).toBe(true);
    });

    it("should return false for expired subscription", async () => {
      const expiredUser = {
        ...mockUser,
        subscriptionStatus: "expired",
      };
      repository.findOne.mockResolvedValue(expiredUser);

      const result = await service.hasActiveSubscription("user-1");

      expect(result).toBe(false);
    });
  });

  describe("handleWebhook", () => {
    beforeEach(() => {
      configService.get.mockReturnValue("test-api-key");
      // Reset axios mock for each test
      (mockedAxios as unknown as jest.Mock).mockReset();
    });

    it("should handle INITIAL_PURCHASE event", async () => {
      const user = { ...mockUser, revenueCatUserId: "rc-user-123" };
      repository.findOne.mockResolvedValue(user);
      (mockedAxios as unknown as jest.Mock).mockResolvedValue({
        data: {
          subscriber: {
            entitlements: {
              premium: {
                expires_date: "2027-01-01T00:00:00Z",
                will_renew: true,
              },
            },
          },
        },
      });
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const payload = {
        event: {
          type: "INITIAL_PURCHASE",
          app_user_id: "rc-user-123",
          product_id: "premium",
        },
      };

      await service.handleWebhook(payload);

      expect(repository.update).toHaveBeenCalledWith(
        "user-1",
        expect.objectContaining({
          subscriptionStatus: "active",
          subscriptionExpiresAt: expect.any(Date),
        }),
      );
    });

    it("should handle CANCELLATION event", async () => {
      const user = { ...mockUser, revenueCatUserId: "rc-user-123" };
      repository.findOne.mockResolvedValue(user);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const payload = {
        event: {
          type: "CANCELLATION",
          app_user_id: "rc-user-123",
        },
      };

      await service.handleWebhook(payload);

      expect(repository.update).toHaveBeenCalledWith("user-1", {
        subscriptionStatus: "cancelled",
      });
    });

    it("should handle EXPIRATION event", async () => {
      const user = { ...mockUser, revenueCatUserId: "rc-user-123" };
      repository.findOne.mockResolvedValue(user);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const payload = {
        event: {
          type: "EXPIRATION",
          app_user_id: "rc-user-123",
        },
      };

      await service.handleWebhook(payload);

      expect(repository.update).toHaveBeenCalledWith("user-1", {
        subscriptionStatus: "expired",
      });
    });

    // Note: This test is skipped because the API key is read in the constructor,
    // so mocking configService.get after module creation doesn't affect the service.
    // To properly test this, we would need a separate describe block with a different module setup.
    it.skip("should ignore webhook if API key not configured", async () => {
      configService.get.mockReturnValue(null);
      const payload = {
        event: { type: "INITIAL_PURCHASE", app_user_id: "123" },
      };

      await service.handleWebhook(payload);

      expect(repository.findOne).not.toHaveBeenCalled();
    });

    it("should ignore webhook if user not found", async () => {
      repository.findOne.mockResolvedValue(null);

      const payload = {
        event: {
          type: "INITIAL_PURCHASE",
          app_user_id: "nonexistent",
        },
      };

      await service.handleWebhook(payload);

      expect(repository.update).not.toHaveBeenCalled();
    });
  });

  describe("linkRevenueCatUser", () => {
    it("should link RevenueCat user ID to user", async () => {
      repository.update.mockResolvedValue({ affected: 1 } as any);

      await service.linkRevenueCatUser("user-1", "rc-user-123");

      expect(repository.update).toHaveBeenCalledWith("user-1", {
        revenueCatUserId: "rc-user-123",
      });
    });
  });

  describe("extendTrial", () => {
    it("should extend trial by specified days", async () => {
      const futureDate = new Date();
      futureDate.setDate(futureDate.getDate() + 30);
      const trialUser = {
        ...mockUser,
        subscriptionStatus: "trial",
        subscriptionExpiresAt: futureDate,
      };
      repository.findOne.mockResolvedValue(trialUser);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const result = await service.extendTrial("user-1", 7);

      expect(result.success).toBe(true);
      expect(result.newExpiresAt).toBeDefined();
      expect(repository.update).toHaveBeenCalledWith(
        "user-1",
        expect.objectContaining({
          subscriptionExpiresAt: expect.any(Date),
        }),
      );

      const updateCall = repository.update.mock.calls[0][1];
      const newExpiresAt = updateCall.subscriptionExpiresAt as Date;
      const daysDiff =
        (newExpiresAt.getTime() - trialUser.subscriptionExpiresAt!.getTime()) /
        (1000 * 60 * 60 * 24);
      expect(daysDiff).toBe(7);
    });

    it("should extend from now if expiration is in the past", async () => {
      const expiredUser = {
        ...mockUser,
        subscriptionStatus: "expired",
        subscriptionExpiresAt: new Date("2020-01-01"),
      };
      repository.findOne.mockResolvedValue(expiredUser);
      repository.update.mockResolvedValue({ affected: 1 } as any);

      const result = await service.extendTrial("user-1", 7);

      expect(result.success).toBe(true);
      const updateCall = repository.update.mock.calls[0][1];
      expect(updateCall.subscriptionStatus).toBe("trial");
    });

    it("should throw error if user not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(service.extendTrial("nonexistent", 7)).rejects.toThrow(
        "User not found",
      );
    });
  });

  describe("getAllUsersWithSubscriptions", () => {
    it("should return all users with subscription info", async () => {
      const users = [
        {
          ...mockUser,
          subscriptionStatus: "active",
          subscriptionExpiresAt: new Date("2025-01-01"),
        },
        {
          ...mockUser,
          id: "user-2",
          subscriptionStatus: "trial",
          subscriptionExpiresAt: new Date("2024-02-01"),
          trialStartedAt: new Date("2024-01-25"),
        },
      ];
      repository.find.mockResolvedValue(users as User[]);

      const result = await service.getAllUsersWithSubscriptions();

      expect(result).toHaveLength(2);
      expect(result[0]).toMatchObject({
        id: "user-1",
        subscriptionStatus: "active",
      });
      expect(result[1]).toMatchObject({
        id: "user-2",
        subscriptionStatus: "trial",
      });
      expect(repository.find).toHaveBeenCalledWith({
        select: [
          "id",
          "email",
          "name",
          "subscriptionStatus",
          "subscriptionExpiresAt",
          "trialStartedAt",
          "createdAt",
        ],
        order: { createdAt: "DESC" },
      });
    });

    it("should return empty array when no users", async () => {
      repository.find.mockResolvedValue([]);

      const result = await service.getAllUsersWithSubscriptions();

      expect(result).toEqual([]);
    });
  });
});

import { Injectable, Logger } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository, Not, IsNull } from "typeorm";
import { UsersService } from "../users/users.service";
import { EmailsService } from "../emails/emails.service";
import { LLMService } from "../llm/llm.service";
import { GitHubService } from "../github/github.service";
import { GitHubApiService } from "../github/github-api.service";
import { CalendarService } from "../calendar/calendar.service";
import { ActionItem } from "../database/entities/action-item.entity";
import { EmailThread } from "../database/entities/email-thread.entity";
import { ActionItemsService } from "../action-items/action-items.service";
import { GitHubRepoMappingService } from "../github/github-repo-mapping.service";
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { EncryptionHelper } from "../encryption/encryption.helper";

export interface SuggestedAction {
  type: string;
  confidence: number;
  reason: string;
  /** Additional action-specific metadata (varies by action type) */
  metadata?: Record<string, unknown>;
}

@Injectable()
export class SuggestedActionsService {
  private readonly logger = new Logger(SuggestedActionsService.name);

  // eslint-disable-next-line max-params
  constructor(
    private readonly usersService: UsersService,
    private readonly emailsService: EmailsService,
    private readonly llmService: LLMService,
    private readonly githubService: GitHubService,
    private readonly githubApiService: GitHubApiService,
    private readonly calendarService: CalendarService,
    private readonly actionItemsService: ActionItemsService,
    private readonly repoMappingService: GitHubRepoMappingService,
    @InjectRepository(ActionItem)
    private readonly actionItemRepository: Repository<ActionItem>,
    @InjectRepository(EmailThread)
    private readonly emailThreadRepository: Repository<EmailThread>,
  ) {}

  private mapActionItemToSuggestedAction(
    actionItem: ActionItem,
  ): SuggestedAction {
    return {
      type: actionItem.actionType || "",
      confidence: actionItem.confidenceScore || 0,
      reason: actionItem.reason || actionItem.description,
      metadata: actionItem.metadata || undefined,
    };
  }

  async detectActions(
    emailId: string,
    userId: string,
  ): Promise<SuggestedAction[]> {
    try {
      const email = await this.emailsService.getEmailById(userId, emailId);
      if (!email) {
        throw new Error("Email not found");
      }

      const threadId = email.emailThreadId;
      if (!threadId) {
        this.logger.warn(
          `Email ${emailId} has no threadId, cannot cache suggested actions`,
        );
        // Fall through to generate without caching
      } else {
        // Get all existing suggested actions for thread (LLM + user-created)
        // actionType IS NOT NULL indicates suggested actions
        const existingActions = await this.actionItemRepository.find({
          where: {
            userId,
            emailThreadId: threadId,
            actionType: Not(IsNull()),
          },
        });

        // Get latest email in thread
        const threadEmails = await this.emailsService.getThreadEmails(
          userId,
          threadId,
        );
        const latestEmailId = threadEmails[0]?.id;

        // Check if LLM-generated actions exist and are still valid
        const llmActions = existingActions.filter((a) => a.source === "llm");
        const llmAction = llmActions[0]; // Check first LLM action for lastEmailId

        // Return existing actions if LLM cache is valid
        if (llmAction && llmAction.lastEmailId === latestEmailId) {
          this.logger.debug(
            `Returning cached suggested actions for thread ${threadId}`,
          );
          return existingActions.map(this.mapActionItemToSuggestedAction);
        }
      }

      // Cache invalid or missing, generate new LLM suggestions
      const user = await this.usersService.findOne(userId);
      const hasGithubToken = !!user?.githubToken;
      const hasCalendarToken = !!user?.googleCalendarAccessToken;

      // Parse GitHub links from email if they exist
      const githubLinks = this.githubService.parseGitHubLinks(
        email.body || "",
        email.htmlBody || undefined,
      );

      // Use LLM to detect suggested actions (now with htmlBody)
      const actions = await this.llmService.detectSuggestedActions(
        {
          subject: email.subject,
          body: email.body || "",
          htmlBody: email.htmlBody || undefined,
          from: email.from,
          fromName: email.fromName || undefined,
        },
        {
          hasGithubLinks: githubLinks.length > 0,
          githubLinks: githubLinks.map((link) => ({
            type: link.type,
            owner: link.owner,
            repo: link.repo,
            number: link.number,
          })),
          hasCalendarToken,
          hasGithubToken,
        },
        // Use default provider
        undefined,
        userId,
      );

      // Get thread category for repo mapping lookup
      const thread = threadId
        ? await this.emailThreadRepository.findOne({
            where: { id: threadId, userId },
          })
        : null;
      const emailCategory = thread?.category || undefined;

      // Get default repo for github_create_issue pre-fill
      const defaultRepo = hasGithubToken
        ? await this.repoMappingService.getRepoForEmail(userId, emailCategory)
        : null;

      // Enhance actions with metadata (e.g., issue info from GitHub links)
      const enhancedActions = actions.map((action) => {
        if (
          action.type === "github_update_status" ||
          action.type === "github_add_comment"
        ) {
          // If there are GitHub links, use the first one as the issue info
          if (githubLinks.length > 0) {
            const link = githubLinks[0];
            if (link.type === "issue") {
              return {
                ...action,
                metadata: {
                  issueInfo: {
                    owner: link.owner,
                    repo: link.repo,
                    number: link.number,
                  },
                },
              };
            }
          }
        }
        if (action.type === "github_create_issue" && defaultRepo) {
          return {
            ...action,
            metadata: {
              ...action.metadata,
              defaultRepo: {
                owner: defaultRepo.owner,
                repo: defaultRepo.repo,
              },
            },
          };
        }
        return action;
      });

      // Save to ActionItem table if we have a threadId
      if (threadId) {
        // Get latest email in thread for cache tracking
        const threadEmails = await this.emailsService.getThreadEmails(
          userId,
          threadId,
        );
        const latestEmailId = threadEmails[0]?.id;

        // Delete old LLM-generated suggested actions
        await this.actionItemRepository.delete({
          emailThreadId: threadId,
          source: "llm",
          actionType: Not(IsNull()),
        });

        // Create new ActionItem records for LLM-generated suggested actions
        const llmEntities = enhancedActions.map((action) =>
          this.actionItemRepository.create({
            userId,
            emailThreadId: threadId,
            emailId: email.id,
            description: `${action.type}: ${action.reason}`,
            actionType: action.type,
            confidenceScore: action.confidence,
            reason: action.reason,
            metadata: action.metadata || undefined,
            source: "llm",
            lastEmailId: latestEmailId,
            isCompleted: false,
          }),
        );
        await this.actionItemRepository.save(llmEntities);

        // Get user-created actions to include in response
        const userActions = await this.actionItemRepository.find({
          where: {
            userId,
            emailThreadId: threadId,
            actionType: Not(IsNull()),
            source: "user",
          },
        });

        return [
          ...enhancedActions,
          ...userActions.map(this.mapActionItemToSuggestedAction),
        ];
      }

      return enhancedActions;
    } catch (error) {
      this.logger.error(`Error detecting actions for email ${emailId}:`, error);
      return [];
    }
  }
}

import { Injectable, OnModuleInit, Logger, Inject } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import PgBoss = require("pg-boss");
import { Email } from "../database/entities/email.entity";
import { SuggestedRepliesService } from "./suggested-replies.service";
import { LLMService } from "../llm/llm.service";
import { UsersService } from "../users/users.service";
import { JobPerformanceTracker } from "../queue/job-performance-tracker";
import { EncryptionHelper } from "../encryption/encryption.helper";
import { CloudWatchService } from "../aws/cloudwatch.service";
import { QUERY_LIMITS } from "../constants/query-limits";

@Injectable()
export class SuggestedRepliesProcessor implements OnModuleInit {
  private readonly logger = new Logger(SuggestedRepliesProcessor.name);

  constructor(
    @Inject("PG_BOSS") private boss: PgBoss,
    @InjectRepository(Email)
    private emailRepository: Repository<Email>,
    private suggestedRepliesService: SuggestedRepliesService,
    private llmService: LLMService,
    private usersService: UsersService,
    private cloudWatchService: CloudWatchService,
  ) {}

  async onModuleInit() {
    this.logger.log("Registering generate-suggested-replies worker");

    await this.boss.work(
      "generate-suggested-replies",
      { teamSize: 4 },
      async (job) => {
        const { userId, threadId, emailId } = job.data as {
          userId: string;
          threadId: string;
          emailId: string;
        };
        const workerId = job.id || "unknown";
        const tracker = new JobPerformanceTracker(
          "generate-suggested-replies",
          workerId,
          this.cloudWatchService,
        );
        tracker.setMetadata({ userId, threadId, emailId });

        this.logger.log(
          `[Worker ${workerId}] Starting suggested reply generation for thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...`,
        );

        try {
          tracker.startPhase("dataFetch");

          const user = await this.usersService.findOne(userId);
          if (!user) {
            this.logger.warn(`[Worker ${workerId}] User ${userId} not found`);
            return;
          }

          const userEmail = EncryptionHelper.decrypt(user.email)?.toLowerCase();

          const latestEmailInThread = await this.emailRepository.findOne({
            where: { emailThreadId: threadId, userId },
            order: { receivedAt: "DESC" },
          });

          if (!latestEmailInThread) {
            this.logger.warn(
              `[Worker ${workerId}] No emails found in thread ${threadId} for user ${userId}`,
            );
            return;
          }

          const lastEmailFrom = latestEmailInThread.from?.toLowerCase() || "";
          const userSentLast = userEmail && lastEmailFrom === userEmail;

          await this.suggestedRepliesService.markAsGenerating(userId, threadId);

          const toneRules = user?.toneSettings?.rules || [];
          const emailExamples = toneRules.filter(
            (rule: string) =>
              !rule.startsWith("Tone:") &&
              !rule.startsWith("Style:") &&
              !rule.startsWith("Common phrase:"),
          );

          const userContext = {
            tone: "professional",
            userName: user?.displayName || user?.name || "User",
            userJobTitle: user?.jobTitle || "",
            emailExamples,
          };

          tracker.endPhase("dataFetch");
          tracker.startPhase("llmCall");

          let options: Array<{ label: string; text: string }>;

          if (userSentLast) {
            this.logger.log(
              `[Worker ${workerId}] User sent last email - generating follow-up suggestion for thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...`,
            );

            const threadEmails = await this.emailRepository.find({
              where: { emailThreadId: threadId, userId },
              order: { receivedAt: "ASC" },
              take: 5,
            });

            const recipientName =
              threadEmails.find((e) => e.from?.toLowerCase() !== userEmail)
                ?.fromName || "there";

            const lastUserEmailDate = latestEmailInThread.receivedAt;
            const now = new Date();
            const daysSinceLastEmail = Math.floor(
              (now.getTime() - new Date(lastUserEmailDate).getTime()) /
                (1000 * 60 * 60 * 24),
            );

            const threadMessages = threadEmails.map((e) => ({
              from: e.from || "",
              fromName: e.fromName || undefined,
              body: e.body || "",
              receivedAt: e.receivedAt,
              isFromUser: e.from?.toLowerCase() === userEmail,
            }));

            const followUpText = await this.llmService.generateFollowUpDraft(
              latestEmailInThread.subject || "",
              threadMessages,
              recipientName,
              Math.max(1, daysSinceLastEmail),
              {
                tone: userContext.tone,
                commonPhrases: emailExamples,
              },
              undefined,
              userId,
            );

            options = [{ label: "Follow Up", text: followUpText }];
          } else {
            options = await this.llmService.generateReplyOptions(
              {
                from: latestEmailInThread.from || "",
                fromName: latestEmailInThread.fromName || undefined,
                subject: latestEmailInThread.subject || "",
                body: latestEmailInThread.body || "",
              },
              userContext,
              undefined,
              userId,
            );
          }

          tracker.endPhase("llmCall");
          tracker.startPhase("dbUpdate");

          await this.suggestedRepliesService.saveSuggestedReplies(
            userId,
            threadId,
            options,
            latestEmailInThread.id,
          );

          tracker.endPhase("dbUpdate");
          tracker.finish();

          this.logger.log(
            `[Worker ${workerId}] Generated ${options.length} suggested replies for thread ${threadId.substring(0, QUERY_LIMITS.THREAD_ID_SHORT)}...`,
          );
        } catch (error) {
          this.logger.error(
            `[Worker ${workerId}] Failed to generate suggested replies for thread ${threadId}`,
            error,
          );

          await this.suggestedRepliesService.markAsNotGenerating(
            userId,
            threadId,
          );

          tracker.finish(error as Error);
          throw error;
        }
      },
    );

    this.logger.log(
      "generate-suggested-replies worker registered successfully",
    );
  }
}

import { Injectable } from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { EmailsService } from "../emails/emails.service";
import { LLMService, LLMProvider } from "../llm/llm.service";
import { SummarizationRule as SummarizationRuleEntity } from "../database/entities/summarization-rule.entity";
import {
  cleanEmailContent,
  cleanEmailForThread,
} from "../llm/email-content-cleaner";
import { CONTEXT_ANALYSIS } from "../constants/llm-constants";

export interface SummarizationRule {
  type: "bullet-points" | "action-items" | "sender-request" | "tldr" | "custom";
  customPrompt?: string;
  provider?: "gemini" | "openai";
}

/**
 * Email with optional htmlBody for summarization
 * (The Email entity has htmlBody but it may not be in the return type)
 */
interface EmailWithHtmlBody {
  body: string;
  htmlBody?: string;
  subject?: string;
  from?: string;
  fromName?: string;
  threadId?: string;
  receivedAt?: Date | string;
}

@Injectable()
export class SummarizationService {
  constructor(
    private emailsService: EmailsService,
    private llmService: LLMService,
    @InjectRepository(SummarizationRuleEntity)
    private summarizationRuleRepository: Repository<SummarizationRuleEntity>,
  ) {}

  async summarizeEmail(
    userId: string,
    emailId: string,
    rule: SummarizationRule,
    prefetchedEmail?: Awaited<ReturnType<EmailsService["getEmailById"]>>,
  ): Promise<string> {
    const email =
      prefetchedEmail ||
      (await this.emailsService.getEmailById(userId, emailId));
    if (!email) {
      throw new Error("Email not found");
    }

    // For thread summaries, get the first email (for context) + last 3 messages (current state)
    // Fetch all emails in ASC order to get first email, then determine which to include
    // ASC to get oldest first
    const allThreadEmails = await this.emailsService.getThreadEmails(
      userId,
      email.threadId,
      { limit: 20, order: "ASC" },
    );

    // Build the messages to summarize: first email + last 3
    // If thread has 4 or fewer emails, just use all of them
    let messagesToSummarize: typeof allThreadEmails;
    if (allThreadEmails.length <= 4) {
      messagesToSummarize = allThreadEmails;
    } else {
      // First email + last 3 (skip middle ones)
      const firstEmail = allThreadEmails[0];
      const last3Emails = allThreadEmails.slice(
        CONTEXT_ANALYSIS.LAST_THREAD_EMAILS_SLICE,
      );
      messagesToSummarize = [firstEmail, ...last3Emails];
    }

    // Combine messages for thread context (clean each message)
    const threadText = messagesToSummarize
      .map((e, idx) => {
        // Cast to EmailWithHtmlBody to access htmlBody which exists on the entity
        const emailWithHtml = e as EmailWithHtmlBody;
        const sender = e.fromName || e.from;
        const date = new Date(e.receivedAt).toLocaleString();
        // Clean each message: strip HTML, remove signatures, limit to 800 chars per message
        const cleanedBody = cleanEmailForThread(e.body, emailWithHtml.htmlBody);
        // Indicate if this is the original email vs recent messages
        const messageLabel =
          idx === 0 && allThreadEmails.length > 4
            ? "Original"
            : `Message ${idx + 1}`;
        return `[${messageLabel} from ${sender} on ${date}]:\n${cleanedBody}`;
      })
      .join("\n\n---\n\n");

    // Cast to EmailWithHtmlBody to access htmlBody which exists on the entity
    const emailWithHtml = email as EmailWithHtmlBody;
    const subject = email.subject || "";
    const text =
      threadText || cleanEmailContent(email.body, emailWithHtml.htmlBody);

    // Use LLM for all summarization types
    try {
      // Convert string provider to LLMProvider enum
      let llmProvider: LLMProvider | undefined;
      if (rule.provider) {
        llmProvider =
          rule.provider === "gemini" ? LLMProvider.GEMINI : LLMProvider.OPENAI;
      }

      if (rule.type === "custom" && rule.customPrompt) {
        // Custom prompt using LLM - use cleaned content
        const cleanedBody = cleanEmailContent(
          email.body,
          emailWithHtml.htmlBody,
        );
        const prompt =
          messagesToSummarize.length > 1
            ? `Email Thread Subject: ${subject}\n\nThis thread contains ${allThreadEmails.length} messages. Here are the key messages (first + last 3):\n\n${threadText}\n\n${rule.customPrompt}`
            : `Email Subject: ${subject}\n\nEmail Body:\n${cleanedBody}\n\n${rule.customPrompt}`;

        return await this.llmService.generateText(
          {
            prompt,
            systemPrompt:
              "You are a helpful assistant that summarizes email threads according to user instructions.",
            temperature: 0.5,
            maxTokens: 500,
            userId,
          },
          llmProvider,
          userId,
        );
      }

      // Use LLM for standard summarization types
      if (messagesToSummarize.length > 1) {
        // Thread summary - use specialized prompt (already cleaned above)
        return await this.llmService.summarizeEmail(
          threadText,
          subject,
          rule.type,
          llmProvider,
          userId,
        );
      } else {
        // Single email summary - clean the content
        const cleanedBody = cleanEmailContent(
          email.body,
          emailWithHtml.htmlBody,
        );
        return await this.llmService.summarizeEmail(
          cleanedBody,
          subject,
          rule.type,
          llmProvider,
          userId,
        );
      }
    } catch (error) {
      // Fallback to simple extraction if LLM fails
      console.error("LLM summarization failed, using fallback", error);
      return this.fallbackSummary(text, subject, rule.type, email.from);
    }
  }

  /**
   * Batch summarize multiple threads in parallel.
   * Each thread gets its own LLM call, but calls are fired concurrently for efficiency.
   * Note: This method is called with emailIds but summarizes at the THREAD level -
   * each email's thread is summarized, and the summary is applied to all emails in that thread.
   * @param userId User ID
   * @param emailIds Array of email IDs (one per thread to summarize)
   * @returns Map of email ID to thread summary string
   */
  async summarizeThreadBatch(
    userId: string,
    emailIds: string[],
  ): Promise<Map<string, string>> {
    if (emailIds.length === 0) {
      return new Map();
    }

    // Fetch all emails to get their thread information
    const emailPromises = emailIds.map((emailId) =>
      this.emailsService.getEmailById(userId, emailId),
    );
    const emails = await Promise.all(emailPromises);

    // Get user's summarization rules once (shared across all threads)
    const userRules = await this.getSummarizationRules(userId);

    // Prepare thread data for summarization
    interface ThreadData {
      // The email ID that triggered this thread summarization
      emailId: string;
      email: NonNullable<(typeof emails)[0]>;
      // Combined text of all messages in thread
      threadText: string;
      // Whether this has multiple messages
      isThread: boolean;
      // Number of messages included in summary
      messageCount: number;
      matchedRule: SummarizationRuleEntity | null;
    }
    const threadsToSummarize: ThreadData[] = [];

    // Fetch all messages in each thread and match summarization rules
    const threadPromises = emails.map(async (email, idx) => {
      if (!email) return null;

      // Get first email + last 3 messages in the thread (same logic as single summarization)
      const allThreadEmails = await this.emailsService.getThreadEmails(
        userId,
        email.threadId,
        { limit: 20, order: "ASC" },
      );

      // Build the messages to summarize: first email + last 3
      let messagesToSummarize: typeof allThreadEmails;
      if (allThreadEmails.length <= 4) {
        messagesToSummarize = allThreadEmails;
      } else {
        const firstEmail = allThreadEmails[0];
        const last3Emails = allThreadEmails.slice(
          CONTEXT_ANALYSIS.LAST_THREAD_EMAILS_SLICE,
        );
        messagesToSummarize = [firstEmail, ...last3Emails];
      }

      // Build thread text
      const threadText = messagesToSummarize
        .map((e, msgIdx) => {
          const sender = e.fromName || e.from;
          const date = new Date(e.receivedAt).toLocaleString();
          const cleanedBody = cleanEmailForThread(
            e.body,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            (e as any).htmlBody,
          );
          const messageLabel =
            msgIdx === 0 && allThreadEmails.length > 4
              ? "Original"
              : `Message ${msgIdx + 1}`;
          return `[${messageLabel} from ${sender} on ${date}]:\n${cleanedBody}`;
        })
        .join("\n\n---\n\n");

      // Match summarization rule for this email using fast domain/keyword matching
      const matchedRule = this.matchRuleFast(
        { from: email.from, subject: email.subject },
        userRules,
      );

      return {
        emailId: emailIds[idx],
        email,
        threadText:
          threadText ||
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          cleanEmailContent(email.body, (email as any).htmlBody),
        isThread: messagesToSummarize.length > 1,
        messageCount: messagesToSummarize.length,
        matchedRule,
      };
    });

    const threadResults = await Promise.all(threadPromises);
    for (const result of threadResults) {
      if (result) {
        threadsToSummarize.push(result);
      }
    }

    if (threadsToSummarize.length === 0) {
      return new Map();
    }

    // Group threads by their matched summarization rule (or null for default)
    const threadsByRule = new Map<string | null, ThreadData[]>();
    for (const threadData of threadsToSummarize) {
      const ruleKey = threadData.matchedRule?.ruleId || null;
      if (!threadsByRule.has(ruleKey)) {
        threadsByRule.set(ruleKey, []);
      }
      threadsByRule.get(ruleKey)!.push(threadData);
    }

    const result = new Map<string, string>();

    // Process each rule group separately
    for (const [ruleKey, threads] of threadsByRule) {
      const rule = threads[0].matchedRule;

      // Prepare thread data for LLM
      const batchData = threads.map((item, idx) => ({
        index: idx,
        subject: item.email.subject || "",
        // Full thread content (first + last 3 messages)
        body: item.threadText,
        isThread: item.isThread,
        messageCount: item.messageCount,
      }));

      try {
        // Extract email IDs for tracking
        const threadEmailIds = threads.map((item) => item.emailId);

        // Call thread summarization with the rule's instructions
        // Pass custom summarization instructions if available
        // Pass email IDs for tracking
        const summaryMap = await this.llmService.summarizeThreads(
          batchData,
          undefined,
          userId,
          rule?.howToSummarize,
          threadEmailIds,
        );

        // Map summaries back to email IDs
        threads.forEach((item, idx) => {
          const summary = summaryMap.get(idx);
          if (summary) {
            result.set(item.emailId, summary);
          }
        });
      } catch (error) {
        console.error(
          `Thread summarization failed for rule ${ruleKey || "default"}, falling back to individual calls`,
          error,
        );

        // Fallback: summarize each thread individually
        for (const item of threads) {
          try {
            const summary = await this.summarizeEmail(userId, item.emailId, {
              type: rule ? "custom" : "tldr",
              customPrompt: rule?.howToSummarize,
            });
            result.set(item.emailId, summary);
          } catch (summaryError) {
            console.error(
              `Failed to summarize thread for email ${item.emailId}:`,
              summaryError,
            );
          }
        }
      }
    }

    return result;
  }

  async getSummarizationRules(
    userId: string,
  ): Promise<SummarizationRuleEntity[]> {
    return this.summarizationRuleRepository.find({
      where: { userId },
      order: { createdAt: "DESC" },
    });
  }

  /**
   * Fast rule matching using domain and keyword matching (no LLM call).
   * Used for automated summarization to avoid extra LLM overhead.
   * @param email The email to match rules against
   * @param rules Array of user's summarization rules
   * @returns Matched rule or null if no match
   */
  matchRuleFast(
    email: { from?: string; subject?: string },
    rules: SummarizationRuleEntity[],
  ): SummarizationRuleEntity | null {
    if (rules.length === 0) {
      return null;
    }

    const fromLower = (email.from || "").toLowerCase();
    const subjectLower = (email.subject || "").toLowerCase();

    for (const rule of rules) {
      const whenToUseLower = rule.whenToUse.toLowerCase();

      // Check for domain match (e.g., "emails from @company.com")
      const domainMatch = whenToUseLower.match(/@([a-z0-9.-]+)/i);
      if (domainMatch) {
        const domain = domainMatch[1].toLowerCase();
        const emailDomain = fromLower
          .match(/@([a-z0-9.-]+)/i)?.[1]
          ?.toLowerCase();
        if (emailDomain === domain) {
          return rule;
        }
      }

      // Check for keyword matches in the rule (simple fast matching)
      const keywords = whenToUseLower.split(/\s+/).filter((w) => w.length > 3);
      for (const keyword of keywords) {
        if (subjectLower.includes(keyword) || fromLower.includes(keyword)) {
          return rule;
        }
      }
    }

    return null;
  }

  /**
   * Summarize an email with automatic rule matching.
   * Uses fast domain/keyword matching to find appropriate summarization rules.
   * This is the recommended method for automated job processing.
   * @param userId User ID
   * @param emailId Email ID
   * @param prefetchedEmail Optional pre-fetched email to avoid redundant DB query
   * @param prefetchedRules Optional pre-fetched rules to avoid redundant DB query
   * @returns Summary string
   */
  async summarizeEmailWithAutoRule(
    userId: string,
    emailId: string,
    prefetchedEmail?: Awaited<ReturnType<EmailsService["getEmailById"]>>,
    prefetchedRules?: SummarizationRuleEntity[],
  ): Promise<string> {
    const email =
      prefetchedEmail ||
      (await this.emailsService.getEmailById(userId, emailId));
    if (!email) {
      throw new Error("Email not found");
    }

    // Fetch user's summarization rules (or use prefetched)
    const userRules =
      prefetchedRules || (await this.getSummarizationRules(userId));

    // Fast match using domain/keyword (no LLM call)
    const matchedRule = this.matchRuleFast(
      { from: email.from, subject: email.subject },
      userRules,
    );

    // Build the SummarizationRule based on matched rule
    let rule: SummarizationRule;
    if (matchedRule) {
      rule = {
        type: "custom",
        customPrompt: matchedRule.howToSummarize,
      };
    } else {
      rule = { type: "tldr" };
    }

    // Pass prefetched email to avoid re-fetching
    return this.summarizeEmail(userId, emailId, rule, email);
  }

  async createSummarizationRule(
    userId: string,
    rule: { whenToUse: string; howToSummarize: string },
  ): Promise<SummarizationRuleEntity> {
    const newRule = this.summarizationRuleRepository.create({
      ...rule,
      userId,
    });
    return this.summarizationRuleRepository.save(newRule);
  }

  async updateSummarizationRule(
    userId: string,
    ruleId: string,
    updates: { whenToUse?: string; howToSummarize?: string },
  ): Promise<SummarizationRuleEntity> {
    await this.summarizationRuleRepository.update({ ruleId, userId }, updates);
    return this.summarizationRuleRepository.findOne({
      where: { ruleId, userId },
    });
  }

  async deleteSummarizationRule(userId: string, ruleId: string): Promise<void> {
    await this.summarizationRuleRepository.delete({ ruleId, userId });
  }

  async matchRuleForEmail(
    userId: string,
    emailId: string,
  ): Promise<SummarizationRuleEntity | null> {
    const email = await this.emailsService.getEmailById(userId, emailId);
    if (!email) {
      return null;
    }

    const rules = await this.getSummarizationRules(userId);
    if (rules.length === 0) {
      return null;
    }

    // Clean email content for matching
    // Cast to EmailWithHtmlBody to access htmlBody which exists on the entity
    const emailWithHtml = email as EmailWithHtmlBody;
    const cleanedBody = cleanEmailContent(email.body, emailWithHtml.htmlBody);

    // Fast path: Check for exact domain matches (e.g., "emails from @company.com")
    // This is a simple optimization for obvious cases, but we still use LLM for semantic matching
    const fromLower = (email.from || "").toLowerCase();
    for (const rule of rules) {
      const whenToUseLower = rule.whenToUse.toLowerCase();
      const domainMatch = whenToUseLower.match(/@([a-z0-9.-]+)/i);
      if (domainMatch) {
        const domain = domainMatch[1].toLowerCase();
        // Extract domain from email address
        const emailDomain = fromLower
          .match(/@([a-z0-9.-]+)/i)?.[1]
          ?.toLowerCase();
        if (emailDomain === domain) {
          // Exact domain match - this is reliable enough to use without LLM
          return rule;
        }
      }
    }

    // Primary method: Use LLM to evaluate which rule matches based on whenToUse criteria
    try {
      // Prepare email context (use more content for better matching)
      // Increased from 1000 for better context
      const emailPreview = cleanedBody.substring(0, 2000);
      const emailText = `Subject: ${email.subject || "(no subject)"}\nFrom: ${email.fromName || email.from || "(unknown sender)"} <${email.from || ""}>\n\nEmail Body:\n${emailPreview}${cleanedBody.length > 2000 ? "\n\n[... email continues ...]" : ""}`;

      // Format rules with their whenToUse criteria
      const ruleDescriptions = rules
        .map((rule, index) => `Rule ${index + 1}: "${rule.whenToUse}"`)
        .join("\n");

      const prompt = `You are evaluating which summarization rule should be applied to an email based on the "whenToUse" criteria for each rule.

Email to evaluate:
${emailText}

Available summarization rules (each has a "whenToUse" description that explains when it should be applied):
${ruleDescriptions}

Your task:
1. Carefully read the "whenToUse" criteria for each rule
2. Determine if the email matches any of the rules based on their "whenToUse" descriptions
3. Consider the email's subject, sender, and content when evaluating matches
4. If the email clearly matches a rule's "whenToUse" criteria, return that rule's number (1-${rules.length})
5. If no rule clearly matches, return "0"

Examples:
- If a rule says "Github emails" and the email is from GitHub (e.g., notifications@github.com, noreply@github.com) or contains GitHub-related content, it matches
- If a rule says "emails from @company.com" and the sender's domain is company.com, it matches
- If a rule says "newsletter emails" and the email is clearly a newsletter, it matches

Respond with ONLY the rule number (1-${rules.length}) or "0" if no match. Do not include any explanation or other text.`;

      // Lower temperature for more consistent matching
      // Just need a number
      const response = await this.llmService.generateText(
        {
          prompt,
          systemPrompt:
            "You are a precise assistant that evaluates whether emails match rule criteria. You respond with only a number: the rule number (1-N) if a match is found, or 0 if no rule matches.",
          temperature: 0.1,
          maxTokens: 5,
          userId,
        },
        undefined,
        userId,
      );

      // Parse response - handle various formats the LLM might return
      // Extract only digits
      const cleanedResponse = response.trim().replace(/[^0-9]/g, "");
      const ruleIndex = parseInt(cleanedResponse, 10) - 1;

      if (ruleIndex >= 0 && ruleIndex < rules.length) {
        return rules[ruleIndex];
      }

      // If LLM returned 0 or invalid response, no rule matches
      if (cleanedResponse === "0") {
        // No matching rule found
        return null;
      }

      // If response is invalid, log and fall through to fallback
      console.warn(
        `LLM returned invalid rule index: "${response.trim()}", parsed as: ${ruleIndex}`,
      );
    } catch (error) {
      console.error("LLM rule matching failed:", error);
      // Fall through to fallback
    }

    // Fallback: If LLM fails or returns invalid response, return first rule
    // This ensures the system still works even if LLM is unavailable
    return rules[0];
  }

  private fallbackSummary(
    text: string,
    subject: string,
    type: string,
    sender: string,
  ): string {
    const sentences = text
      .split(/[.!?]+/)
      .filter((sentence) => sentence.trim().length > 0);

    switch (type) {
      case "bullet-points":
        return (
          sentences
            .slice(0, 5)
            .map((sentence) => `• ${sentence.trim()}`)
            .join("\n") || "• No key points found"
        );
      case "action-items":
        const actionKeywords = [
          "please",
          "need",
          "should",
          "must",
          "action",
          "do",
          "complete",
        ];
        const actionSentences = sentences
          .filter((sentence) =>
            actionKeywords.some((keyword) =>
              sentence.toLowerCase().includes(keyword),
            ),
          )
          .slice(0, 5)
          .map((sentence) => `• ${sentence.trim()}`)
          .join("\n");
        return actionSentences || "• No action items found";
      case "sender-request":
        return `From ${sender}: ${sentences[0]?.trim() || "No specific request found."}`;
      case "tldr":
      default:
        const summary =
          sentences[0]?.substring(0, 200) || text.substring(0, 200);
        return `TL;DR: ${summary}${summary.length >= 200 ? "..." : ""}`;
    }
  }
}

import { Request } from "express";

/**
 * Common type definitions to replace `any` types throughout the codebase
 */

/**
 * Standard error type for catch blocks
 * Use instead of: catch (error: unknown)
 */
export type StandardError = Error | unknown;

/**
 * JWT payload returned by JwtStrategy.validate()
 * This is what gets attached to req.user after JWT authentication
 */
export interface JwtUserPayload {
  userId: string;
  email: string;
}

/**
 * Request with authenticated user from JWT
 * Use this instead of `@Request() req` with `(req.user as any).userId`
 */
export interface AuthenticatedRequest extends Request {
  user: JwtUserPayload;
}

/**
 * Error with optional code property (common in Node.js errors)
 */
export interface ErrorWithCode extends Error {
  code?: string | number;
}

/**
 * Type guard to check if an error has a code property
 */
export function isErrorWithCode(error: unknown): error is ErrorWithCode {
  return error instanceof Error && "code" in error;
}

/**
 * Email entity with optional htmlBody (used in summarization)
 */
export interface EmailWithHtmlBody {
  body: string;
  htmlBody?: string;
  subject?: string;
  from?: string;
  fromName?: string;
  threadId?: string;
  receivedAt?: Date | string;
}

/**
 * LLM provider type
 */
export type LLMProvider = "gemini" | "openai" | undefined;

/**
 * Google API response types
 */
export interface GoogleApiResponse<T = unknown> {
  // eslint-disable-next-line id-denylist
  data: T;
  status?: number;
  statusText?: string;
  headers?: Record<string, string>;
}

/**
 * Google People API response types
 */
export interface GooglePeopleResponse {
  connections?: Array<{
    resourceName?: string;
    emailAddresses?: Array<{ value?: string }>;
    names?: Array<{
      displayName?: string;
      givenName?: string;
      familyName?: string;
    }>;
    phoneNumbers?: Array<{ value?: string }>;
    organizations?: Array<{
      name?: string;
      title?: string;
    }>;
    photos?: Array<{ url?: string }>;
  }>;
  nextPageToken?: string;
}

/**
 * Google Gmail API response types
 */
export interface GmailMessage {
  id: string;
  threadId: string;
  labelIds?: string[];
  snippet?: string;
  payload?: {
    headers?: Array<{ name: string; value: string }>;
    body?: {
      // eslint-disable-next-line id-denylist
      data?: string;
    };
    parts?: Array<{
      mimeType?: string;
      body?: {
        // eslint-disable-next-line id-denylist
        data?: string;
      };
      parts?: Array<{
        mimeType?: string;
        body?: {
          // eslint-disable-next-line id-denylist
          data?: string;
        };
      }>;
    }>;
  };
  internalDate?: string;
}

export interface GmailThread {
  id: string;
  messages?: GmailMessage[];
  historyId?: string;
}

export interface GmailListResponse {
  messages?: Array<{ id: string; threadId: string }>;
  nextPageToken?: string;
  resultSizeEstimate?: number;
}

/**
 * GitHub API response types
 */
export interface GitHubIssueResponse {
  number: number;
  title: string;
  state: "open" | "closed";
  body?: string;
  user?: {
    login: string;
  };
  assignees?: Array<{ login: string }>;
  labels?: Array<{ name: string }>;
  pull_request?: {
    url: string;
  };
}

export interface GitHubPullRequestResponse extends GitHubIssueResponse {
  merged?: boolean;
  mergeable?: boolean;
  review_comments?: number;
  commits?: number;
  additions?: number;
  deletions?: number;
}

/**
 * Generic API error response
 */
export interface ApiError {
  code?: number | string;
  message?: string;
  error?: string;
  errors?: Array<{ message: string; domain?: string; reason?: string }>;
  status?: number;
  statusText?: string;
  response?: {
    statusText?: string;
    // eslint-disable-next-line id-denylist
    data?: unknown;
  };
}

/**
 * Type guard to check if error is an ApiError
 */
export function isApiError(error: unknown): error is ApiError {
  return (
    typeof error === "object" &&
    error !== null &&
    ("code" in error || "message" in error || "error" in error)
  );
}

/**
 * Type guard to check if error is a standard Error
 */
export function isError(error: unknown): error is Error {
  return error instanceof Error;
}

/**
 * Database error type (PostgreSQL/TypeORM errors)
 */
export interface DatabaseError {
  code?: string;
  message?: string;
}

/**
 * Type guard to check if error is a DatabaseError
 */
export function isDatabaseError(error: unknown): error is DatabaseError {
  return (
    typeof error === "object" &&
    error !== null &&
    ("code" in error || "message" in error)
  );
}

/**
 * Safely extract error message from unknown error
 */
export function getErrorMessage(error: unknown): string {
  if (isError(error)) {
    return error.message;
  }
  if (isApiError(error)) {
    return error.message || error.error || "Unknown API error";
  }
  if (typeof error === "string") {
    return error;
  }
  return "Unknown error";
}

/**
 * Gaxios error structure (Google API client errors)
 */
export interface GaxiosErrorDetails {
  status?: number;
  statusText?: string;
  message?: string;
  errorMessage?: string;
  errorReason?: string;
  errorDomain?: string;
  responseData?: unknown;
  requestUrl?: string;
  requestMethod?: string;
}

/**
 * Type guard to check if error is a Gaxios error (Google API client error)
 */
export function isGaxiosError(error: unknown): error is {
  response?: { status?: number; statusText?: string; data?: unknown };
  config?: { url?: string; method?: string };
  message?: string;
} {
  return (
    typeof error === "object" &&
    error !== null &&
    "response" in error &&
    typeof (error as { response?: unknown }).response === "object"
  );
}

/**
 * Extract detailed error information from Gaxios/Google API errors
 * This is useful for debugging Gmail API errors which often have empty messages
 * but contain useful info in response.data
 */
export function getGaxiosErrorDetails(error: unknown): GaxiosErrorDetails {
  const details: GaxiosErrorDetails = {};

  if (!isGaxiosError(error)) {
    // Not a Gaxios error, return basic info
    if (isError(error)) {
      details.message = error.message;
    } else if (typeof error === "string") {
      details.message = error;
    }
    return details;
  }

  // Extract response info
  if (error.response) {
    details.status = error.response.status;
    details.statusText = error.response.statusText;
    details.responseData = error.response.data;

    // Try to extract error message from response data
    const data = error.response.data as {
      error?: {
        message?: string;
        code?: number;
        errors?: Array<{ message?: string; reason?: string; domain?: string }>;
      };
    };
    if (data?.error) {
      details.errorMessage = data.error.message;
      if (data.error.errors && data.error.errors.length > 0) {
        details.errorReason = data.error.errors[0].reason;
        details.errorDomain = data.error.errors[0].domain;
      }
    }
  }

  // Extract request info
  if (error.config) {
    details.requestUrl = error.config.url;
    details.requestMethod = error.config.method;
  }

  // Include the error message if present
  if (error.message) {
    details.message = error.message;
  }

  return details;
}

/**
 * Format Gaxios error details into a human-readable string for logging
 */
export function formatGaxiosError(error: unknown): string {
  const details = getGaxiosErrorDetails(error);

  const parts: string[] = [];

  if (details.status) {
    parts.push(`HTTP ${details.status}`);
    if (details.statusText) {
      parts.push(`(${details.statusText})`);
    }
  }

  if (details.errorMessage) {
    parts.push(`- ${details.errorMessage}`);
  } else if (details.message) {
    parts.push(`- ${details.message}`);
  }

  if (details.errorReason) {
    parts.push(`[reason: ${details.errorReason}]`);
  }

  if (details.requestUrl) {
    parts.push(`| URL: ${details.requestUrl}`);
  }

  if (parts.length === 0) {
    // Fallback: stringify the whole error
    try {
      return JSON.stringify(error, Object.getOwnPropertyNames(error));
    } catch {
      return "Unknown error (could not stringify)";
    }
  }

  return parts.join(" ");
}

import {
  Injectable,
  BadRequestException,
  NotFoundException,
  Logger,
} from "@nestjs/common";
import { InjectRepository } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { User } from "../database/entities/user.entity";
import {
  UserContext,
  ContextKey,
  Source,
} from "../database/entities/user-context.entity";
import { BatchSchedule } from "../database/entities/batch-schedule.entity";
import { BlockedSender } from "../database/entities/blocked-sender.entity";
import { BlockedKeyword } from "../database/entities/blocked-keyword.entity";
import { SummarizationRule } from "../database/entities/summarization-rule.entity";
import { EncryptionHelper } from "../encryption/encryption.helper";
import { ExportedUserData } from "./data-export.service";
import { AutoResponderConfig } from "../auto-responder/types/auto-responder.types";

export interface ImportOptions {
  /** Whether to replace existing data or merge with it */
  mergeMode: "replace" | "merge";
  /** Which sections to import */
  sections: {
    profile?: boolean;
    batchSchedule?: boolean;
    blockedSenders?: boolean;
    blockedKeywords?: boolean;
    contexts?: boolean;
    toneRules?: boolean;
    summarizationRules?: boolean;
    autoResponderSettings?: boolean;
  };
}

export interface ImportResult {
  success: boolean;
  imported: {
    profile: boolean;
    batchSchedule: boolean;
    blockedSenders: number;
    blockedKeywords: number;
    contexts: number;
    toneRules: number;
    summarizationRules: number;
    autoResponderSettings: boolean;
  };
  skipped: {
    blockedSenders: number;
    blockedKeywords: number;
    contexts: number;
  };
  errors: string[];
}

const DEFAULT_IMPORT_OPTIONS: ImportOptions = {
  mergeMode: "merge",
  sections: {
    profile: true,
    batchSchedule: true,
    blockedSenders: true,
    blockedKeywords: true,
    contexts: true,
    toneRules: true,
    summarizationRules: true,
    autoResponderSettings: true,
  },
};

@Injectable()
export class DataImportService {
  private readonly logger = new Logger(DataImportService.name);

  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
    @InjectRepository(UserContext)
    private userContextRepository: Repository<UserContext>,
    @InjectRepository(BatchSchedule)
    private batchScheduleRepository: Repository<BatchSchedule>,
    @InjectRepository(BlockedSender)
    private blockedSenderRepository: Repository<BlockedSender>,
    @InjectRepository(BlockedKeyword)
    private blockedKeywordRepository: Repository<BlockedKeyword>,
    @InjectRepository(SummarizationRule)
    private summarizationRuleRepository: Repository<SummarizationRule>,
  ) {}

  /**
   * Validate the imported data structure
   */
  private validateImportData(data: unknown): ExportedUserData {
    if (!data || typeof data !== "object") {
      throw new BadRequestException(
        "Invalid import data: must be a JSON object",
      );
    }

    const importData = data as Record<string, unknown>;

    // Check required fields
    if (!importData.version) {
      throw new BadRequestException(
        "Invalid import data: missing version field",
      );
    }

    if (!importData.exportedAt) {
      throw new BadRequestException(
        "Invalid import data: missing exportedAt field",
      );
    }

    // Validate version compatibility
    const version = importData.version as string;
    if (!version.startsWith("1.")) {
      throw new BadRequestException(
        `Incompatible import version: ${version}. Expected version 1.x`,
      );
    }

    return importData as unknown as ExportedUserData;
  }

  /**
   * Import user data from a JSON export
   */
  async importUserData(
    userId: string,
    data: unknown,
    options: Partial<ImportOptions> = {},
  ): Promise<ImportResult> {
    const mergedOptions: ImportOptions = {
      ...DEFAULT_IMPORT_OPTIONS,
      ...options,
      sections: {
        ...DEFAULT_IMPORT_OPTIONS.sections,
        ...options.sections,
      },
    };

    const importData = this.validateImportData(data);
    const result: ImportResult = {
      success: true,
      imported: {
        profile: false,
        batchSchedule: false,
        blockedSenders: 0,
        blockedKeywords: 0,
        contexts: 0,
        toneRules: 0,
        summarizationRules: 0,
        autoResponderSettings: false,
      },
      skipped: {
        blockedSenders: 0,
        blockedKeywords: 0,
        contexts: 0,
      },
      errors: [],
    };

    // Verify user exists
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException("User not found");
    }

    try {
      // Import profile
      if (mergedOptions.sections.profile && importData.profile) {
        await this.importProfile(userId, importData.profile);
        result.imported.profile = true;
      }

      // Import batch schedule
      if (mergedOptions.sections.batchSchedule && importData.batchSchedule) {
        await this.importBatchSchedule(
          userId,
          importData.batchSchedule,
          mergedOptions.mergeMode,
        );
        result.imported.batchSchedule = true;
      }

      // Import blocked senders
      if (mergedOptions.sections.blockedSenders && importData.blockedSenders) {
        const { imported, skipped } = await this.importBlockedSenders(
          userId,
          importData.blockedSenders,
          mergedOptions.mergeMode,
        );
        result.imported.blockedSenders = imported;
        result.skipped.blockedSenders = skipped;
      }

      // Import blocked keywords
      if (
        mergedOptions.sections.blockedKeywords &&
        importData.blockedKeywords
      ) {
        const { imported, skipped } = await this.importBlockedKeywords(
          userId,
          importData.blockedKeywords,
          mergedOptions.mergeMode,
        );
        result.imported.blockedKeywords = imported;
        result.skipped.blockedKeywords = skipped;
      }

      // Import contexts
      if (mergedOptions.sections.contexts && importData.contexts) {
        const { imported, skipped } = await this.importContexts(
          userId,
          importData.contexts,
          mergedOptions.mergeMode,
        );
        result.imported.contexts = imported;
        result.skipped.contexts = skipped;
      }

      // Import tone rules
      if (mergedOptions.sections.toneRules && importData.toneRules) {
        await this.importToneRules(
          userId,
          importData.toneRules,
          mergedOptions.mergeMode,
        );
        result.imported.toneRules = importData.toneRules.length;
      }

      // Import summarization rules
      if (
        mergedOptions.sections.summarizationRules &&
        importData.summarizationRules
      ) {
        const imported = await this.importSummarizationRules(
          userId,
          importData.summarizationRules,
          mergedOptions.mergeMode,
        );
        result.imported.summarizationRules = imported;
      }

      // Import auto-responder settings
      if (
        mergedOptions.sections.autoResponderSettings &&
        importData.autoResponderSettings
      ) {
        await this.importAutoResponderSettings(
          userId,
          importData.autoResponderSettings,
        );
        result.imported.autoResponderSettings = true;
      }

      this.logger.log(
        `Successfully imported data for user ${userId}: ${JSON.stringify(result.imported)}`,
      );
    } catch (error) {
      this.logger.error(`Error importing data for user ${userId}:`, error);
      result.success = false;
      result.errors.push(
        error instanceof Error ? error.message : "Unknown error during import",
      );
    }

    return result;
  }

  private async importProfile(
    userId: string,
    profile: ExportedUserData["profile"],
  ): Promise<void> {
    const updates: Partial<User> = {};

    if (profile.displayName !== undefined) {
      updates.displayName = profile.displayName;
    }
    if (profile.jobTitle !== undefined) {
      updates.jobTitle = profile.jobTitle;
    }

    if (Object.keys(updates).length > 0) {
      await this.userRepository.update(userId, updates);
    }
  }

  private async importBatchSchedule(
    userId: string,
    schedule: NonNullable<ExportedUserData["batchSchedule"]>,
    mergeMode: "replace" | "merge",
  ): Promise<void> {
    const existing = await this.batchScheduleRepository.findOne({
      where: { userId },
    });

    if (existing) {
      if (mergeMode === "replace") {
        await this.batchScheduleRepository.update(existing.id, {
          deliveryDays: schedule.deliveryDays,
          deliveryTimes: schedule.deliveryTimes,
          timezone: schedule.timezone,
          isEnabled: schedule.isEnabled,
          urgentBypassSchedule: schedule.urgentBypassSchedule,
        });
      } else {
        // In merge mode, only update fields that have meaningful values
        await this.batchScheduleRepository.update(existing.id, {
          deliveryDays: schedule.deliveryDays,
          deliveryTimes: schedule.deliveryTimes,
          timezone: schedule.timezone,
          isEnabled: schedule.isEnabled,
          urgentBypassSchedule: schedule.urgentBypassSchedule,
        });
      }
    } else {
      await this.batchScheduleRepository.save({
        userId,
        deliveryDays: schedule.deliveryDays,
        deliveryTimes: schedule.deliveryTimes,
        timezone: schedule.timezone,
        isEnabled: schedule.isEnabled,
        urgentBypassSchedule: schedule.urgentBypassSchedule,
      });
    }
  }

  private async importBlockedSenders(
    userId: string,
    senders: ExportedUserData["blockedSenders"],
    mergeMode: "replace" | "merge",
  ): Promise<{ imported: number; skipped: number }> {
    if (mergeMode === "replace") {
      await this.blockedSenderRepository.delete({ userId });
    }

    let imported = 0;
    let skipped = 0;

    for (const sender of senders) {
      const emailHash = EncryptionHelper.hashEmail(sender.email);

      // Check if already exists
      const existing = await this.blockedSenderRepository.findOne({
        where: { userId, emailHash },
      });

      if (existing) {
        skipped++;
        continue;
      }

      // Extract domain hash if email contains @
      let domainHash: string | undefined;
      if (sender.email.includes("@")) {
        const domain = sender.email.split("@")[1];
        if (domain) {
          domainHash = EncryptionHelper.hashEmail(domain);
        }
      }

      await this.blockedSenderRepository.save({
        userId,
        email: sender.email,
        emailHash,
        domainHash,
        senderName: sender.senderName,
        reason: sender.reason,
        blockedAt: new Date(sender.blockedAt),
      });

      imported++;
    }

    return { imported, skipped };
  }

  private async importBlockedKeywords(
    userId: string,
    keywords: ExportedUserData["blockedKeywords"],
    mergeMode: "replace" | "merge",
  ): Promise<{ imported: number; skipped: number }> {
    if (mergeMode === "replace") {
      await this.blockedKeywordRepository.delete({ userId });
    }

    let imported = 0;
    let skipped = 0;

    for (const keyword of keywords) {
      const keywordHash = EncryptionHelper.hashEmail(
        keyword.keyword.toLowerCase(),
      );

      // Check if already exists
      const existing = await this.blockedKeywordRepository.findOne({
        where: { userId, keywordHash },
      });

      if (existing) {
        skipped++;
        continue;
      }

      await this.blockedKeywordRepository.save({
        userId,
        keyword: keyword.keyword,
        keywordHash,
        exactMatch: keyword.exactMatch,
        reason: keyword.reason,
        blockedAt: new Date(keyword.blockedAt),
      });

      imported++;
    }

    return { imported, skipped };
  }

  private async importContexts(
    userId: string,
    contexts: ExportedUserData["contexts"],
    mergeMode: "replace" | "merge",
  ): Promise<{ imported: number; skipped: number }> {
    if (mergeMode === "replace") {
      await this.userContextRepository.delete({ userId });
    }

    let imported = 0;
    let skipped = 0;

    for (const context of contexts) {
      // Validate context key is a valid enum value
      if (
        !Object.values(ContextKey).includes(context.contextKey as ContextKey)
      ) {
        this.logger.warn(`Skipping invalid context key: ${context.contextKey}`);
        skipped++;
        continue;
      }

      // Check for duplicate in merge mode
      if (mergeMode === "merge") {
        const existing = await this.userContextRepository.findOne({
          where: {
            userId,
            contextKey: context.contextKey as ContextKey,
            contextValue: context.contextValue,
          },
        });

        if (existing) {
          skipped++;
          continue;
        }
      }

      // Validate source is a valid enum value
      const source =
        context.source === "USER_EDITED"
          ? Source.USER_EDITED
          : Source.AUTOGENERATED;

      await this.userContextRepository.save({
        userId,
        contextKey: context.contextKey as ContextKey,
        contextValue: context.contextValue,
        priority: context.priority,
        source,
        explanation: context.explanation,
      });

      imported++;
    }

    return { imported, skipped };
  }

  private async importToneRules(
    userId: string,
    toneRules: string[],
    mergeMode: "replace" | "merge",
  ): Promise<void> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user) {
      throw new NotFoundException("User not found");
    }

    if (mergeMode === "replace") {
      await this.userRepository.update(userId, {
        toneSettings: { rules: toneRules },
      });
    } else {
      // Merge: combine existing rules with new ones, avoiding duplicates
      const existingRules = user.toneSettings?.rules || [];
      const mergedRules = [...new Set([...existingRules, ...toneRules])];
      await this.userRepository.update(userId, {
        toneSettings: { rules: mergedRules },
      });
    }
  }

  private async importSummarizationRules(
    userId: string,
    rules: ExportedUserData["summarizationRules"],
    mergeMode: "replace" | "merge",
  ): Promise<number> {
    if (mergeMode === "replace") {
      await this.summarizationRuleRepository.delete({ userId });
    }

    let imported = 0;

    for (const rule of rules) {
      // Check for duplicate in merge mode
      if (mergeMode === "merge") {
        const existing = await this.summarizationRuleRepository.findOne({
          where: {
            userId,
            whenToUse: rule.whenToUse,
            howToSummarize: rule.howToSummarize,
          },
        });

        if (existing) {
          continue;
        }
      }

      await this.summarizationRuleRepository.save({
        userId,
        whenToUse: rule.whenToUse,
        howToSummarize: rule.howToSummarize,
      });

      imported++;
    }

    return imported;
  }

  private async importAutoResponderSettings(
    userId: string,
    settings: AutoResponderConfig,
  ): Promise<void> {
    await this.userRepository.update(userId, {
      autoResponderSettings: settings,
    });
  }
}

