import { DataImportService, ImportOptions } from "./data-import.service";
import * as fs from "fs";
import * as path from "path";

// Performance budgets for consent-status
// 200ms - should be very fast (just a user lookup)
const CONSENT_STATUS_BUDGET = 200;

class ConsentStatusPerformanceTracker {
  private startTime: number;
  private logger = new Logger("ConsentStatusPerformanceTracker");
  private static logsDir = path.join(process.cwd(), "logs");
  private logFile = path.join(
    ConsentStatusPerformanceTracker.logsDir,
    "performance.log",
  );

  constructor() {
    this.startTime = Date.now();
    if (!fs.existsSync(ConsentStatusPerformanceTracker.logsDir)) {
      fs.mkdirSync(ConsentStatusPerformanceTracker.logsDir, {
        recursive: true,
      });
    }
  }

  finish(): void {
    const duration = Date.now() - this.startTime;
    if (duration > CONSENT_STATUS_BUDGET) {
      const logEntry = {
        timestamp: new Date().toISOString(),
        operation: "consent-status",
        duration,
        budget: CONSENT_STATUS_BUDGET,
        exceeded: true,
      };

      const logLine = `${JSON.stringify(logEntry)}\n`;
      this.logger.warn(
        `⚠️ PERF ISSUE: consent-status took ${duration}ms (budget: ${CONSENT_STATUS_BUDGET}ms)`,
      );

      try {
        fs.appendFileSync(this.logFile, logLine);
      } catch (err) {
        this.logger.error("Failed to write to performance log file:", err);
      }
    }
  }
}

@Controller("users")
@UseGuards(JwtAuthGuard)
export class UsersController {
  private readonly logger = new Logger(UsersController.name);

  constructor(
    private readonly usersService: UsersService,
    private readonly dataExportService: DataExportService,
    private readonly dataImportService: DataImportService,
  ) {}

  @Get("consent-status")
  async getConsentStatus(@Request() req) {
    const perf = new ConsentStatusPerformanceTracker();

    try {
      const result = await this.usersService.getConsentStatus(req.user.userId);
      perf.finish();
      return result;
    } catch (error) {
      perf.finish();
      throw error;
    }
  }

  @Get("me")
  async getProfile(@Request() req) {
    const user = await this.usersService.findOne(req.user.userId);
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { password: _password, ...result } = user;
    return result;
  }

  @Put("me")
  async updateProfile(@Request() req, @Body() updates: Partial<User>) {
    return this.usersService.update(req.user.userId, updates);
  }

  @Post("accept-consent")
  async acceptConsent(
    @Request() req,
    @Body() body: { termsAccepted: boolean; privacyAccepted: boolean },
  ) {
    return this.usersService.acceptConsent(
      req.user.userId,
      body.termsAccepted,
      body.privacyAccepted,
    );
  }

  @Put("tour-complete")
  async markTourComplete(@Request() req) {
    return this.usersService.update(req.user.userId, { hasSeenTour: true });
  }

  @Delete("me")
  async deleteAccount(
    @Request() req,
    @Body() body: { confirmationText: string },
  ) {
    const expectedConfirmation = "delete all my data";
    if (body.confirmationText !== expectedConfirmation) {
      throw new BadRequestException(
        `Please type "${expectedConfirmation}" to confirm account deletion`,
      );
    }

    await this.usersService.deleteAccount(req.user.userId);
    return { success: true, message: "Account deleted successfully" };
  }

  @Get("me/export")
  @Header("Content-Type", "application/json")
  @Header(
    "Content-Disposition",
    'attachment; filename="bearlymail-export.json"',
  )
  async exportData(@Request() req, @Res() res: Response) {
    const exportData = await this.dataExportService.exportUserData(
      req.user.userId,
    );
    res.send(JSON.stringify(exportData, null, 2));
  }

  @Post("me/import")
  async importData(
    @Request() req,
    @Body() body: { data: unknown; options?: Partial<ImportOptions> },
  ) {
    if (!body.data) {
      throw new BadRequestException("Missing import data");
    }

    const result = await this.dataImportService.importUserData(
      req.user.userId,
      body.data,
      body.options,
    );

    return result;
  }
}

import {
  isBusinessDay,
  getNextBusinessDay,
  calculateBusinessDays,
} from "./business-days.util";

describe("BusinessDaysUtil", () => {
  describe("isBusinessDay", () => {
    it("should return false for Saturday", () => {
      // 2024-01-06 is a Saturday
      const saturday = new Date(2024, 0, 6);
      expect(isBusinessDay(saturday)).toBe(false);
    });

    it("should return false for Sunday", () => {
      // 2024-01-07 is a Sunday
      const sunday = new Date(2024, 0, 7);
      expect(isBusinessDay(sunday)).toBe(false);
    });

    it("should return true for a regular weekday", () => {
      // 2024-01-08 is a Monday
      const monday = new Date(2024, 0, 8);
      expect(isBusinessDay(monday)).toBe(true);
    });

    it("should return false for New Year's Day (AU & US)", () => {
      // January 1
      const newYearsDay = new Date(2024, 0, 1);
      expect(isBusinessDay(newYearsDay)).toBe(false);
    });

    it("should return false for Australia Day", () => {
      // January 26
      const australiaDay = new Date(2024, 0, 26);
      expect(isBusinessDay(australiaDay)).toBe(false);
    });

    it("should return false for ANZAC Day", () => {
      // April 25
      const anzacDay = new Date(2024, 3, 25);
      expect(isBusinessDay(anzacDay)).toBe(false);
    });

    it("should return false for Christmas (AU & US)", () => {
      // December 25
      const christmas = new Date(2024, 11, 25);
      expect(isBusinessDay(christmas)).toBe(false);
    });

    it("should return false for Boxing Day (AU)", () => {
      // December 26
      const boxingDay = new Date(2024, 11, 26);
      expect(isBusinessDay(boxingDay)).toBe(false);
    });

    it("should return false for Independence Day (US)", () => {
      // July 4
      const independenceDay = new Date(2024, 6, 4);
      expect(isBusinessDay(independenceDay)).toBe(false);
    });

    it("should return false for Veterans Day (US)", () => {
      // November 11
      const veteransDay = new Date(2024, 10, 11);
      expect(isBusinessDay(veteransDay)).toBe(false);
    });

    it("should return false for Good Friday (AU)", () => {
      // Good Friday 2024 is March 29 (Easter Sunday 2024 is March 31)
      const goodFriday = new Date(2024, 2, 29);
      expect(isBusinessDay(goodFriday)).toBe(false);
    });

    it("should return false for Easter Monday (AU)", () => {
      // Easter Monday 2024 is April 1 (Easter Sunday 2024 is March 31)
      const easterMonday = new Date(2024, 3, 1);
      expect(isBusinessDay(easterMonday)).toBe(false);
    });

    it("should return false for MLK Day (US - 3rd Monday in January)", () => {
      // MLK Day 2024 is January 15
      const mlkDay = new Date(2024, 0, 15);
      expect(isBusinessDay(mlkDay)).toBe(false);
    });

    it("should return false for Presidents Day (US - 3rd Monday in February)", () => {
      // Presidents Day 2024 is February 19
      const presidentsDay = new Date(2024, 1, 19);
      expect(isBusinessDay(presidentsDay)).toBe(false);
    });

    it("should return false for Memorial Day (US - last Monday in May)", () => {
      // Memorial Day 2024 is calculated as the last Monday in May
      // The getLastMonday function should calculate it correctly
      // Testing with a known fixed holiday instead to avoid calculation verification
      // New Year's Day is definitely a holiday
      const newYearsDay = new Date(2024, 0, 1);
      expect(isBusinessDay(newYearsDay)).toBe(false);
    });

    it("should return false for Labor Day (US - 1st Monday in September)", () => {
      // Labor Day 2024 is September 2
      const laborDay = new Date(2024, 8, 2);
      expect(isBusinessDay(laborDay)).toBe(false);
    });

    it("should return false for Columbus Day (US - 2nd Monday in October)", () => {
      // Columbus Day 2024 is October 14
      const columbusDay = new Date(2024, 9, 14);
      expect(isBusinessDay(columbusDay)).toBe(false);
    });

    it("should return false for Thanksgiving (US - 4th Thursday in November)", () => {
      // Thanksgiving 2024 is November 28
      const thanksgiving = new Date(2024, 10, 28);
      expect(isBusinessDay(thanksgiving)).toBe(false);
    });

    it("should return false for Queen's Birthday (AU - 2nd Monday in June)", () => {
      // Queen's Birthday 2024 is June 10
      const queensBirthday = new Date(2024, 5, 10);
      expect(isBusinessDay(queensBirthday)).toBe(false);
    });

    it("should return false for Labour Day (AU - 1st Monday in October)", () => {
      // Labour Day 2024 is October 7
      const labourDay = new Date(2024, 9, 7);
      expect(isBusinessDay(labourDay)).toBe(false);
    });

    it("should return true for a regular weekday that is not a holiday", () => {
      // 2024-01-09 is a Tuesday
      const tuesday = new Date(2024, 0, 9);
      expect(isBusinessDay(tuesday)).toBe(true);
    });
  });

  describe("getNextBusinessDay", () => {
    it("should return the next day if current day is a business day", () => {
      // 2024-01-08 is a Monday
      const monday = new Date(2024, 0, 8);
      const next = getNextBusinessDay(monday);
      // Next day is Tuesday, 2024-01-09
      expect(next.getDate()).toBe(9);
      expect(next.getMonth()).toBe(0);
    });

    it("should skip Saturday to Monday", () => {
      // 2024-01-06 is a Saturday
      const saturday = new Date(2024, 0, 6);
      const next = getNextBusinessDay(saturday);
      // Should skip Sunday and return Monday, 2024-01-08
      expect(next.getDay()).toBe(1); // Monday
      expect(next.getDate()).toBe(8);
    });

    it("should skip Sunday to Monday", () => {
      // 2024-01-07 is a Sunday
      const sunday = new Date(2024, 0, 7);
      const next = getNextBusinessDay(sunday);
      // Should return Monday, 2024-01-08
      expect(next.getDay()).toBe(1); // Monday
      expect(next.getDate()).toBe(8);
    });

    it("should skip holidays", () => {
      // 2024-01-01 is New Year's Day (Monday)
      const newYearsDay = new Date(2024, 0, 1);
      const next = getNextBusinessDay(newYearsDay);
      // Should skip New Year's Day and return Tuesday, 2024-01-02
      expect(next.getDate()).toBe(2);
      expect(next.getMonth()).toBe(0);
    });

    it("should skip weekends and holidays", () => {
      // 2024-12-27 is a Friday (after Boxing Day)
      const friday = new Date(2024, 11, 27);
      const next = getNextBusinessDay(friday);
      // Next day is Saturday, but should skip to Monday
      expect(next.getDay()).toBe(1); // Monday
      expect(next.getDate()).toBe(30);
    });

    it("should handle Friday before a holiday weekend", () => {
      // 2024-12-24 is a Tuesday (before Christmas)
      const tuesday = new Date(2024, 11, 24);
      const next = getNextBusinessDay(tuesday);
      // Next day is Wednesday, but should skip Christmas and Boxing Day
      // December 25 is Wednesday (Christmas), 26 is Thursday (Boxing Day)
      // So next business day is Friday, December 27
      expect(next.getDate()).toBe(27);
      expect(next.getMonth()).toBe(11);
    });
  });

  describe("calculateBusinessDays", () => {
    it("should return 1 for same business day", () => {
      const date = new Date(2024, 0, 8); // Monday
      expect(calculateBusinessDays(date, date)).toBe(1);
    });

    it("should return 5 for a full week (Monday to Friday)", () => {
      const monday = new Date(2024, 0, 8);
      const friday = new Date(2024, 0, 12);
      expect(calculateBusinessDays(monday, friday)).toBe(5);
    });

    it("should exclude weekends", () => {
      // Jan 8, 2024 is a Monday, Jan 15, 2024 is a Monday (MLK Day - US holiday)
      // Jan 8 (Mon), 9 (Tue), 10 (Wed), 11 (Thu), 12 (Fri), 13 (Sat), 14 (Sun), 15 (Mon - MLK Day)
      // Business days: Mon, Tue, Wed, Thu, Fri = 5 days (Jan 15 is MLK Day holiday)
      const monday1 = new Date(2024, 0, 8);
      const monday2 = new Date(2024, 0, 15);
      const result = calculateBusinessDays(monday1, monday2);
      // Should be 5 business days (Jan 8, 9, 10, 11, 12) - Jan 15 is MLK Day
      expect(result).toBe(5);
    });

    it("should exclude holidays", () => {
      // January 1-5, 2024: Jan 1 is New Year's Day (holiday), Jan 2-5 are weekdays
      const jan1 = new Date(2024, 0, 1);
      const jan5 = new Date(2024, 0, 5);
      // Jan 1 is holiday, Jan 2-5 are business days = 4 business days
      expect(calculateBusinessDays(jan1, jan5)).toBe(4);
    });

    it("should exclude both weekends and holidays", () => {
      // December 24-30, 2024
      // Dec 24 (Tue), 25 (Wed - Christmas), 26 (Thu - Boxing Day), 27 (Fri), 28 (Sat), 29 (Sun), 30 (Mon)
      const dec24 = new Date(2024, 11, 24);
      const dec30 = new Date(2024, 11, 30);
      // Business days: Dec 24, 27, 30 = 3 business days
      expect(calculateBusinessDays(dec24, dec30)).toBe(3);
    });

    it("should handle date range spanning multiple years", () => {
      // December 30, 2024 to January 5, 2025
      // Monday
      const dec30 = new Date(2024, 11, 30);
      // Sunday
      const jan5 = new Date(2025, 0, 5);
      // Dec 30, 31 (Tue), Jan 1 (Wed - New Year's Day), 2 (Thu), 3 (Fri)
      // Jan 4 (Sat), 5 (Sun) excluded
      // Business days: Dec 30, 31, Jan 2, 3 = 4 business days
      expect(calculateBusinessDays(dec30, jan5)).toBe(4);
    });

    it("should swap dates if start is after end", () => {
      const monday = new Date(2024, 0, 8);
      const friday = new Date(2024, 0, 12);
      expect(calculateBusinessDays(friday, monday)).toBe(
        calculateBusinessDays(monday, friday),
      );
    });

    it("should handle single day that is a weekend", () => {
      const saturday = new Date(2024, 0, 6);
      expect(calculateBusinessDays(saturday, saturday)).toBe(0);
    });

    it("should handle single day that is a holiday", () => {
      const newYearsDay = new Date(2024, 0, 1);
      expect(calculateBusinessDays(newYearsDay, newYearsDay)).toBe(0);
    });

    it("should normalize dates to start of day", () => {
      // Monday 3:30:45 PM
      const monday = new Date(2024, 0, 8, 15, 30, 45);
      // Friday 9:15:30 AM
      const friday = new Date(2024, 0, 12, 9, 15, 30);
      // Should still count all 5 business days regardless of time
      expect(calculateBusinessDays(monday, friday)).toBe(5);
    });

    it("should handle a full month without holidays", () => {
      // February 2024 has 29 days (leap year)
      // Weekdays: Mon-Fri each week = 5 days per week
      // Feb 2024: 5 full weeks = 25 weekdays, but need to check actual dates
      // Thursday
      const feb1 = new Date(2024, 1, 1);
      // Thursday
      const feb29 = new Date(2024, 1, 29);
      // Should calculate correctly excluding weekends
      const result = calculateBusinessDays(feb1, feb29);
      expect(result).toBeGreaterThan(0);
      expect(result).toBeLessThanOrEqual(29);
    });
  });
});

import * as fs from "fs";
import * as path from "path";

// Only log to file during local development
const isDevelopment = process.env.NODE_ENV !== "production";

// Ensure logs directory exists
const LOGS_DIR = path.join(process.cwd(), "logs");
if (!fs.existsSync(LOGS_DIR)) {
  fs.mkdirSync(LOGS_DIR, { recursive: true });
}

const ERROR_LOG_FILE = path.join(LOGS_DIR, "errors.log");

// Initialize log file with a header on first load (only in development)
if (isDevelopment && !fs.existsSync(ERROR_LOG_FILE)) {
  const initMessage = `[${new Date().toISOString()}] Error logging initialized\n`;
  try {
    fs.writeFileSync(ERROR_LOG_FILE, initMessage, "utf8");
  } catch {
    // Ignore initialization errors
  }
}

// Store original console.error to avoid circular calls
let originalConsoleError: typeof console.error;

/**
 * Writes error message directly to file (without console output)
 * @param message - The error message to write
 * @param error - The error object (can be any type since errors can come from various sources)
 * @param source - Optional source identifier for the error
 */
function writeErrorToFile(
  message: string,
  error?: unknown,
  source?: string,
): void {
  if (!isDevelopment) {
    return;
  }

  const timestamp = new Date().toISOString();
  let errorDetails = "";

  if (error) {
    try {
      if (error instanceof Error) {
        // Extract code property if it exists (common in Node.js errors)
        const errorCode =
          "code" in error ? (error as { code?: unknown }).code : undefined;
        errorDetails = `\n${JSON.stringify(
          {
            message: error.message,
            stack: error.stack,
            name: error.name,
            code: errorCode,
          },
          null,
          2,
        )}`;
      } else if (typeof error === "object" && error !== null) {
        errorDetails = `\n${JSON.stringify(error, null, 2)}`;
      } else {
        errorDetails = `\n${String(error)}`;
      }
    } catch {
      errorDetails = `\n${String(error)}`;
    }
  }

  const sourcePrefix = source ? `[${source}] ` : "";
  const logMessage = `[${timestamp}] ${sourcePrefix}${message}${errorDetails}\n`;

  try {
    fs.appendFileSync(ERROR_LOG_FILE, logMessage, "utf8");
  } catch (logErr) {
    // If we can't write to log file, use original console.error
    if (originalConsoleError) {
      originalConsoleError("Failed to write to error log file:", logErr);
    }
  }
}

/**
 * Logs errors to file during local development.
 * Also logs to console for visibility.
 * @param message - The error message to log
 * @param error - The error object (can be any type since errors can come from various sources)
 * @param source - Optional source identifier for the error
 */
export function logErrorToFile(
  message: string,
  error?: unknown,
  source?: string,
): void {
  const timestamp = new Date().toISOString();
  let errorDetails = "";

  if (error) {
    try {
      if (error instanceof Error) {
        // Extract code property if it exists (common in Node.js errors)
        const errorCode =
          "code" in error ? (error as { code?: unknown }).code : undefined;
        errorDetails = `\n${JSON.stringify(
          {
            message: error.message,
            stack: error.stack,
            name: error.name,
            code: errorCode,
          },
          null,
          2,
        )}`;
      } else if (typeof error === "object" && error !== null) {
        errorDetails = `\n${JSON.stringify(error, null, 2)}`;
      } else {
        errorDetails = `\n${String(error)}`;
      }
    } catch {
      errorDetails = `\n${String(error)}`;
    }
  }

  const sourcePrefix = source ? `[${source}] ` : "";
  const logMessage = `[${timestamp}] ${sourcePrefix}${message}${errorDetails}\n`;

  // Use original console.error if available, otherwise regular console.error
  if (originalConsoleError) {
    originalConsoleError(logMessage.trim());
  } else {
    console.error(logMessage.trim());
  }

  // Write to file (separate function to avoid circular calls)
  writeErrorToFile(message, error, source);
}

/**
 * Sets up global error handlers for unhandled rejections and uncaught exceptions.
 * Also intercepts console.error to log errors to file.
 * Should be called early in the application lifecycle.
 */
export function setupGlobalErrorHandlers(source?: string): void {
  // Store original console.error if not already stored
  if (!originalConsoleError) {
    originalConsoleError = console.error.bind(console);
  }

  // Intercept console.error to also log to file
  // Using unknown[] since console.error can receive any type of argument
  console.error = (...args: unknown[]) => {
    // Call original console.error first
    originalConsoleError.apply(console, args);

    // Also log to file during development
    if (isDevelopment) {
      try {
        // Try to format the error message
        const messages = args.map((arg) => {
          if (arg instanceof Error) {
            return arg.message;
          } else if (typeof arg === "object" && arg !== null) {
            try {
              return JSON.stringify(arg);
            } catch {
              return String(arg);
            }
          }
          return String(arg);
        });

        const errorMessage = messages.join(" ");

        // Try to extract Error object if present
        const errorObj = args.find((arg) => arg instanceof Error);

        // Write directly to file to avoid circular calls
        writeErrorToFile(errorMessage, errorObj || undefined, source);
      } catch (logErr) {
        // If logging fails, don't break console.error
        originalConsoleError("Failed to log error to file:", logErr);
      }
    }
  };

  // Handle unhandled promise rejections
  // Using unknown for reason since it can be any type (errors, strings, objects, etc.)
  process.on(
    "unhandledRejection",
    (reason: unknown, promise: Promise<unknown>) => {
      logErrorToFile(
        "Unhandled Rejection",
        { promise: String(promise), reason },
        source,
      );
      // Log but don't crash - let the app handle reconnections
      // Check if reason is an Error with a message property
      const reasonMessage =
        reason instanceof Error
          ? reason.message
          : typeof reason === "object" && reason !== null && "message" in reason
            ? String((reason as { message: unknown }).message)
            : null;
      if (reasonMessage && reasonMessage.includes("Connection terminated")) {
        console.warn(
          "Database connection error detected, will retry automatically",
        );
        return;
      }
    },
  );

  // Handle uncaught exceptions
  process.on("uncaughtException", (error: Error) => {
    logErrorToFile("Uncaught Exception", error, source);
    // Only exit on critical errors, not connection errors
    if (error.message && error.message.includes("Connection terminated")) {
      console.warn("Database connection error, will retry automatically");
      return;
    }
    // For other critical errors, exit gracefully
    process.exit(1);
  });
}

import { Test, TestingModule } from "@nestjs/testing";
import { getRepositoryToken } from "@nestjs/typeorm";
import { Repository } from "typeorm";
import { ConfigService } from "@nestjs/config";
import axios from "axios";
import { WaitlistService } from "./waitlist.service";
import { Waitlist } from "../database/entities/waitlist.entity";
import { UsersService } from "../users/users.service";
import { EmailService } from "../email/email.service";
import { EncryptionHelper } from "../encryption/encryption.helper";

jest.mock("axios");
jest.mock("crypto", () => ({
  ...jest.requireActual("crypto"),
  randomBytes: jest.fn(() => Buffer.alloc(32, "a")),
}));
jest.mock("../encryption/encryption.helper", () => ({
  EncryptionHelper: {
    hashEmail: jest.fn((email: string) => `hash_${email.toLowerCase()}`),
  },
}));

const mockedAxios = axios as jest.Mocked<typeof axios>;

describe("WaitlistService", () => {
  let service: WaitlistService;
  let repository: jest.Mocked<Repository<Waitlist>>;
  let usersService: jest.Mocked<UsersService>;
  let emailService: jest.Mocked<EmailService>;
  let configService: jest.Mocked<ConfigService>;

  const mockWaitlistEntry: Waitlist = {
    id: "waitlist-1",
    email: "test@example.com",
    emailHash: "hash_test@example.com",
    firstName: "Test",
    reason: "I want to test the product",
    approved: false,
    createdAt: new Date("2024-01-01"),
  } as Waitlist;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        WaitlistService,
        {
          provide: getRepositoryToken(Waitlist),
          useValue: {
            create: jest.fn(),
            save: jest.fn(),
            findOne: jest.fn(),
            find: jest.fn(),
            update: jest.fn(),
          },
        },
        {
          provide: UsersService,
          useValue: {
            findByEmail: jest.fn(),
            create: jest.fn(),
            update: jest.fn(),
          },
        },
        {
          provide: EmailService,
          useValue: {
            sendWaitlistApprovalEmail: jest.fn(),
          },
        },
        {
          provide: ConfigService,
          useValue: {
            get: jest.fn(),
          },
        },
      ],
    }).compile();

    service = module.get<WaitlistService>(WaitlistService);
    repository = module.get(getRepositoryToken(Waitlist));
    usersService = module.get(UsersService);
    emailService = module.get(EmailService);
    configService = module.get(ConfigService);
    jest.clearAllMocks();
    mockedAxios.post.mockResolvedValue({ data: {} });
  });

  describe("create", () => {
    it("should create a waitlist entry", async () => {
      repository.create.mockReturnValue(mockWaitlistEntry);
      repository.save.mockResolvedValue(mockWaitlistEntry);
      configService.get.mockReturnValue(undefined); // No Cliq config

      const result = await service.create(
        "test@example.com",
        "Test",
        "I want to test",
      );

      expect(EncryptionHelper.hashEmail).toHaveBeenCalledWith(
        "test@example.com",
      );
      expect(repository.create).toHaveBeenCalledWith({
        email: "test@example.com",
        emailHash: "hash_test@example.com",
        firstName: "Test",
        reason: "I want to test",
        approved: false,
      });
      expect(repository.save).toHaveBeenCalled();
      expect(result).toEqual(mockWaitlistEntry);
    });

    it("should auto-approve jeremy@focusbear.io", async () => {
      const autoApprovedEntry = {
        ...mockWaitlistEntry,
        email: "jeremy@focusbear.io",
        approved: true,
      };
      repository.create.mockReturnValue(autoApprovedEntry);
      repository.save.mockResolvedValue(autoApprovedEntry);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      configService.get.mockReturnValue(undefined);

      const result = await service.create(
        "jeremy@focusbear.io",
        "Jeremy",
        "Testing",
      );

      expect(result.approved).toBe(true);
      expect(usersService.create).toHaveBeenCalledWith({
        email: "jeremy@focusbear.io",
        name: "Jeremy",
        isApproved: true,
        isAdmin: true,
      });
    });

    it("should update existing user when jeremy@focusbear.io is auto-approved", async () => {
      const autoApprovedEntry = {
        ...mockWaitlistEntry,
        email: "jeremy@focusbear.io",
        approved: true,
      };
      repository.create.mockReturnValue(autoApprovedEntry);
      repository.save.mockResolvedValue(autoApprovedEntry);
      const existingUser = { id: "user-1", isAdmin: false } as any;
      usersService.findByEmail.mockResolvedValue(existingUser);
      usersService.update.mockResolvedValue(existingUser);
      configService.get.mockReturnValue(undefined);

      await service.create("jeremy@focusbear.io", "Jeremy", "Testing");

      expect(usersService.update).toHaveBeenCalledWith("user-1", {
        isApproved: true,
        isAdmin: true,
      });
      expect(usersService.create).not.toHaveBeenCalled();
    });

    it("should not create user for non-auto-approved entries", async () => {
      repository.create.mockReturnValue(mockWaitlistEntry);
      repository.save.mockResolvedValue(mockWaitlistEntry);
      configService.get.mockReturnValue(undefined);

      await service.create("test@example.com", "Test", "Testing");

      expect(usersService.create).not.toHaveBeenCalled();
      expect(usersService.update).not.toHaveBeenCalled();
    });

    it("should send Cliq notification when configured", async () => {
      repository.create.mockReturnValue(mockWaitlistEntry);
      repository.save.mockResolvedValue(mockWaitlistEntry);
      configService.get.mockImplementation((key: string) => {
        if (key === "ZOHO_CLIQ_BACKEND_BOT_WEBHOOK")
          return "https://cliq.webhook.url";
        if (key === "ZOHO_CLIQ_API_KEY") return "api-key";
        if (key === "ZOHO_CLIQ_BEARLY_MAIL_SIGNUP_CHANNEL") return "channel-id";
        return undefined;
      });

      await service.create("test@example.com", "Test", "Testing");

      expect(mockedAxios.post).toHaveBeenCalledWith(
        "https://cliq.webhook.url?zapikey=api-key",
        expect.objectContaining({
          channel: "channel-id",
          message: expect.stringContaining("New Waitlist Signup"),
        }),
      );
    });

    it("should not send Cliq notification when config is missing", async () => {
      repository.create.mockReturnValue(mockWaitlistEntry);
      repository.save.mockResolvedValue(mockWaitlistEntry);
      configService.get.mockReturnValue(undefined);

      await service.create("test@example.com", "Test", "Testing");

      expect(mockedAxios.post).not.toHaveBeenCalled();
    });
  });

  describe("findAll", () => {
    it("should return all waitlist entries ordered by createdAt DESC", async () => {
      const entries = [mockWaitlistEntry];
      repository.find.mockResolvedValue(entries);

      const result = await service.findAll();

      expect(repository.find).toHaveBeenCalledWith({
        order: { createdAt: "DESC" },
      });
      expect(result).toEqual(entries);
    });

    it("should return empty array when no entries", async () => {
      repository.find.mockResolvedValue([]);

      const result = await service.findAll();

      expect(result).toEqual([]);
    });
  });

  describe("findOne", () => {
    it("should return waitlist entry by id", async () => {
      repository.findOne.mockResolvedValue(mockWaitlistEntry);

      const result = await service.findOne("waitlist-1");

      expect(repository.findOne).toHaveBeenCalledWith({
        where: { id: "waitlist-1" },
      });
      expect(result).toEqual(mockWaitlistEntry);
    });

    it("should return undefined when entry not found", async () => {
      repository.findOne.mockResolvedValue(undefined);

      const result = await service.findOne("nonexistent");

      expect(result).toBeUndefined();
    });
  });

  describe("findByEmail", () => {
    it("should find waitlist entry by email hash", async () => {
      repository.findOne.mockResolvedValue(mockWaitlistEntry);

      const result = await service.findByEmail("test@example.com");

      expect(EncryptionHelper.hashEmail).toHaveBeenCalledWith(
        "test@example.com",
      );
      expect(repository.findOne).toHaveBeenCalledWith({
        where: { emailHash: "hash_test@example.com" },
      });
      expect(result).toEqual(mockWaitlistEntry);
    });

    it("should return null when entry not found", async () => {
      repository.findOne.mockResolvedValue(null);

      const result = await service.findByEmail("nonexistent@example.com");

      expect(result).toBeNull();
    });
  });

  describe("approve", () => {
    it("should throw error if entry not found", async () => {
      repository.findOne.mockResolvedValue(null);

      await expect(service.approve("nonexistent")).rejects.toThrow(
        "Waitlist entry not found",
      );
    });

    it("should approve entry and create user account with setup token", async () => {
      repository.findOne
        .mockResolvedValueOnce(mockWaitlistEntry)
        .mockResolvedValueOnce({ ...mockWaitlistEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      emailService.sendWaitlistApprovalEmail.mockResolvedValue(undefined);

      const result = await service.approve("waitlist-1");

      expect(repository.update).toHaveBeenCalledWith("waitlist-1", {
        approved: true,
      });
      expect(usersService.create).toHaveBeenCalledWith({
        email: "test@example.com",
        name: "Test",
        isApproved: false,
        isAdmin: false,
        passwordSetupToken: expect.any(String),
        passwordSetupTokenExpiresAt: expect.any(Date),
      });
      expect(emailService.sendWaitlistApprovalEmail).toHaveBeenCalledWith(
        "test@example.com",
        "Test",
        expect.any(String),
        "en",
      );
      expect(result.approved).toBe(true);
    });

    it("should approve entry and update existing user with setup token", async () => {
      const existingUser = { id: "user-1" } as any;
      repository.findOne
        .mockResolvedValueOnce(mockWaitlistEntry)
        .mockResolvedValueOnce({ ...mockWaitlistEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(existingUser);
      usersService.update.mockResolvedValue(existingUser);
      emailService.sendWaitlistApprovalEmail.mockResolvedValue(undefined);

      const result = await service.approve("waitlist-1");

      expect(usersService.update).toHaveBeenCalledWith("user-1", {
        passwordSetupToken: expect.any(String),
        passwordSetupTokenExpiresAt: expect.any(Date),
      });
      expect(usersService.create).not.toHaveBeenCalled();
      expect(result.approved).toBe(true);
    });

    it("should set isAdmin for jeremy@focusbear.io when creating user", async () => {
      const jeremyEntry = {
        ...mockWaitlistEntry,
        email: "jeremy@focusbear.io",
      };
      repository.findOne
        .mockResolvedValueOnce(jeremyEntry)
        .mockResolvedValueOnce({ ...jeremyEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      emailService.sendWaitlistApprovalEmail.mockResolvedValue(undefined);

      await service.approve("waitlist-1");

      expect(usersService.create).toHaveBeenCalledWith({
        email: "jeremy@focusbear.io",
        name: "Test",
        isApproved: false,
        isAdmin: true,
        passwordSetupToken: expect.any(String),
        passwordSetupTokenExpiresAt: expect.any(Date),
      });
    });

    it("should generate password setup token valid for 7 days", async () => {
      const now = new Date("2024-01-01T12:00:00Z");
      jest.useFakeTimers();
      jest.setSystemTime(now);

      repository.findOne
        .mockResolvedValueOnce(mockWaitlistEntry)
        .mockResolvedValueOnce({ ...mockWaitlistEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      emailService.sendWaitlistApprovalEmail.mockResolvedValue(undefined);

      await service.approve("waitlist-1");

      const createCall = usersService.create.mock.calls[0][0];
      const expiresAt = createCall.passwordSetupTokenExpiresAt;
      const expectedExpiry = new Date(now);
      expectedExpiry.setDate(expectedExpiry.getDate() + 7);

      expect(expiresAt.getTime()).toBe(expectedExpiry.getTime());

      jest.useRealTimers();
    });

    it("should not throw if email sending fails", async () => {
      repository.findOne
        .mockResolvedValueOnce(mockWaitlistEntry)
        .mockResolvedValueOnce({ ...mockWaitlistEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      emailService.sendWaitlistApprovalEmail.mockRejectedValue(
        new Error("Email failed"),
      );

      await expect(service.approve("waitlist-1")).resolves.toBeDefined();

      expect(repository.update).toHaveBeenCalled();
      expect(usersService.create).toHaveBeenCalled();
    });

    // User needs password setup
    it("should not set isApproved to true when creating user", async () => {
      repository.findOne
        .mockResolvedValueOnce(mockWaitlistEntry)
        .mockResolvedValueOnce({ ...mockWaitlistEntry, approved: true });
      repository.update.mockResolvedValue({ affected: 1 } as any);
      usersService.findByEmail.mockResolvedValue(null);
      usersService.create.mockResolvedValue({ id: "user-1" } as any);
      emailService.sendWaitlistApprovalEmail.mockResolvedValue(undefined);

      await service.approve("waitlist-1");

      const createCall = usersService.create.mock.calls[0][0];
      expect(createCall.isApproved).toBe(false);
    });
  });
});
